INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-8ebb3021c30c48f8', 'pad-see-ew-ga', 245, 'Hủ tiếu xào xì dầu thịt gà kiểu Thái (Pad See Ew)', 'Bánh phở tươi bản lớn xào lửa lớn cháy cạnh thơm khói chảo, áo đều sốt hắc xì dầu dầu hào cùng ức gà mềm, trứng tơi và cải thìa giòn xanh', 'Pad See Ew là món mì xào xì dầu trứ danh tại các khu chợ đêm Thái Lan, nổi bật với sợi bánh phở tươi bản to dẻo dai áp chảo hơi xém cạnh, vị mặn ngọt hài hòa từ hắc xì dầu, dầu hào và cải xanh giòn ngọt.', 'Trút Pad See Ew nóng hổi ra đĩa, rắc thêm chút tiêu trắng xay và dọn kèm ớt tươi thái lát ngâm giấm hoặc chanh tươi tùy thích.', 'Nên ăn nóng ngay để sợi bánh phở tơi mềm và thơm mùi chảo; nếu còn dư bảo quản ngăn mát trong 24 giờ, xào nóng lại với 1 muỗng canh nước lọc trên lửa lớn.', 'thai', 'mon_xao', NULL, 'medium', 20, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad See Ew","Mì xào","Ức gà","Xì dầu"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["chicken","egg","molluscs","soybean","wheat"]', 621, 620.7, 2597, 37.8, 23.2, 4.4, 64.1, 2.7, 10.2, 1327, 3.32, '["Dark Soy Sauce Label Ref","NIN VN Fresh Pho Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170390","USDA FDC 170933","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 171477","USDA FDC 173647","USDA FDC 174277"]', 'd56f2264d6c428eb1627cff414db56cb4e2a75abc971409e5cbd662adb1797e2', '159f24857839a9905520c0343720c30f217abf8d93cf4b05f0aafd30fb8cc680', 4),
('imp-8e2f2113f406a7d8', 'ga-xien-sate-sa', 246, 'Thịt gà xiên sả nướng kiểu Thái (Satay Sả)', 'Đùi gà rút xương cắt dải ướp hỗn hợp sả tươi, tỏi, rễ ngò xay cùng nước cốt dừa béo thơm, nướng áp chảo xém vàng mọng nước', 'Gà xiên sả kiểu Thái thơm nức hương sả tươi, tỏi và ngò rí quyện cùng nước cốt dừa giúp thịt đùi gà mềm mọng lạ miệng, nướng xém cạnh vàng ươm mà không hề bị khô.', 'Xếp các xiên gà nướng nóng hổi ra đĩa, dọn kèm chanh tươi cắt múi cau để vắt trực tiếp khi ăn cùng xôi nếp, cơm trắng hoặc đồ chua rau củ.', 'Thịt gà ướp có thể bọc kín bảo quản ngăn mát qua đêm để nướng ngon hơn; xiên đã nướng giữ trong tủ mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu 180°C trong 4 phút.', 'thai', 'mon_chien', NULL, 'medium', 35, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Xiên nướng","Thịt gà","Sả thơm","Tiệc cuối tuần"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["chicken","egg","molluscs","soybean","wheat"]', 401, 401.1, 1679, 31.7, 24.2, 8.4, 14.1, 0.9, 3.2, 948, 2.37, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 169997","USDA FDC 170172","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 174277"]', 'a3076131cdf47f7867e36b0f4f9d5dbcb5719a35285cf2773b1a45f943208a8d', 'e0b82588383bf76f7eafea87ef6a847613d25f67e748dceb5870bfc43e7b6554', 4),
('imp-574963de4a60d466', 'ca-hap-chanh-ot-thai', 247, 'Cá chẽm hấp chanh ớt kiểu Thái (Pla Neung Manao)', 'Cá tươi nguyên con hấp sả chín mọng ngọt thịt, chan đẫm sốt nước dùng gà pha chanh tươi, nước mắm, tỏi băm và ớt hiểm cay nồng', 'Pla Neung Manao là món cá hấp kinh điển trong các bữa tiệc Thái Lan, giữ trọn độ ngọt thanh mềm mọng của thịt cá tươi hòa quyện cùng nước sốt chanh tỏi ớt chua tê bùng vị và hương cần tàu tươi mát.', 'Chuyển cá hấp sang đĩa bầu dục sâu lòng, xếp lá cần tàu xung quanh rồi rưới đều nước sốt chanh tỏi ớt nóng ấm lên mình cá; dọn ăn ngay với cơm trắng.', 'Món cá hấp ngon nhất khi thưởng thức nóng ngay lúc vừa rưới sốt; nếu bảo quản ngăn mát trong 24 giờ, nên giữ riêng phần sốt và hấp nóng lại cá 5 phút trước khi chan sốt.', 'thai', 'mon_hap_luoc', NULL, 'medium', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món hấp","Cá tươi","Chua cay","Thanh mát"]', '["lunch","dinner"]', '["steam"]', '["celery","fish"]', 227, 226.7, 948, 35.1, 4.4, 1.2, 10.6, 1.1, 5.2, 1281, 3.2, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169988","USDA FDC 169997","USDA FDC 170106","USDA FDC 172185","USDA FDC 172883","USDA FDC 175176","USDA FDC Palm Sugar Ref"]', '9eaf09b92f49adaf1c7afc9b9b36ebd2ced88e2d58fc9e5f84daffb521f55933', 'e3bde15fc4c32e1b0e0d8f211ae2f59b37e590d9f1395a9954c1ae0c5b6fcd61', 4),
('imp-295e7045e644d2ca', 'goi-muc-mi-soi-thai', 248, 'Gỏi miến mực chua cay kiểu Thái (Yam Wun Sen)', 'Miến dong dai trong trộn cùng mực tươi chần giòn, sả hành thơm nồng, tôm khô giã tỏi ớt và nước sốt chanh đường thốt nốt chua cay', 'Yam Wun Sen là món gỏi miến khai vị thanh mát trứ danh của Thái Lan với sợi miến trong dai không bết dính, mực tươi giòn ngọt quyện sốt nước mắm chanh đường thốt nốt chua cay đậm vị.', 'Bày gỏi miến mực ra đĩa sâu lòng, rắc mè rang vàng và vài lát ớt đỏ lên trên; thưởng thức ngay khi còn mát tươi như món khai vị hoặc ăn nhẹ.', 'Miến dễ hút nước và nở mềm nên ngon nhất khi trộn và dùng hết ngay trong vòng 1–2 giờ sau khi chế biến.', 'thai', 'mon_cuon_nom', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Gỏi trộn","Miến trộn","Hải sản","Chua cay"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","fish","molluscs","sesame","shrimp","squid"]', 328, 327.7, 1371, 16.5, 2.2, 0.4, 60.6, 1.8, 7.9, 1415, 3.54, '["USDA / Asian Dried Shrimp Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168952","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170499","USDA FDC 172185","USDA FDC 173474","USDA FDC 173647","USDA FDC 174223","USDA FDC Palm Sugar Ref"]', '65db5d6e999ac7f5e2c46bbd68c888feafd9d8e89bd2bdf4fb2581e6636fde20', 'e50f897449e3b30c1483ab8144540f374b33f0bedfda29e0bc0eaee5e91f7dd0', 4),
('imp-5e0a488541baee5e', 'trung-chien-kai-jeow', 249, 'Trứng chiên giòn phồng kiểu Thái (Kai Jeow)', 'Trứng gà đánh sủi bọt cùng nước mắm và hành lá chiên ngập dầu nóng già tạo lớp viền xốp giòn vàng rụm, bên trong mềm béo đậm đà', 'Kai Jeow là món trứng chiên đường phố nổi tiếng của Thái Lan với kỹ thuật rót trứng từ trên cao vào chảo dầu thật nóng, tạo lớp vỏ ngoài phồng xốp giòn tan mà ruột trứng vẫn giữ độ ẩm mềm.', 'Đặt miếng trứng chiên Kai Jeow phồng giòn lên đĩa cơm trắng nóng, rắc lá ngò rí và dọn kèm chén tương ớt chua ngọt hoặc nước mắm ớt chanh.', 'Món trứng chiên phồng ngon nhất khi dùng nóng ngay vừa vớt ra; nếu để nguội trứng sẽ xẹp bớt nhưng vẫn bảo quản tủ mát trong ngày và áp chảo nóng lại không dầu 2 phút.', 'thai', 'mon_chien', NULL, 'easy', 5, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Trứng chiên","Món chiên","Nhanh gọn","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["deep_fry"]', '["egg","fish"]', 205, 205.1, 858, 9.3, 16.6, 3.6, 4.9, 0.8, 2.9, 805, 2.01, '["USDA FDC 168155","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC Sriracha Ref"]', '87fc527a1de83deba08fca26f9555cfb20f207212220e36ad164efdcdc4f81cb', 'bfceef1163d35155a92027c58c182fddf201296e076147b0678dd45fc74d1f80', 4),
('imp-bcc430e4b54c1e65', 'canh-tom-chuet-tom', 250, 'Canh bắp cải tôm tươi thanh ngọt kiểu Thái (Tom Chuet)', 'Nước canh trong dịu ngọt vị tôm tươi và bắp cải non hầm mềm, hòa quyện cà chua chín, hương tỏi phi và hành ngò nhẹ nhàng không cay', 'Tom Chuet là món canh thanh mát không cay quen thuộc trên mâm cơm gia đình Thái Lan, kết hợp vị ngọt tự nhiên từ tôm tươi áp chảo sơ cùng bắp cải mềm ngọt, cà chua chín và nước dùng thơm mùi tỏi phi.', 'Múc canh Tom Chuet nóng ra tô lớn, rắc tiêu đen xay và ngò rí lên trên; rất hợp dùng kèm các món mặn hoặc món xào cay kiểu Thái.', 'Canh rau bắp cải nên dùng hết trong ngày để giữ độ ngọt tươi; nếu bảo quản ngăn mát tối đa 24 giờ, đun sôi nhanh lại trên lửa vừa rồi dùng ngay.', 'thai', 'mon_canh', NULL, 'easy', 12, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Không cay","Thanh đạm","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","shrimp","soybean","wheat"]', 135, 134.5, 563, 16.4, 3.8, 0.6, 10.7, 3.4, 5.6, 976, 2.44, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 169997","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '6b7a523d16da748c9cbd39d203bec562f27ee3a160eb653ceaae101224a6cf40', '62b7b43cc399bd95b4d7420fd7a036f578ab719135d5c55bf9aff18ebbaf2fef', 4),
('imp-103ea67cd56c9c96', 'mi-y-carbonara-ba-chi', 251, 'Mì Ý Carbonara ba chỉ giòn', 'Sợi Spaghetti áo lớp sốt kem trứng và phô mai Pecorino Romano sánh mượt không dùng kem tươi, kết hợp thịt ba chỉ muối áp chảo giòn thơm và tiêu đen', 'Mì Ý Carbonara chuẩn truyền thống thành Rome không hề dùng kem tươi mà tạo độ sánh mượt nhờ kỹ thuật nhũ tương hóa hỗn hợp trứng gà, phô mai Pecorino Romano bào mịn cùng mỡ ba chỉ muối giòn và nước luộc mì giàu tinh bột.', 'Chia mì ra 4 đĩa sâu lòng đã làm ấm, rắc đều thịt ba chỉ giòn, thêm phô mai Pecorino Romano bào và tiêu đen mới xay lên trên rồi thưởng thức ngay.', 'Mì Carbonara cần ăn ngay khi còn nóng để sốt trứng giữ được độ kem bóng mịn; món này không thích hợp để qua đêm hay hâm lại vì trứng dễ tách nước và vón cục.', 'italian', 'mon_bun_pho', NULL, 'medium', 10, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Carbonara","Ba chỉ","Béo mịn"]', '["lunch","dinner"]', '["boil","pan_fry","toss_mix"]', '["egg","milk","pork","wheat"]', 544, 543.5, 2274, 24.6, 21.1, 8.2, 62, 2.8, 2.5, 963, 2.41, '["USDA FDC 167923","USDA FDC 168927","USDA FDC 169230","USDA FDC 170931","USDA FDC 171287","USDA FDC 173468","USDA FDC 173647","USDA FDC Pecorino Ref"]', '08d0130579c2fc016838b595f70e369306b3145344070a0a484d26f095185165', 'b13104e7bb071423d8c42207677951f5706747cbb19f8e9bb6ea1d513f39bf84', 4),
('imp-34505f9722b38fc1', 'mi-y-bo-bam-bologna', 252, 'Mì Ý bò bằm sốt Ragù Bologna', 'Thịt bò heo xay và ba chỉ xông khói hầm chậm cùng rau củ soffritto, rượu vang đỏ và sốt cà chua đậm đà phủ sợi mì Spaghetti', 'Sốt Ragù Bologna là tinh hoa ẩm thực miền Emilia-Romagna với thịt bò xay kết hợp thịt heo xay và ba chỉ muối xào xém, hầm liu riu hàng giờ cùng cà rốt, cần tây, hành tây, rượu vang đỏ và cà chua Passata tạo nên độ sánh đậm quyện vị.', 'Trộn mì Ý Spaghetti trực tiếp vào nồi sốt Ragù nóng hổi cùng chút nước luộc mì, chia ra 4 đĩa sâu lòng và rắc phô mai Parmesan bào mịn lên trên.', 'Sốt Ragù Bologna bảo quản hộp kín trong ngăn mát đến 3–4 ngày hoặc cấp đông đến 2 tháng; khi dùng hâm nóng sốt trên lửa nhỏ, thêm chút nước dùng bò nếu đặc.', 'italian', 'mon_bun_pho', NULL, 'medium', 20, 90, 4, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Ragù Bologna","Thịt bò bằm","Cuối tuần"]', '["lunch","dinner"]', '["boil","braise","simmer"]', '["beef","celery","milk","pork","sulphites","wheat"]', 853, 853.1, 3569, 41, 42.1, 15.7, 72.2, 5.2, 8.4, 1327, 3.32, '["USDA FDC 167902","USDA FDC 167923","USDA FDC 168927","USDA FDC 169072","USDA FDC 169230","USDA FDC 169988","USDA FDC 170000","USDA FDC 170393","USDA FDC 170460","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171593","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174036"]', 'b66ae0364b7a4f5ba2ab7aa5097a64a79e09241db73599f86f6f5a24e6cc6150', '11a5a25322ca2af9292581cc1e113b93ce71a989a0b3245dcf0834f730f12ad8', 4),
('imp-266d7af134d7286a', 'mi-y-nam-kem', 253, 'Mì Ý nấm đùi gà sốt kem', 'Nấm đùi gà áp chảo vàng thơm cùng bơ tỏi quyện sốt kem sữa sánh mịn và phô mai Parmesan ôm trọn sợi mì Spaghetti nóng hổi', 'Mì Ý nấm đùi gà sốt kem là món pasta ấm áp, dễ nấu chỉ trong 30 phút. Nấm đùi gà giòn ngọt được xào vàng với bơ lạt và dầu ô liu rồi hòa quyện cùng kem tươi, sữa tươi và phô mai Parmesan béo ngậy.', 'Múc mì ra 3 đĩa sâu lòng khi còn nóng, rắc thêm ngò tây tươi thái nhỏ, chút phô mai Parmesan bào và tiêu đen xay lên trên.', 'Thưởng thức ngay khi còn nóng để sốt kem giữ độ mượt; nếu bảo quản ngăn mát tối đa 2 ngày, hâm nóng trên chảo lửa nhỏ cùng vài muỗng sữa tươi.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Nấm đùi gà","Sốt kem","Nhanh gọn"]', '["lunch","dinner"]', '["boil","stir_fry","simmer","toss_mix"]', '["milk","wheat"]', 673, 672.6, 2814, 20.8, 33.9, 18.4, 72.7, 4.7, 6.4, 770, 1.93, '["USDA FDC 168580","USDA FDC 168927","USDA FDC 169230","USDA FDC 170416","USDA FDC 170848","USDA FDC 170859","USDA FDC 170931","USDA FDC 171265","USDA FDC 171413","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647"]', 'e2d9731003d9de4f9a2079be84bab973ce43e7e8d8de42402aaf4af3968120c8', '43009c07cd4fd7de4245814281f387cddce09405bd485a56b8490be3947e5370', 4),
('imp-8b2c852ba59f2143', 'risotto-rau-bina-nam', 254, 'Cơm Risotto rau bina và nấm', 'Gạo Arborio om chậm với nước dùng rau củ nóng, nấm đùi gà áp chảo vàng thơm, rau bina xanh mướt và đánh bóng cuối bằng bơ phô mai', 'Cơm Risotto rau bina và nấm là sự kết hợp hài hòa giữa vị ngọt giòn của nấm đùi gà áp chảo, sắc xanh tươi mát từ cải bó xôi cùng hạt gạo Arborio mềm dẻo sóng sánh trong nước dùng rau củ, bơ lạt và phô mai Parmesan.', 'Múc cơm Risotto nóng ra 3 đĩa sâu lòng, rắc thêm tiêu đen mới xay và chút phô mai Parmesan bào mịn lên trên rồi dùng ngay khi cơm còn sóng sánh.', 'Risotto ngon nhất khi ăn nóng ngay lúc vừa tắt bếp; phần dư bảo quản ngăn mát tối đa 2 ngày, hâm lại bằng chảo nhỏ với ít nước dùng rau củ nóng.', 'italian', 'mon_kho', NULL, 'medium', 15, 30, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Cơm Risotto","Rau bina","Nấm đùi gà","Thanh đạm"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["milk","sulphites"]', 577, 576.8, 2412, 15, 18.4, 7.9, 84.1, 5, 6.1, 1418, 3.54, '["USDA FDC 168462","USDA FDC 168580","USDA FDC 169230","USDA FDC 170000","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 171595","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC Arborio Rice Ref"]', '4dc2dc902cfda0f26defb1ba00a0791720c4e7a244126b8fede0ff7885953196', '7c10fe09541c9202f605ad23d76ec87fb33312646b15218af25248fde13a9dea', 4),
('imp-de5ce12092f4f0aa', 'frittata-rau-bina-pho-mai', 255, 'Trứng chiên kiểu Ý Frittata rau bina phô mai', 'Khối trứng chiên dày xốp kết hợp rau bina xào thơm, hành tây ngọt dịu cùng hai lớp phô mai Parmesan và Mozzarella tan chảy béo ngậy', 'Frittata rau bina phô mai là món trứng chiên dày kiểu Ý giàu đạm và chất xơ, dễ làm ngay trên bếp chảo chống dính mà không cần lò nướng. Rau bina được làm xẹp và vắt thật ráo nước để khối trứng chiên lên xốp mềm, thơm ngậy phô mai.', 'Trượt khối Frittata ra thớt hoặc đĩa lớn, để nguội bớt 2 phút rồi cắt thành 6 múi tam giác đều nhau, ăn kèm salad rau trộn dầu giấm hoặc bánh mì nướng.', 'Frittata ăn ngon cả khi nóng lẫn nguội; có thể bọc kín bảo quản ngăn mát 2–3 ngày và hâm nóng nhẹ bằng chảo khô lửa nhỏ hoặc thưởng thức ở nhiệt độ phòng.', 'italian', 'mon_chien', NULL, 'easy', 10, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Frittata","Trứng chiên","Rau bina","Phô mai"]', '["breakfast","lunch","dinner"]', '["pan_fry","stir_fry"]', '["egg","milk"]', 345, 345.4, 1445, 24.8, 23.9, 8.6, 8.5, 2.4, 2.6, 1043, 2.61, '["USDA FDC 168462","USDA FDC 169230","USDA FDC 170000","USDA FDC 170845","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468"]', '846524a24b5a932b4878721d1feb219e79686d05a40d4afa02c555304b6fc511', '5ff16d7d8e38658f595624c3549c27ecbb484392825d8633541817c8231c65d0', 4),
('imp-b8d2cb0b37dbdb81', 'ga-sot-chanh-bo-y', 256, 'Ức gà áp chảo sốt chanh bơ kiểu Ý', 'Miếng ức gà áo bột mỏng áp chảo vàng giòn hai mặt rồi om thấm sốt chanh vàng thơm lừng hương thảo, đánh bóng béo mượt bằng bơ lạt lạnh', 'Pollo al limone là món gà sốt chanh bơ thanh lịch đặc trưng của ẩm thực Ý. Ức gà cắt miếng đều được phủ lớp bột mì mỏng rồi áp chảo vàng ươm, sau đó rim nhẹ trong nước cốt và vỏ chanh vàng cùng hương thảo, hoàn thiện với bơ lạt lạnh tạo sốt bóng mượt.', 'Xếp gà ra đĩa ấm, rưới đều phần sốt chanh bơ sánh bóng lên trên và rắc chút ngò tây tươi thái nhỏ; ăn kèm cơm trắng, mì Ý bơ tỏi hoặc bánh mì giòn chấm sốt.', 'Thịt gà sốt chanh bơ bảo quản trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn hâm nóng lại trên chảo lửa nhỏ cùng 1–2 muỗng canh nước lọc để sốt không bị tách dầu.', 'italian', 'mon_chien', NULL, 'easy', 10, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Ức gà","Sốt chanh bơ","Áp chảo","Thanh nhẹ"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["chicken","milk","wheat"]', 369, 369.3, 1545, 35.1, 21.2, 7.9, 9.1, 1.5, 0.8, 717, 1.79, '["USDA FDC 167746","USDA FDC 169230","USDA FDC 169761","USDA FDC 170416","USDA FDC 170931","USDA FDC 171413","USDA FDC 171477","USDA FDC 173430","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647"]', '3381b926a82817c310adceb950e9ca381f87d198f8f1c0c01fd41adf150e66ec', '30ed9cdca30621c608616283c422c08b6a1844e5d4db67b25be4ef026e433889', 4),
('imp-a4d02f2246e0e115', 'ga-cacciatore-nam', 257, 'Gà om nấm sốt cà chua Cacciatore', 'Đùi gà áp chảo vàng da om mềm thấm đẫm sốt cà chua tươi, nấm đùi gà giòn ngọt, rượu vang trắng và hương thảo kiểu thợ săn Ý', 'Gà om nấm Cacciatore là món ăn đồng quê ấm áp của nước Ý. Đùi gà áo bột mỏng áp chảo xém da rồi được om chậm trong nền rau củ hành tây, cần tây, nấm đùi gà, rượu vang trắng và cà chua chín mọng thơm mùi hương thảo, lá nguyệt quế.', 'Múc gà om nấm cùng nước sốt đỏ sánh ra đĩa sâu lòng, rắc ngò tây tươi băm nhuyễn; dùng nóng kèm bánh mì giòn chấm sốt, cơm trắng hoặc mì Ý luộc.', 'Món gà om Cacciatore để qua đêm càng thấm vị; bảo quản hộp kín trong ngăn mát tối đa 3 ngày và hâm nóng lại trên chảo lửa nhỏ đến khi sôi đều.', 'italian', 'mon_kho', NULL, 'medium', 15, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Cacciatore","Đùi gà om","Nấm đùi gà","Cà chua"]', '["lunch","dinner"]', '["pan_fry","braise","simmer"]', '["celery","chicken","sulphites","wheat"]', 434, 434.3, 1817, 33.9, 23.8, 5.6, 16.5, 4, 5.6, 809, 2.02, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169761","USDA FDC 169988","USDA FDC 170000","USDA FDC 170416","USDA FDC 170457","USDA FDC 170917","USDA FDC 170931","USDA FDC 171319","USDA FDC 171413","USDA FDC 172385","USDA FDC 172883","USDA FDC 173190","USDA FDC 173468","USDA FDC 173475"]', 'd54870ed48f7eca95054bd9541d96e3452b127e039448df06d95949b43c4e9f5', 'f84aef6a626a26c03fd36b7f47babb29fa237c499816312627e7a238527b2484', 4),
('imp-a60814a4aca4143b', 'vien-thit-polpette-ca-chua', 258, 'Thịt viên bò sốt cà chua Polpette', 'Thịt bò xay trộn ruột bánh mì tươi, trứng gà và hai loại phô mai Ý vo viên nhỏ om mềm trong sốt cà chua Passata thơm lá húng quế', 'Polpette là món thịt viên om sốt cà chua truyền thống trong bữa cơm gia đình Ý. Thịt bò xay được nhào cùng ruột bánh mì gối tươi, trứng gà, nhục đậu khấu và phô mai Parmesan, Pecorino giúp viên thịt mềm ẩm mà không bị khô, sau đó thả trực tiếp vào sốt cà chua ninh sánh.', 'Múc các viên thịt Polpette ra đĩa sâu lòng cùng nhiều sốt cà chua nóng hổi, điểm thêm vài lá húng quế tươi; dùng kèm bánh mì giòn chấm sốt hoặc trộn với mì Ý.', 'Thịt viên om sốt bảo quản hộp kín trong ngăn mát tối đa 2–3 ngày; khi dùng hâm nóng trên chảo lửa nhỏ cùng chút nước lọc đến khi sốt sôi nhẹ.', 'italian', 'mon_kho', NULL, 'medium', 25, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Polpette","Thịt bò viên","Sốt cà chua","Gia đình"]', '["lunch","dinner"]', '["braise","simmer"]', '["beef","egg","milk","wheat"]', 644, 644.2, 2696, 41.2, 39.9, 14.4, 31.5, 5.2, 12.3, 1512, 3.78, '["USDA FDC 169072","USDA FDC 169230","USDA FDC 170000","USDA FDC 170416","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171326","USDA FDC 171413","USDA FDC 172232","USDA FDC 172687","USDA FDC 173468","USDA FDC 174036","USDA FDC Pecorino Ref"]', 'e78fa2063c5b1ff16bc643117f05fc486f568fd0d421273b2698d7beaf4968da', 'abf00a5ed6ad194afdb22f7b08337394b2871ff1e9f1c7968134c4c016c61228', 4),
('imp-5504378372dc989b', 'sup-minestrone-rau-cu', 259, 'Súp rau củ Ý Minestrone', 'Nồi súp rau củ đa sắc màu ninh chậm từ cà rốt, bí đỏ, khoai tây, đậu trắng, bắp cải và nui Ý ngắn thơm dịu mùi hương thảo và dầu ô liu', 'Súp Minestrone là món canh rau củ truyền thống giàu chất xơ của nước Ý. Hàng chục loại rau củ tươi được cắt hạt lựu đều nhau rồi cho vào nồi theo từng đợt chín dần, hòa quyện cùng đậu trắng bùi béo và bó thơm hương thảo, nguyệt quế.', 'Múc súp Minestrone nóng ra bát sâu lòng, rưới nhẹ một vòng dầu ô liu nguyên chất và rắc thêm tiêu đen xay; có thể dùng kèm bánh mì nướng giòn hoặc phô mai Parmesan bào.', 'Súp Minestrone để qua đêm hương vị càng hòa quyện; bảo quản hộp kín trong ngăn mát tối đa 3 ngày và đun sôi lại trên lửa vừa trước khi ăn (nên luộc riêng nui nếu để lâu).', 'italian', 'mon_canh', NULL, 'easy', 20, 45, 5, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Súp Minestrone","Rau củ","Thanh nhẹ","Mùa lạnh"]', '["lunch","dinner"]', '["stir_fry","simmer"]', '["celery","wheat"]', 322, 322.3, 1349, 10.7, 10.3, 1.5, 50.7, 9.1, 9.8, 749, 1.87, '["USDA FDC 168448","USDA FDC 168927","USDA FDC 169230","USDA FDC 169246","USDA FDC 169291","USDA FDC 169961","USDA FDC 169975","USDA FDC 169986","USDA FDC 169988","USDA FDC 170000","USDA FDC 170026","USDA FDC 170393","USDA FDC 170457","USDA FDC 170917","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173475","USDA FDC 173647","USDA FDC 175200"]', '2740cce4459f436dc6b8d1dcf3c0f3a7ed3bd8395469e14ec05f0d4c57c0cca2', '00ea92644faff9a08bc0d28f15716588474189d05e025fe49096fa48a419be13', 4),
('imp-b6496331f7aa0ee9', 'mi-y-tom-kem-chanh', 260, 'Mì Ý tôm tươi sốt kem chanh', 'Tôm tươi giòn ngọt nấu cùng sốt kem béo mượt thơm nồng tỏi bơ, rượu vang trắng, phô mai Parmesan và hương chanh vàng thanh mát', 'Mì Ý tôm tươi sốt kem chanh là món pasta hải sản sang trọng nhưng chế biến gọn nhẹ. Vị ngọt tự nhiên của tôm tươi hòa cùng sốt kem tươi sánh mịn, phô mai Parmesan và vị chua dịu từ vỏ, nước cốt chanh vàng giúp món ăn béo mà không hề ngán.', 'Gắp mì và tôm ra 3 đĩa sâu lòng khi còn nóng, rưới đều sốt kem chanh lên trên, rắc ngò tây tươi thái nhỏ và chút phô mai Parmesan bào mịn.', 'Món mì hải sản sốt kem ngon nhất khi dùng ngay lúc nóng; nếu còn dư bảo quản ngăn mát tối đa 2 ngày và hâm nóng nhẹ trên chảo lửa nhỏ với chút kem tươi.', 'italian', 'mon_bun_pho', NULL, 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món Ý","Mì Ý","Tôm tươi","Sốt kem chanh","Hải sản"]', '["lunch","dinner"]', '["boil","simmer","toss_mix"]', '["crustaceans","milk","shrimp","sulphites","wheat"]', 738, 737.6, 3086, 39.7, 36.9, 22.6, 57.4, 2.9, 4.5, 919, 2.3, '["USDA FDC 167746","USDA FDC 168927","USDA FDC 169230","USDA FDC 169761","USDA FDC 170416","USDA FDC 170848","USDA FDC 170859","USDA FDC 170931","USDA FDC 173190","USDA FDC 173430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179"]', '908df6c3d9f0a408f77cba18541171b7c9e3fc95f12181404a15c1a2456f9286', '8f8a6613387bbb561438f4dbc4cb19bae311b751917c0c04adb2f0c436f03485', 4),
('imp-d6f7b2ef8f347338', 'canh-dua-suon-non', 261, 'Canh dứa sườn non', 'Sườn non heo hầm mềm ngọt xương hòa quyện cùng vị chua ngọt tự nhiên của dứa chín và cà chua đặc trưng ẩm thực Nam Bộ', 'Canh dứa sườn non là món canh khai vị quen thuộc trong bữa cơm Nam Bộ. Sườn non được chần sạch rồi hầm liu riu ra nước ngọt thanh, nấu cùng dứa chín và cà chua tạo vị chua ngọt tự nhiên rất bắt cơm.', 'Dọn canh nóng vào tô lớn, rắc hành lá và ngò gai thái nhỏ; dùng kèm cơm trắng và chén nước mắm ớt mặn để chấm từng miếng sườn non mềm ngọt.', 'Có thể bảo quản ngăn mát tủ lạnh trong hộp kín tối đa 2 ngày; khi ăn đun sôi lại trên lửa vừa 5 phút để sườn nóng đều và thấm vị nước canh.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Sườn non","Dứa chín","Nam Bộ","Chua ngọt"]', '["lunch","dinner"]', '["simmer"]', '["fish","pork"]', 327, 327, 1368, 14.5, 23.6, 7.7, 15, 2, 10.3, 1493, 3.73, '["USDA FDC 167861","USDA FDC 169124","USDA FDC 169655","USDA FDC 169918","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN/Asian Seasoning Powder Avg"]', 'b2964be88a73bd77f88807efcb925e53a0fe6edadb0b047c77156bd29f0524e0', '50283ebdc7b6c09b55126ad7b39adbecb011c08985f532f78772a85bf77a5746', 4),
('imp-5e0564249085d9c1', 'canh-tom-bong-cai', 262, 'Canh tôm bông cải xanh', 'Nước canh trong veo ngọt thanh tự nhiên từ tôm tươi quyện cùng những bông cải xanh giòn ngọt đầy dinh dưỡng', 'Canh tôm bông cải xanh là món canh nấu nhanh giàu đạm và chất xơ. Tôm tươi bóc vỏ giã dập nhẹ hoặc giữ nguyên con nấu cùng bông cải xanh giòn ngọt, tạo nên bát canh trong thanh, nhẹ bụng cho cả gia đình.', 'Dọn canh nóng ra tô, rắc hành lá, ngò rí và chút tiêu xay; ăn kèm cơm trắng và một món mặn như thịt kho tiêu hoặc trứng chiên.', 'Món canh rau xanh ngon nhất khi dùng ngay lúc mới nấu để bông cải giữ màu xanh tươi và độ giòn; nếu bảo quản tủ mát tối đa 24 giờ, chỉ hâm sôi nhanh 1–2 phút trước khi ăn.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Tôm tươi","Bông cải xanh","Thanh mát","Nấu nhanh"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 138, 137.7, 576, 16.4, 5.1, 0.8, 8.6, 2.6, 2.1, 1336, 3.34, '["USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170379","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', 'a5377f7dcb2f463d99683d78e8829e3869a71f9d004b05efcf12e598166590e6', 'd599b2117f91735348416ebb790d7d97520fe921d987fef3fae78490f4be4d42', 4),
('imp-9daae727e7894587', 'canh-ga-bap-cai-ngot', 263, 'Canh gà nấu bắp cải ngọt', 'Thịt đùi gà ta hầm thơm gừng tươi cùng bắp cải giòn ngọt và cà rốt đỏ cam, nước canh trong veo ấm bụng cho bữa cơm gia đình', 'Canh gà nấu bắp cải ngọt mang đến hương vị thanh dịu dễ ăn. Thịt đùi gà chặt miếng ướp nhẹ gừng hành rồi ninh mềm, kết hợp cùng bắp cải và cà rốt tiết ra vị ngọt tự nhiên giúp nước canh trong lành và đậm đà.', 'Dùng canh nóng trong bữa cơm chiều mát hoặc ngày mưa, rắc thêm hành lá và tiêu xay; chấm thịt gà với muối tiêu chanh hoặc nước mắm ớt.', 'Nếu dùng không hết, để nguội hoàn toàn rồi đậy kín cất ngăn mát tối đa 24 giờ; khi hâm lại đun sôi nhẹ 3–4 phút trên lửa vừa để bắp cải không bị nát.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Đùi gà","Bắp cải","Cà rốt","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["chicken","fish"]', 279, 278.5, 1166, 23.8, 15.4, 3.8, 11.3, 3.3, 5.9, 1252, 3.13, '["USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'd59920258983adce2292b97cad4f10595b84d8935d2393fded5c9848d29d5ff9', 'd3797087cc02a3ba321f0e54f6f66d4bc75be8d1e5bce5a2d9e69d262244a5be', 4),
('imp-20123919cd3164a8', 'canh-ca-hoi-ca-chua', 264, 'Canh chua cá hồi cà chua dứa', 'Cá hồi béo mềm không tanh hòa quyện nước canh chua thanh từ cà chua, dứa chín, măng chua và chanh tươi thơm mùi rau ngổ', 'Canh chua cá hồi cà chua dứa kết hợp miếng cá hồi giàu béo mềm ngọt với hương vị canh chua truyền thống gồm dứa thơm, cà chua, măng chua, dọc mùng và rau ngổ. Nước canh đậm đà chua thanh dịu nhẹ, rất hợp cơm ngày nóng.', 'Dọn canh nóng ra tô, rắc hành lá, rau ngổ và vài lát ớt tươi; chấm thịt cá hồi với nước mắm ớt để cảm nhận trọn vị béo ngọt.', 'Canh cá hồi nên ăn hết trong bữa để tránh cá bị bở và dậy mùi tanh; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi nhẹ nước dùng rồi hâm cá ở lửa nhỏ 2 phút.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Món canh","Cá hồi","Canh chua","Hải sản","Bổ dưỡng"]', '["lunch","dinner"]', '["simmer"]', '["fish","salmon"]', 384, 384.3, 1607, 28.3, 20.6, 4.3, 23.4, 4.5, 15, 1403, 3.51, '["NIN VN Doc Mung Ref","USDA FDC 168155","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169958","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175167","VN Herb Ref","VN/Asian Seasoning Powder Avg"]', 'ad6478a303e338eed8299f3ff4e0639300c8930f652802408d35a6469fe9b31b', '5fe30bc37fe646fa8e0042c0a80710186548ca011a076d068587186861faf681', 4),
('imp-d500b08871587628', 'tom-kho-dua-keo', 265, 'Tôm kho dứa sánh keo', 'Tôm tươi bóc vỏ chừa đuôi rim cùng dứa chín cắt lát và nước mắm đường sánh keo, hòa quyện vị chua thanh ngọt mặn chuẩn cơm nhà Nam Bộ', 'Tôm tươi thịt chắc ngọt quyện trong lớp nước sốt dứa chín chua dịu sánh keo bám bóng màu đỏ cam, thơm mùi hành tỏi phi và tiêu xay cay ấm.', 'Trút tôm kho dứa ra đĩa, rưới sốt keo và rắc hành lá cùng tiêu xay; ăn nóng với cơm trắng dẻo và canh rau tập tàng.', 'Ngon nhất khi thưởng thức nóng trong ngày; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo lửa nhỏ.', 'vietnamese', 'mon_kho', 'nam', 'easy', 15, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món kho","Tôm tươi","Dứa chín","Nam Bộ","Đưa cơm"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["crustaceans","fish","shrimp"]', 198, 197.6, 827, 20, 6.2, 0.9, 17.3, 1.5, 12.4, 1274, 3.19, '["USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '9dfd65a718a70b14640cebedce6147684664665850916dfd2c1220e78a12f1e2', '3a141299485836379c70c0698da6f7a5fa755b50e4ac744b1f945b7ed0cfa4b9', 4),
('imp-c7e40140f9ee9591', 'ga-kho-sa-ot-do', 266, 'Gà kho sả ớt đỏ', 'Thịt đùi gà kho sả băm và ớt hiểm đỏ lên màu cánh gián bắt mắt, vị mặn ngọt đậm đà quyện hương thơm cay nồng chuẩn vị Nam Bộ', 'Đùi gà chặt miếng săn chắc thấm đẫm hương thơm nồng của sả băm và ớt hiểm đỏ cay dịu, nước sốt thắng caramel nâu đỏ sánh bóng cực kỳ bắt cơm.', 'Múc gà kho sả ớt ra đĩa sâu lòng, rắc hành lá cắt khúc và tiêu xay; ăn nóng với cơm trắng cùng đĩa rau luộc hoặc dưa leo.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi dùng đun nóng lại trên lửa nhỏ với 1–2 muỗng nước ấm để sốt bóng mượt.', 'vietnamese', 'mon_kho', 'nam', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Gà kho sả ớt","Nam Bộ","Món kho","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["chicken","fish"]', 359, 358.6, 1501, 29.3, 19.4, 4.8, 16.3, 0.7, 8.5, 1326, 3.32, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'eabfdd51857dab2b3c7f650d6a014159dbe1a2d9b7fcb802037152682e7711fa', '97198b0e316540be70733d94c939920b9c1d8f14d2b5d5a269b301c2b9791bd2', 4),
('imp-ebbd704089d9c62a', 'ga-xao-hanh-tay', 267, 'Gà xào hành tây sốt dầu hào', 'Thịt đùi gà săn mềm om thấm sốt dầu hào nước tương đậm vị, kết hợp hành tây giòn ngọt và hương sả tỏi thơm lừng', 'Gà xào hành tây sốt dầu hào có lớp thịt đùi gà mềm mọng không bị khô, thấm đẫm hương sả, hành tím và tỏi phi quyện trong nước sốt mặn ngọt hài hòa cùng những múi hành tây chín tới giòn ngọt thanh.', 'Múc gà xào hành tây ra đĩa sâu lòng cùng phần nước sốt nâu óng, rắc thêm chút tiêu đen xay; dùng nóng kèm cơm trắng hoặc bánh mì đều rất ngon.', 'Cất hộp kín trong ngăn mát tủ lạnh tối đa 2 ngày; khi dùng hâm nóng trên chảo lửa vừa với 1 muỗng canh nước lọc khoảng 3 phút cho gà và sốt nóng đều.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 20, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt gà","Hành tây","Đậm đà","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["chicken","fish","molluscs","soybean","wheat"]', 399, 398.9, 1669, 31.2, 22.9, 5.4, 16.6, 1.7, 7.7, 1543, 3.86, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '58242de04412affdc6fe7a3a3d56fa77c0cbf081e22c2ead18e3f27ff92afb4f', '218863f835479482e8712b3da375608d1c980348acc90ca9272c6458b5724562', 4),
('imp-b7ae5824ff7e6a74', 'su-su-xao-toi', 268, 'Su su xào tỏi', 'Su su non thái lát mỏng giòn sần sật xào lửa lớn cùng tỏi ta đập dập thơm nồng và hành lá xanh mướt', 'Su su xào tỏi là món rau xào thanh mát, mộc mạc mà đưa cơm với những lát su su non giòn ngọt không hề bị nhựa hay nhũn, quyện hương thơm nồng nàn của tỏi đập dập phi vàng và chút vị đậm đà từ nước mắm ngon.', 'Gắp su su xào tỏi ra đĩa khi còn nóng, rắc thêm chút tiêu đen xay; dùng kèm cơm trắng và các món kho mặn.', 'Món rau xào nên ăn ngay trong bữa khi còn nóng để cảm nhận trọn vẹn độ giòn ngọt tự nhiên.', 'vietnamese', 'mon_xao', 'trung', 'easy', 15, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Rau củ","Thanh đạm","Dưới 20 phút","Miền Trung"]', '["lunch","dinner"]', '["stir_fry"]', '["fish"]', 117, 117, 489, 2.5, 7.3, 1.1, 12.8, 3.8, 3.8, 894, 2.24, '["USDA FDC 169230","USDA FDC 169990","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'd0eaf2f55f7a75f6db36fd46dc144e184959e027614892eb64c71b96b3cdbd1f', 'f00fefbae95ff59358f94768a9b9619056906ff5f528fec27a7c0a4ff6b1e7a3', 4),
('imp-30c2038c8737538c', 'bo-xao-nam-dui', 269, 'Bò xào nấm đùi gà', 'Thịt thăn bò mềm mọng xào lửa lớn cùng nấm đùi gà giòn sần sật thấm đẫm nước thịt và sốt dầu hào đậm đà', 'Bò xào nấm đùi gà là sự kết hợp tuyệt vời giữa từng lát thịt bò thăn mềm ngọt và những miếng nấm đùi gà giòn dai sần sật, hút trọn vị ngọt của thịt bò cùng hương thơm dầu hào, tỏi phi và tiêu đen.', 'Gắp bò xào nấm đùi gà ra đĩa nóng, rắc ngò rí và tiêu xay lên trên; dùng ngay với cơm trắng và chấm kèm nước tương ớt lát.', 'Món xào ngon nhất khi dùng nóng; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hãy đảo nóng nhanh trên chảo lửa lớn khoảng 1 phút trước khi ăn.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 18, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Nấm","Đậm đà","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","molluscs","soybean","wheat"]', 304, 303.9, 1272, 22.8, 20, 5.3, 9.5, 2.4, 1.8, 981, 2.45, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC Monosodium Glutamate","VN/Asian Seasoning Powder Avg"]', '5530cbf228a59a7c54bf38970eb9cefa4d17960c91a2d723447b2e97bc410a28', 'a6cc72fa42c21de964498c549da3d7c88b7d1bedae4fb75835f335f64d247fa1', 4),
('imp-019bbf517408a529', 'ca-chien-sot-ca-chua', 270, 'Cá chiên sốt cà chua', 'Cá thu phi lê chiên vàng săn chắc om trong sốt cà chua chín nhuyễn đậm đà mặn ngọt đưa cơm', 'Cá chiên sốt cà chua là món ăn gia đình quen thuộc với khúc cá thịt trắng béo ngọt được chiên vàng đều hai mặt giữ độ săn chắc, sau đó rim nhỏ lửa trong phần sốt cà chua chín đỏ sánh mịn quyện hương thơm hành tím, tỏi và dầu hào.', 'Bày từng khúc cá ra đĩa sâu lòng, rưới phần sốt cà chua óng mượt cùng hành lá và tiêu xay lên trên, ăn nóng kèm cơm trắng dẻo và dưa leo thái lát.', 'Có thể bảo quản hộp kín trong ngăn mát tủ lạnh tới 2 ngày; khi ăn chỉ cần hâm lại trên chảo lửa nhỏ khoảng 5 phút có thêm 1–2 muỗng canh nước lọc để sốt mềm sánh trở lại.', 'vietnamese', 'mon_chien', 'nam', 'medium', 15, 22, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Cá thu","Sốt cà chua","Nam Bộ","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["fish","molluscs","soybean","wheat"]', 263, 263.1, 1101, 27.4, 12.7, 2.2, 9.8, 1.6, 6.6, 1144, 2.86, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175148"]', 'a5612ada9305bbc10be9301e59143c24ffcfb4f5ac9c2133e41091f43a5a0aed', 'f45b338d98afb78e1d8b1fbc90983188b11cd15e265ed125194be25e26ed78a7', 4),
('imp-d7836b7d1a4d90b3', 'nam-chien-gion', 271, 'Nấm đùi gà chiên giòn', 'Nấm đùi gà xé dải chần ráo tẩm trứng và bột năng chiên hai lần giòn rụm, thơm lá húng quế chiên', 'Nấm đùi gà chiên giòn là món ăn vặt lẫn món mặn đưa cơm rất bắt miệng. Thân nấm đùi gà được chần sơ vắt ráo để giữ độ dai ngọt tự nhiên, nhúng qua trứng gà rồi áo bột năng khô chiên hai lửa cùng lá húng quế, tạo lớp vỏ giòn tan mà bên trong vẫn mềm mọng.', 'Xếp nấm chiên giòn và lá húng quế chiên ra đĩa, rắc thêm chút hành lá thái nhỏ nếu thích, dùng nóng ngay và chấm kèm tương ớt cay ngọt.', 'Món này ngon nhất khi ăn nóng ngay sau khi chiên lần hai; tránh để qua đêm trong tủ lạnh vì lớp bột năng sẽ hút ẩm và mất độ giòn.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Nấm đùi gà","Giòn rụm","Ăn vặt","Trẻ em thích"]', '["lunch","dinner"]', '["deep_fry","boil"]', '["egg"]', 313, 313.3, 1311, 5.5, 18.5, 2.9, 33.7, 2.9, 3.7, 756, 1.89, '["USDA FDC 168580","USDA FDC 169717","USDA FDC 170005","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC Sriracha Ref"]', 'd9c60c3abd47b2413b458bc805c0d44033f28f98e29b59b8106b2753209803a6', '392567b19f37770001c4123b0d6338f7210add82bd02805b2ef6ed719ed210fe', 4),
('imp-9d527dacd46efc67', 'dau-phu-chien-sa', 272, 'Đậu phụ chiên sả ớt chay', 'Đậu phụ chiên vàng giòn rụm xóc đều sả băm tỏi ớt phi thơm lừng, đậm vị nước tương ăn kèm dưa leo', 'Đậu phụ chiên sả ớt chay là món ăn dân dã nhưng cực kỳ gây nghiện nhờ sự kết hợp giữa miếng đậu phụ chiên vỏ giòn ruột béo và lớp sả ớt phi thơm giòn đậm vị nước tương, hạt nêm chay. Món thực hiện nhanh gọn, phù hợp cả bữa cơm chay lẫn mặn.', 'Xếp đậu phụ chiên sả ớt vào lòng đĩa có viền dưa leo thái lát mỏng, rắc ngò rí lên trên và dọn nóng cùng cơm trắng, chấm kèm nước tương ớt thái lát.', 'Ngon nhất khi dùng nóng ngay lúc lớp sả phi và vỏ đậu còn giòn; nếu còn dư có thể cất ngăn mát 24 giờ và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4 phút.', 'vietnamese', 'mon_chien', 'nam', 'easy', 12, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Món chay","Đậu phụ","Sả ớt","Nam Bộ"]', '["lunch","dinner"]', '["deep_fry","pan_fry"]', '["soybean","wheat"]', 311, 310.7, 1300, 19.2, 20.4, 3, 19.1, 2.6, 3.6, 1062, 2.65, '["USDA FDC 168409","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', 'c44b20a07f18b2eff2012e54930d7c60c3170464e5b8047555538a2857e19cbc', 'c7c9d348dbad1219be862c1936cd1b931ebcc74c8d8f4be58a1ecf189c2ff876', 4),
('imp-236e3b84d403909e', 'ga-luoc-hanh-la', 273, 'Đùi gà luộc hành lá da vàng giòn', 'Đùi gà tơ luộc chín mềm mọng nước bằng cách ủ nhiệt, da căng bóng vàng ươm ăn kèm muối tiêu chanh lá chanh', 'Đùi gà góc tư luộc vừa sôi rồi ủ chín từ từ giúp thịt mềm ngọt giữ trọn nước, không bị nứt rách da hay đỏ xương; sốc lạnh nhanh cho lớp da giòn sần sật ánh vàng hấp dẫn.', 'Chặt đùi gà thành miếng vừa ăn xếp ra đĩa, rắc hành lá thái nhỏ và lá chanh thái chỉ; dọn kèm chén muối tiêu chanh ớt và tận dụng nước luộc nấu canh hoặc cháo.', 'Gà luộc bọc kín bảo quản ngăn mát tối đa 2 ngày; khi ăn có thể dùng nguội chặt lát hoặc hấp lại 5 phút cho ấm nóng.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Món luộc","Gà ta","Giản dị","Cơm nhà","Thanh đạm"]', '["lunch","dinner"]', '["boil"]', '["chicken"]', 381, 380.8, 1594, 40.3, 21.7, 6, 4.5, 1.2, 1, 1214, 3.04, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 169231","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 172231","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'b415115cee7f8e2a289b40da34cfa3686886fd43b03a650a1c4a390855ac7c0f', '8cb5f24779f43fdc212667a83a14f891d2dcb8e5709cd7f785d2d8c7ec53bcf0', 4),
('imp-df7571988423623f', 'muc-hap-sa-ot', 274, 'Mực tươi hấp sả ớt kiểu miền Trung', 'Mực tươi ướp nước mắm tiêu đường hấp nhanh cùng sả đập dập và ớt hiểm, chấm nước mắm chanh cay thơm đậm vị', 'Mực tươi làm sạch nguyên con hoặc cắt khoanh, ướp nhẹ nước mắm đường tiêu rồi hấp lửa lớn cùng sả đập dập, gừng, ớt hiểm và hành lá; thịt mực trắng giòn ngọt lịm chấm nước mắm chanh ớt đúng điệu miền Trung.', 'Gắp mực hấp sả ớt ra đĩa, chan nhẹ phần nước ngọt tiết ra khi hấp; dùng nóng chấm nước mắm chanh tiêu ớt kèm cơm trắng hoặc bánh tráng cuốn rau sống.', 'Mực hấp ngon nhất khi dùng nóng ngay sau khi chín để giữ độ giòn. Nếu còn dư, bảo quản ngăn mát tối đa 24 giờ và hấp lại nhanh 2 phút.', 'vietnamese', 'mon_hap_luoc', 'trung', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Mực","Sả","Miền Trung","Dưới 20 phút"]', '["lunch","dinner"]', '["steam"]', '["fish","molluscs","squid"]', 161, 161, 674, 23.2, 2.1, 0.5, 11.6, 0.8, 3.7, 1008, 2.52, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 172185","USDA FDC 173647","USDA FDC 174223"]', '56f89c617271ff422afd716b7ae28f920c6a84307c3da81dba72399a46d2108a', 'bcfd87168444f192ec189d624a8f668d833bdb623861d3f44b8a72481809de10', 4),
('imp-2b88b3e83b941e80', 'goi-su-su-tom', 275, 'Gỏi su su tôm giòn mát', 'Su su bào sợi giòn sần sật trộn tôm luộc ngọt thịt, cà rốt, rau răm và ngò rí trong nước mắm chanh tỏi ớt chua ngọt thanh sạch', 'Gỏi su su tôm giòn mát mang vị thanh sạch lạ miệng với từng sợi su su và cà rốt ướp muối vắt ráo giòn sần sật, kết hợp tôm tươi luộc chín đỏ au chẻ đôi, rau răm thơm nồng, hành tím phi giòn và lạc rang bùi béo.', 'Bày gỏi ra đĩa, rắc đậu phộng rang giã dập, hành phi giòn và ngò rí lên trên; dọn ăn ngay kèm bánh phồng tôm.', 'Nên vắt thật ráo su su trước khi trộn và ăn ngay trong bữa; nếu chuẩn bị trước, bảo quản su su cà rốt vắt ráo, tôm luộc và nước trộn riêng trong ngăn mát tối đa 12 giờ.', 'vietnamese', 'mon_cuon_nom', 'trung', 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi su su","Tôm tươi","Thanh mát","Khai vị","Miền Trung"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","fish","peanut","shrimp"]', 347, 347, 1451, 19.5, 12.3, 1.7, 43.7, 5.7, 16.4, 1530, 3.82, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 169990","USDA FDC 169997","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN Banh Da Ref","VN Rau Ram Ref"]', 'fad96a7a670b68958e530dddf5fc3e761549a98c23274d1f9b058bc2ca615228', '1a5264f3e5b9709011baec7adcc0f49a6df72946b253065073ae38e534fdcbc4', 4),
('imp-0b34a73de8ccab71', 'goi-dau-phu-dua-leo', 276, 'Gỏi đậu phụ dưa leo chay thanh mát', 'Đậu phụ chiên vàng giòn thái sợi trộn dưa leo bỏ ruột giòn mát, cà rốt, rau răm, húng quế và đậu phộng rang trong nước mắm chay chanh tỏi ớt', 'Gỏi đậu phụ dưa leo là món khai vị chay thanh đạm mà đậm vị với từng miếng đậu phụ chiên vàng giòn bên ngoài mềm béo bên trong, quyện cùng dưa leo và cà rốt bóp muối vắt khô giòn sần sật, rau thơm và đậu phộng rang bùi thơm.', 'Bày gỏi ra đĩa, rắc hành lá cắt nhỏ và phần đậu phộng rang giã dập còn lại lên mặt; ăn kèm bánh đa nướng hoặc bánh phồng chay giòn rụm.', 'Đậu phụ chiên nên trộn ngay trước bữa ăn để giữ lớp vỏ giòn; bảo quản riêng dưa leo cà rốt đã vắt ráo và nước mắm chay trong ngăn mát tủ lạnh tối đa 12 giờ.', 'vietnamese', 'mon_cuon_nom', 'nam', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi chay","Đậu phụ","Dưa leo","Thanh đạm","Mát lành"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["peanut","soybean"]', 312, 312.3, 1307, 18.3, 20.3, 2.8, 21, 4.3, 12, 923, 2.31, '["USDA FDC 168155","USDA FDC 168409","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 172232","USDA FDC 172430","USDA FDC 172475","USDA FDC 173468","VN Rau Ram Ref","Vegetarian Fish Sauce Ref"]', '27be4748d81d03c872673d58e7fd65ac82255ea1daad0f4cfaa7418b1b2e7f91', '066f6f2866b780544e0dff65718ff85a2806c0a0d6394b4e5c6a83e707605173', 4),
('imp-0ea0e53318af9de9', 'bun-bo-nam-bo-tron', 277, 'Bún bò Nam Bộ trộn', 'Thịt bò thăn ướp sả tỏi xì dầu xào nhanh trên lửa lớn, trộn cùng bún tươi, rau sống mát lành, hành phi giòn, đậu phộng rang và nước mắm chua ngọt', 'Tô bún bò Nam Bộ trộn hài hòa giữa vị thịt bò xào sả tỏi mềm mọng nóng hổi, bún tươi thanh mát, rau thơm, giá đỗ giòn sần sật cùng hành phi thơm lừng, đậu phộng rang bùi béo và nước mắm chua ngọt.', 'Xếp xà lách, rau thơm, giá đỗ, dưa leo, cà rốt bào và bún tươi vào tô, đặt thịt bò xào hành tây nóng lên trên, rắc đậu phộng rang, hành phi, hành lá rồi chan nước mắm chua ngọt trộn đều.', 'Có thể chuẩn bị sẵn hành phi, đậu phộng rang và nước mắm pha trước 1–2 ngày; thịt bò nên ướp trước khi ăn và xào nhanh tay ngay trước lúc dọn để giữ độ mềm ngọt.', 'vietnamese', 'mon_bun_pho', 'nam', 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Bún bò Nam Bộ","Món trộn","Thịt bò xào","Thanh mát"]', '["lunch","dinner"]', '["stir_fry","toss_mix","assemble"]', '["beef","fish","molluscs","peanut","soybean","wheat"]', 622, 622.3, 2604, 32.6, 24.6, 6.1, 71.5, 6.8, 13.6, 1753, 4.38, '["NIN VN Fresh Bun Ref","USDA FDC 168155","USDA FDC 168409","USDA FDC 168573","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 172430","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'cf9d8d7be436332194bc029fee56f61dd9d02dfc28cd50046fc866a53f7ff532', '9e93926e735e7ba7654f8f4b275275bfb46bbf3d80f25a40f01a1c32fa50cfcd', 4),
('imp-1fa2a5a65ec5a26d', 'bun-rieu-cua-dau', 278, 'Bún riêu cua đậu', 'Riêu cua đồng kết tảng béo ngậy hòa nước dùng cà chua giấm bỗng chua thanh, ăn kèm đậu phụ chiên vàng và đĩa rau sống chẻ sợi giòn mát', 'Tô bún riêu cua đậu thanh thuần vị quê nhà nổi bật với tảng riêu cua đồng xốp béo, phần nước gạch cua phi hành đỏ óng cùng cà chua, đậu phụ chiên giòn và hương thơm dịu của giấm bỗng.', 'Chia bún tươi ra tô, gắp tảng riêu cua, đậu phụ chiên và cà chua lên trên, chan nước dùng nóng hổi, rắc hành lá rồi dọn kèm rau muống chẻ, hoa chuối bào, kinh giới, chanh, ớt và mắm tôm.', 'Nước riêu và đậu phụ chiên bảo quản ngăn mát tối đa 24 giờ; khi hâm lại giữ lửa vừa tránh khuấy mạnh để không vỡ tảng riêu, sau đó chan lên bún mới trụng.', 'vietnamese', 'mon_bun_pho', 'bac', 'hard', 30, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Bún riêu","Cua đồng","Đậu phụ rán","Ẩm thực miền Bắc"]', '["breakfast","lunch","dinner"]', '["simmer","pan_fry","boil","assemble"]', '["crab","crustaceans","fish","shrimp","soybean"]', 525, 525.3, 2197, 29.8, 17, 2.6, 66.5, 8.2, 7, 2218, 5.55, '["Annatto Infused Oil Ref","Asian Shrimp Paste Ref","NIN VN Fresh Bun Ref","SE Asian Banana Blossom Ref","USDA FDC 168155","USDA FDC 169247","USDA FDC 169378","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172475","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 174208","VN/Asian Seasoning Powder Avg"]', '0ed5aa6fcf26c963d9985af4ebc519381b0523962aa5a61d157a272e30b12468', 'afbc8f9420c7573f05ed755bfb3bdcb4e1e9b801b7144805a5abc50597605231', 4),
('imp-ff6d8fe6659e4976', 'bun-cha-ha-noi', 279, 'Bún chả Hà Nội', 'Thịt ba chỉ thái miếng và chả băm viên ướp nước cốt sả hành nướng vàng ươm trong lò, ăn kèm bún tươi, dưa góp giòn và bát nước mắm ấm', 'Bún chả Hà Nội chế biến gọn gàng tại nhà với chả miếng ba chỉ và chả viên nạc vai ướp nước hàng, mắm tôm, cốt sả hành, nướng lò vàng bóng không khô, hòa quyện cùng nước chấm ấm và dưa góp đu đủ cà rốt.', 'Thả chả miếng và chả viên nướng nóng vào bát nước mắm ấm cùng dưa góp đu đủ cà rốt, ăn kèm bún tươi sợi nhỏ và đĩa rau sống kinh giới, tía tô, xà lách.', 'Chả đã nướng có thể bảo quản ngăn mát tối đa 2 ngày; khi ăn nướng lại ở 180°C trong 4 phút rồi thả vào bát nước chấm đun ấm.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 35, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Bún chả","Hà Nội","Món nướng lò","Bữa trưa"]', '["lunch","dinner"]', '["grill_roast","toss_mix","assemble"]', '["crustaceans","fish","pork","shrimp"]', 801, 800.7, 3350, 22.7, 48.3, 16.9, 69.9, 5.2, 17.7, 2016, 5.04, '["Asian Shrimp Paste Ref","MEXT Shiso Ref","NIN VN Fresh Bun Ref","USDA FDC 167820","USDA FDC 167902","USDA FDC 168155","USDA FDC 168573","USDA FDC 168833","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Green Papaya Ref","VN/Asian Seasoning Powder Avg"]', '7e3421425f8c6bc68e4ce3d7c4c66819cbcade652a4c1c2a3a48b6d34ba7320c', '3c7bc5288635673745ee143d9d17ff1701f89ff67b523fdc710699a63d6d4e9f', 4),
('imp-675a6c1cea0b604e', 'com-rang-chay-nam-dau', 280, 'Cơm rang chay nấm đậu phụ rau củ', 'Hạt cơm rang tơi ráo quyện đều nấm đùi gà, đậu phụ chiên hạt lựu, cà rốt giòn ngọt và nước tương thơm lừng', 'Đĩa cơm rang chay đầy đủ dưỡng chất và màu sắc bắt mắt với từng hạt cơm nguội rang tơi ráo bóng nhẹ, hòa quyện cùng nấm đùi gà dai ngọt, đậu phụ cắt hạt lựu béo mềm, cà rốt giòn tươi và mùi thơm quyến rũ của tỏi phi, hành lá.', 'Múc cơm rang nóng ra đĩa, rắc thêm hành lá và tiêu đen xay; ăn kèm dưa leo thái lát và chén nước tương ớt cắt khoanh.', 'Món ăn ngon nhất khi thưởng thức nóng ngay; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hãy rang nóng lại trên chảo khô lửa vừa 3–4 phút cho hạt cơm tơi lại.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Cơm rang","Đậu phụ","Nấm đùi gà","Nhanh gọn"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["soybean","wheat"]', 438, 437.9, 1832, 16.6, 13.9, 2.1, 63.9, 4.3, 4.3, 1174, 2.94, '["USDA FDC 168580","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '5cd1edeb2d0fd54275023965b3d144843d7d01eadbfca7ae389ea06cb83b8afb', '6562f9f2f3939ab489e19ad55a212bd1dad7f524e96d9710c8b5ce23ea675015', 4),
('imp-4dbcf05ec1f88763', 'nam-xao-sa-ot-chay', 281, 'Nấm đùi gà xào sả ớt chay', 'Nấm đùi gà thái lát dày xào săn vàng cạnh cùng sả băm, ớt hiểm cay nồng, nước tương đậm đà và mè rang thơm bùi', 'Món xào chay đậm đà đưa cơm với từng lát nấm đùi gà giòn dai thấm đẫm nước tương mặn ngọt, phủ đầy sả phi thơm lừng, ớt hiểm cay ấm cùng chút mè trắng rang bùi béo và hành lá xanh tươi.', 'Gắp nấm đùi gà xào sả ớt ra đĩa, rắc mè trắng rang và ngò rí lên trên; dùng nóng cùng cơm trắng dẻo thơm.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2–3 ngày vì nấm xào khô sả ớt càng để càng thấm vị; hâm nóng lại trên chảo 2–3 phút trước khi ăn.', 'vietnamese', 'mon_chay', 'nam', 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Món chay","Nam Bộ","Nấm đùi gà","Xào sả ớt","Đậm vị"]', '["lunch","dinner"]', '["stir_fry"]', '["sesame","soybean","wheat"]', 148, 147.8, 618, 5.9, 7.5, 1.1, 18.1, 3.3, 5.7, 1124, 2.81, '["USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","USDA FDC Monosodium Glutamate","Vegetarian Seasoning Powder Ref"]', '48d9bd7223c1d2c2db1e74a5440af04903061f99e9ef47a55266a5c19b5d6438', '6a413b7030fe5b27b5e46fd405e83e67ba4c1af488febcea9ef38491908121e7', 4),
('imp-b88c09328fa3f33a', 'goi-cuon-chay-nam-dau', 282, 'Gỏi cuốn chay nấm đậu phụ', 'Bánh tráng cuốn chặt tay nhân bún tươi, đậu phụ chiên tẩm nước tương, nấm đùi gà xào, rau sống giòn mát và nước chấm chua ngọt', 'Những cuốn gỏi chay tròn đầy thanh mát với lớp bánh tráng dẻo mỏng ôm trọn nhân đậu phụ chiên tẩm nước tương đậm vị, nấm đùi gà xào dai ngọt, bún gạo tươi, cà rốt, dưa leo, giá đỗ và rau thơm giòn tươi, chấm cùng nước tương chanh ớt mè rang.', 'Xếp gỏi cuốn ra đĩa, có thể cắt đôi chéo để lộ phần nhân nhiều màu sắc hấp dẫn; dọn ăn ngay kèm chén nước chấm nước tương chua cay rắc mè trắng rang.', 'Gỏi cuốn ngon nhất khi dùng ngay sau khi cuốn; nếu chưa ăn ngay cần bọc màng bọc thực phẩm từng cuốn để bánh tráng không bị khô cứng và dùng trong vòng 4 giờ.', 'vietnamese', 'mon_chay', 'nam', 'easy', 25, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Món chay","Gỏi cuốn","Nam Bộ","Mát lành","Bánh tráng"]', '["breakfast","lunch","dinner"]', '["pan_fry","stir_fry","boil","assemble"]', '["sesame","soybean","wheat"]', 391, 391.4, 1638, 16.7, 11.7, 1.7, 60, 5.6, 9.5, 1254, 3.14, '["NIN VN Fresh Bun Ref","USDA FDC 168155","USDA FDC 168409","USDA FDC 168580","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 169994","USDA FDC 170150","USDA FDC 170393","USDA FDC 171319","USDA FDC 171413","USDA FDC 172232","USDA FDC 172238","USDA FDC 172475","USDA FDC 173468","USDA FDC 174277","USDA FDC Rice Paper Ref","Vegetarian Seasoning Powder Ref"]', '9d5c1f888ba2c790ca92db94015eb8766aaff98f7795f4a08eac9bdbce67cf49', 'a379b7a19540c9204b4d4bcf0eb05f45a759b2c3418b5043d3d4febd97a81f45', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-66711b78b6c12643', 'com-tam-suon-nuong', 283, 'Cơm tấm sườn nướng', 'Sườn cốt lết ướp mật ong sữa tươi nướng xém thơm bên cơm tấm dẻo, trứng ốp la, mỡ hành và đồ chua nước mắm kẹo', 'Đĩa cơm tấm sườn nướng chuẩn vị Sài Gòn với miếng sườn cốt lết ướp sữa tươi mật ong nướng vàng ươm mềm mọng, hạt cơm tấm tơi dẻo phủ mỡ hành béo xanh, trứng gà ốp la lòng đào, đồ chua củ cải cà rốt giòn thanh và chén nước mắm chua ngọt kẹo.', 'Xếp cơm tấm ra đĩa lớn, đặt sườn nướng, trứng ốp la và đồ chua bên cạnh, rưới mỡ hành béo thơm lên cơm và sườn rồi ăn nóng kèm chén nước mắm tỏi ớt chua ngọt.', 'Sườn ướp có thể bảo quản ngăn mát qua đêm để nướng sáng hôm sau càng thấm vị; cơm tấm và sườn chín giữ ngăn mát tối đa 2 ngày, hâm nóng sườn bằng nồi chiên không dầu 170°C trong 4 phút.', 'vietnamese', 'mon_nhanh_sang', 'nam', 'medium', 25, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Cơm tấm","Sườn nướng","Nam Bộ","Quốc dân","Mỡ hành"]', '["breakfast","lunch","dinner"]', '["grill_roast","pan_fry","boil"]', '["egg","fish","milk","molluscs","pork","soybean","wheat"]', 725, 724.8, 3032, 41.5, 20.7, 5.7, 90.1, 2.8, 21.9, 1979, 4.95, '["USDA FDC 167827","USDA FDC 168452","USDA FDC 169230","USDA FDC 169640","USDA FDC 169655","USDA FDC 169756","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647"]', '60cc8450baebff5124d0d21e275acc44364270700cd0a4b6d71305b05a505090', '1a33ffcfd7217cd652016f46c7cd1e2f288e0bdb66b3640110ad4129cbd9869d', 4),
('imp-6a3a83f38e6d3f9c', 'chao-bo-gung', 284, 'Cháo bò gừng', 'Cháo gạo rang nấu sánh mịn cùng thịt bò thăn thái mỏng chín tới, gừng sợi ấm nồng và hành lá tía tô', 'Tô cháo bò gừng nóng hổi thơm lừng với hạt gạo tẻ kết hợp gạo nếp rang thơm nở bung sánh mịn, lát thịt bò thăn mềm ngọt chín tái tới ngay trong cháo sôi cùng gừng tươi thái chỉ, hành lá và lá tía tô giải cảm ấm người.', 'Chan cháo đang sôi sục lên bát thịt bò ướp gừng tỏi đã lót sẵn tía tô và hành lá, rắc tiêu đen xay rồi dùng nóng ngay.', 'Nên ăn nóng ngay sau khi chan cháo để thịt bò mềm ngọt không bị dai. Phần cháo trắng nấu sẵn có thể bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi lại cháo rồi mới thả thịt bò ướp vào.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 30, 4, '/frigo/illustrations/delicious-meal.png', '["Cháo bò","Gừng ấm","Ăn sáng","Bổ dưỡng","Ấm bụng"]', '["breakfast","dinner"]', '["boil","simmer"]', '["beef","fish"]', 379, 379.4, 1588, 20.2, 11.5, 3.7, 47.1, 1.8, 1.3, 1250, 3.13, '["MEXT Shiso Ref","USDA FDC 168881","USDA FDC 169230","USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170187","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '958040d9cdab014541f274242c7b737fe2145bf545c1fe7a2918ae239964d027', '40d5175650b3d9fdee9e671597138882ebb8afd1bd01b6e03a37dc672488c8b4', 4),
('imp-b1dcb812f8671a49', 'banh-trang-nuong-pho-mai', 285, 'Bánh tráng nướng phô mai', 'Bánh tráng gạo nướng chảo giòn rụm phủ trứng gà, phô mai mozzarella kéo sợi, xúc xích và hành phi thơm lừng', 'Món bánh tráng nướng phô mai kiểu Đà Lạt hấp dẫn ngay trên chảo chống dính với đế bánh tráng gạo giòn tan, lớp trứng gà hành lá béo thơm phủ đầy phô mai mozzarella tan chảy kéo sợi, xúc xích thái lát, hành tím phi và tương ớt mayonnaise.', 'Gấp đôi chiếc bánh tráng nướng giòn rụm hoặc cắt thành miếng tam giác bằng kéo, thưởng thức ngay khi phô mai còn kéo sợi nóng hổi.', 'Bánh tráng nướng ngon nhất khi ăn ngay sau khi nướng để đế giữ độ giòn rụm. Không nên bảo quản bánh đã nướng quá lâu vì trứng và sốt sẽ làm mềm đế bánh.', 'vietnamese', 'mon_nhanh_sang', 'nam', 'easy', 8, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Bánh tráng nướng","Phô mai","Nam Bộ","Ăn vặt","Dưới 20 phút"]', '["breakfast","lunch"]', '["pan_fry","grill_roast"]', '["egg","milk","pork"]', 362, 361.6, 1513, 16, 23.2, 7.5, 21.9, 0.8, 4, 847, 2.12, '["USDA / Chinese Sausage Ref","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170845","USDA FDC 171009","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC Rice Paper Ref","USDA FDC Sriracha Ref"]', '67a3a8bb4c245ac92bdf1aeb030129af27a767dffa5b30e606675249a507777b', '2fcdc1bb673ca9bd537b22f4f8857f8f58d7b187c7337d54e83cf798694e644d', 4),
('imp-8f24a253602fc9be', 'lau-ca-chua-dua', 286, 'Lẩu cá chua dứa miền Tây', 'Cá diêu hồng tươi săn ngọt nấu trong nước lẩu chua thanh từ dứa chín, cà chua và nước cốt chanh, thơm nồng sả gừng và rau ngổ', 'Lẩu cá chua dứa miền Tây mang hương vị thanh mát đặc trưng vùng sông nước. Cá diêu hồng tươi cắt khúc nấu chín vừa tới giữ thịt trắng ngọt săn chắc, hòa quyện nước lẩu chua dịu từ dứa chín, cà chua và chanh tươi, thơm lừng mùi sả, gừng, ngò gai và rau ngổ.', 'Bày đĩa cá diêu hồng, nấm đùi gà, rau muống, dọc mùng và bún tươi quanh nồi lẩu sôi; nhúng cá và rau ăn nóng, chấm thịt cá với chén nước mắm gừng ớt mặn.', 'Món lẩu cá nên dùng hết trong bữa để thịt cá không bị tanh hay bở; phần nước lẩu chưa nhúng cá có thể bảo quản ngăn mát tối đa 24 giờ và đun sôi lại 3 phút.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 20, 40, 5, '/frigo/illustrations/delicious-meal.png', '["Món lẩu","Cá diêu hồng","Dứa chín","Miền Tây","Chua ngọt"]', '["lunch","dinner"]', '["simmer","boil"]', '["fish"]', 453, 453, 1894, 38.2, 10.4, 2, 53.3, 5.6, 11.9, 1789, 4.47, '["Chili Oil / Satay Ref","NIN VN Doc Mung Ref","NIN VN Fresh Rice Noodle Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169378","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","VN Culinary Herb Ref","VN Herb Ref","VN/Asian Seasoning Powder Avg"]', '22a53d21e7539c4707152b453f5b656b0fcf21ea4be56413425dd97023bfa3c5', '401f027f0997c41a335be332df973a1809e67e39e2b475a5c98d620e9d121c0d', 4),
('imp-cd86ce166f002f60', 'suon-ham-tuong-dau', 287, 'Sườn non hầm tương đậu đen', 'Sườn non áp chảo vàng cạnh hầm liu riu cùng đậu tương đen lên men tàu xì, xì dầu và gừng tỏi cho đến khi mềm rục tách xương', 'Món hầm truyền thống Trung Hoa nổi bật với hương vị bùi mặn đặc trưng của đậu tương đen lên men (tàu xì) quyện cùng xì dầu, rượu Thiệu Hưng và gừng tỏi thơm nồng, thấm sâu vào từng miếng sườn non mềm rục.', 'Múc sườn hầm cùng nước sốt đen bóng sánh đặc ra đĩa sâu lòng, rắc hành lá xanh thái nhỏ và ăn nóng với cơm trắng dẻo.', 'Để nguội hoàn toàn và bảo quản hộp kín trong ngăn mát tối đa 3 ngày; khi ăn hâm lại trên lửa nhỏ với 2 muỗng canh nước lọc để sốt không bị khét.', 'chinese', 'mon_kho', NULL, 'medium', 15, 65, 4, '/frigo/illustrations/delicious-meal.png', '["Món hầm","Sườn non","Tàu xì","Đậm đà","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","braise","simmer"]', '["pork","soybean","wheat"]', 450, 450.3, 1884, 22.6, 35.7, 12, 6.9, 0.8, 2.9, 1242, 3.11, '["Dark Soy Sauce Label Ref","Douchi Reference","Shaoxing Wine Ref","USDA FDC 167861","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '2ad9f16afa492acfbdf199db9e6ccabeb271bc27a7a5351ea2bce2d023c6ae38', '578407ad83eb01054e0969f099e3a8ef8a4187c26b27934546fd944520418774', 4),
('imp-3e8e08fb584de7f3', 'bo-ham-gung-dam', 288, 'Thịt bò hầm gừng cà rốt đậm vị', 'Nạm bò mềm rục thấm đẫm hương gừng ấm, hồi quế, tương đậu cay và xì dầu đặc, quyện cùng cà rốt ngọt thanh sánh mịn', 'Món bò hầm chuẩn vị gia đình Trung Hoa ấm nồng mùi gừng tươi thái lát, hoa hồi và lá nguyệt quế, hòa quyện vị cay nhẹ từ tương đậu bản Tứ Xuyên cùng nước dùng bò sánh đậm ôm trọn từng miếng thịt bò mềm tan và cà rốt ngọt bùi.', 'Múc thịt bò hầm và cà rốt ra tô sâu lòng, chan nước sốt nâu đỏ sánh mịn, rắc hành lá thái nhỏ và ăn nóng cùng cơm trắng hoặc bánh mì.', 'Món hầm để qua đêm trong ngăn mát tủ lạnh sẽ càng thấm gia vị, bảo quản kín tối đa 3 ngày; hâm sôi kỹ lại trên lửa nhỏ trước khi dùng.', 'chinese', 'mon_kho', NULL, 'medium', 20, 135, 4, '/frigo/illustrations/delicious-meal.png', '["Thịt bò","Món hầm","Gừng ấm","Mùa lạnh","Đậm đà"]', '["lunch","dinner"]', '["boil","pan_fry","braise","simmer"]', '["beef","soybean","wheat"]', 618, 618.4, 2588, 46.7, 38.3, 14.8, 19.2, 2.6, 8.8, 1563, 3.91, '["Dark Soy Sauce Label Ref","Pixian Doubanjiang Ref","Shaoxing Wine Ref","USDA FDC 169076","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170198","USDA FDC 170393","USDA FDC 170917","USDA FDC 171316","USDA FDC 171413","USDA FDC 171593","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC Sucrose Ref"]', '3e3d2ec42347c2113274bcb2968f1c484f4f2b50edb4342f109b2359747cd77b', '51aed921a28a41a1f840bea2596fbbb64701d152d2efe0ce537275aeb15a50f8', 4),
('imp-abcc9b72400680cf', 'trung-cuon-hanh-la-trung', 289, 'Trứng cuộn hành lá áp chảo kiểu Trung', 'Những cuộn trứng mỏng mềm xốp mịn thơm lừng hành lá và tiêu trắng, rưới nhẹ xì dầu nhạt đậm đà cho bữa sáng hoặc món khai vị', 'Món trứng cuộn hành lá đơn giản nhưng tinh tế của bếp Hoa, tráng từng lớp mỏng trên chảo chống dính với chút bột bắp và rượu Thiệu Hưng giúp trứng xốp mềm ẩm mượt, cuộn tròn cắt khúc gọn đẹp rồi rưới xì dầu nhạt thơm dịu.', 'Xếp các khúc trứng cuộn ra đĩa, rưới đều xì dầu nhạt lên mặt hoặc chấm riêng, ăn nóng với cơm trắng hoặc cháo trắng rất bắt vị.', 'Món ngon nhất khi thưởng thức nóng ngay sau khi cuộn; nếu dư, bọc kín để ngăn mát tối đa 24 giờ và áp chảo lại 1 phút trên lửa nhỏ.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 10, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Trứng cuộn","Nhanh gọn","Khai vị","Bữa sáng","Trung Hoa"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","soybean","wheat"]', 271, 270.6, 1132, 14.9, 20.3, 4.9, 5.5, 0.7, 1.9, 1439, 3.6, '["Shaoxing Wine Ref","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 170933","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '943b96147f67772de3ee35f57398dfc50e1879b102de1d654bbc464785b91fd9', '0ae67a8d69b3b9edd1741d99006f9d949343067d3d683cfc07468b58d9f482f5', 4),
('imp-26359a897d4be366', 'sup-tom-nam-trung', 290, 'Súp tôm nấm đùi gà gừng ấm', 'Tôm tươi giòn ngọt nấu cùng nấm đùi gà trong nước dùng gà trong veo, thơm nồng vị gừng, tỏi phi và dầu mè dịu nhẹ', 'Món súp khai vị nhẹ bụng mà giàu dinh dưỡng kiểu nhà hàng Trung Hoa: nước dùng gà thanh ngọt quyện hương gừng tươi ấm áp, những lát nấm đùi gà dai ngọt tự nhiên và thịt tôm ướp rượu Thiệu Hưng chín tới hồng hào giòn sần sật.', 'Múc súp nóng ra tô, rưới thêm vài giọt dầu mè thơm và rắc lá hành xanh thái nhỏ, dùng nóng ngay làm món khai vị hoặc ăn cùng bữa cơm gia đình.', 'Nên dùng hết trong ngày để tôm giữ độ giòn ngọt; nếu bảo quản tủ mát tối đa 24 giờ, chỉ đun sôi lại phần nước súp nấm rồi thả tôm vào đảo nóng nhanh 1 phút.', 'chinese', 'mon_canh', NULL, 'easy', 15, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Súp","Tôm tươi","Nấm đùi gà","Thanh ngọt","Khai vị"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","sesame","shrimp","soybean","wheat"]', 157, 156.7, 656, 16.2, 6.9, 1.2, 7.4, 1.5, 2, 1525, 3.81, '["Shaoxing Wine Ref","USDA FDC 168580","USDA FDC 169230","USDA FDC 169231","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171413","USDA FDC 172883","USDA FDC 173468","USDA FDC 174277","USDA FDC 175179"]', '5655514a1e723966a27e0c13b5b93b8054589314d103108005cdfb889a92c671', '60df14591a8c48871c4350b6e73f4fac3ba0657118ec7a4889f818b1655db3d4', 4),
('imp-00e0b1417e11b291', 'dau-phu-xao-hanh-tay', 291, 'Đậu phụ chiên giòn xào hành tây', 'Đậu phụ cứng áo bột bắp chiên vàng giòn, xào cùng hành tây thái mỏng và gừng tỏi trong nước sốt xì dầu rượu Thiệu Hưng sánh bóng', 'Những miếng đậu phụ cứng thấm khô áo lớp bột bắp mỏng chiên vàng giòn rụm hai mặt, sau đó đảo nhanh trên chảo nóng cùng hành tây ngọt thanh, gừng tỏi phi thơm và nước sốt xì dầu đậm – nhạt quyện vị dịu của rượu Thiệu Hưng và đường nâu.', 'Trút đậu phụ xào hành tây lên đĩa hoặc phủ trực tiếp lên bát cơm trắng nóng, rắc thêm hành lá xanh và hạt mè trắng rang cho dậy hương thơm.', 'Món ngon nhất khi dùng nóng để cảm nhận vỏ đậu giòn ráo; nếu còn dư, bảo quản hộp kín ngăn mát tối đa 2 ngày và áp chảo lại 3 phút trên lửa vừa.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Đậu phụ","Xào","Hành tây","Chay","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["sesame","soybean","wheat"]', 349, 348.7, 1458, 16.4, 20.2, 2.9, 28.3, 2.7, 8.3, 891, 2.23, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', '5f18d5d029a71946a591caa14d7d088b4b6b6636bf1e26ce342864ef214e2fea', '4b8e5e93523695d72fe13d5945c92aa368f924e21290d90f0af9cedaca79a4dc', 4),
('imp-45274582db71eb9f', 'mi-xao-tom-quang-dong', 292, 'Mì xào tôm cải bắp kiểu Quảng Đông', 'Sợi mì trứng mềm dai xào lửa lớn cùng tôm tươi giòn ngọt, bắp cải, giá đỗ và nước sốt dầu hào xì dầu óng ánh', 'Đĩa mì xào kiểu Quảng Đông đậm đà hương chảo nóng với từng sợi mì trứng mềm dai không bết dính, hòa quyện vị ngọt mặn dịu của dầu hào, xì dầu và dầu mè, kết hợp tôm tươi săn giòn cùng bắp cải thái sợi và giá đỗ giòn mát.', 'Gắp mì xào tôm nóng hổi ra đĩa rộng, dùng ngay khi bắp cải và giá đỗ còn giữ độ giòn tươi, có thể kèm chén tương ớt nếu thích vị cay.', 'Món ngon nhất khi ăn nóng ngay sau khi xào; nếu còn dư, bảo quản kín trong ngăn mát tối đa 24 giờ và đảo nóng nhanh 2–3 phút trên chảo không dính.', 'chinese', 'mon_xao', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Quảng Đông","Tôm tươi","Bắp cải","Nhanh gọn"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry"]', '["crustaceans","egg","molluscs","sesame","shrimp","soybean","wheat"]', 579, 578.7, 2422, 28.4, 15.9, 2.6, 81.7, 4.7, 10.4, 1487, 3.72, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 169963","USDA FDC 169975","USDA FDC 170005","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'b3118fcb707e84eb574de9cf142e871a6e09eccdca45e30947a49a5ead8615ed', '071992d0dcb5b0c1493f78916b79aa500abe6c31d01ff0c9ef7f0fc31d2a5df7', 4),
('imp-3d2e5735cbfe9654', 'tom-rang-muoi-tieu', 293, 'Tôm rang muối tiêu ớt kiểu Hồng Kông', 'Tôm tươi nguyên vỏ áo bột bắp chiên giòn rụm ăn được cả vỏ, xóc đều tỏi phi vàng, ớt hiểm và bột muối tiêu Tứ Xuyên thơm nồng', 'Món tôm rang muối tiêu trứ danh của ẩm thực Hồng Kông với từng con tôm nguyên vỏ áo bột bắp mỏng chiên giòn tan đến mức ăn được cả vỏ, xóc nhanh cùng bột tiêu Tứ Xuyên rang muối biển thơm lừng, tỏi phi vàng giòn và ớt hiểm cay nồng.', 'Bày tôm ra đĩa khi vừa tắt bếp, rắc thêm phần bột muối tiêu còn lại lên trên và dùng nóng ngay để tận hưởng trọn vẹn độ giòn của vỏ tôm.', 'Tôm rang muối tiêu ngon nhất khi thưởng thức ngay lúc nóng giòn; hạn chế để qua đêm vì vỏ tôm sẽ hút ẩm và mất độ giòn.', 'chinese', 'mon_chien', NULL, 'medium', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm rang","Muối tiêu","Hồng Kông","Giòn rụm","Khai vị"]', '["lunch","dinner"]', '["deep_fry","stir_fry"]', '["crustaceans","shrimp"]', 176, 175.7, 735, 19.1, 6.1, 0.9, 11.6, 0.9, 0.6, 926, 2.32, '["Spice Reference","USDA FDC 169230","USDA FDC 169231","USDA FDC 169698","USDA FDC 170005","USDA FDC 170106","USDA FDC 171413","USDA FDC 173468","USDA FDC 175179"]', '979adc7095fc9c35e64dda9ead19cdd5b8bea9b3758293e1529e1c8ed3a5e8aa', '2993bcd05bee6109542a76e4f859e203c023e35878132470bfcfeeb8288b3ace', 4),
('imp-73568e9a99d0ccdf', 'trung-xao-hanh-tay', 294, 'Trứng xào hành tây mềm thơm kiểu Trung', 'Những mảng trứng bông xốp ẩm mượt kết hợp hành tây xào chín mềm ngọt thanh, nêm hạt nêm gà và tiêu đen dậy vị đưa cơm', 'Món xào gia đình quen thuộc của bếp Trung Hoa hoàn thành chỉ trong 15 phút: trứng gà đánh cùng chút sữa tươi và mayonnaise nên cực kỳ mềm xốp, quyện cùng hành tây xào ẩm với nước lọc giữ trọn vị ngọt tự nhiên.', 'Trút trứng xào hành tây nóng hổi ra đĩa nông, ăn ngay cùng cơm trắng nóng hoặc cháo trắng vào bữa sáng đều rất hợp vị.', 'Món ngon nhất khi dùng nóng ngay sau khi xào; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nóng nhẹ trên chảo chống dính.', 'chinese', 'mon_nhanh_sang', NULL, 'easy', 5, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Trứng xào","Hành tây","Nhanh gọn","Cơm nhà","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","milk"]', 302, 302.4, 1265, 12, 25.8, 5.4, 5.5, 0.9, 2.5, 982, 2.46, '["USDA FDC 170000","USDA FDC 170005","USDA FDC 170931","USDA FDC 171009","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '37741dd046f1fb28cbbc9bcf93cdfc50562c65cdef83519a56b4a261c84707bd', '63e1081999ca586931e30afeef95dce771add397458ce0f173f69bcf504b4dcd', 4),
('imp-a17f5a86a1bc891c', 'ba-chi-luoc-cham-tuong', 295, 'Thịt ba chỉ luộc thái mỏng rưới sốt tỏi ớt Tứ Xuyên', 'Ba chỉ luộc chín mềm da dẻo thơm hương hồi quế, thái lát mỏng xếp trên dưa leo giòn mát, rưới sốt dầu ớt tỏi thơm nồng cay tê', 'Món ba chỉ luộc sốt tỏi (Toán Nê Bạch Nhục) trứ danh vùng Tứ Xuyên: thịt ba chỉ nguyên tảng luộc liu riu cùng gừng, hành, hoa hồi và tiêu Tứ Xuyên cho mềm mọng, thái lát mỏng mượt rồi chan sốt xì dầu giấm đen, tỏi băm và dầu ớt thơm lừng.', 'Xếp dưa leo thái sợi lót đáy đĩa, bày các lát ba chỉ luộc mỏng đều lên trên, chan đều sốt tỏi ớt mè rang và rắc lá hành xanh rồi dùng nguội hoặc ấm nhẹ với cơm trắng.', 'Thịt luộc thái lát và sốt pha sẵn nên bảo quản riêng trong hộp kín ngăn mát tối đa 3 ngày; khi ăn chỉ cần chan sốt và dùng mát lạnh.', 'chinese', 'mon_hap_luoc', NULL, 'medium', 15, 35, 4, '/frigo/illustrations/delicious-meal.png', '["Thịt ba chỉ","Luộc","Tứ Xuyên","Khai vị","Mùa hè"]', '["lunch","dinner"]', '["boil","assemble"]', '["pork","sesame","soybean","wheat"]', 654, 654, 2736, 12.3, 62.8, 20.2, 11.2, 2.2, 4.1, 927, 2.32, '["Chinkiang Black Vinegar Ref","Shaoxing Wine Ref","Spice Reference","USDA FDC 167820","USDA FDC 168409","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170189","USDA FDC 171028","USDA FDC 171316","USDA FDC 171319","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277"]', '4d861e98d879db04fe0e2a752ef71e0d3d22b22ad45e1703031da5d4476a55ec', '0be1e4c5a7c5dd5bd67cd125b4d0253e966fecb0e67b679807b5660577d416ae', 4),
('imp-fbbe89a1039604fc', 'nam-xao-toi-trung', 296, 'Nấm đùi gà xào tỏi nước tương', 'Từng khoanh nấm đùi gà khía caro áp chảo xém vàng dai giòn như bào ngư, đảo nhanh trong sốt tỏi băm xì dầu nhạt thơm lừng', 'Món nấm xào 10 phút đậm hương vị nhà hàng Trung Hoa: nấm đùi gà thái khoanh dày khía caro áp chảo xém cạnh săn giòn, rồi quyện cùng hỗn hợp tỏi phi thơm lẫn tỏi sống băm nhuyễn, xì dầu nhạt và chút dầu hào dậy vị ngọt tự nhiên.', 'Trút nấm đùi gà xào tỏi ra đĩa nóng, rắc hành lá xanh và ớt khoanh, thưởng thức ngay cùng cơm trắng nóng.', 'Nên dùng hết trong bữa ăn để cảm nhận trọn vẹn độ giòn sần sật của nấm; bảo quản ngăn mát tối đa 24 giờ và áp chảo lại 2 phút trên lửa lớn.', 'chinese', 'mon_xao', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Nấm đùi gà","Xào tỏi","Nhanh gọn","Chay","Cơm nhà"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["molluscs","soybean","wheat"]', 137, 136.7, 572, 5.4, 8.9, 1.3, 12.2, 3.4, 2.7, 710, 1.77, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277"]', '6e51ed29ffbcb1ca4a6629c232c704f71be1acbce88bc0b0711d10a1a5ffc902', 'a10da6a01d0856dcb4b2dba22d4c884e9f76cee6febce8670ebbf3a97970c740', 4),
('imp-3ee45f761eb0b78d', 'mi-lanh-ga-trung', 297, 'Mì lạnh gà xé dưa leo sốt mè Tứ Xuyên', 'Sợi mì dai mát trộn cùng thịt ức gà xé tơi mềm mọng, dưa leo giòn ngọt và nước sốt tương mè giấm đen dầu ớt béo cay thanh mát', 'Tô mì lạnh gà xé Tứ Xuyên giải ngấy lý tưởng cho ngày nắng nóng: ức gà ủ chín mềm mọng nước rồi xé sợi tơi, kết hợp sợi mì luộc xả lạnh dai giòn, dưa leo bào sợi mát lành và nước sốt tương mè béo bùi quyện giấm đen, xì dầu, dầu ớt và tiêu Tứ Xuyên tê dịu.', 'Xếp dưa leo, thịt gà xé lên mặt tô mì lạnh, chan đẫm nước sốt tương mè, rắc đậu phộng rang giã dập, mè rang và hành lá rồi trộn đều ngay trước khi ăn.', 'Bảo quản riêng gà xé, mì trộn dầu và hũ nước sốt trong ngăn mát tối đa 2 ngày; chỉ trộn tất cả nguyên liệu cùng dưa leo ngay trước khi thưởng thức.', 'chinese', 'mon_bun_pho', NULL, 'easy', 20, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Mì lạnh","Ức gà","Sốt mè","Tứ Xuyên","Giải nhiệt"]', '["lunch","dinner"]', '["boil","toss_mix","assemble"]', '["chicken","peanut","sesame","soybean","wheat"]', 657, 657.3, 2750, 44.3, 32.8, 4.9, 47.8, 4.4, 10.6, 1633, 4.08, '["Chili Oil / Satay Ref","Chinkiang Black Vinegar Ref","NIN VN Fresh Rice Noodle Ref","Spice Reference","USDA FDC 168409","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170189","USDA FDC 171028","USDA FDC 171413","USDA FDC 171477","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'e4aee95732debdec907ebecf8b2fc85880293009ffcaf8045cb04f2ce2b1a302', '7746db7c9e1ab211da781b07783ce02dc1e36f5b4f9f29f5e58ba7ba4598601f', 4),
('imp-cbb5635bfe848a49', 'ga-om-gung-tuong', 298, 'Đùi gà om gừng xì dầu kiểu Hoa', 'Đùi gà nguyên xương áp chảo vàng da, om liu riu cùng thật nhiều gừng tươi, hoa hồi, rượu Thiệu Hưng và xì dầu đặc sánh bóng', 'Món đùi gà om xì dầu đậm vị cơm nhà Trung Hoa: thịt đùi gà có xương giữ trọn độ mọng ngọt sau khi áp chảo vàng da, om thấm đẫm hương gừng tươi thái lát ấm nồng, hồi quế, đường nâu và hai loại xì dầu tạo nước sốt nâu bóng sánh đẹp.', 'Gắp đùi gà om gừng ra đĩa sâu lòng, rưới nước sốt sánh bóng và rắc hành lá xanh thái nhỏ lên trên, ăn nóng kèm cơm trắng dẻo và rau luộc.', 'Để nguội bảo quản hộp kín ngăn mát tối đa 3 ngày; khi ăn hâm lại trên lửa nhỏ với 2–3 muỗng canh nước lọc đến khi thịt gà nóng đều.', 'chinese', 'mon_kho', NULL, 'easy', 15, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Đùi gà","Món om","Gừng tươi","Xì dầu","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","braise","simmer"]', '["chicken","sesame","soybean","wheat"]', 606, 606.1, 2537, 57.3, 35, 9, 11.1, 0.6, 6.6, 1191, 2.98, '["Dark Soy Sauce Label Ref","Shaoxing Wine Ref","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 170005","USDA FDC 170917","USDA FDC 170933","USDA FDC 171028","USDA FDC 171316","USDA FDC 171413","USDA FDC 172385","USDA FDC 173647","USDA FDC 174277"]', '7248cc48f78e158b92d2ab0db61498e677ea91b5e3e53aadda2165b2d6508602', '37e4468fb9940bc7d142858cfc6a42d4b93b0b9d390adaaccceb7c620fdc0770', 4),
('imp-7bf9327b2c48f2d4', 'suon-nuong-tuong', 299, 'Sườn non nướng tương mật ong kiểu Hoa', 'Sườn non ướp đậm xì dầu, tương đen Hoisin, tỏi và ngũ vị hương nướng lò chín mềm, phết mật ong bóng nâu thơm lừng cạnh cháy xém', 'Những dẻ sườn non nướng kiểu xá xíu Trung Hoa hấp dẫn với vị mặn ngọt hài hòa từ xì dầu nhạt, tương đen Hoisin, rượu Thiệu Hưng và ngũ vị hương, nướng chín mềm ẩm trong lò rồi phết mật ong lửa lớn tạo lớp vỏ caramel óng ả xém cạnh.', 'Chặt sườn thành từng khúc vừa ăn, xếp ra đĩa rắc hành lá thái nhỏ và dọn nóng cùng cơm trắng, dưa leo hoặc cải thìa xào tỏi cho bữa tiệc cuối tuần.', 'Bảo quản sườn đã nướng trong hộp kín ngăn mát tối đa 3 ngày; khi dùng hâm nóng lại bằng lò nướng hoặc nồi chiên không dầu 5 phút ở 180°C.', 'chinese', 'mon_lau_tiec', NULL, 'medium', 20, 55, 4, '/frigo/illustrations/delicious-meal.png', '["Sườn nướng","Mật ong","Ngũ vị hương","Cuối tuần","Tiệc nhà"]', '["lunch","dinner"]', '["grill_roast"]', '["pork","sesame","soybean","wheat"]', 623, 622.5, 2605, 32.1, 46.9, 17, 15.9, 0.7, 12.4, 1564, 3.91, '["Five Spice USDA Ref","Shaoxing Wine Ref","USDA FDC 167861","USDA FDC 169230","USDA FDC 169640","USDA FDC 169655","USDA FDC 170005","USDA FDC 170933","USDA FDC 171028","USDA FDC 171370","USDA FDC 173468","USDA FDC 174277"]', '6d971caffe940d40fd7f04d076fb47a7b21c262c89801b7713251ff07837e785', 'dacda88453a567dd3974968e96bdb14561ac94f1dc44e8f667d010635c73a6a3', 4),
('imp-bbfdcf2e3b277fed', 'soba-nong-ga', 300, 'Mì Soba nóng thịt gà', 'Sợi mì Soba kiều mạch nóng trong nước dùng Dashi Kombu cá bào đậm vị, phủ đùi gà áp chảo da giòn và hành boa-rô thơm ngọt', 'Mì Soba nóng thịt gà (Torinanban Soba) là món mì nước ấm áp kinh điển của Nhật Bản, kết hợp nước dùng Dashi truyền thống từ tảo bẹ Kombu và cá bào Katsuobushi, đùi gà áp chảo da vàng giòn, hành boa-rô xém ngọt cùng chút gừng mài thơm nồng.', 'Xếp mì Soba nóng vào 3 tô, chan ngập nước dùng Dashi cùng thịt gà và hành boa-rô áp xém, thêm chút gừng tươi mài nhuyễn và bột ớt 7 vị Shichimi rồi thưởng thức ngay.', 'Nếu chưa ăn hết ngay, bảo quản riêng phần mì Soba đã luộc ráo và phần nước dùng thịt gà trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn đun sôi nước dùng rồi trụng nóng lại mì.', 'japanese', 'mon_bun_pho', NULL, 'easy', 20, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Mì Soba","Thịt gà","Nước dùng Dashi","Ẩm thực Nhật","Mì nước"]', '["lunch","dinner"]', '["boil","pan_fry","simmer"]', '["buckwheat","chicken","fish","sesame","soybean","wheat"]', 597, 597, 2498, 34.8, 15.1, 3.6, 77.2, 4.6, 9.4, 1694, 4.24, '["MEXT Dry Soba 01097","MEXT Hon-Mirin 16031","MEXT Katsuobushi 10099","MEXT Sake 16021","MEXT Spice Ref","USDA FDC 168457","USDA FDC 169231","USDA FDC 169246","USDA FDC 171413","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'cf125bd130ac99f2617a502f1c53f2ed1ff31c3ebb784b7c51b312640aae8cac', '522a686fb73f3caa5d4eeb5a446a0a65708214f1958cad43d1129712d060a736', 4),
('imp-f2334219f33e48d0', 'tom-nuong-muoi-nhat', 301, 'Tôm nướng muối kiểu Nhật', 'Tôm sú nguyên vỏ ướp sơ rượu Sake, xiên thẳng rắc muối hạt biển nướng xém cạnh giữ trọn thịt ngọt chắc, chấm chanh tiêu', 'Tôm nướng muối kiểu Nhật (Ebi Shioyaki) tôn vinh trọn vẹn vị ngọt tự nhiên của tôm sú nguyên vỏ, chỉ cần ướp nhanh với rượu Sake khử tanh, xiên que giữ thân thẳng đẹp và phủ lớp muối hạt nướng xém vỏ giòn thơm.', 'Xếp tôm nướng muối đỏ au ra đĩa cùng múi chanh tươi, rắc chút hành lá thái nhỏ và dọn kèm chén muối tiêu đen xay để chấm thịt tôm sau khi bóc vỏ.', 'Tôm nướng muối ngon nhất khi dùng nóng ngay sau khi nướng để vỏ giòn và thịt ngọt mọng; nếu dư, bóc vỏ bảo quản ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo.', 'japanese', 'mon_lau_tiec', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Tôm nướng","Shioyaki","Hải sản","Ẩm thực Nhật","Món nướng"]', '["lunch","dinner"]', '["grill_roast"]', '["crustaceans","shrimp"]', 104, 103.9, 435, 21.1, 1.3, 0.2, 1.8, 0.5, 0.3, 448, 1.12, '["MEXT Sake 16021","USDA FDC 168155","USDA FDC 170005","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 175179"]', 'f48c5e1f33bbc6725d60adfa682fd174bf88cceacff0de86dac6ed6d6f9b8000', 'd642d9cf84c90257a7fb5d81f887a2dc504c6158898587200e6c48ad933674dc', 4),
('imp-8f6eeb8b34b7cd65', 'com-muc-nuong', 302, 'Cơm mực nướng sốt Teriyaki', 'Cơm gạo Nhật dẻo thơm ăn cùng mực ống nguyên con áp chảo cháy cạnh áo đẫm sốt xì dầu Sake Mirin gừng mài sánh bóng', 'Cơm mực nướng sốt Teriyaki (Ikayaki Don) mang hương vị quán ăn lễ hội Nhật Bản, kết hợp cơm trắng gạo hạt ngắn dẻo ngọt cùng mực ống nguyên con áp chảo xém cạnh thơm lừng, áo lớp sốt xì dầu Sake Mirin gừng tươi sánh bóng đậm đà.', 'Xới cơm nóng ra 3 bát, xếp các khoanh mực và phần râu mực áp chảo lên trên, rưới đẫm phần sốt Teriyaki gừng còn lại trong chảo và rắc hành lá thái nhỏ.', 'Ngon nhất khi ăn nóng ngay lúc mực vừa nướng xong; nếu còn dư, bảo quản riêng cơm và mực trong hộp kín ở ngăn mát tối đa 24 giờ và làm nóng nhanh trong 1–2 phút.', 'japanese', 'mon_nhanh_sang', NULL, 'medium', 15, 40, 3, '/frigo/illustrations/delicious-meal.png', '["Cơm mực","Mực nướng","Teriyaki","Ẩm thực Nhật","Hải sản"]', '["lunch","dinner"]', '["pan_fry","boil"]', '["molluscs","soybean","squid","wheat"]', 565, 565.3, 2365, 27.5, 5.2, 1, 95.6, 1.6, 10.6, 708, 1.77, '["MEXT Hon-Mirin 16031","MEXT Sake 16021","USDA FDC 169231","USDA FDC 169655","USDA FDC 169756","USDA FDC 170005","USDA FDC 171413","USDA FDC 173647","USDA FDC 174223","USDA FDC 174277"]', '38a712c2179e886f41a32b3000c00a6bdcb55aa04a314d94d2180c6652d9ba34', '85602b430c7d8ede0fb26481b237125881d8fceac182ecda69d48ab3c6ddcdaa', 4),
('imp-9e4ad3e4074d2a1c', 'salad-bap-cai-tom-nhat', 303, 'Salad bắp cải tôm Nhật', 'Bắp cải, cà rốt và hành tây thái sợi giòn mát trộn tôm sú luộc ngọt thịt, quyện sốt Mayonnaise mật ong giấm chanh dịu nhẹ', 'Salad bắp cải tôm kiểu Nhật kết hợp bắp cải thái sợi mỏng, cà rốt giòn ngọt và hành tây ngâm lạnh hết hăng cùng tôm sú luộc đỏ au săn chắc, áo đều lớp sốt Mayonnaise pha mật ong, giấm gạo, chanh tươi và chút xì dầu thanh dịu.', 'Bày salad bắp cải tôm đã làm mát ra đĩa sâu lòng, rắc hành lá thái nhỏ lên trên để tạo màu sắc tươi tắn và dùng lạnh như món khai vị hoặc ăn kèm đồ chiên nướng.', 'Nên trộn sốt ngay trước khi ăn hoặc bảo quản trong ngăn mát tối đa 24 giờ; nếu chuẩn bị trước, để riêng phần sốt và rau tôm để giữ độ giòn tươi.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Salad Nhật","Bắp cải","Tôm tươi","Món trộn","Thanh mát"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","egg","shrimp","soybean","wheat"]', 208, 208.2, 872, 14.5, 11.7, 1.9, 12.6, 2.3, 9.1, 431, 1.08, '["USDA FDC 168155","USDA FDC 169640","USDA FDC 169975","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 171009","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '82be1318d6db17c16ed33d24e68463949dfb0cda5d0fcbb617f48d35a8065cfa', 'c971312346e978f1ef35dd12e8c724906a24d0f92568bc751b51751f0873a8a5', 4),
('imp-4023e971948407f6', 'ca-hoi-om-ca-chua', 304, 'Cá hồi om cà chua kiểu Nhật', 'Cá hồi áp chảo áo bột mỏng om cùng cà chua tươi, hành tây và nấm đùi gà trong nước sốt xì dầu Mirin thanh ngọt đậm đà', 'Món cá hồi om cà chua phong cách gia đình Nhật kết hợp vị béo ngậy của phi lê cá hồi áp chảo với nước sốt cà chua tươi chua dịu, ngọt thanh hành tây và hương thơm umami từ nấm cùng xì dầu Nhật Bản.', 'Dọn cá hồi om cà chua ra đĩa sâu lòng khi còn nóng hổi, rưới đều nước sốt sánh mịn lên mặt cá, rắc thêm hành lá xanh và ăn kèm cơm trắng hạt dẻo.', 'Món ăn ngon nhất khi dùng nóng trong ngày; nếu còn dư, bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày và hâm nóng nhẹ trên lửa nhỏ với 1–2 muỗng canh nước lọc để sốt không bị cạn.', 'japanese', 'mon_kho', NULL, 'easy', 15, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Món om Nhật","Cá hồi","Cà chua","Cơm nhà","Bữa tối ấm"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["fish","salmon","soybean","wheat"]', 329, 329.3, 1377, 24, 18, 3.7, 17.4, 2.9, 8.6, 1001, 2.5, '["MEXT Hon-Mirin 16031","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169761","USDA FDC 170000","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175167"]', 'e4d0ac5f33c5848b2f14efbf86ccbf3a192f08317f6e0bcfffb8547f503985e7', 'f44aa223e896a540d72869b4ac32bbdcdfc45e72bd137e4d9c47819f748fd6fe', 4),
('imp-76ddca35768468fe', 'bo-nuong-yakiniku-muoi', 305, 'Bò nướng Yakiniku muối chanh', 'Thịt bò thái lát mỏng nướng xém cạnh trên vỉ nóng, thưởng thức cùng muối tiêu, chanh tươi và sốt hành lá Negi-shio thơm lừng dầu mè', 'Phiên bản Yakiniku vị thanh kiểu Nhật không ướp sốt ngọt dày, giữ trọn vị ngọt thịt của lát bò thăn nướng cháy cạnh, kết hợp muối tiêu, vị chua thơm của chanh tươi và chén sốt hành lá dầu mè Negi-shio béo thơm.', 'Nướng từng mẻ thịt bò nóng hổi tại bàn, vắt trực tiếp vài giọt chanh tươi lên miếng thịt vừa chín, chấm hoặc cuộn kèm sốt hành lá Negi-shio và ăn cùng cơm trắng nóng.', 'Thịt bò nên nướng đến đâu ăn đến đó để giữ độ mềm mọng. Phần sốt hành lá Negi-shio chưa dùng hết có thể đậy kín trong hũ thủy tinh, bảo quản ngăn mát tủ lạnh từ 5–7 ngày.', 'japanese', 'mon_lau_tiec', NULL, 'easy', 15, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Yakiniku","Thịt bò nướng","Sốt Negi-shio","Cuối tuần","Nhật Bản"]', '["lunch","dinner"]', '["grill_roast","toss_mix"]', '["beef","sesame"]', 294, 293.8, 1230, 25.9, 18.4, 5.7, 5.2, 1.6, 1.1, 770, 1.92, '["MEXT Sake 16021","USDA FDC 167746","USDA FDC 169230","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 173468"]', '23767f393aced35d01513a53af99bc9727fa92fdef0322bce18c4a05293a6e60', '3e704595a0aa42d42847225a27bf983a74e0d3a431fbadd2650d77eceddd8d10', 4),
('imp-1bbb2341036dd966', 'bong-cai-tron-me-nhat', 306, 'Bông cải xanh trộn mè Nhật (Goma-ae)', 'Bông cải xanh chần giòn giữ màu xanh mướt trộn sốt hạt mè trắng rang giã dập, xì dầu và mật ong thanh dịu chuẩn vị món phụ Nhật Bản', 'Món rau phụ Goma-ae truyền thống của Nhật Bản với bông cải xanh chần vừa chín tới giòn ngọt tự nhiên, quyện lớp sốt bùi béo từ mè trắng rang giã dập hòa cùng xì dầu Nhật, Sake, Dashi và mật ong.', 'Bày bông cải trộn mè ra đĩa sâu lòng nhỏ, rắc thêm phần mè nguyên hạt và hành lá thái nhỏ lên mặt; dùng nguội mát hoặc ở nhiệt độ phòng như món rau phụ cân bằng bữa cơm Nhật.', 'Món Goma-ae ngon nhất khi dùng trong ngày để giữ độ giòn và mùi mè rang; có thể bảo quản ngăn mát tủ lạnh trong hộp kín tối đa 2 ngày và ăn nguội trực tiếp, không hâm nóng lại.', 'japanese', 'mon_cuon_nom', NULL, 'easy', 10, 8, 3, '/frigo/illustrations/delicious-meal.png', '["Goma-ae","Bông cải xanh","Món phụ Nhật","Thanh đạm","Mè rang"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["fish","sesame","soybean","wheat"]', 104, 103.6, 433, 4.9, 4.8, 0.7, 11.9, 3.4, 4.8, 676, 1.69, '["MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 169640","USDA FDC 170005","USDA FDC 170150","USDA FDC 170379","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '057a11cd7573ac6086cc5152aaff443689bea95ecab16ba70bfc159a78f4705c', 'fc1bec01a6f290f407856d926baddf2f83d8842c2f279cb025fef5628ebe8057', 4),
('imp-5ed977305ac677b6', 'com-bo-hanh-nhat', 307, 'Cơm bơ xì dầu hành lá Nhật Bản', 'Cơm trắng hạt ngắn nóng hổi trộn bơ lạt tan chảy, xì dầu Nhật thơm dịu, hành lá xanh tươi cùng cá bào và rong biển Nori béo ngậy khó cưỡng', 'Món cơm trộn Butter Shoyu Gohan kinh điển của Nhật Bản: hơi nóng từ cơm mới nấu làm viên bơ lạt tan chảy, hòa quyện vị mặn thanh của xì dầu Nhật, hành lá tươi, cá bào Katsuobushi và rong biển Nori giòn thơm.', 'Dùng ngay khi cơm còn nóng bốc hơi, trộn đều tay để bơ và xì dầu phủ bóng từng hạt cơm; có thể ăn kèm một quả trứng ốp la lòng đào hoặc súp Miso nóng.', 'Nên chế biến và ăn ngay từng phần vì cơm bơ để nguội sẽ đông bơ và mất độ thơm béo; không khuyến khích bảo quản lại món đã trộn.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 5, 5, 2, '/frigo/illustrations/delicious-meal.png', '["Cơm bơ Nhật","Bữa sáng nhanh","Nhật Bản","Đơn giản","Tiện lợi"]', '["breakfast","lunch","dinner"]', '["assemble","toss_mix"]', '["fish","milk","sesame","soybean","wheat"]', 372, 371.5, 1555, 8.8, 13.5, 7.6, 52.9, 1.5, 0.4, 496, 1.24, '["MEXT Katsuobushi 10099","USDA FDC 168456","USDA FDC 168878","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 173430","USDA FDC 174277"]', 'db7b6bb9c0e1bc9f1be0082caa3063063e1efdca7d0b78c1213057eeeed06d1f', '6ec168fb522896395cd4b379763a4378efd79e6d5cd3cfc00b40ebab02a2fa86', 4),
('imp-57294c4da3e61e24', 'sup-miso-tom-nam', 308, 'Súp Miso tôm nấm đùi gà', 'Nước dùng Dashi thanh ngọt nấu cùng tôm tươi nguyên con, nấm đùi gà giòn ngọt, rong biển Wakame và tương Miso Nhật thơm ấm bụng', 'Bát súp Miso hải sản chuẩn vị Nhật Bản kết hợp vị ngọt tự nhiên từ tôm tươi nấu cùng rượu Sake khử tanh, nấm đùi gà cắt lát sần sật, rong biển Wakame mềm mượt và tương Miso hòa tan sau khi tắt bếp giữ trọn hương thơm.', 'Múc súp Miso nóng ra 3 bát nhỏ, chia đều tôm, nấm và rong biển, rắc thêm hành lá thái khoanh; dùng nóng làm món canh khai vị hoặc ăn kèm cơm trắng và cá nướng.', 'Súp Miso ngon nhất khi thưởng thức ngay sau khi nấu; nếu bảo quản tủ mát tối đa 1 ngày, chỉ hâm nóng lại trên lửa nhỏ cho đến khi vừa bốc hơi, tuyệt đối không đun sôi bùng để tránh mất mùi thơm của Miso.', 'japanese', 'mon_canh', NULL, 'easy', 10, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Súp Miso","Tôm tươi","Nấm đùi gà","Canh Nhật","Ấm bụng"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp","soybean","wheat"]', 101, 101.1, 423, 14.3, 1.5, 0.2, 8, 2, 1.8, 964, 2.41, '["MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA FDC 168580","USDA FDC 170005","USDA FDC 170496","USDA FDC 172446","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', 'f1137148cb5755b0b45bb8bbcc3a65e9c169bb0083df129695f38218c320360b', '192ba2451aa6187b9167ef3447b9dc84ef426ad02966e76e0d7cc1adf25c5fc9', 4),
('imp-ea9ba867b7d2c6ad', 'ga-hap-gung-bap-cai', 309, 'Ức gà hấp gừng bắp cải kiểu Nhật', 'Ức gà hấp mềm ẩm trên lớp bắp cải ngọt thanh, rưới sốt nước tương Ponzu chua dịu quyện dầu mè, gừng tươi và mè trắng rang', 'Món ức gà hấp kiểu Nhật nhẹ nhàng, giàu đạm và ít dầu mỡ: thịt ức gà hấp chín tới trên nền bắp cải ngọt giúp giữ độ ẩm mềm, sau đó xé sợi trộn sốt nước tương Ponzu, gừng bào và dầu mè thơm bùi.', 'Bày thịt gà xé cùng bắp cải hấp ra đĩa lớn, rưới đều nước sốt Ponzu gừng và phần nước ngọt tiết ra khi hấp, rắc thêm hạt mè trắng rang và hành lá thái nhỏ; dùng nóng hoặc nguội mát đều ngon.', 'Bảo quản phần gà hấp và sốt riêng trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn có thể dùng nguội như salad gà hoặc hấp lại 3–4 phút cho ấm nóng.', 'japanese', 'mon_hap_luoc', NULL, 'easy', 10, 18, 3, '/frigo/illustrations/delicious-meal.png', '["Món hấp","Ức gà","Bắp cải","Thanh đạm","Nhật Bản"]', '["lunch","dinner"]', '["steam","toss_mix"]', '["chicken","sesame","soybean","wheat"]', 225, 225.3, 943, 27.1, 7.7, 1.3, 10.6, 3.5, 4.9, 952, 2.38, '["MEXT Ponzu Ref","MEXT Sake 16021","USDA FDC 169231","USDA FDC 169975","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171477","USDA FDC 173468","USDA FDC 173647"]', 'b6394ae05e8f409ed7d5a714eb6b814380fbd1662860744e56f07d994f2e3200', 'd90c8f2b754d248625a2d4ae3f9c219ae624fb673070f29cb76eed38d84f61da', 4),
('imp-7d764feba948bce3', 'canh-kimchi-ca', 310, 'Canh kim chi cá hồi đậu phụ', 'Nồi canh kim chi jjigae cay ấm với cá hồi tươi béo ngậy, đậu phụ mềm mịn và nước dùng chua thanh chuẩn vị Hàn', 'Canh kim chi cá hồi đậu phụ là biến tấu đậm đà của món kimchi jjigae truyền thống Hàn Quốc. Vị chua cay tự nhiên của kim chi cải thảo lên men kỹ hòa cùng thịt cá hồi béo ngọt và đậu phụ thanh mát, rất đưa cơm trong những ngày se lạnh.', 'Dọn canh nóng hổi ngay trong nồi đất hoặc tô sâu lòng, rắc hành lá thái vát lên mặt và ăn kèm cơm trắng nóng dẻo.', 'Nên thưởng thức ngay khi còn nóng để cá và đậu phụ giữ nguyên thớ đẹp; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hâm sôi nhẹ trên lửa nhỏ.', 'korean', 'mon_canh', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Canh kim chi","Hàn Quốc","Cá hồi","Đậu phụ","Cay ấm"]', '["lunch","dinner"]', '["simmer"]', '["fish","salmon","sesame","soybean","wheat"]', 357, 357.2, 1494, 28.8, 22.9, 4.4, 10.9, 3.5, 5, 1100, 2.75, '["Korean Chili Flake Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175167"]', 'b5e33aff19d45425d3c90c525e97d3e193ff249b411d6f6849d87823a29595c7', '1712fa2a5a869cc7c495c8384c6169ddf210a52c77a620d46fbe26492d86cad4', 4),
('imp-a24e0f07380bfdc2', 'suon-ham-galbi-han', 311, 'Sườn bò hầm kiểu Hàn (Galbi Jjim)', 'Sườn bò hầm mềm róc xương quyện sốt tương ngọt bóng, thấm vị củ cải, cà rốt, nấm hương và táo đỏ sang trọng', 'Sườn bò hầm Galbi Jjim là món ăn truyền thống trong các dịp lễ tiệc của Hàn Quốc. Từng dẻ sườn bò được ngâm chần kỹ để sạch tạp chất rồi hầm liu riu với nước ngâm nấm hương, nước tương và rượu mirin đến khi thịt mềm róc xương, phủ lớp sốt nâu bóng óng ánh.', 'Bày sườn và rau củ ra đĩa sâu lòng hoặc thố giữ nhiệt, rắc hành lá cắt khúc lên trên, ăn nóng kèm cơm trắng và kim chi cải thảo.', 'Có thể bảo quản ngăn mát tủ lạnh tới 3 ngày trong hộp kín (vớt bỏ lớp mỡ đông trên mặt trước khi hâm). Hâm nóng trên bếp lửa nhỏ với 2–3 muỗng canh nước trong 8–10 phút.', 'korean', 'mon_lau_tiec', NULL, 'hard', 45, 110, 5, '/frigo/illustrations/delicious-meal.png', '["Galbi jjim","Sườn bò","Món tiệc","Hàn Quốc","Hầm mềm"]', '["lunch","dinner"]', '["boil","braise"]', '["beef","sesame","soybean","wheat"]', 488, 488.2, 2042, 21.6, 21.6, 8.2, 50.1, 4.1, 34.3, 1279, 3.2, '["MEXT Hon-Mirin 16031","USDA Beef Rib / Bone Ref","USDA FDC 168436","USDA FDC 168452","USDA FDC 168836","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 173647","USDA FDC 174277","USDA FDC Jujube Ref"]', 'aa467d2cc877f2a3ddf087b28e2690154db2d38f95a39da67f4dc408d17cd3b5', 'a83ddd95ace30fcbfa0926b79e0653fbba6864ebb53c859f729160446d1adfe0', 4),
('imp-706c3678abea88b4', 'trung-chien-tron-han', 312, 'Trứng chiên hành lá kiểu Hàn (Gyeran Jeon)', 'Trứng chiên tròn vàng ruộm viền giòn, thơm hành lá xanh mướt chấm nước tương pha chua ngọt kiểu hộp cơm Hàn', 'Gyeran Jeon là món trứng chiên tròn dẹt giản dị nhưng rất được ưa chuộng trong bữa cơm gia đình và hộp cơm trưa Hàn Quốc. Trứng đánh kỹ chiên trên chảo chống dính với lượng dầu vừa đủ cho mặt ngoài vàng đều, viền giòn nhẹ và bên trong mềm ẩm thơm hành lá.', 'Cắt miếng tam giác hoặc miếng vuông vừa ăn, bày ra đĩa cùng chén nước tương giấm mè; dùng nóng với cơm trắng hoặc xếp vào hộp cơm.', 'Ngon nhất khi ăn ngay lúc vừa chiên xong; có thể bảo quản nguội trong hộp kín ở ngăn mát tối đa 24 giờ và áp chảo lại 1 phút không dầu trước khi ăn.', 'korean', 'mon_chien', NULL, 'easy', 8, 10, 2, '/frigo/illustrations/delicious-meal.png', '["Gyeran jeon","Trứng chiên","Hàn Quốc","Món nhanh","Hộp cơm"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","sesame","soybean","wheat"]', 208, 208, 870, 12.9, 15.5, 3.8, 4.2, 0.8, 1.8, 1326, 3.32, '["USDA FDC 169655","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172238","USDA FDC 173468","USDA FDC 174277"]', '0a6f2f08188a37b52da64283582e2a59cfbe82f07b81c020d7db05555e7c6e78', '9ef3dced68ed443fd525136b6957b2df20deac416089a8cff16ecb1b84cab24c', 4),
('imp-d88e008b28a31151', 'muc-xao-kimchi', 313, 'Mực xào kim chi cay đậm kiểu Hàn', 'Mực tươi khứa caro giòn sần sật xào lửa lớn cùng kim chi chua, hành tây và sốt tương ớt Gochujang đỏ bóng', 'Món mực xào kim chi (Ojingeo Kimchi Bokkeum) kết hợp độ giòn ngọt tự nhiên của mực tươi khứa caro với vị chua cay đậm đà từ kim chi cải thảo chín kỹ và tương ớt Gochujang. Kỹ thuật xào nhanh lửa lớn giữ cho mực không ra nước và sốt áo bóng đều từng miếng.', 'Dọn nóng ra đĩa sâu lòng, rắc mè trắng rang lên trên; ăn ngay cùng cơm trắng nóng dẻo hoặc xúc trực tiếp lên cơm như món cơm trộn.', 'Mực xào ngon nhất khi ăn ngay lúc vừa tắt bếp để giữ độ giòn; nếu bảo quản tủ mát tối đa 24 giờ, nên đảo nhanh lại trên chảo nóng lửa vừa 1–2 phút, tránh hâm quá lâu làm mực dai.', 'korean', 'mon_xao', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Mực xào","Kim chi","Hàn Quốc","Cay đậm","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["molluscs","sesame","soybean","squid","wheat"]', 372, 371.9, 1556, 27.2, 16.4, 2.6, 30.7, 5.4, 12.2, 1532, 3.83, '["Korean Chili Flake Ref","USDA / Korean Gochujang Ref","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170393","USDA FDC 170497","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 174223","USDA FDC 174277"]', '914ac0652c1c90430c8b66cb9a41f56b254b99410ddd64e6cc36f0f3f8ae07d9', '4b31e0118588497dda4c46ac857dc5179ba269975428cc6aa14dcf1437341edc', 4),
('imp-3ec4d8a534fc8861', 'ga-nuong-bulgogi', 314, 'Gà nướng Bulgogi kiểu Hàn (Dak Bulgogi)', 'Đùi gà rút xương ướp nước tương, đường nâu, mật ong và gừng tỏi nướng áp chảo xém cạnh thơm lừng', 'Gà nướng Bulgogi (Dak Bulgogi) sử dụng phần đùi gà mềm mọng ướp đậm đà trong hỗn hợp nước tương, đường nâu, mật ong, rượu mirin, dầu mè và gừng tỏi. Khi nướng hoặc áp chảo trên lửa vừa-cao, lớp gia vị caramel hóa tạo bề mặt vàng xém thơm lừng mà thịt bên trong vẫn mọng nước.', 'Thái gà thành miếng vừa ăn, rưới nước sốt ướp đã đun sánh và rắc hành lá, mè rang lên trên; ăn nóng với cơm trắng hoặc cuốn lá xà lách kèm kim chi.', 'Có thể ướp gà trước trong ngăn mát qua đêm để tiện nấu nhanh; gà đã nướng bảo quản hộp kín ngăn mát tối đa 2 ngày và hâm nóng bằng lò nướng 180°C trong 5 phút.', 'korean', 'mon_lau_tiec', NULL, 'easy', 20, 15, 4, '/frigo/illustrations/delicious-meal.png', '["Dak bulgogi","Gà nướng","Hàn Quốc","Mặn ngọt","Cuốn rau"]', '["lunch","dinner"]', '["grill_roast","pan_fry"]', '["chicken","sesame","soybean","wheat"]', 338, 338.2, 1416, 26.5, 18.4, 4.4, 15.6, 0.9, 11.9, 839, 2.1, '["MEXT Hon-Mirin 16031","USDA FDC 168833","USDA FDC 169230","USDA FDC 169231","USDA FDC 169640","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172385","USDA FDC 174277"]', 'c5957f3b217229ee5baee0671cb331a26dfe07332d7b7f6a252aec97fcc4699b', '4d0e2c7e73fce62d8c6f2467e12ac21c8f0cd4c76a9c48ae015080597937201e', 4),
('imp-750cef719bf5f2f6', 'chao-kimchi-han', 315, 'Cháo kim chi trứng kiểu Hàn (Kimchi Juk)', 'Tô cháo kim chi sánh mịn đậm vị chua cay ấm bụng với trứng gà đánh ủ mềm, dầu mè thơm và rong biển vụn', 'Cháo kim chi Hàn Quốc (Kimchi Juk) là món cháo nóng hổi thanh nhẹ nhưng giàu hương vị nhờ bước xào kim chi chua cùng dầu mè và ép nhẹ cơm cho thơm béo trước khi ninh. Trứng gà được ủ chín mềm trong cháo nóng, kết hợp cùng rong biển vụn và hành lá tạo nên tô cháo ấm bụng cho bữa sáng hoặc ngày se lạnh.', 'Múc cháo nóng ra tô sâu lòng, rắc hành lá, rong biển khô cắt vụn, chút ớt bột Hàn và mè trắng rang lên trên; thưởng thức ngay khi còn nóng.', 'Cháo ngon nhất khi ăn ngay lúc vừa nấu xong; nếu để nguội sẽ đặc lại, khi hâm nóng chỉ cần thêm 50–100 ml nước lọc và khuấy đều trên lửa nhỏ.', 'korean', 'mon_nhanh_sang', NULL, 'easy', 10, 25, 3, '/frigo/illustrations/delicious-meal.png', '["Kimchi juk","Cháo Hàn","Bữa sáng","Cay ấm","Trứng gà"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["egg","fish","sesame","soybean","wheat"]', 348, 348.3, 1457, 11.3, 12, 2.5, 48.7, 2.8, 5, 1071, 2.68, '["Korean Chili Flake Ref","USDA FDC 168456","USDA FDC 169230","USDA FDC 169655","USDA FDC 169756","USDA FDC 170005","USDA FDC 170150","USDA FDC 170497","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173647","USDA FDC 174277"]', '11a9c6dd0fc07d67694f982adf43440118425cc408550deb1590185444ac8f34', '491c49589409ae0be299c27cd02c5e7ebc1d99c71cf2b8be4045114692d2a303', 4),
('imp-28d20ebe44b82a22', 'nam-xao-tuong-han', 316, 'Nấm đùi gà xào tương kiểu Hàn', 'Nấm đùi gà thái miếng dày xào săn bóng với nước tương, dầu hào, tỏi phi và ớt sừng giòn dai thanh ngọt', 'Nấm đùi gà xào tương là món banchan (món phụ) quen thuộc trên mâm cơm Hàn Quốc nhờ cách làm nhanh gọn chỉ trong 20 phút. Nấm đùi gà xào lửa vừa giữ được độ dai giòn sần sật, thấm đều hỗn hợp nước tương đặc, dầu hào và mè rang thơm bùi.', 'Bày nấm ra đĩa nhỏ rắc hành lá và mè trắng rang; dùng nóng với cơm trắng hoặc để nguội làm món ăn kèm trong hộp cơm văn phòng vẫn giữ độ giòn dai.', 'Bảo quản trong hộp kín ở ngăn mát tủ lạnh tới 3 ngày; có thể ăn nguội kiểu banchan hoặc đảo lại nhanh trên chảo nóng 1 phút.', 'korean', 'mon_xao', NULL, 'easy', 10, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Banchan","Nấm đùi gà","Hàn Quốc","Xào tương","Món nhanh"]', '["lunch","dinner"]', '["stir_fry"]', '["molluscs","sesame","soybean","wheat"]', 165, 165.3, 691, 5.4, 11.4, 1.6, 13.8, 3.4, 5.1, 786, 1.96, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170150","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 174277"]', '1aa38449437ecdc8e1cabe7818b03852208b74bb5809257ec181a3e364c52f46', '0c17b36d2426611b912ea9d330b112e384c4db5194681408c1f9f221181295d4', 4),
('imp-922028bd2fb07eb8', 'dau-phu-chien-tuong-han', 317, 'Đậu phụ chiên sốt tương hành kiểu Hàn (Dubu Buchim)', 'Đậu phụ chiên áp chảo vàng giòn hai mặt, rim nhanh cùng sốt tương tỏi hành siro ngô sánh bóng đậm đà', 'Đậu phụ chiên sốt tương hành (Dubu Jorim / Dubu Buchim) là món banchan truyền thống có mặt trong hầu hết bữa cơm Hàn Quốc. Miếng đậu phụ chắc được thấm khô và áp chảo vàng đều hai mặt rồi rim nhẹ trong nước tương, siro ngô, tỏi băm và ớt bột tạo nên lớp áo bóng mặn ngọt hài hòa.', 'Xếp đậu phụ ra đĩa, chan phần sốt tương hành sánh bóng lên trên và rắc mè trắng rang; dùng nóng hay nguội cùng cơm trắng đều rất ngon.', 'Có thể bảo quản ngăn mát tủ lạnh tới 3 ngày trong hộp kín; món này ăn nguội kiểu banchan vẫn đậm đà hoặc hâm nóng nhẹ bằng chảo 2 phút.', 'korean', 'mon_chien', NULL, 'easy', 10, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Dubu buchim","Đậu phụ","Banchan","Hàn Quốc","Chiên sốt"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["sesame","soybean","wheat"]', 271, 271.1, 1134, 18, 19.5, 2.8, 11.2, 2.5, 6.5, 778, 1.94, '["Korean Chili Flake Ref","USDA FDC 168836","USDA FDC 169230","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173647","USDA FDC 174277"]', 'a839b902adbcad5a246ed11c992832f14ef29813cca345f524911f5704f15940', 'c8ea81420518f570a85813b6274d46ea9ba593d18afbd9bc8d4578377720bd29', 4),
('imp-b575db6fcd68a387', 'canh-trung-han', 318, 'Canh trứng kiểu Hàn (Gyeran Guk)', 'Tô canh trứng thanh nhẹ nấu nước dùng tảo bẹ ngọt tự nhiên, vân trứng tơ mềm mịn thơm hành lá và dầu mè', 'Canh trứng Gyeran Guk là món canh nhà quốc dân của Hàn Quốc vì chỉ mất 15 phút chế biến nhưng vô cùng ấm bụng và dễ tiêu hóa. Nước dùng đun cùng tảo bẹ kombu ngọt thanh tự nhiên, nêm nhẹ nước tương và nước mắm rồi rưới trứng gà đánh tan tạo thành những vân trứng mềm mịn như mây.', 'Múc canh ra tô nóng, rắc chút tiêu đen và nhỏ vài giọt dầu mè thơm; ăn kèm cơm trắng nóng hoặc chan trực tiếp cơm vào canh cho bữa sáng nhẹ nhàng.', 'Canh trứng nên dùng hết trong bữa để giữ vân trứng mềm mượt và không bị tanh; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 12 giờ và đun sôi nhẹ lại.', 'korean', 'mon_canh', NULL, 'easy', 5, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gyeran guk","Canh trứng","Hàn Quốc","Thanh đạm","Món nhanh"]', '["breakfast","lunch","dinner"]', '["simmer"]', '["egg","fish","sesame","soybean","wheat"]', 112, 111.6, 467, 8.4, 7.2, 2.1, 3.1, 0.5, 0.6, 891, 2.23, '["USDA FDC 168457","USDA FDC 169230","USDA FDC 170005","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '21e84ec0f5d392b884efedfc34da3b92822d4ccb519b2915d1a591a136535a5a', '963259b5d459c3161fe24cef3cabe6afc4652909bbac5714da33b5fe4626de5b', 4),
('imp-53933600fa3853f3', 'bo-xao-nam-han', 319, 'Thịt bò xào nấm kiểu Hàn', 'Thịt bò thái lát mỏng ướp sốt tương mè tỏi đường xào lửa lớn cùng nấm đùi gà giòn ngọt và hành tây', 'Thịt bò xào nấm kiểu Hàn kết hợp hương vị bulgogi mặn ngọt thơm dầu mè với nấm đùi gà thái lát dọc dai giòn và hành tây ngọt thanh. Thịt bò được thái mỏng ngang thớ và ướp thấm gia vị trước khi xào nhanh trên chảo nóng, giúp thịt mềm mọng mà không bị ra nước.', 'Dọn thịt bò và nấm nóng hổi ra đĩa, rắc hạt mè trắng rang lên trên; ăn kèm cơm trắng nóng hoặc cuốn cùng rau xà lách và kim chi.', 'Có thể ướp thịt bò trước trong ngăn mát tới 12 giờ; món xào ngon nhất khi ăn nóng ngay, nếu bảo quản tủ mát tối đa 24 giờ và đảo lại nhanh trên chảo nóng 1–2 phút.', 'korean', 'mon_xao', NULL, 'easy', 20, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Bulgogi xào","Thịt bò","Nấm đùi gà","Hàn Quốc","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","sesame","soybean","wheat"]', 435, 435.1, 1821, 31.9, 26.9, 7.3, 17.6, 2.9, 9.1, 847, 2.12, '["USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170187","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 174277"]', '543b94203f7714453264c4fdac486ab87dd50e0e4dc328db7aa0ba94e807f99b', '3c782f0eb8065c8f21b8a6c806663185133698f5fd32fa24e94f203279ef04c7', 4),
('imp-81fc284c0bafa826', 'tom-xao-sa-ot-thai', 320, 'Tôm tươi xào sả ớt lá chanh kiểu Thái', 'Tôm tươi săn ngọt xào lửa lớn cùng sả băm, tỏi, ớt hiểm và lá chanh Thái thơm nồng, áo đều sốt dầu hào xì dầu đường thốt nốt óng mượt', 'Món tôm xào sả ớt kiểu Thái nổi bật nhờ sự kết hợp giữa sả băm, tỏi, ớt hiểm và lá chanh Kaffir thơm nồng đặc trưng, quyện cùng nước sốt xào sánh bóng từ dầu hào, xì dầu và đường thốt nốt.', 'Bày tôm xào sả ớt nóng hổi ra đĩa, rưới phần sốt sánh thơm trong chảo lên trên và dọn ăn ngay với cơm trắng dẻo.', 'Tôm xào ngon nhất khi ăn nóng ngay lúc thịt còn giòn ngọt; nếu còn dư bảo quản ngăn mát 24 giờ và làm nóng nhanh trên chảo lửa vừa khoảng 1–2 phút.', 'thai', 'mon_xao', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món xào","Tôm tươi","Sả ớt","Đậm đà"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","fish","molluscs","shrimp","soybean","wheat"]', 216, 216.3, 905, 26, 7.7, 1.2, 11.9, 0.5, 4.7, 1162, 2.91, '["Citrus Leaf Culinary Ref","Dark Soy Sauce Label Ref","USDA FDC 168573","USDA FDC 169230","USDA FDC 170106","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179","USDA FDC Palm Sugar Ref"]', '3406ef52ca5a61b090f2ccf657369cae798eec75309e291f53d60fd6256c7f18', 'a95fef2099fccbbc1c12a966d1bf90f86f85f18f64d2c32ec32b17ea9badd496', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-15e4185437e9198c', 'mi-xao-pad-thai-tom', 321, 'Mì xào Pad Thai tôm truyền thống', 'Bánh phở khô ngâm mềm xào nhanh lửa lớn với sốt me đường thốt nốt thắng caramen, tôm áp chảo, đậu phụ ép, trứng gà, giá đỗ và hẹ tươi', 'Công thức Pad Thai tôm truyền thống cân chỉnh chuẩn cho 3 phần ăn, giữ nguyên kỹ thuật thắng caramen đường thốt nốt cùng nước cốt me chua dịu, đậu phụ ép chiên cạnh vàng và sợi trứng tơi quyện quanh từng sợi bánh phở.', 'Gắp Pad Thai ra 3 đĩa, đặt tôm áp chảo lên trên, rắc đậu phộng rang giã dập và ớt khô xay; dọn kèm múi chanh, giá đỗ và hẹ sống.', 'Thưởng thức ngon nhất ngay lúc vừa xào xong; phần dư bảo quản ngăn mát tối đa 24 giờ và làm nóng trên chảo với 1 muỗng canh nước lọc.', 'thai', 'mon_xao', NULL, 'medium', 25, 20, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Pad Thai","Mì xào","Truyền thống","Tôm tươi"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","egg","fish","peanut","shrimp","soybean"]', 772, 772.3, 3232, 44.5, 28.5, 4.9, 88.7, 6.6, 27.9, 1721, 4.3, '["USDA / Asian Dried Shrimp Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169745","USDA FDC 169918","USDA FDC 169963","USDA FDC 169994","USDA FDC 170499","USDA FDC 171287","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172430","USDA FDC 172475","USDA FDC 173647","USDA FDC 175179","USDA FDC Palm Sugar Ref"]', 'e9688803f56e52ce29df722f271dde523c5b23f16535e34a65f4b3566a1a71e2', '43174c886f2e91af5f7707bf7841412f95c30b9e68a0918ca2b1bb9c9fb86c70', 4),
('imp-cc62ea4de6a7436b', 'goi-dua-tom-thai', 322, 'Gỏi dứa tôm tươi chua cay kiểu Thái', 'Dứa chín vàng mọng trộn cùng tôm luộc giòn ngọt, hành tím thái mỏng, ớt hiểm và nước mắm chanh chua cay thanh mát, rắc đậu phộng rang bùi', 'Gỏi dứa tôm tươi kiểu Thái là món khai vị giải ngấy tuyệt vời với vị ngọt mọng tự nhiên của dứa chín hòa quyện tôm luộc giòn săn, vị chua cay mặn ngọt cân bằng và hương bạc hà the mát.', 'Bày gỏi dứa tôm ra đĩa rộng, rắc đậu phộng rang giã dập cùng lá bạc hà xắt rối lên trên; dùng ngay làm món khai vị hoặc ăn kèm cơm trắng.', 'Dứa chín dễ tiết nước sau khi trộn muối mắm nên món gỏi ngon nhất khi dùng ngay trong vòng 1 giờ sau khi trộn.', 'thai', 'mon_cuon_nom', NULL, 'easy', 15, 5, 3, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Gỏi trộn","Dứa chín","Tôm tươi","Khai vị"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["crustaceans","fish","peanut","shrimp"]', 263, 262.7, 1099, 24, 8.1, 1.1, 28, 4.2, 19.3, 1057, 2.64, '["USDA FDC 168155","USDA FDC 169124","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 172185","USDA FDC 172430","USDA FDC 173474","USDA FDC 173647","USDA FDC 175179"]', '490144712173babacf18df90449d8c404ab7202f9c750ce6e2a4807b5952af60', '6760c2a4d072f36a5df5f0cab6ba0b2f178b1ad690d97cb2daf0e7cbb82b4b99', 4),
('imp-3d7573766352454e', 'canh-ga-sa-thai', 323, 'Canh gà nấu sả nấm chua thanh kiểu Thái (Tom Yum Gai)', 'Thịt đùi gà hầm mềm trong nước dùng gà trong thanh dậy hương hành tím nướng, sả, riềng, lá chanh Thái cùng nấm đùi gà giòn và vị chua me chanh', 'Món canh gà sả nấm kiểu Thái mang hương vị chua cay thanh tao từ nước cốt me kết hợp chanh tươi, hành tím áp chảo thơm lừng cùng sả, riềng, lá chanh Thái, thịt đùi gà mềm ngọt và nấm đùi gà giòn sần sật.', 'Múc canh gà sả nấm nóng hổi ra tô lớn, rắc hành lá thái nhỏ lên trên và ăn kèm cơm trắng nóng.', 'Có thể bảo quản trong hộp kín ngăn mát tối đa 2 ngày (nên vớt bỏ xác sả riềng trước khi cất); khi ăn hâm nóng lại trên lửa vừa tới sôi lăn tăn.', 'thai', 'mon_canh', NULL, 'medium', 15, 25, 4, '/frigo/illustrations/delicious-meal.png', '["Thái Lan","Món canh","Thịt gà","Nấm đùi gà","Chua cay"]', '["lunch","dinner"]', '["simmer"]', '["chicken","fish"]', 270, 270.3, 1132, 25.1, 11.8, 3.2, 16.7, 2.6, 7.7, 1729, 4.32, '["Citrus Leaf Culinary Ref","USDA / SE Asian Galangal Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 168580","USDA FDC 169230","USDA FDC 169655","USDA FDC 169918","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 172185","USDA FDC 172385","USDA FDC 172883"]', 'a82b1a0fc2bf14448dd30e2020525e7939be6909f339965f3b1bfa08bf983dd1', 'cf4ff082166e43e0a2ad6f661c79c6f8fe71c01f5533874132681ba4e60ef573', 4),
('imp-88fc351665d5e9fc', 'bo-xao-ot-thai', 324, 'Bò xào ớt kiểu Thái', 'Thịt bò thăn xào nhanh trên lửa lớn cùng ớt chuông, ớt hiểm, hành tây và sốt dầu hào sánh đậm vị Thái', 'Bò xào ớt kiểu Thái là món xào lửa lớn nổi tiếng với từng lát thịt bò mềm mọng áo đều lớp sốt dầu hào, xì dầu đậm đà, hòa cùng vị cay thơm của ớt hiểm, tỏi phi và độ giòn ngọt tự nhiên của ớt chuông, hành tây.', 'Dọn nóng ngay ra đĩa, rắc thêm hành lá; dùng kèm cơm trắng nóng hổi và có thể thêm một quả trứng ốp la lòng đào kiểu Thái.', 'Ngon nhất khi ăn ngay sau khi xào; nếu còn dư, để nguội rồi bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo nóng 1–2 phút.', 'thai', 'mon_xao', NULL, 'easy', 15, 12, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Thịt bò","Ẩm thực Thái","Cay nồng","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","fish","molluscs","soybean","wheat"]', 333, 333.1, 1394, 23.4, 19.3, 5.4, 17.1, 5.3, 6.3, 1037, 2.59, '["Dark Soy Sauce Label Ref","USDA FDC 168437","USDA FDC 169230","USDA FDC 169655","USDA FDC 169698","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170108","USDA FDC 170187","USDA FDC 170933","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172883","USDA FDC 173647","USDA FDC 174277"]', 'b9124173535dfc3f7c7ec602f64492404e4d9ebf72ef5c5a1d66c3cc5f98b1c0', 'f925fc6eadbab9d2f980b752a1c9fdf433e6f4b54815c73817ee8057ac1b568c', 4),
('imp-4ec49419e966f676', 'ca-nuong-muoi-sa', 325, 'Cá diêu hồng nướng muối sả kiểu Thái', 'Cá nguyên con giữ vảy nhồi sả và lá chanh Kaffir bọc muối hạt nướng thơm, thịt trắng mọng chấm sốt hải sản xanh cay nồng', 'Cá diêu hồng nướng muối sả kiểu Thái (Pla Pao) giữ nguyên lớp vảy cá bọc muối hạt mịn giúp khóa trọn độ ẩm và vị ngọt tự nhiên của thớ thịt cá trắng bên trong, thơm dịu mùi sả và lá chanh Kaffir, chấm cùng sốt chanh tỏi ớt chua cay đặc trưng.', 'Lột bỏ lớp da bọc muối khi ăn, dọn phần thịt cá trắng nóng hổi kèm bún tươi, rau xà lách và chén sốt chấm chanh tỏi ớt hải sản.', 'Nên ăn hết khi cá còn ấm nóng; phần thịt cá gỡ sẵn có thể bọc kín bảo quản ngăn mát tối đa 24 giờ, làm nóng lại bằng nồi chiên không dầu hoặc áp chảo 3 phút.', 'thai', 'mon_lau_tiec', NULL, 'medium', 20, 40, 4, '/frigo/illustrations/delicious-meal.png', '["Món nướng","Cá diêu hồng","Ẩm thực Thái","Nướng muối","Tiệc gia đình"]', '["lunch","dinner"]', '["grill_roast"]', '["fish","wheat"]', 245, 245.4, 1026, 39.4, 4.8, 1.3, 9.7, 0.7, 4.2, 1301, 3.25, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 169761","USDA FDC 170106","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', 'd62c1eb63358727dc5dab4f8ddaedc748d1dae72a89c48b21cd6d4731e3518ec', '71a03252d0e0dbc64f25c251b6471e679362bbbe35f4c2b0436618d878f73058', 4),
('imp-e47b2f01ee81031a', 'mi-xao-dua-tom-thai', 326, 'Mì xào dứa tôm kiểu Thái', 'Sợi hủ tiếu gạo xào dai mềm với tôm tươi, dứa chín chua ngọt, trứng gà, giá đỗ và sốt me đậm vị Pad Thai', 'Mì xào dứa tôm kiểu Thái kết hợp sợi hủ tiếu gạo dai mềm áo sốt me chua ngọt cùng tôm tươi săn giòn, dứa chín mọng nước, trứng gà tơi béo và đậu phộng rang bùi thơm, mang hương vị đường phố Bangkok tươi mới.', 'Bày mì ra đĩa lớn, rắc hành lá tươi và đậu phộng rang giã dập lên trên; dọn nóng kèm múi chanh tươi và ít ớt bột khô tùy khẩu vị.', 'Nên thưởng thức ngay khi sợi mì còn nóng dẻo; phần dư có thể bảo quản ngăn mát tối đa 24 giờ và làm nóng bằng chảo chống dính với 1 muỗng canh nước.', 'thai', 'mon_xao', NULL, 'easy', 25, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Mì xào","Pad Thai","Tôm tươi","Dứa thơm","Ẩm thực Thái"]', '["lunch","dinner"]', '["stir_fry"]', '["crustaceans","egg","fish","peanut","shrimp","soybean","wheat"]', 619, 618.6, 2589, 30.4, 22.3, 3.7, 77, 5.2, 19.1, 1713, 4.28, '["USDA FDC 168155","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 169745","USDA FDC 169918","USDA FDC 169963","USDA FDC 170005","USDA FDC 171287","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '37fc230fce50a0143635905fef8371defe76b656707fc3e53c2675b96159eb11', '26779337a3ba10e1083221bb37b461634638ed134c6e87f6cb84913092c0b624', 4),
('imp-192973f6e1b702b5', 'dau-phu-chien-sot-cay-thai', 327, 'Đậu phụ chiên sốt cay kiểu Thái', 'Đậu phụ chiên vỏ giòn ruộm rưới sốt tương ớt tỏi, đường thốt nốt và nước cốt chanh chua cay ngọt hài hòa', 'Đậu phụ chiên sốt cay kiểu Thái hấp dẫn với lớp vỏ ngoài chiên vàng giòn rụm, bên trong vẫn mềm béo, quyện cùng nước sốt chua cay mặn ngọt từ đường thốt nốt, nước cốt chanh, tương ớt và tỏi phi thơm lừng.', 'Xếp đậu phụ chiên nóng ra đĩa, rưới đều sốt cay hoặc dọn chén sốt chấm riêng bên cạnh; rắc ngò rí, hành lá và vài lát ớt hiểm, dùng làm món khai vị hoặc ăn kèm cơm trắng.', 'Đậu chiên giòn nên ăn ngay lúc nóng; nếu dư, tách riêng đậu và sốt để tủ mát 24 giờ, chiên lại đậu trong nồi chiên không dầu 4 phút ở 180°C trước khi rưới sốt.', 'thai', 'mon_chien', NULL, 'easy', 20, 15, 3, '/frigo/illustrations/delicious-meal.png', '["Đậu phụ chiên","Món chay","Khai vị","Ẩm thực Thái","Chua cay"]', '["lunch","dinner"]', '["deep_fry","assemble"]', '["soybean","wheat"]', 404, 404.3, 1691, 20.4, 22.1, 3.2, 36.3, 3.4, 14.9, 1023, 2.56, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169698","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 171413","USDA FDC 172475","USDA FDC 174277","USDA FDC Palm Sugar Ref","USDA FDC Sriracha Ref"]', 'a6777df67ee49288a65f8ce9fa97899c7a1f5650f253d44d9ce9746b8b26f19b', 'e0df246cf9b1c255028596d2ff500a98037e7230f87f2debf0c3968c7c637480', 4),
('imp-2a705e2ff35573b1', 'canh-chua-me-tom-thai', 328, 'Canh chua me tôm kiểu Thái', 'Canh chua me Gaeng Som dịu thanh với tôm tươi, cà chua, nấm đùi gà và thịt cá nghiền sánh nhẹ chuẩn vị Thái', 'Canh chua me tôm kiểu Thái (Gaeng Som) mang vị chua thanh dịu từ me chín kết hợp hậu ngọt của đường thốt nốt, nước dùng sánh nhẹ nhờ thịt cá phi lê nghiền mịn, ăn kèm tôm tươi ngọt thịt, cà chua và nấm đùi gà giòn ngon.', 'Múc canh chua me nóng ra tô lớn, rắc hành lá và vài lát ớt hiểm tươi lên trên; dọn ăn nóng kèm cơm trắng hoặc trứng chiên kiểu Thái.', 'Canh ngon nhất trong ngày; bảo quản phần dư trong hộp kín ở ngăn mát tối đa 24 giờ, đun sôi nhẹ lại trước khi ăn (tránh đun lâu làm tôm bị dai).', 'thai', 'mon_canh', NULL, 'easy', 20, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Canh chua","Tôm tươi","Gaeng Som","Ẩm thực Thái","Thanh mát"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 211, 211.3, 885, 25.5, 2.6, 0.6, 24.1, 3.6, 14.4, 1316, 3.29, '["Asian Shrimp Paste Ref","USDA FDC 168155","USDA FDC 168580","USDA FDC 169230","USDA FDC 169918","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171319","USDA FDC 172185","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 175148","USDA FDC 175179","USDA FDC Palm Sugar Ref"]', '9ba186380118971ee20883248094ad55193eb264cad2e8a0456d899a98224c14', 'be72bb899d807fa79d123731256a2a70d383ae9c0dbdd38e9a276b4caf23d1e9', 4),
('imp-f050984a2c4deb91', 'goi-nam-chua-cay-thai', 329, 'Gỏi nấm chua cay kiểu Thái', 'Nấm đùi gà, nấm kim châm và nấm mỡ chần giòn trộn hành tây tím, cà chua bi cùng nước sốt chanh tỏi ớt chay thanh mát', 'Gỏi nấm chua cay kiểu Thái kết hợp ba loại nấm chần giòn ngọt là nấm đùi gà, nấm mỡ và nấm kim châm, trộn đều với hành tây tím, cà chua bi, cần tây và nước sốt chanh tỏi ớt chua cay mặn ngọt bùng vị, rắc đậu phộng rang bùi béo.', 'Bày gỏi nấm ra đĩa sâu lòng, rắc đậu phộng rang giã dập lên mặt; dùng ngay làm món khai vị thanh mát hoặc ăn kèm cơm trắng, xôi nếp đều hợp.', 'Gỏi nên trộn và ăn hết trong vòng 2 giờ để nấm giữ độ giòn và không ra nước; nếu chuẩn bị trước, bảo quản riêng nấm đã chần ráo và chén nước trộn trong ngăn mát tối đa 12 giờ.', 'thai', 'mon_cuon_nom', NULL, 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Gỏi nấm","Món chay","Khai vị","Ẩm thực Thái","Thanh mát"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["celery","peanut","soybean","wheat"]', 217, 217.4, 909, 11.7, 9.8, 1.3, 26.8, 7, 10.9, 1037, 2.59, '["USDA FDC 168155","USDA FDC 168580","USDA FDC 169230","USDA FDC 169251","USDA FDC 169253","USDA FDC 169655","USDA FDC 169988","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 172430","USDA FDC 173468","USDA FDC 174277"]', '639dd78768e775b3901c292be6a0245c45f27bd6097d67fc7b72bd4e41e293c2', '0faa57b2cac9ee2a8a31fc64a3c2fb958b4f2f0a154846be403bc391b7dda3d1', 4);

