('imp-f050984a2c4deb91_v4_ing_12', 'imp-f050984a2c4deb91', 11, 'GARLIC', 'Tỏi khô', '1/2 củ (12–13 g, ~4 tép)', 'bóc vỏ, băm thật nhuyễn', 'sauce', 0.5, 'piece', 12.5, 0.87, 10.88, 0, 1),
('imp-f050984a2c4deb91_v4_ing_13', 'imp-f050984a2c4deb91', 12, 'CHILI', 'Ớt hiểm đỏ tươi', '2 quả (10 g)', 'rửa sạch, bỏ cuống, băm nhỏ hoặc thái lát mỏng', 'sauce', 2, 'piece', 10, 0.9, 9, 0, 1),
('imp-f050984a2c4deb91_v4_ing_14', 'imp-f050984a2c4deb91', 13, 'PEANUT', 'Đậu phộng rang chín', '55 g', 'bỏ vỏ lụa, giã dập thô để rắc lên đĩa gỏi', 'garnish', 55, 'g', 55, 1, 55, 0, 1),
('imp-f050984a2c4deb91_v4_ing_15', 'imp-f050984a2c4deb91', 14, 'SALT', 'Muối ăn (chần nấm)', '5 g (1 muỗng cà phê)', 'hòa vào nồi nước sôi để chần nấm sạch và giòn hơn', 'main', 5, 'g', 5, 0.05, 0.25, 0, 1),
('imp-f050984a2c4deb91_v4_ing_16', 'imp-f050984a2c4deb91', 15, 'COOKING_WATER', 'Nước lọc (chần nấm)', '1000 ml', 'đun sôi để chần từng loại nấm rồi vớt bỏ nước', 'main', 1000, 'ml', 1000, 0, 0, 0, 0);

INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-8ebb3021c30c48f8_v4_step_1', 'imp-8ebb3021c30c48f8', 1, 'marinate', 'Thái ướp ức gà và pha sốt xào xì dầu', 'Thái lát mỏng 340 g ức gà phi lê rồi bóp đều cùng 10 ml xì dầu nhạt, 2 g đường cát trắng và 15 ml nước lọc, ướp nghỉ 12 phút cho thịt ngậm nước mềm mọng. Pha sẵn hỗn hợp sốt gồm 25 ml dầu hào, 15 ml xì dầu nhạt còn lại và 15 ml xì dầu đen đặc Thái, chia đều thành 3 phần.', NULL, 12),
('imp-8ebb3021c30c48f8_v4_step_2', 'imp-8ebb3021c30c48f8', 2, 'prep', 'Gỡ tơi bánh phở và sơ chế cải thìa', 'Gỡ tơi nhẹ tay 600 g bánh phở tươi thành 3 phần (~200 g/phần) để khi xào áp chảo từng suất không bị dồn cục. Rửa sạch 225 g cải thìa, thái xéo phần cọng và cắt khúc phần lá; băm nhỏ 3/4 củ tỏi khô; chuẩn bị sẵn 3 quả trứng gà bên bếp.', 'Xào Pad See Ew từng phần 1 suất ăn trên chảo rộng giúp sợi phở tiếp xúc mặt chảo nóng, xém cạnh thơm khói mà không bị đứt nát.', NULL),
('imp-8ebb3021c30c48f8_v4_step_3', 'imp-8ebb3021c30c48f8', 3, 'cook', 'Áp chảo chín thơm thịt ức gà', 'Làm nóng chảo đáy rộng trên lửa lớn với 15 ml dầu ăn, dàn đều thịt ức gà đã ướp thành một lớp mỏng và áp chảo khoảng 3 phút đến khi hai mặt hơi xém vàng, thịt chín trắng hoàn toàn thì trút ra đĩa riêng.', 'Áp chảo thịt ức gà thành một lớp mỏng trên lửa lớn giúp thịt săn chín nhanh và giữ được độ mọng nước bên trong.', 3),
('imp-8ebb3021c30c48f8_v4_step_4', 'imp-8ebb3021c30c48f8', 4, 'cook', 'Phi tỏi, đánh trứng tơi và xào cải thìa', 'Cho khoảng 13 ml dầu ăn cùng 1/3 lượng tỏi băm vào chảo xào thơm trên lửa vừa lớn trong 20 giây, đập 1 quả trứng gà vào đánh vỡ lòng đỏ chờ đông một nửa rồi đảo tơi. Cho ngay 1/3 lượng cải thìa vào đảo nhanh tay 15 giây cho rau xanh bóng.', NULL, NULL),
('imp-8ebb3021c30c48f8_v4_step_5', 'imp-8ebb3021c30c48f8', 5, 'cook', 'Áp chảo xém bánh phở cùng sốt xì dầu', 'Cho 1 phần bánh phở (200 g), 1 phần nước sốt xì dầu và 1/3 phần đường cát trắng còn lại (~7 g) vào chảo, tăng lửa lớn và đảo hất nhẹ nhàng cho sợi phở áo đều màu nâu bóng. Dàn phẳng mặt phở để yên 20 giây cho hơi xém cạnh thơm mùi khói chảo rồi lật áp xém thêm 20 giây nữa.', 'Dùng thao tác hất chảo hoặc xẻng lùa từ dưới đáy thay vì chọc thẳng vào sợi phở sẽ giữ sợi bánh nguyên đẹp.', 2),
('imp-8ebb3021c30c48f8_v4_step_6', 'imp-8ebb3021c30c48f8', 6, 'finish', 'Trộn thịt gà và lặp lại cho các phần còn lại', 'Trút 1/3 phần ức gà đã xào vào chảo (chừa lại nước thừa dưới đĩa), đảo nhanh 15 giây cho quyện đều rồi múc ra đĩa. Lau nhanh mặt chảo bằng khăn giấy và lặp lại bước 4–6 cho 2 phần còn lại; rắc 2 g tiêu trắng xay lên trên và dùng nóng.', NULL, NULL),
('imp-8e2f2113f406a7d8_v4_step_1', 'imp-8e2f2113f406a7d8', 1, 'prep', 'Ngâm que tre và xay nhuyễn sốt ướp sả', 'Ngâm que tre vào nước lạnh trước ít nhất 30 phút để que không bị cháy khi nướng. Cho 6 cây sả thái lát mỏng, 1 củ tỏi bóc vỏ và 15 g rễ ngò rí vào máy xay nhuyễn mịn; tiếp tục thêm 45 ml nước cốt dừa, lòng trắng của 1 quả trứng gà, 8 g bột bắp, 15 ml xì dầu nhạt, 20 ml dầu hào, 8 g đường cát trắng, 4 g muối ăn, 2 g tiêu đen xay và 10 ml dầu ăn vào xay quyện thành hỗn hợp sốt ướp sệt thơm.', 'Ngâm ngập que tre trong nước đủ 30 phút sẽ giúp đầu que không bị bén lửa hay đen sạm trên chảo nóng.', 30),
('imp-8e2f2113f406a7d8_v4_step_2', 'imp-8e2f2113f406a7d8', 2, 'marinate', 'Thái dải và ướp thịt đùi gà thấm vị', 'Cắt 600 g thịt đùi gà rút xương thành từng dải dài dày khoảng 1 cm, cho vào tô lớn đổ toàn bộ hỗn hợp sốt sả vừa xay vào bóp trộn đều. Bọc kín tô để ướp trong ngăn mát tối thiểu 30 phút cho gia vị thấm sâu.', NULL, 30),
('imp-8e2f2113f406a7d8_v4_step_3', 'imp-8e2f2113f406a7d8', 3, 'prep', 'Xiên thịt gà vào que tre gọn đẹp', 'Luồn từng dải thịt gà dọc theo chiều dài que tre đã ngâm nước, dàn phẳng nhẹ để miếng thịt áp đều và chừa lại khoảng 1/3 đuôi que trống làm tay cầm tiện lợi.', 'Xiên dải thịt gà theo chiều dọc ôm sát que tre giúp thịt chín đều cả hai mặt khi áp chảo.', NULL),
('imp-8e2f2113f406a7d8_v4_step_4', 'imp-8e2f2113f406a7d8', 4, 'cook', 'Áp chảo mặt đầu và phết nước cốt dừa', 'Làm nóng chảo gang rộng hoặc vỉ nướng trên lửa vừa lớn với 10 ml dầu ăn còn lại, xếp các xiên gà vào áp chảo mặt đầu khoảng 4 phút đến khi xém vàng thơm lừng. Dùng cọ sạch phết nhẹ 15 ml nước cốt dừa giữ riêng lên mặt trên các xiên gà.', 'Chỉ dùng nước cốt dừa sạch chưa chạm thịt sống để phết lên xiên khi nướng nhằm đảm bảo an toàn vệ sinh thực phẩm.', 4),
('imp-8e2f2113f406a7d8_v4_step_5', 'imp-8e2f2113f406a7d8', 5, 'cook', 'Lật mặt nướng chín hoàn toàn các xiên gà', 'Lật đều các xiên gà sang mặt còn lại và nướng tiếp khoảng 5 phút nữa trên lửa vừa đến khi hai mặt xém vàng đều, thịt gà chín kỹ hoàn toàn bên trong không còn màu hồng và nước thịt chảy ra trong.', NULL, 5),
('imp-8e2f2113f406a7d8_v4_step_6', 'imp-8e2f2113f406a7d8', 6, 'finish', 'Nghỉ thịt và dọn kèm chanh tươi', 'Gắp các xiên gà nướng ra đĩa để nghỉ 2 phút cho nước thịt ổn định mọng mềm, xếp 1 quả chanh tươi cắt múi cau bên cạnh và dọn nóng.', NULL, NULL),
('imp-574963de4a60d466_v4_step_1', 'imp-574963de4a60d466', 1, 'prep', 'Làm sạch, khứa mình cá và chuẩn bị xửng hấp', 'Thấm thật khô 650 g cá chẽm đã làm sạch, dùng dao sắc khứa 3 đường chéo sâu tới sát xương trên mỗi mặt mình cá để hơi nóng thấm đều nhanh chín. Đập dập 2 cây sả cắt khúc, nhồi một nửa vào bụng cá và lót phần còn lại dưới đáy đĩa chịu nhiệt rồi đặt cá lên trên.', 'Thấm khô mình cá và lót sả bên dưới giúp cá không bị dính đĩa và khử sạch mùi tanh khi hấp.', NULL),
('imp-574963de4a60d466_v4_step_2', 'imp-574963de4a60d466', 2, 'cook', 'Hấp cá chín mềm giữ trọn vị ngọt', 'Đun sôi mạnh nồi nước hấp trên lửa lớn rồi đặt đĩa cá vào xửng, đậy kín nắp và hấp liên tục 11 phút đến khi mắt cá đục trắng hẳn và dùng đũa tách nhẹ phần thịt dày nhất thấy chín trắng róc xương hoàn toàn.', 'Chỉ đặt cá vào xửng khi nước đã sôi bùng để thịt cá săn nhanh bên ngoài và giữ được vị ngọt mọng bên trong.', 11),
('imp-574963de4a60d466_v4_step_3', 'imp-574963de4a60d466', 3, 'prep', 'Sơ chế tỏi, ớt hiểm và rau thơm ăn kèm', 'Trong lúc hấp cá, băm thật nhỏ 1 củ tỏi khô và 4 quả ớt hiểm tươi, thái lát xéo 1 quả ớt hiểm còn lại để trang trí. Rửa sạch 30 g cần tàu cắt khúc 4 cm và thái nhỏ 15 g ngò rí; vắt lấy nước cốt 2,5 quả chanh tươi lọc bỏ hạt.', NULL, NULL),
('imp-574963de4a60d466_v4_step_4', 'imp-574963de4a60d466', 4, 'sauce', 'Nấu tan đường và pha sốt chanh tỏi ớt', 'Đun sôi 100 ml nước dùng gà với 12 g đường thốt nốt băm nhỏ trong nồi nhỏ khoảng 2 phút đến khi đường tan hoàn toàn rồi tắt bếp, đổ ra tô. Cho tỏi băm, ớt hiểm băm nhỏ, 35 ml nước mắm ngon và nước cốt chanh tươi vào khuấy đều nếm vừa vị chua cay nổi bật.', 'Cho nước cốt chanh và tỏi ớt vào tô nước dùng ấm thay vì đun sôi trực tiếp giúp tỏi giữ mùi thơm cay nồng và chanh không bị đắng.', 2),
('imp-574963de4a60d466_v4_step_5', 'imp-574963de4a60d466', 5, 'finish', 'Chuyển cá sang đĩa sạch và xếp cần tàu', 'Cẩn thận nhấc cá vừa hấp chín sang đĩa bầu dục sâu lòng, bỏ phần nước hấp cá đọng dưới đĩa cũ để món ăn không bị tanh, sau đó xếp phần lớn cần tàu cắt khúc quanh mình cá.', NULL, NULL),
('imp-574963de4a60d466_v4_step_6', 'imp-574963de4a60d466', 6, 'finish', 'Chan sốt nóng và hoàn thiện món cá hấp', 'Trộn 15 g ngò rí thái nhỏ vào tô sốt, khuấy đều rồi rưới toàn bộ sốt chanh tỏi ớt lên khắp mình cá, trang trí thêm vài lá cần tàu và ớt thái lát lên trên rồi dọn nóng ngay.', NULL, NULL),
('imp-295e7045e644d2ca_v4_step_1', 'imp-295e7045e644d2ca', 1, 'prep', 'Ngâm miến, tôm khô và thái mực cùng rau thơm', 'Ngâm 150 g miến khô trong nước lạnh 10 phút cho mềm đều; đồng thời ngâm 15 g tôm khô vào chút nước ấm 10 phút rồi vớt ráo. Thái khoanh 250 g mực ống làm sạch. Thái lát thật mỏng 2 cây sả và 25 g hành tím, cắt khúc 3/4 bó hành lá và 15 g ngò rí, nhặt 10 g lá bạc hà, thái lát 1 quả ớt hiểm.', 'Thái sả thật mỏng theo khoanh tròn để khi trộn gỏi không bị xơ cứng và tỏa mùi thơm dịu.', 10),
('imp-295e7045e644d2ca_v4_step_2', 'imp-295e7045e644d2ca', 2, 'cook', 'Luộc miến dai trong và xả nước lạnh', 'Đun sôi 1000 ml nước lọc trên lửa lớn, thả miến vào luộc nhanh 2 phút đến khi sợi miến chuyển trong mềm thì vớt ra xả ngay dưới vòi nước lạnh cho dai tơi, để thật ráo rồi dùng kéo cắt ngắn khoảng 10 cm.', 'Xả lạnh ngay sau khi luộc giúp sợi miến dong không bị dính bết và giữ được độ dai giòn.', 2),
('imp-295e7045e644d2ca_v4_step_3', 'imp-295e7045e644d2ca', 3, 'cook', 'Chần mực giòn ngọt vừa chín tới', 'Dùng tiếp nồi nước sôi đó chần 250 g mực trong 2 phút đến khi khoanh mực cuộn tròn trắng đục và chín hoàn toàn thì vớt ra ngâm nhanh tô nước nguội rồi để thật ráo nước.', NULL, 2),
('imp-295e7045e644d2ca_v4_step_4', 'imp-295e7045e644d2ca', 4, 'sauce', 'Giã tôm khô tỏi ớt và pha nước trộn gỏi', 'Cho tôm khô đã ngâm mềm cùng 1/2 củ tỏi và 2 quả ớt hiểm vào cối giã dập nhuyễn vừa để dậy vị ngọt thơm cay nồng. Khuấy tan 20 g đường thốt nốt băm nhỏ với 40 ml nước mắm ngon và nước cốt của 2 quả chanh tươi thành hỗn hợp sốt chua mặn ngọt hài hòa.', 'Giã tôm khô cùng tỏi ớt giúp nước trộn gỏi có vị ngọt umami đậm đà và mùi thơm quyện tự nhiên.', NULL),
('imp-295e7045e644d2ca_v4_step_5', 'imp-295e7045e644d2ca', 5, 'finish', 'Trộn miến, mực cùng các loại rau thơm', 'Cho miến đã ráo nước vào âu lớn, rưới nước trộn gỏi vào đảo đều cho từng sợi miến thấm gia vị. Tiếp tục cho mực chần, hỗn hợp tôm khô tỏi ớt giã, sả thái lát, hành tím, hành lá, ngò rí và lá bạc hà vào trộn nhẹ tay cho hòa quyện.', NULL, NULL),
('imp-295e7045e644d2ca_v4_step_6', 'imp-295e7045e644d2ca', 6, 'finish', 'Trình bày và rắc mè rang vàng', 'Nếm lại cho vừa vị chua cay mặn ngọt đặc trưng rồi bày gỏi miến mực ra đĩa sâu lòng, rắc 5 g mè trắng rang vàng cùng ớt thái lát lên trên và dùng ngay.', NULL, NULL),
('imp-5e0a488541baee5e_v4_step_1', 'imp-5e0a488541baee5e', 1, 'prep', 'Thái hành lá, ớt hiểm và chuẩn bị giấy thấm dầu', 'Thái nhỏ 3/4 bó hành lá gồm cả đầu trắng và lá xanh, thái lát mỏng 2 quả ớt hiểm đỏ và nhặt rửa sạch 10 g lá ngò rí để ráo. Lót sẵn 2 lớp giấy thấm dầu lên đĩa rộng và rót 20 ml tương ớt ra chén chấm.', NULL, NULL),
('imp-5e0a488541baee5e_v4_step_2', 'imp-5e0a488541baee5e', 2, 'prep', 'Đánh bông nhẹ trứng gà với nước mắm và chanh', 'Đập 3 quả trứng gà vào tô vừa, thêm 10 ml nước mắm ngon cùng vài giọt nước cốt từ 1/2 quả chanh tươi. Dùng nĩa hoặc phới đánh mạnh tay khoảng 1 phút cho lòng trắng và lòng đỏ hòa đều và nổi lớp bọt mịn trên mặt, sau đó khuấy hành lá cùng ớt hiểm thái lát vào.', 'Đánh trứng nổi bọt khí và thêm vài giọt chanh giúp cấu trúc trứng nhẹ xốp, phồng cao ngay khi gặp dầu nóng.', 1),
('imp-5e0a488541baee5e_v4_step_3', 'imp-5e0a488541baee5e', 3, 'cook', 'Đun nóng già dầu ăn trong chảo nhỏ sâu lòng', 'Đổ 100 ml dầu ăn vào chảo nhỏ sâu lòng hoặc nồi nhỏ đáy dày, đun trên lửa vừa lớn khoảng 2 phút đến khi dầu thật nóng già, lăn tăn gợn sóng. Nhỏ thử 1 giọt trứng vào kiểm tra: nếu trứng sủi bọt và nổi phồng ngay lập tức là đạt nhiệt độ chuẩn.', 'Dùng chảo đường kính nhỏ (~18 cm) giúp lượng dầu sâu hơn và gom miếng trứng dày phồng đẹp mắt.', 2),
('imp-5e0a488541baee5e_v4_step_4', 'imp-5e0a488541baee5e', 4, 'cook', 'Rót trứng từ trên cao và chiên giòn mặt dưới', 'Khuấy nhanh lại tô trứng rồi rót từ độ cao khoảng 15–20 cm theo vòng xoắn ốc vào giữa chảo dầu nóng để trứng tự sủi bọt tạo lớp ren viền giòn xốp. Giữ lửa vừa lớn và chiên yên khoảng 1–2 phút đến khi mặt dưới chuyển vàng nâu giòn rụm và mép trứng phồng giòn.', 'Rót trứng từ trên cao theo dòng nhỏ giúp không khí hòa vào dầu sôi, tạo viền trứng xốp giòn đặc trưng kiểu Thái.', 2),
('imp-5e0a488541baee5e_v4_step_5', 'imp-5e0a488541baee5e', 5, 'cook', 'Lật mặt chiên vàng đều cả hai bên', 'Dùng xẻng bản rộng nhẹ nhàng lật ngửa miếng trứng sang mặt còn lại, chiên tiếp khoảng 30–45 giây cho mặt kia vàng giòn đều mà phần lõi bên trong vẫn giữ được độ mềm béo ẩm mượt.', NULL, NULL),
('imp-5e0a488541baee5e_v4_step_6', 'imp-5e0a488541baee5e', 6, 'finish', 'Thấm ráo dầu thừa và dọn nóng với tương ớt', 'Vớt trứng ra đĩa đã lót sẵn giấy thấm dầu, chấm nhẹ mặt trên để hút bớt dầu thừa rồi chuyển sang đĩa sạch, rắc lá ngò rí tươi lên mặt và dọn nóng cùng chén tương ớt.', NULL, NULL),
('imp-bcc430e4b54c1e65_v4_step_1', 'imp-bcc430e4b54c1e65', 1, 'prep', 'Sơ chế tôm tươi và các loại rau củ', 'Rửa sạch 300 g tôm tươi đã bóc vỏ rút chỉ lưng, để ráo nước. Cắt miếng vuông 3–4 cm phần 1/2 bắp cải trắng, bổ múi cau 2 quả cà chua chín, băm nhỏ 1/2 củ tỏi khô, thái nhỏ đầu hành trắng và cắt khúc 2 cm phần lá xanh của 1 bó hành lá cùng 15 g ngò rí.', NULL, NULL),
('imp-bcc430e4b54c1e65_v4_step_2', 'imp-bcc430e4b54c1e65', 2, 'cook', 'Phi thơm tỏi hành và xào săn tôm tươi', 'Làm nóng nồi trên lửa vừa với 15 ml dầu ăn, cho tỏi băm và đầu hành trắng vào phi thơm 30 giây đến khi vừa ngả vàng dịu. Trút 300 g tôm tươi vào đảo nhanh tay khoảng 2 phút đến khi bề mặt tôm săn lại và chuyển sắc hồng cam.', 'Xào sơ tôm với tỏi phi trước khi đổ nước giúp thịt tôm thơm ngon hơn và nước canh có độ ngọt béo tự nhiên.', 2),
('imp-bcc430e4b54c1e65_v4_step_3', 'imp-bcc430e4b54c1e65', 3, 'cook', 'Đổ nước lọc đun sôi và hớt sạch bọt', 'Rót 1400 ml nước lọc vào nồi tôm, tăng lửa lớn đun sôi bùng rồi hạ lửa vừa, dùng vá hớt thật sạch lớp bọt nổi trên mặt để nước canh trong vắt đẹp mắt.', NULL, 4),
('imp-bcc430e4b54c1e65_v4_step_4', 'imp-bcc430e4b54c1e65', 4, 'cook', 'Nấu cà chua và bắp cải vừa chín tới', 'Thả cà chua bổ múi cau vào nồi nấu 2 phút cho cà chua hơi mềm và tiết vị ngọt chua thanh. Tiếp tục cho bắp cải vào nấu sôi vừa thêm 4 phút đến khi bắp cải vừa chín mềm trong mà vẫn còn độ giòn ngọt, không bị nhũn nát.', 'Không đun bắp cải quá lâu để giữ trọn độ giòn ngọt tự nhiên và màu xanh trắng tươi sáng của rau.', 6),
('imp-bcc430e4b54c1e65_v4_step_5', 'imp-bcc430e4b54c1e65', 5, 'cook', 'Nêm gia vị xì dầu thanh dịu vừa miệng', 'Nêm vào nồi canh 30 ml xì dầu, 4 g muối ăn và 4 g đường cát trắng, khuấy nhẹ cho gia vị tan đều rồi đun sôi lăn tăn thêm 1 phút, nếm chỉnh lại độ mặn ngọt hài hòa.', NULL, NULL),
('imp-bcc430e4b54c1e65_v4_step_6', 'imp-bcc430e4b54c1e65', 6, 'finish', 'Hoàn thiện với hành ngò và tiêu đen xay', 'Tắt bếp ngay rồi thả phần lá xanh của hành lá và ngò rí cắt khúc vào nồi đảo nhẹ, múc canh ra tô lớn, rắc 2 g tiêu đen xay lên trên và dùng nóng.', 'Cho tiêu đen và hành ngò sau cùng khi tắt bếp giúp giữ được mùi thơm dịu ấm đặc trưng của món canh Tom Chuet.', NULL),
('imp-103ea67cd56c9c96_v4_step_1', 'imp-103ea67cd56c9c96', 1, 'prep', 'Thái ba chỉ và đánh hỗn hợp sốt trứng phô mai', 'Thái 150 g thịt ba chỉ muối xông khói Pancetta thành sợi dày 1 cm. Đập 4 quả trứng gà tươi (ưu tiên lấy lòng đỏ hoặc 1 quả nguyên kèm 3 lòng đỏ cho sốt sánh đậm), cho vào tô cùng 50 g phô mai Pecorino Romano bào mịn và 3 g tiêu đen xay, dùng phới lồng đánh đều thành hỗn hợp sánh mịn.', 'Dùng chủ yếu lòng đỏ trứng giúp sốt Carbonara có màu vàng óng và độ sánh kem mượt mà không bị tanh.', NULL),
('imp-103ea67cd56c9c96_v4_step_2', 'imp-103ea67cd56c9c96', 2, 'cook', 'Áp chảo ba chỉ muối ra mỡ vàng giòn', 'Cho thịt ba chỉ muối vào chảo chống dính khô (không cần thêm dầu), bật lửa vừa-lớn áp chảo khoảng 8–10 phút đến khi thịt tiết mỡ và các cạnh vàng giòn. Có thể thêm tỏi tươi đập dập (nếu dùng) đảo 1 phút cho thơm rồi gắp bỏ tỏi. Vớt thịt ra bát riêng, giữ nguyên phần mỡ nóng trong chảo.', 'Canh lửa vừa để thịt ba chỉ muối tiết mỡ từ từ và giòn đều mà không bị cháy khét gây đắng.', 9),
('imp-103ea67cd56c9c96_v4_step_3', 'imp-103ea67cd56c9c96', 3, 'cook', 'Luộc mì Ý Spaghetti và giữ nước tinh bột', 'Trong lúc áp chảo thịt, đun sôi mạnh nồi lớn với 3 lít nước lọc và 15 g muối hạt. Cho 320 g mì Ý Spaghetti khô vào luộc khoảng 8 phút đến độ al dente. Trước khi vớt mì, múc giữ lại khoảng 100 ml nước luộc mì nóng.', NULL, 8),
('imp-103ea67cd56c9c96_v4_step_4', 'imp-103ea67cd56c9c96', 4, 'sauce', 'Áo mì qua nền mỡ ba chỉ và nước luộc', 'Tắt bếp chảo mỡ ba chỉ để chảo nguội bớt 1 phút. Rưới khoảng 50 ml nước luộc mì vào chảo mỡ, trút mì Ý đã vớt sang chảo rồi đảo nhanh tay cho sợi mì thấm đều lớp nhũ tương mỡ thịt nóng ấm.', NULL, NULL),
('imp-103ea67cd56c9c96_v4_step_5', 'imp-103ea67cd56c9c96', 5, 'cook', 'Trộn sốt trứng phô mai ngoài bếp lửa', 'Nhấc hẳn chảo mì khỏi bếp để tránh quá nhiệt, đổ từ từ hỗn hợp trứng và phô mai Pecorino vào, vừa đổ vừa đảo và xóc liên tục 1–2 phút. Thêm từng muỗng nước luộc mì còn lại nếu sốt quá đặc đến khi tạo thành lớp kem bóng mượt bám đều sợi mì.', 'Tuyệt đối tắt bếp và nhấc chảo khỏi nguồn nhiệt trước khi đổ trứng để nhiệt dư chỉ làm chín mượt sốt mà không biến thành trứng bác lợn cợn.', 2),
('imp-103ea67cd56c9c96_v4_step_6', 'imp-103ea67cd56c9c96', 6, 'finish', 'Trộn ba chỉ giòn và dọn nóng ngay', 'Trút phần lớn thịt ba chỉ giòn trở lại chảo đảo đều lần cuối. Chia mì ra 4 đĩa sâu lòng, rắc phần thịt giòn còn lại cùng 10 g phô mai Pecorino Romano bào và 1 g tiêu đen xay lên trên, thưởng thức nóng ngay.', NULL, NULL),
('imp-34505f9722b38fc1_v4_step_1', 'imp-34505f9722b38fc1', 1, 'prep', 'Băm nhuyễn rau củ soffritto và thái ba chỉ', 'Gọt vỏ cà rốt, rửa sạch cần tây và bóc vỏ hành tây vàng, băm thật nhuyễn cả ba loại (cùng 2 tép tỏi tươi băm nếu dùng) để rau tan quyện vào sốt khi hầm. Thái 100 g thịt ba chỉ muối Pancetta thành hạt lựu nhỏ 5 mm.', NULL, NULL),
('imp-34505f9722b38fc1_v4_step_2', 'imp-34505f9722b38fc1', 2, 'cook', 'Áp chảo thịt ba chỉ, thịt bò và thịt heo xay', 'Đun nóng 25 ml dầu ô liu nguyên chất và 20 g bơ lạt trong nồi đáy dày ở lửa vừa, cho thịt ba chỉ muối vào đảo 4 phút cho ra mỡ và hơi xém cạnh. Trút 300 g thịt bò xay và 150 g thịt heo xay vào dàn mỏng, để yên 2 phút cho mặt dưới xém vàng rồi dằm tơi, đảo thêm 6 phút đến khi thịt chín săn hết màu hồng. Nêm 3 g muối ăn và 2 g tiêu đen xay.', 'Để thịt áp chảo xém vàng nhẹ trước khi đảo tơi giúp kích hoạt hương thơm đậm đà đặc trưng cho Ragù.', 10),
('imp-34505f9722b38fc1_v4_step_3', 'imp-34505f9722b38fc1', 3, 'cook', 'Xào mềm rau củ và khử rượu vang đỏ', 'Cho hỗn hợp cà rốt, cần tây, hành tây (và tỏi băm nếu dùng) vào nồi thịt, đảo đều khoảng 6 phút ở lửa vừa đến khi rau củ mềm trong. Tăng lửa lớn, đổ 100 ml rượu vang đỏ nấu ăn vào khuấy đều 3 phút đến khi bay hết mùi cồn.', NULL, 9),
('imp-34505f9722b38fc1_v4_step_4', 'imp-34505f9722b38fc1', 4, 'sauce', 'Hầm chậm sốt cà chua Ragù sánh đậm', 'Thêm 300 g cà chua nghiền nhuyễn Passata và 30 g cà chua cô đặc (nếu dùng) cùng 2 g muối ăn còn lại vào nồi, đảo đều đun sôi nhẹ. Hạ lửa thật nhỏ, đậy vung hờ và hầm ít nhất 60 phút, mỗi 15 phút khuấy một lần và châm từng ít nước dùng bò (nếu dùng) khi thấy sốt đặc khô.', 'Sốt Ragù đạt chuẩn khi thịt mềm nhừ, nước sốt sánh quyện và có lớp mỡ đỏ óng nổi nhẹ trên mặt.', 60),
('imp-34505f9722b38fc1_v4_step_5', 'imp-34505f9722b38fc1', 5, 'cook', 'Luộc mì Ý Spaghetti độ al dente', 'Khi sốt gần hầm xong, đun sôi mạnh nồi với 3 lít nước lọc và 10 g muối ăn. Thả 320 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút để mì đạt độ dai vừa tới, giữ lại 100 ml nước luộc mì trước khi vớt.', 'Nên chừa lại khoảng 100 ml nước luộc mì giàu tinh bột để làm bóng và kết nối sốt thịt vào sợi mì.', 9),
('imp-34505f9722b38fc1_v4_step_6', 'imp-34505f9722b38fc1', 6, 'finish', 'Trộn mì quyện sốt và rắc phô mai Parmesan', 'Trút mì Ý vào nồi sốt Ragù cùng 2–3 muỗng canh nước luộc mì, đảo đều tay 2 phút trên lửa vừa để sốt bám đều từng sợi mì. Nếm lại cho vừa miệng, chia ra 4 đĩa sâu lòng và rắc 40 g phô mai Parmesan bào lên trên nếu thích.', NULL, NULL),
('imp-266d7af134d7286a_v4_step_1', 'imp-266d7af134d7286a', 1, 'prep', 'Sơ chế nấm đùi gà, tỏi và ngò tây', 'Dùng khăn ẩm lau sạch 225 g nấm đùi gà tươi (không rửa ngập nước để nấm khỏi nhũn), cắt bỏ phần gốc già rồi thái lát dày 0,5 cm. Bóc vỏ, băm nhỏ 3 tép tỏi tươi; rửa sạch và thái nhỏ 10 g ngò tây tươi.', NULL, NULL),
('imp-266d7af134d7286a_v4_step_2', 'imp-266d7af134d7286a', 2, 'cook', 'Luộc mì Ý Spaghetti giữ lại nước tinh bột', 'Đun sôi mạnh nồi lớn với 2,5 lít nước lọc và 8 g muối ăn. Thả 255 g mì Ý Spaghetti khô vào luộc khoảng 8 phút (ít hơn 1 phút so với hướng dẫn bao bì) để đạt độ al dente. Múc giữ lại 150 ml nước luộc mì rồi vớt mì ra.', NULL, 8),
('imp-266d7af134d7286a_v4_step_3', 'imp-266d7af134d7286a', 3, 'cook', 'Xào vàng nấm đùi gà với bơ tỏi', 'Làm nóng chảo lớn trên lửa vừa với 20 g bơ lạt và 15 ml dầu ô liu. Cho tỏi băm vào phi thơm 30 giây, sau đó trút nấm đùi gà vào xào khoảng 7 phút đến khi nấm ra hết nước, săn lại và vàng đều hai mặt. Nêm 4 g muối ăn và 1,5 g tiêu đen xay.', 'Không đảo nấm liên tục trong 3 phút đầu để bề mặt nấm tiếp xúc nhiệt tốt và lên màu vàng nâu hấp dẫn.', 7),
('imp-266d7af134d7286a_v4_step_4', 'imp-266d7af134d7286a', 4, 'sauce', 'Nấu sốt kem tươi và sữa tươi sánh nhẹ', 'Hạ lửa nhỏ, rót 150 ml kem tươi và 100 ml sữa tươi không đường vào chảo nấm, khuấy nhẹ cho hòa quyện. Đun liu riu khoảng 3 phút cho sốt hơi sánh lại mà không để sôi bùng tránh tách béo.', 'Giữ sốt kem sôi lăn tăn nhẹ thay vì sôi mạnh để kết cấu kem sữa mịn mượt và không bị tách váng.', 3),
('imp-266d7af134d7286a_v4_step_5', 'imp-266d7af134d7286a', 5, 'cook', 'Trộn mì Ý và làm tan phô mai Parmesan', 'Cho mì Ý Spaghetti đã vớt vào chảo sốt, đảo đều 2 phút trên lửa nhỏ-vừa để từng sợi mì thấm kem; thêm dần từng muỗng nước luộc mì nếu sốt đặc. Tắt bếp rồi rắc 25 g phô mai Parmesan bào vào đảo nhanh đến khi phô mai tan mượt.', 'Chỉ cho phô mai vào khi đã tắt bếp hoặc lửa thật nhỏ để phô mai tan đều mịn, không bị vón sợi.', 2),
('imp-266d7af134d7286a_v4_step_6', 'imp-266d7af134d7286a', 6, 'finish', 'Hoàn thiện với ngò tây và dọn nóng', 'Nếm lại gia vị, rắc 10 g ngò tây tươi thái nhỏ vào đảo nhẹ. Chia mì ra 3 đĩa sâu lòng, rắc thêm 10 g phô mai Parmesan bào còn lại cùng 0,5 g tiêu đen xay lên trên và thưởng thức nóng ngay.', NULL, NULL),
('imp-8b2c852ba59f2143_v4_step_1', 'imp-8b2c852ba59f2143', 1, 'prep', 'Đun nóng nước dùng và sơ chế nấm, rau bina', 'Đun sôi lăn tăn 1 lít nước dùng rau củ trên bếp nhỏ để giữ nóng liên tục. Lau sạch 280 g nấm đùi gà tươi bằng khăn ẩm rồi thái lát dày 0,5 cm. Rửa sạch và để ráo 100 g rau bina tươi; băm nhỏ hành tây và tỏi tươi.', NULL, NULL),
('imp-8b2c852ba59f2143_v4_step_2', 'imp-8b2c852ba59f2143', 2, 'cook', 'Xào thơm hành tỏi và áp chảo nấm vàng cạnh', 'Làm nóng nồi đáy dày trên lửa vừa với 20 ml dầu ô liu nguyên chất và 15 g bơ lạt, cho hành tây vào xào 4 phút đến khi mềm trong rồi thêm tỏi băm đảo 1 phút. Tăng lửa lớn, cho nấm đùi gà vào xào khoảng 5 phút đến khi nấm xém vàng và thơm, nêm 2 g muối ăn.', 'Xào nấm trên lửa lớn giúp nước nấm bay hơi nhanh, giữ được độ giòn ngọt mà không bị sũng nước.', 9),
('imp-8b2c852ba59f2143_v4_step_3', 'imp-8b2c852ba59f2143', 3, 'cook', 'Rang gạo Arborio và khử rượu vang trắng', 'Hạ về lửa vừa, đổ 250 g gạo Ý Arborio vào đảo đều 2 phút cho từng hạt gạo áo dầu và trong mờ ở viền. Rót 80 ml rượu vang trắng khô vào khuấy liên tục 2 phút đến khi rượu bay hơi gần hết.', NULL, 4),
('imp-8b2c852ba59f2143_v4_step_4', 'imp-8b2c852ba59f2143', 4, 'cook', 'Om cơm Risotto từng vá nước dùng nóng', 'Múc từng vá nước dùng rau củ nóng (~120 ml) chế vào nồi gạo, khuấy đều tay để tinh bột gạo tiết ra sánh mịn; đợi nước rút gần hết mới châm vá kế tiếp. Lặp lại thao tác này khoảng 18 phút đến khi hạt gạo chín mềm ngoài, hơi dai nhẹ ở lõi.', 'Không đổ nước dùng ồ ạt một lần vì gạo sẽ bị luộc nhão mà mất đi độ sánh kem đặc trưng.', 18),
('imp-8b2c852ba59f2143_v4_step_5', 'imp-8b2c852ba59f2143', 5, 'cook', 'Trộn rau bina tươi giữ màu xanh mướt', 'Khi cơm đã gần đạt độ chín mong muốn, thả 100 g rau bina tươi vào nồi, đảo nhanh tay khoảng 2 phút cho lá vừa héo mềm và hòa quyện đều vào cơm mà vẫn giữ được màu xanh tươi.', NULL, 2),
('imp-8b2c852ba59f2143_v4_step_6', 'imp-8b2c852ba59f2143', 6, 'finish', 'Đánh bóng bơ phô mai và dọn nóng', 'Tắt bếp, cho 15 g bơ lạt lạnh còn lại cùng 30 g phô mai Parmesan bào mịn vào đánh mạnh tay 1 phút đến khi cơm bóng mượt. Đậy nắp nghỉ 1 phút, nêm lại 2 g muối ăn còn lại và 1,5 g tiêu đen xay rồi múc ra 3 đĩa sâu lòng dùng nóng ngay.', 'Dùng bơ lạt thật lạnh cho bước đánh bóng cuối khi đã tắt bếp giúp Risotto đạt độ sánh kem óng mượt.', NULL),
('imp-de5ce12092f4f0aa_v4_step_1', 'imp-de5ce12092f4f0aa', 1, 'prep', 'Làm xẹp và vắt ráo rau bina tươi', 'Rửa sạch 250 g rau bina tươi qua nhiều lần nước cho hết cát, nhặt bỏ cuống già. Cho rau vào chảo khô trên lửa vừa (không thêm dầu hay nước), đảo khoảng 2 phút cho rau xẹp hết rồi trút ra rổ để nguội bớt, dùng tay vắt thật ráo nước và thái thô.', 'Vắt thật kiệt nước ở rau bina là bước quan trọng nhất để món Frittata không bị chảy nước hay nhão.', 2),
('imp-de5ce12092f4f0aa_v4_step_2', 'imp-de5ce12092f4f0aa', 2, 'cook', 'Phi thơm hành tây, tỏi và xào lại rau bina', 'Làm sạch chảo, cho 12 ml dầu ô liu vào đun lửa vừa. Cho hành tây thái hạt lựu vào phi 3 phút đến khi mềm trong, thêm tỏi băm (nếu dùng) đảo 30 giây. Trút rau bina đã vắt ráo vào đảo 1 phút cùng 1 g muối ăn và 0,5 g tiêu đen xay, tắt bếp để nguội 4 phút.', NULL, 4),
('imp-de5ce12092f4f0aa_v4_step_3', 'imp-de5ce12092f4f0aa', 3, 'prep', 'Đánh bông trứng gà với hai loại phô mai', 'Đập 6 quả trứng gà tươi ra tô lớn, đánh mạnh tay bằng phới lồng khoảng 1 phút cho trứng bông nhẹ. Thêm 40 g phô mai Parmesan bào, 60 g phô mai Mozzarella bào sợi, 30 ml sữa tươi không đường (nếu dùng), 3 g muối ăn và 1 g tiêu đen xay vào khuấy đều. Trút hỗn hợp rau đã nguội bớt vào trộn đều.', 'Phải đợi rau nguội bớt mới trộn vào trứng để tránh làm trứng bị chín vón lợn cợn trước khi chiên.', NULL),
('imp-de5ce12092f4f0aa_v4_step_4', 'imp-de5ce12092f4f0aa', 4, 'cook', 'Chiên chậm Frittata ở lửa nhỏ và đậy vung', 'Lau sạch chảo chống dính đường kính 24 cm, tráng 13 ml dầu ô liu còn lại trên lửa nhỏ-vừa rồi đổ hỗn hợp trứng rau vào dàn đều mặt. Để yên 2 phút cho mép trứng se lại, dùng phới đẩy nhẹ mép vào giữa và nghiêng chảo cho trứng lỏng chảy xuống đáy lặp lại trong 6 phút, sau đó đậy nắp nấu thêm 2 phút cho mặt trên se đặc.', NULL, 8),
('imp-de5ce12092f4f0aa_v4_step_5', 'imp-de5ce12092f4f0aa', 5, 'cook', 'Lật mặt áp vàng hai bên khối Frittata', 'Úp một chiếc đĩa phẳng lớn lên miệng chảo, dứt khoát lật ngược khối Frittata ra đĩa rồi nhẹ nhàng trượt mặt còn lại xuống chảo. Áp chảo thêm khoảng 3 phút trên lửa nhỏ đến khi cả hai mặt đều vàng đẹp và phần lõi trứng chín chắc hoàn toàn.', 'Chiên ở lửa nhỏ giúp khối trứng dày chín đều vào tận lõi mà mặt đáy không bị cháy khét.', 3),
('imp-de5ce12092f4f0aa_v4_step_6', 'imp-de5ce12092f4f0aa', 6, 'finish', 'Nghỉ ngắn, cắt múi tam giác và thưởng thức', 'Trượt Frittata ra đĩa lớn, để nghỉ 2 phút cho kết cấu định hình chắc rồi cắt thành 6 múi tam giác đều nhau, thưởng thức khi còn ấm nóng hoặc ở nhiệt độ phòng.', NULL, NULL),
('imp-b8d2cb0b37dbdb81_v4_step_1', 'imp-b8d2cb0b37dbdb81', 1, 'prep', 'Sơ chế ức gà và vắt nước cốt chanh vàng', 'Rửa sạch 450 g ức gà phi lê, thấm thật khô bằng khăn giấy rồi cắt thành các miếng đều nhau dày khoảng 1,5 cm. Bào lấy vỏ vàng của 1,5 quả chanh vàng tươi (tránh phần cùi trắng đắng) và vắt lấy khoảng 70 ml nước cốt; băm nhỏ tỏi tươi và lá hương thảo.', NULL, NULL),
('imp-b8d2cb0b37dbdb81_v4_step_2', 'imp-b8d2cb0b37dbdb81', 2, 'prep', 'Áo lớp bột mì mỏng lên từng miếng gà', 'Cho 20 g bột mì đa dụng ra đĩa rộng, lăn đều hai mặt từng miếng ức gà qua bột rồi giũ nhẹ tay cho rớt bớt phần bột thừa để chỉ còn lại lớp áo thật mỏng.', 'Lớp bột mì mỏng giúp miếng gà giữ ẩm bên trong khi áp chảo và tự động làm sánh mượt nước sốt chanh ở bước sau.', NULL),
('imp-b8d2cb0b37dbdb81_v4_step_3', 'imp-b8d2cb0b37dbdb81', 3, 'cook', 'Áp chảo ức gà vàng đều hai mặt', 'Làm nóng chảo lớn trên lửa vừa với 25 ml dầu ô liu nguyên chất và 20 g bơ lạt. Khi bơ tan sủi bọt, xếp gà thành một lớp phẳng không chồng lên nhau, áp chảo khoảng 3–4 phút mỗi mặt đến khi vàng đều hai bên rồi gắp gà ra đĩa giữ ấm.', 'Không đảo lật gà quá sớm trong 3 phút đầu để lớp vỏ bột áp chảo xém vàng đẹp và không bị bong.', 7),
('imp-b8d2cb0b37dbdb81_v4_step_4', 'imp-b8d2cb0b37dbdb81', 4, 'sauce', 'Phi tỏi hương thảo và cạo đáy chảo làm sốt', 'Hạ lửa vừa-nhỏ trên cùng chảo đó, cho tỏi băm và lá hương thảo vào phi nhanh 30 giây cho thơm (không để tỏi cháy). Đổ 100 ml nước lọc và nước cốt chanh vàng vào, dùng muỗng gỗ cạo sạch phần cháy xém ngon dưới đáy chảo.', NULL, 2),
('imp-b8d2cb0b37dbdb81_v4_step_5', 'imp-b8d2cb0b37dbdb81', 5, 'cook', 'Rim gà thấm sốt chanh đến khi chín thấu', 'Trút ức gà trở lại chảo cùng vỏ chanh vàng bào, nêm 5 g muối ăn và 1,5 g tiêu đen xay. Rim liu riu khoảng 4 phút, trở mặt nhẹ nhàng cho thịt gà chín hoàn toàn hết phần lõi hồng và sốt hơi sánh ôm quanh miếng thịt.', NULL, 4),
('imp-b8d2cb0b37dbdb81_v4_step_6', 'imp-b8d2cb0b37dbdb81', 6, 'finish', 'Đánh bóng sốt với bơ lạnh và dọn nóng', 'Tắt bếp hoàn toàn, thả 15 g bơ lạt lạnh cắt nhỏ vào chảo rồi lắc nhẹ và đảo đều đến khi bơ tan chảy tạo lớp sốt chanh bơ bóng mượt. Xếp gà ra đĩa, rưới sốt lên trên và rắc ngò tây tươi (nếu dùng) rồi thưởng thức nóng ngay.', 'Đánh tan bơ lạnh ngoài bếp lửa giúp sốt chanh bơ sánh óng ánh mà không bị tách nước hay ngấy dầu.', NULL),
('imp-a4d02f2246e0e115_v4_step_1', 'imp-a4d02f2246e0e115', 1, 'prep', 'Thấm khô, ướp gia vị và áo bột đùi gà', 'Rửa sạch 750 g đùi gà có da có xương, thấm thật khô bằng khăn giấy. Xoa đều 3 g muối ăn và 1 g tiêu đen xay lên các mặt gà rồi rắc 16 g bột mì đa dụng áo thành lớp mỏng, giũ bỏ bột thừa. Chuẩn bị sẵn nấm đùi gà thái lát, cà chua chín băm nhỏ, hành tây thái lát, cần tây và tỏi băm.', 'Thấm thật khô da gà giúp khi áp chảo gà nhanh vàng giòn và không làm dầu bị bắn.', NULL),
('imp-a4d02f2246e0e115_v4_step_2', 'imp-a4d02f2246e0e115', 2, 'cook', 'Áp chảo đùi gà vàng đều các mặt', 'Đun nóng chảo lớn sâu lòng trên lửa vừa-cao với 30 ml dầu ô liu nguyên chất. Đặt gà mặt da úp xuống áp chảo tổng cộng khoảng 8–10 phút, trở đều các mặt đến khi da gà vàng nâu đẹp mắt thì gắp gà ra đĩa, giữ lại ít mỡ thơm trong chảo.', NULL, 9),
('imp-a4d02f2246e0e115_v4_step_3', 'imp-a4d02f2246e0e115', 3, 'cook', 'Xào mềm hành tây, cần tây và nấm đùi gà', 'Cho hành tây vào chảo đậy nắp xào 2 phút ở lửa vừa cho bắt đầu mềm. Mở nắp, thêm nấm đùi gà thái lát, cần tây, tỏi băm, lá hương thảo và Oregano khô cùng 2 lá nguyệt quế khô vào đảo đều khoảng 5 phút đến khi nấm cạn nước và dậy mùi thơm.', NULL, 7),
('imp-a4d02f2246e0e115_v4_step_4', 'imp-a4d02f2246e0e115', 4, 'sauce', 'Khử rượu vang trắng và nấu nền cà chua', 'Đổ 120 ml rượu vang trắng khô vào chảo, đun sôi 2 phút đồng thời dùng muỗng gỗ cạo sạch phần cháy xém dưới đáy chảo cho đến khi bay hết mùi cồn. Trút cà chua chín băm nhỏ, ớt vảy khô (nếu dùng), nước dùng gà (nếu cần), 3 g muối ăn và 0,5 g tiêu đen xay còn lại vào đảo đều.', 'Cạo sạch phần xém vàng dưới đáy chảo khi khử rượu vang sẽ mang lại chiều sâu hương vị cho nước sốt om.', 2),
('imp-a4d02f2246e0e115_v4_step_5', 'imp-a4d02f2246e0e115', 5, 'cook', 'Om chậm đùi gà thấm sốt cà chua', 'Xếp đùi gà trở lại chảo, múc sốt rưới phủ lên mặt thịt. Đậy nắp hờ, hạ lửa nhỏ và om liu riu khoảng 25 phút đến khi thịt gà chín mềm, xiên vào sát xương không còn nước hồng và nước sốt sánh đỏ đậm.', 'Nếu sốt còn hơi loãng sau khi gà chín, gắp gà ra đĩa rồi đun sôi sốt 2–3 phút cho cô sánh lại trước khi rưới lên gà.', 25),
('imp-a4d02f2246e0e115_v4_step_6', 'imp-a4d02f2246e0e115', 6, 'finish', 'Vớt lá nguyệt quế, rắc ngò tây và dọn nóng', 'Vớt bỏ lá nguyệt quế khô ra khỏi chảo, nếm lại gia vị cho vừa miệng. Để món ăn nghỉ 10 phút cho hương vị hòa quyện sâu hơn, rắc 15 g ngò tây tươi thái nhỏ lên trên rồi dọn nóng.', NULL, NULL),
('imp-a60814a4aca4143b_v4_step_1', 'imp-a60814a4aca4143b', 1, 'prep', 'Chuẩn bị vụn ruột bánh mì và trộn thịt bò', 'Cắt bỏ phần vỏ cứng của 3 lát ruột bánh mì gối tươi, xé nhỏ hoặc xay vụn mịn (trộn với 60 ml sữa tươi nếu dùng). Cho 500 g thịt bò xay, vụn bánh mì, 50 g phô mai Parmesan bào, 50 g phô mai Pecorino bào, 2 quả trứng gà tươi, 10 g ngò tây tươi băm, 0,5 g nhục đậu khấu xay, 4 g muối ăn và 2 g tiêu đen xay vào tô lớn, nhào vừa đủ quyện đều.', 'Dùng ruột bánh mì tươi thay vụn khô giúp viên thịt bò giữ ẩm và mềm xốp sau khi om.', NULL),
('imp-a60814a4aca4143b_v4_step_2', 'imp-a60814a4aca4143b', 2, 'marinate', 'Ướp lạnh hỗn hợp thịt và vo viên vừa ăn', 'Bọc kín tô thịt, cho vào ngăn mát tủ lạnh nghỉ khoảng 30 phút để vụn bánh mì hút ẩm đều giúp hỗn hợp kết dính chắc. Sau đó chia hỗn hợp thành các phần nhỏ đều nhau (~20 g mỗi phần) và vo tròn bằng hai lòng bàn tay.', NULL, 30),
('imp-a60814a4aca4143b_v4_step_3', 'imp-a60814a4aca4143b', 3, 'sauce', 'Xào chậm hành tây tỏi làm nền sốt cà chua', 'Bắc nồi rộng đáy lên bếp ở lửa nhỏ với 45 ml dầu ô liu nguyên chất. Cho hành tây băm và tỏi băm vào xào chậm khoảng 10–12 phút, đảo thường xuyên đến khi hành mềm trong suốt và ngọt dịu mà không để cháy vàng.', 'Xào chậm hành tây trên lửa nhỏ giúp sốt cà chua có vị ngọt thanh tự nhiên mà không cần thêm đường.', 10),
('imp-a60814a4aca4143b_v4_step_4', 'imp-a60814a4aca4143b', 4, 'sauce', 'Đun sôi nhẹ sốt cà chua Passata', 'Đổ 800 g cà chua xay nhuyễn Passata vào nồi hành tỏi, nêm 3 g muối ăn còn lại, khuấy đều và đun đến khi sốt sôi lăn tăn nhẹ.', NULL, NULL),
('imp-a60814a4aca4143b_v4_step_5', 'imp-a60814a4aca4143b', 5, 'cook', 'Thả viên thịt om chín mềm trong sốt cà chua', 'Nhẹ nhàng thả từng viên thịt bò vào nồi sốt đang sôi lăn tăn, lắc nhẹ tay cầm nồi để các viên xếp đều mà không dùng muỗng khuấy mạnh tránh vỡ viên. Đậy nắp, hạ lửa nhỏ và om liu riu khoảng 25 phút đến khi viên thịt chín kỹ hoàn toàn bên trong và sốt sánh mịn.', 'Chỉ lắc nhẹ nồi trong 10 phút đầu để viên thịt định hình chắc chắn trước khi đảo nhẹ.', 25),
('imp-a60814a4aca4143b_v4_step_6', 'imp-a60814a4aca4143b', 6, 'finish', 'Thêm lá húng quế tươi và dọn nóng', 'Thả 6 g lá húng quế Tây tươi vào nồi, đun thêm 5 phút ở lửa nhỏ cho dậy hương thơm tươi mát rồi tắt bếp. Nếm lại sốt cho vừa miệng, múc thịt viên cùng nhiều sốt nóng ra đĩa và thưởng thức ngay.', NULL, 5),
('imp-5504378372dc989b_v4_step_1', 'imp-5504378372dc989b', 1, 'prep', 'Thái hạt lựu toàn bộ rau củ và bó lá thơm', 'Rửa sạch và cắt hạt lựu đều cỡ 1 cm đối với bí đỏ, khoai tây, bí ngòi và cà chua chín; tách bông nhỏ súp lơ trắng; thái miếng vừa ăn bắp cải; thái khoanh mỏng tỏi tây; băm nhỏ hành tây tím, cà rốt, cần tây và tỏi tươi; chuẩn bị sẵn đậu trắng Borlotti và đậu Hà Lan. Buộc nhánh hương thảo cùng 2 lá nguyệt quế khô bằng chỉ bếp thành bó thơm.', 'Thái rau củ kích thước đồng đều giúp các nguyên liệu chín mềm cùng lúc mà không bị nát.', NULL),
('imp-5504378372dc989b_v4_step_2', 'imp-5504378372dc989b', 2, 'cook', 'Xào chậm rau củ nền dậy hương ngọt', 'Làm nóng nồi lớn trên lửa vừa với 40 ml dầu ô liu nguyên chất. Cho hành tây tím, cà rốt, cần tây, tỏi tây và tỏi tươi vào xào chậm khoảng 8 phút, đảo đều tay đến khi rau mềm thơm mà không bị cháy cạnh.', NULL, 8),
('imp-5504378372dc989b_v4_step_3', 'imp-5504378372dc989b', 3, 'cook', 'Nấu lần lượt đậu, bí đỏ, khoai tây và súp lơ', 'Cho bó thơm cùng đậu trắng Borlotti vào nồi, chế khoảng 600 ml nước lọc ngập mặt rau rồi đun sôi 2 phút. Lần lượt cho bí đỏ, khoai tây rồi súp lơ trắng vào theo cách tương tự, mỗi đợt châm thêm chút nước lọc vừa ngập mặt và nấu sôi 2 phút trước khi cho loại tiếp theo.', 'Kỹ thuật cho rau cứng vào trước theo từng đợt giúp khoai tây và bí đỏ chín bùi mà vẫn giữ nguyên khối đẹp mắt.', 8),
('imp-5504378372dc989b_v4_step_4', 'imp-5504378372dc989b', 4, 'cook', 'Ninh súp mềm ngọt trong 20 phút', 'Châm phần nước lọc còn lại vào nồi cho ngập hết rau củ, đậy nắp, đun sôi rồi hạ lửa nhỏ ninh liu riu khoảng 20 phút để nước dùng ngọt thanh tự nhiên.', NULL, 20),
('imp-5504378372dc989b_v4_step_5', 'imp-5504378372dc989b', 5, 'cook', 'Thả rau mềm và nui Ý vào nấu chín tới', 'Mở nắp, cho bí ngòi, đậu Hà Lan, cà chua chín và bắp cải vào nồi cùng 8 g muối ăn và 1,5 g tiêu đen xay, nấu sôi lại 3 phút. Tiếp theo thả 100 g nui Ý ngắn Ditalini vào (nếu dùng) nấu thêm khoảng 7 phút cho nui chín dai vừa tới.', 'Chỉ cho nui Ý vào khi sắp dọn ăn để tránh nui hút cạn nước và nở bở.', 10),
('imp-5504378372dc989b_v4_step_6', 'imp-5504378372dc989b', 6, 'finish', 'Vớt bó thơm, rưới dầu ô liu và dọn nóng', 'Vớt bỏ bó lá hương thảo và nguyệt quế, nêm nếm lại độ mặn vừa miệng rồi tắt bếp. Múc súp Minestrone ra 5 bát sâu lòng, rưới 10 ml dầu ô liu nguyên chất còn lại cùng 0,5 g tiêu đen xay lên trên và thưởng thức nóng.', NULL, NULL),
('imp-b6496331f7aa0ee9_v4_step_1', 'imp-b6496331f7aa0ee9', 1, 'prep', 'Sơ chế tôm tươi, chanh vàng và tỏi băm', 'Bóc vỏ 400 g tôm tươi, rút sạch chỉ đen dọc sống lưng, rửa nhanh nước lạnh rồi thấm thật khô bằng giấy bếp. Bào lấy vỏ vàng của 1 quả chanh vàng tươi và vắt lấy khoảng 30 ml nước cốt; băm nhuyễn tỏi tươi, thái nhỏ ngò tây và bào sẵn 60 g phô mai Parmesan.', 'Thấm thật ráo nước trên thân tôm giúp nước sốt kem chanh không bị loãng khi nấu tôm.', NULL),
('imp-b6496331f7aa0ee9_v4_step_2', 'imp-b6496331f7aa0ee9', 2, 'cook', 'Luộc mì Ý Spaghetti và giữ nước tinh bột', 'Đun sôi mạnh nồi lớn với 2,5 lít nước lọc cùng 9 g muối ăn. Cho 200 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút cho đến độ al dente. Múc giữ lại 60 ml nước luộc mì rồi vớt mì ra.', NULL, 9),
('imp-b6496331f7aa0ee9_v4_step_3', 'imp-b6496331f7aa0ee9', 3, 'sauce', 'Nấu nền sốt kem bơ chanh và rượu vang', 'Trong lúc luộc mì, đặt chảo lớn lên bếp lửa vừa, cho 30 g bơ lạt vào đun tan. Thêm tỏi băm, vỏ chanh vàng bào, nước cốt chanh, 90 ml rượu vang trắng khô và 180 ml kem tươi vào khuấy đều, đun sôi lăn tăn khoảng 4 phút cho rượu bay bớt mùi cồn.', NULL, 4),
('imp-b6496331f7aa0ee9_v4_step_4', 'imp-b6496331f7aa0ee9', 4, 'sauce', 'Làm sánh sốt với bột mì và phô mai Parmesan', 'Rắc từ từ 5 g bột mì đa dụng vào chảo, vừa rắc vừa khuấy liên tục bằng phới để sốt sánh mịn không vón cục. Tiếp tục cho 60 g phô mai Parmesan bào vào khuấy tan hoàn toàn, nêm 3 g muối ăn và 1,5 g tiêu đen xay.', 'Khuấy liên tục khi cho bột mì và phô mai ở lửa nhỏ giúp sốt kem mịn mượt và không bị tách dầu.', 2),
('imp-b6496331f7aa0ee9_v4_step_5', 'imp-b6496331f7aa0ee9', 5, 'cook', 'Nấu chín tôm tươi trong sốt kem chanh', 'Thả tôm tươi đã sơ chế vào chảo sốt đang sôi liu riu, đảo đều và nấu khoảng 4–5 phút đến khi tôm chuyển màu hồng cam, cong tròn săn chắc và chín hoàn toàn bên trong. Không nấu quá lâu để giữ thịt tôm giòn ngọt.', 'Chỉ nấu tôm vừa chuyển hồng cam và săn lại trong 4–5 phút để thịt tôm ngọt giòn mà không bị bở hay dai.', 5),
('imp-b6496331f7aa0ee9_v4_step_6', 'imp-b6496331f7aa0ee9', 6, 'finish', 'Trộn mì Ý với sốt tôm và dọn nóng', 'Cho mì Ý Spaghetti vào chảo sốt tôm cùng 1–2 muỗng canh nước luộc mì đã giữ lại, đảo đều tay 1 phút cho từng sợi mì phủ đều sốt. Tắt bếp, chia ra 3 đĩa sâu lòng, rắc ngò tây tươi (nếu dùng) lên trên và thưởng thức nóng ngay.', NULL, NULL),
('imp-d6f7b2ef8f347338_v4_step_1', 'imp-d6f7b2ef8f347338', 1, 'prep', 'Chần sạch và ướp gia vị cho sườn non', 'Chặt 500 g sườn non heo thành khúc dài 3–4 cm, chà xát với 4 g muối ăn rồi rửa sạch. Đun sôi một nồi nước phụ, thả sườn vào chần 3 phút trên lửa lớn cho ra hết tạp chất rồi vớt ra xả sạch dưới vòi nước lạnh, để ráo. Ướp sườn với 10 ml nước mắm, 3 g hạt nêm, một nửa hành tím băm, đầu hành băm và 0,5 g tiêu đen xay trong 15 phút.', 'Chần sườn rồi rửa lại dưới vòi nước lạnh trước khi ướp là bí quyết giúp nước canh sườn trong veo, không có mùi hôi và ít bọt đục.', 15),
('imp-d6f7b2ef8f347338_v4_step_2', 'imp-d6f7b2ef8f347338', 2, 'prep', 'Sơ chế dứa chín, cà chua, me và rau thơm', 'Gọt sạch vỏ và mắt 1/2 quả dứa chín, bỏ lõi rồi thái lát xéo dày 0,8 cm. Rửa sạch 2 quả cà chua, bổ múi cau. Ngâm 20 g cơm me chín với 50 ml nước nóng lấy từ phần nước lọc, dằm nhuyễn rồi lọc qua rây lấy nước cốt. Rửa sạch và thái khúc hành lá, ngò gai.', NULL, NULL),
('imp-d6f7b2ef8f347338_v4_step_3', 'imp-d6f7b2ef8f347338', 3, 'cook', 'Xào săn sườn non rồi hầm mềm ngọt nước', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, phi thơm phần hành tím băm còn lại rồi cho sườn non đã ướp vào đảo săn 3 phút cho thịt bên ngoài hơi se lại. Đổ 1450 ml nước lọc vào nồi, đun sôi bùng rồi hạ lửa nhỏ liu riu, đậy hé vung hầm 25 phút và thường xuyên hớt bọt để sườn mềm rục và nước dùng ngọt trong.', 'Giữ lửa nhỏ liu riu khi hầm sườn để thịt tiết chất ngọt từ từ vào nước dùng mà nước không bị đục và không cạn nhanh.', 25),
('imp-d6f7b2ef8f347338_v4_step_4', 'imp-d6f7b2ef8f347338', 4, 'cook', 'Xào sơ cà chua dứa và nấu hòa quyện', 'Trong chảo nhỏ, làm nóng 5 ml dầu ăn còn lại trên lửa vừa, cho dứa thái lát và cà chua bổ múi cau vào đảo nhẹ 2 phút cho cà chua lên màu đẹp rồi trút toàn bộ vào nồi sườn đang hầm. Tiếp tục nấu thêm 5 phút trên lửa vừa để vị chua ngọt tự nhiên của dứa và cà chua tiết vào nước canh.', NULL, 5),
('imp-d6f7b2ef8f347338_v4_step_5', 'imp-d6f7b2ef8f347338', 5, 'cook', 'Nêm nếm chua ngọt cân bằng', 'Từ từ rót nước cốt me đã lọc vào nồi tùy khẩu vị chua mong muốn, nêm tiếp 20 ml nước mắm ngon, 5 g hạt nêm còn lại, 4 g muối ăn và 6 g đường cát trắng. Khuấy nhẹ và nấu thêm 2 phút cho gia vị thấm đều vào từng miếng sườn non, đảm bảo sườn chín mềm rời xương nhẹ.', 'Nêm nước cốt me từng chút một và nếm thử lại vì độ chua tự nhiên của dứa chín và cà chua sẽ khác nhau theo mùa.', NULL),
('imp-d6f7b2ef8f347338_v4_step_6', 'imp-d6f7b2ef8f347338', 6, 'finish', 'Rắc hành ngò và dọn canh nóng', 'Tắt bếp, thả hành lá cắt khúc và ngò gai vào nồi canh cho dậy mùi thơm đặc trưng miền Nam. Múc canh ra tô lớn, rắc nốt 0,5 g tiêu đen xay lên mặt và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-5e0564249085d9c1_v4_step_1', 'imp-5e0564249085d9c1', 1, 'prep', 'Sơ chế tôm tươi và ướp gia vị khử tanh', 'Bóc bỏ vỏ và đầu 250 g tôm tươi, rút sạch chỉ đen dọc sống lưng, rửa sạch với nước lạnh rồi để ráo (có thể băm dập 1/3 lượng tôm để nước canh đậm ngọt hơn, phần còn lại để nguyên con). Ướp tôm với 6 ml nước mắm, 2 g hạt nêm, 1/3 lượng tỏi băm, đầu hành băm nhỏ và 0,5 g tiêu đen xay trong 10 phút.', 'Nếu muốn giữ nước canh thật ngọt tự nhiên, bạn có thể rửa sạch phần đầu và vỏ tôm rồi giã lọc lấy nước cốt nấu canh trước khi cho bông cải vào.', 10),
('imp-5e0564249085d9c1_v4_step_2', 'imp-5e0564249085d9c1', 2, 'prep', 'Tách nhánh và làm sạch bông cải xanh', 'Tách 1 bông cải xanh thành từng nhánh nhỏ vừa miệng, phần thân cọng non tước bỏ lớp vỏ xơ ngoài rồi thái lát vát dày 0,5 cm. Ngâm bông cải vào thau nước pha loãng 2 g muối ăn trong 5 phút cho sạch kẽ hoa, vớt ra xả lại nước sạch và để ráo. Thái nhỏ hành lá và ngò rí.', NULL, 5),
('imp-5e0564249085d9c1_v4_step_3', 'imp-5e0564249085d9c1', 3, 'cook', 'Phi thơm tỏi và xào săn tôm tươi', 'Đặt nồi lên bếp ở lửa vừa với 15 ml dầu ăn, cho phần tỏi băm còn lại vào phi 30 giây đến khi dậy mùi thơm vàng nhẹ. Trút tôm đã ướp vào đảo nhanh 2 phút đến khi tôm chuyển sang màu đỏ cam săn lại và chín tới thì vớt riêng phần tôm nguyên con ra đĩa để không bị dai khi nấu lâu.', 'Vớt tôm xào săn ra riêng trước khi nấu bông cải giúp giữ thịt tôm săn ngọt, không bị teo nhỏ và dai xác.', 2),
('imp-5e0564249085d9c1_v4_step_4', 'imp-5e0564249085d9c1', 4, 'cook', 'Nấu sôi nước canh và làm chín bông cải xanh', 'Đổ 1100 ml nước lọc vào nồi vừa xào tôm, bật lửa lớn đun sôi bùng rồi hớt sạch bọt nổi. Thả phần cọng bông cải vào nấu trước 2 phút, sau đó cho toàn bộ nhánh bông cải xanh vào nấu thêm 3 phút trên lửa vừa đến khi bông cải chuyển màu xanh mướt và chín giòn vừa tới.', 'Không đậy nắp kín khi nấu bông cải xanh để rau giữ được màu xanh tươi bắt mắt và không bị nồng mùi.', 3),
('imp-5e0564249085d9c1_v4_step_5', 'imp-5e0564249085d9c1', 5, 'cook', 'Thả tôm trở lại nồi và nêm gia vị thanh ngọt', 'Nêm 12 ml nước mắm ngon, 3 g hạt nêm và 3 g muối ăn vào nồi canh, khuấy nhẹ cho tan đều. Trút đĩa tôm đã xào vào đun sôi trở lại khoảng 1 phút cho tôm chín kỹ hoàn toàn và hòa quyện vị ngọt vào nước canh.', NULL, NULL),
('imp-5e0564249085d9c1_v4_step_6', 'imp-5e0564249085d9c1', 6, 'finish', 'Hoàn thiện tô canh với hành ngò và tiêu', 'Tắt bếp ngay khi canh sôi lại để bông cải không bị nhũn, thả hành lá và ngò rí thái nhỏ vào. Múc canh ra tô, rắc 0,5 g tiêu đen xay còn lại lên trên rồi dọn ăn nóng với cơm trắng.', NULL, NULL),
('imp-9daae727e7894587_v4_step_1', 'imp-9daae727e7894587', 1, 'prep', 'Làm sạch khử mùi và ướp thịt đùi gà', 'Chà xát 550 g đùi gà với 2 g muối ăn và vài lát gừng tươi đập dập trong 2 phút để khử mùi hôi, xả sạch với nước lạnh rồi chặt miếng vừa ăn 3–4 cm, để ráo. Ướp thịt gà với 8 ml nước mắm, 3 g hạt nêm, một nửa hành tím băm, phần gừng băm còn lại, đầu hành băm và 0,5 g tiêu đen xay trong 15 phút.', 'Chà xát da gà bằng muối ăn kết hợp gừng đập dập rồi rửa lại nước sạch sẽ khử hoàn toàn mùi hôi đặc trưng của gia cầm.', 15),
('imp-9daae727e7894587_v4_step_2', 'imp-9daae727e7894587', 2, 'prep', 'Sơ chế bắp cải, cà rốt và hành lá', 'Tách từng lá 1/2 bắp cải trắng, rửa sạch dưới vòi nước rồi cắt miếng vuông cạnh 4 cm cho dễ gắp. Gọt vỏ 1 củ cà rốt, thái khoanh tròn dày 0,5 cm. Rửa sạch phần lá xanh hành lá rồi thái khúc dài 2 cm.', NULL, NULL),
('imp-9daae727e7894587_v4_step_3', 'imp-9daae727e7894587', 3, 'cook', 'Phi thơm hành tím và xào săn thịt gà', 'Bắc nồi lên bếp ở lửa vừa với 15 ml dầu ăn, cho phần hành tím băm còn lại và vài sợi gừng tươi vào phi thơm 30 giây. Trút toàn bộ thịt gà đã ướp vào đảo đều khoảng 4 phút đến khi bề mặt da và thịt gà săn lại, dậy mùi thơm hấp dẫn.', 'Xào săn thịt gà trước khi đổ nước giúp phần thịt bên ngoài se lại, giữ nước ngọt bên trong và làm nước canh thơm đậm hơn.', 4),
('imp-9daae727e7894587_v4_step_4', 'imp-9daae727e7894587', 4, 'cook', 'Hầm gà lấy nước dùng ngọt trong', 'Đổ 1500 ml nước lọc vào nồi gà, bật lửa lớn đun sôi bùng rồi dùng vá hớt thật sạch lớp bọt nổi. Hạ xuống lửa vừa nhỏ, đậy hé vung ninh gà khoảng 15 phút cho thịt gà chín mềm hoàn toàn và nước dùng ngọt thanh.', 'Ninh gà với lửa vừa nhỏ và mở hé vung giúp nước canh giữ độ trong veo, không bị đục váng mỡ.', 15),
('imp-9daae727e7894587_v4_step_5', 'imp-9daae727e7894587', 5, 'cook', 'Nấu chín cà rốt, bắp cải và nêm gia vị', 'Thả cà rốt thái khoanh vào nồi nấu 5 phút trước, sau đó cho toàn bộ bắp cải vào nấu thêm 5 phút trên lửa vừa đến khi bắp cải chín mềm ngọt nhưng vẫn giữ độ giòn nhẹ. Nêm 12 ml nước mắm còn lại, 3 g hạt nêm, 4 g muối ăn và 4 g đường cát trắng cho vừa khẩu vị gia đình.', NULL, 10),
('imp-9daae727e7894587_v4_step_6', 'imp-9daae727e7894587', 6, 'finish', 'Thêm hành lá, tiêu xay và dọn canh', 'Kiểm tra thịt gà chín mềm không còn sắc hồng bên trong xương và rau củ vừa độ chín tới thì tắt bếp. Thả hành lá thái khúc vào nồi đảo nhẹ, múc canh ra tô lớn và rắc 0,5 g tiêu đen xay lên mặt trước khi dùng nóng.', NULL, NULL),
('imp-20123919cd3164a8_v4_step_1', 'imp-20123919cd3164a8', 1, 'prep', 'Sơ chế và ướp cá hồi khử mùi tanh', 'Thấm khô 350 g cá hồi tươi rồi cắt miếng vuông dày 3–4 cm để cá không bị nát khi nấu. Ướp cá với 8 ml nước mắm, 2 g hạt nêm, 1 g tiêu đen xay và đầu hành lá băm nhỏ trong 10 phút cho thịt cá săn và đậm vị.', 'Không ướp cá hồi với nước cốt chanh quá sớm vì axit sẽ làm thịt cá bị tái chín bề mặt và dễ bở khi nấu.', 10),
('imp-20123919cd3164a8_v4_step_2', 'imp-20123919cd3164a8', 2, 'prep', 'Xử lý măng chua, dọc mùng và sơ chế rau quả', 'Luộc kỹ 120 g măng chua trong nước sôi 3–5 phút rồi chắt bỏ nước luộc, xả sạch vắt ráo để loại bỏ độc tố và mùi hăng. Tước vỏ xơ 100 g dọc mùng, thái lát xéo, bóp nhẹ với 2 g muối ăn rồi rửa nhiều lần cho hết ngứa. Thái múi cau 3 quả cà chua, thái lát 1/3 quả dứa chín; rửa sạch giá đỗ, hành lá, rau ngổ, ớt tươi và băm nhỏ hành tím, tỏi khô.', NULL, 2),
('imp-20123919cd3164a8_v4_step_3', 'imp-20123919cd3164a8', 3, 'cook', 'Phi thơm hành tỏi và xào cà chua dứa măng', 'Làm nóng nồi với 15 ml dầu ăn trên lửa vừa, phi thơm hành tím và tỏi khô băm trong 1 phút. Cho một nửa lượng cà chua bổ múi cau, dứa thái lát và măng chua vào xào đều 3 phút để cà chua tiết màu đỏ cam óng đẹp và măng thấm dầu thơm.', NULL, 3),
('imp-20123919cd3164a8_v4_step_4', 'imp-20123919cd3164a8', 4, 'cook', 'Đun sôi nước dùng và nấu chín cá hồi', 'Đổ 1200 ml nước lọc vào nồi, bật lửa lớn đun sôi bùng rồi hớt sạch bọt nổi. Hạ xuống lửa vừa, thả nhẹ từng miếng cá hồi đã ướp cùng phần cà chua còn lại vào nồi nấu khoảng 4–5 phút đến khi thịt cá chuyển hồng cam đục đều, chín tới hoàn toàn mà không bị khô bở.', 'Hạn chế đảo mạnh sau khi thả cá hồi; chỉ dùng vá nhấn nhẹ cá ngập trong nước sôi lăn tăn để giữ miếng cá nguyên vẹn.', 4),
('imp-20123919cd3164a8_v4_step_5', 'imp-20123919cd3164a8', 5, 'cook', 'Nêm gia vị và chần nhanh dọc mùng, giá đỗ', 'Nêm 17 ml nước mắm ngon, 3 g hạt nêm, 2 g muối ăn và 12 g đường cát trắng vào nồi. Thả dọc mùng vào nấu thêm 1 phút cho vừa chín tới rồi thả giá đỗ vào, tắt bếp ngay để giá vẫn giữ được độ giòn ngọt.', NULL, NULL),
('imp-20123919cd3164a8_v4_step_6', 'imp-20123919cd3164a8', 6, 'finish', 'Vắt nước cốt chanh và hoàn thiện với rau ngổ', 'Khi nồi canh đã tắt bếp và bớt sôi sùng sục, từ từ rưới nước cốt 1 quả chanh tươi vào để tạo vị chua thanh mà không bị đắng. Rắc hành lá, rau ngổ và ớt tươi thái lát lên mặt, múc canh nóng ra tô dùng kèm cơm trắng.', 'Luôn vắt nước cốt chanh sau khi tắt bếp để giữ trọn hương thơm tinh dầu chanh và tránh làm nước canh bị đắng.', NULL),
('imp-d500b08871587628_v4_step_1', 'imp-d500b08871587628', 1, 'prep', 'Sơ chế tôm tươi, dứa chín và gia vị thơm', 'Rửa sạch 350 g tôm tươi, cắt bỏ đầu và râu, bóc vỏ chừa lại phần đuôi rồi khều sạch chỉ đen ở lưng và để thật ráo nước. Gọt sạch vỏ bỏ mắt 1/2 quả dứa chín, thái lát mỏng 0,5 cm; băm nhỏ hành tím và tỏi khô chia làm hai phần; thái lát ớt hiểm và cắt nhỏ hành lá.', 'Chọn dứa chín vàng có mùi thơm dịu sẽ giúp món tôm kho có vị chua thanh tự nhiên mà không bị chua gắt.', NULL),
('imp-d500b08871587628_v4_step_2', 'imp-d500b08871587628', 2, 'marinate', 'Ướp tôm thấm vị trước khi kho', 'Trộn đều tôm trong tô với một nửa phần hành tím và tỏi băm, 18 ml nước mắm ngon, 6 g đường cát trắng và nửa lượng tiêu đen xay. Ướp khoảng 15 phút để thịt tôm săn chắc và đậm vị.', NULL, 15),
('imp-d500b08871587628_v4_step_3', 'imp-d500b08871587628', 3, 'cook', 'Phi thơm hành tỏi ớt và xào săn tôm', 'Làm nóng chảo sâu lòng với 20 ml dầu ăn trên lửa vừa, phi thơm phần hành tím, tỏi băm còn lại cùng ớt hiểm thái lát trong 1 phút. Trút toàn bộ tôm đã ướp vào đảo đều trên lửa vừa lớn khoảng 3 phút cho đến khi tôm cong lại và chuyển màu đỏ cam đều.', 'Đảo nhẹ tay và không xào quá lâu ở bước đầu để giữ tôm nguyên con mọng nước, không bị khô teo.', 3),
('imp-d500b08871587628_v4_step_4', 'imp-d500b08871587628', 4, 'cook', 'Thêm dứa chín và gia vị vào chảo tôm', 'Cho dứa cắt lát vào đảo nhẹ cùng tôm 1 phút, sau đó rưới 100 ml nước lọc vào xâm xấp mặt tôm, nêm tiếp 12 ml nước mắm còn lại, 9 g đường cát trắng và 4 g hạt nêm.', NULL, NULL),
('imp-d500b08871587628_v4_step_5', 'imp-d500b08871587628', 5, 'cook', 'Kho mở nắp cho nước sốt sánh keo bóng', 'Đợi nước trong chảo sôi lên thì hạ lửa nhỏ, kho mở nắp liu riu khoảng 8–10 phút, thỉnh thoảng đảo nhẹ cho dứa tiết nước ngọt và nước kho rút cạn sánh keo bóng mượt bám đều quanh thân tôm và lát dứa.', 'Không cho quá nhiều nước từ đầu vì bản thân dứa chín cũng sẽ tiết thêm nước ngọt trong khi kho.', 9),
('imp-d500b08871587628_v4_step_6', 'imp-d500b08871587628', 6, 'finish', 'Nêm lại, rắc hành lá và tiêu thưởng thức', 'Nếm thử xem vị mặn ngọt chua hài hòa đã vừa miệng chưa rồi tắt bếp. Rắc hành lá thái nhỏ và phần tiêu đen xay còn lại lên trên, đảo nhẹ và dọn tôm kho dứa dùng nóng với cơm trắng.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-c7e40140f9ee9591_v4_step_1', 'imp-c7e40140f9ee9591', 1, 'prep', 'Làm sạch đùi gà và băm nhuyễn sả ớt', 'Chà xát 700 g đùi gà với 4 g muối hạt cho hết mùi hôi, rửa sạch lại nhiều lần với nước rồi để ráo, chặt miếng vừa ăn cỡ 3,5–4 cm. Lột vỏ già của 5 cây sả tươi, đập dập rồi băm nhuyễn; băm nhỏ 3 quả ớt hiểm đỏ, tỏi và hành tím; thái lát quả ớt còn lại và cắt khúc hành lá.', 'Dùng sả non phần củ trắng bên dưới để băm sẽ giúp thịt gà thơm ngọt và không bị xơ cứng khi ăn.', NULL),
('imp-c7e40140f9ee9591_v4_step_2', 'imp-c7e40140f9ee9591', 2, 'marinate', 'Ướp thịt gà với sả ớt đỏ và dầu ăn', 'Trộn thịt gà trong tô lớn cùng toàn bộ sả băm, 3 quả ớt hiểm băm, hành tím và tỏi băm, 20 ml nước mắm, 8 g đường cát trắng, 5 g hạt nêm, 3 g muối, 1 g tiêu đen xay và 12 ml dầu ăn. Trộn đều và ướp trong 25 phút cho thấm sâu.', 'Trộn thêm chút dầu ăn vào lúc ướp giúp bề mặt thịt gà mềm mọng, không bị khô xơ trong suốt quá trình kho.', 25),
('imp-c7e40140f9ee9591_v4_step_3', 'imp-c7e40140f9ee9591', 3, 'sauce', 'Thắng nước màu cánh gián bóng đẹp', 'Làm nóng nồi đáy dày với 8 ml dầu ăn còn lại và 20 g đường cát trắng trên lửa nhỏ. Đun đến khi đường tan hết và chuyển màu nâu cánh gián thì nhanh tay rót 30 ml nước lọc ấm vào khuấy đều rồi tắt bếp tạm trong vài giây.', 'Hãm nước màu bằng nước ấm ngay khi vừa đạt màu cánh gián để đường không cháy đen gây vị đắng gắt.', NULL),
('imp-c7e40140f9ee9591_v4_step_4', 'imp-c7e40140f9ee9591', 4, 'cook', 'Xào săn thịt gà trong nồi nước màu', 'Bật bếp lại ở lửa vừa lớn, cho toàn bộ thịt gà đã ướp vào nồi nước màu và đảo đều tay trong 5 phút đến khi thịt săn chắc, da gà hơi xém vàng và dậy mùi sả ớt thơm nức.', NULL, 5),
('imp-c7e40140f9ee9591_v4_step_5', 'imp-c7e40140f9ee9591', 5, 'cook', 'Kho nhỏ lửa cho gà chín kỹ thấm sốt', 'Rót 100 ml nước lọc ấm cùng 10 ml nước mắm còn lại vào xâm xấp mặt thịt, đợi nước sôi thì đậy nắp, hạ lửa nhỏ kho liu riu 20 phút và đảo nhẹ vài lần cho gà chín hoàn toàn tận xương.', NULL, 20),
('imp-c7e40140f9ee9591_v4_step_6', 'imp-c7e40140f9ee9591', 6, 'finish', 'Sánh sốt, rắc hành lá và trình bày', 'Mở nắp kho thêm 3–4 phút trên lửa vừa nhỏ đến khi nước sốt cạn sánh sệt, áo bóng quanh từng miếng gà. Nêm lại vừa ăn, tắt bếp rồi rắc hành lá cắt khúc, ớt thái lát và 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng.', NULL, NULL),
('imp-ebbd704089d9c62a_v4_step_1', 'imp-ebbd704089d9c62a', 1, 'prep', 'Sơ chế thịt đùi gà và các loại hành, sả, tỏi', 'Thịt đùi gà rút xương rửa sạch, thấm khô rồi cắt miếng vừa ăn dày khoảng 2 cm. Hành tây bóc vỏ, cắt múi cau; sả tươi và hành tím khô băm thật nhuyễn; tỏi khô băm nhỏ và chia làm hai phần.', NULL, NULL),
('imp-ebbd704089d9c62a_v4_step_2', 'imp-ebbd704089d9c62a', 2, 'marinate', 'Ướp thịt đùi gà thấm sốt dầu hào sả tỏi', 'Cho thịt đùi gà vào tô cùng sả băm, hành tím băm, một nửa lượng tỏi băm, 15 ml dầu hào, 10 ml nước mắm ngon, 10 ml nước tương (xì dầu), 10 g đường cát trắng, 6 g hạt nêm, 3 g muối ăn và 1 g tiêu đen xay. Trộn thật đều và ướp 20–25 phút cho gà ngấm sâu gia vị.', 'Ướp đủ thời gian giúp sả, dầu hào và nước tương thấm vào từng thớ thịt đùi gà mềm ngọt.', 20),
('imp-ebbd704089d9c62a_v4_step_3', 'imp-ebbd704089d9c62a', 3, 'cook', 'Phi thơm tỏi và xào săn thịt gà', 'Đặt chảo lên bếp lửa lớn, đun nóng 25 ml dầu ăn rồi cho phần tỏi băm còn lại vào phi thơm vàng nhẹ. Trút toàn bộ thịt đùi gà đã ướp vào đảo nhanh tay trong 4 phút đến khi thịt săn chắc và vàng cạnh.', NULL, 4),
('imp-ebbd704089d9c62a_v4_step_4', 'imp-ebbd704089d9c62a', 4, 'cook', 'Om chín kỹ thịt đùi gà với nước lọc', 'Hạ xuống lửa vừa-nhỏ, rót 40 ml nước lọc vào chảo rồi đậy nắp om khoảng 8 phút cho thịt đùi gà chín hoàn toàn tận lõi (không còn dịch hồng bên trong) và phần sốt hơi sánh lại.', 'Om với lượng nước nhỏ giúp thịt đùi gà chín mềm mọng nước mà gia vị không bị cháy đáy chảo.', 8),
('imp-ebbd704089d9c62a_v4_step_5', 'imp-ebbd704089d9c62a', 5, 'cook', 'Xào nhanh hành tây giữ độ giòn ngọt', 'Mở nắp, tăng lên lửa lớn và thả toàn bộ hành tây cắt múi cau vào đảo đều tay trong khoảng 2–3 phút đến khi hành tây vừa chín tới, chuyển màu hơi trong nhưng vẫn giữ được độ giòn ngọt.', 'Chỉ cho hành tây vào sau khi gà đã chín kỹ để hành không bị nhũn nát và vẫn giữ vị ngọt tự nhiên.', 3),
('imp-ebbd704089d9c62a_v4_step_6', 'imp-ebbd704089d9c62a', 6, 'finish', 'Nêm lại và dọn nóng', 'Nêm nếm lại sốt cho vừa khẩu vị rồi tắt bếp. Bày gà xào hành tây sốt dầu hào ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và dùng nóng cùng cơm trắng.', NULL, NULL),
('imp-b7ae5824ff7e6a74_v4_step_1', 'imp-b7ae5824ff7e6a74', 1, 'prep', 'Gọt vỏ và ngâm nước muối loại bỏ nhựa su su', 'Ngâm 3 quả su su non trong nước sạch 2 phút hoặc gọt vỏ trực tiếp dưới vòi nước để không bị dính nhựa. Chẻ đôi bỏ hạt rồi thái lát mỏng vừa ăn dày khoảng 0,3 cm. Ngâm lát su su trong thau nước pha 2 g muối ăn khoảng 5 phút để sạch nhựa và giữ sắc xanh rồi xả sạch, để thật ráo.', 'Ngâm nhanh qua nước muối loãng rồi để ráo giúp lát su su giòn thanh và không bị thâm sẫm.', 5),
('imp-b7ae5824ff7e6a74_v4_step_2', 'imp-b7ae5824ff7e6a74', 2, 'prep', 'Chuẩn bị tỏi đập dập, hành lá và ớt', 'Tỏi khô bóc vỏ, đập dập rồi băm nhỏ, chia thành hai phần bằng nhau. Hành lá rửa sạch cắt khúc 3 cm; ớt sừng đỏ thái lát xéo mỏng.', NULL, NULL),
('imp-b7ae5824ff7e6a74_v4_step_3', 'imp-b7ae5824ff7e6a74', 3, 'cook', 'Phi thơm phần tỏi ban đầu', 'Làm nóng 25 ml dầu ăn trong chảo trên lửa vừa, cho một nửa lượng tỏi băm vào phi đều tay khoảng 30–40 giây đến khi tỏi ngả vàng nhẹ và tỏa hương thơm nồng.', 'Không phi tỏi quá sẫm màu vì tỏi cháy sẽ tạo vị đắng cho đĩa rau thanh nhẹ.', NULL),
('imp-b7ae5824ff7e6a74_v4_step_4', 'imp-b7ae5824ff7e6a74', 4, 'cook', 'Xào nhanh su su trên lửa lớn', 'Tăng bếp lên lửa lớn, trút toàn bộ su su đã để ráo vào chảo dầu tỏi và đảo nhanh tay liên tục khoảng 3 phút. Nêm 5 g hạt nêm, 2 g muối ăn còn lại và 8 ml nước mắm ngon, đảo đều thêm 1,5 phút cho lát su su hơi trong và chín giòn.', 'Giữ lửa lớn suốt quá trình xào giúp su su chín nhanh bên ngoài mà vẫn giòn sần sật, không bị ra nhiều nước.', 4),
('imp-b7ae5824ff7e6a74_v4_step_5', 'imp-b7ae5824ff7e6a74', 5, 'cook', 'Thêm phần tỏi cuối, hành lá và ớt lát', 'Khi su su vừa chín tới, rắc nốt một nửa lượng tỏi băm còn lại cùng hành lá cắt khúc và ớt sừng đỏ thái lát vào chảo, đảo đều thêm 30 giây cho dậy mùi tỏi tươi rồi tắt bếp ngay.', NULL, NULL),
('imp-b7ae5824ff7e6a74_v4_step_6', 'imp-b7ae5824ff7e6a74', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Bày su su xào tỏi ra đĩa, rắc 1,5 g tiêu đen xay lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-30c2038c8737538c_v4_step_1', 'imp-30c2038c8737538c', 1, 'marinate', 'Thái lát và ướp thịt bò mềm với dầu hào', 'Thấm khô thịt thăn bò rồi thái lát mỏng ngang thớ. Cho thịt vào tô ướp cùng một nửa lượng tỏi băm, 15 ml dầu hào, 3 g muối ăn, 2 g bột ngọt, 1 g tiêu đen xay và 10 ml dầu ăn; trộn đều và để thấm 15 phút.', 'Ướp dầu ăn và dầu hào giúp từng lát thịt bò mềm bóng, giữ ẩm tốt khi xào lửa lớn.', 15),
('imp-30c2038c8737538c_v4_step_2', 'imp-30c2038c8737538c', 2, 'prep', 'Sơ chế nấm đùi gà và hành ngò', 'Nấm đùi gà cắt bỏ phần gốc dính đất, rửa nhanh với nước muối loãng rồi vớt ra để thật ráo nước, thái lát vát dày khoảng 0,5 cm vừa ăn. Phần tỏi còn lại băm nhỏ; hành lá và ngò rí rửa sạch cắt khúc.', 'Không ngâm nấm đùi gà quá lâu trong nước vì nấm sẽ hút nước và tiết ra nhiều nước khi xào.', NULL),
('imp-30c2038c8737538c_v4_step_3', 'imp-30c2038c8737538c', 3, 'cook', 'Xào tái thịt bò trên lửa lớn', 'Đun nóng 15 ml dầu ăn trong chảo trên lửa lớn, phi thơm phần tỏi băm còn lại rồi trút thịt bò đã ướp vào đảo nhanh tay 1,5–2 phút đến khi thịt vừa chín tái 80% thì trút ngay ra đĩa riêng.', NULL, 2),
('imp-30c2038c8737538c_v4_step_4', 'imp-30c2038c8737538c', 4, 'cook', 'Xào nấm đùi gà lửa lớn cho săn giòn', 'Dùng lại chảo, thêm 10 ml dầu ăn đun nóng rồi cho nấm đùi gà vào xào trên lửa lớn khoảng 3–4 phút. Nêm 5 g hạt nêm, đảo đều đến khi miếng nấm hơi xém vàng cạnh và chín săn giòn.', 'Xào nấm trên lửa lớn giúp bề mặt nấm săn thơm và không bị ra nước lênh láng.', 4),
('imp-30c2038c8737538c_v4_step_5', 'imp-30c2038c8737538c', 5, 'cook', 'Đảo quyện thịt bò và nấm đùi gà', 'Trút toàn bộ thịt bò đã xào tái cùng nước thịt trong đĩa trở lại chảo nấm đùi gà, đảo nhanh tay trên lửa lớn 45–60 giây để nấm hút trọn vị ngọt của thịt bò và thịt bò chín hoàn toàn.', NULL, NULL),
('imp-30c2038c8737538c_v4_step_6', 'imp-30c2038c8737538c', 6, 'finish', 'Thêm hành lá, ngò rí và dọn nóng', 'Cho hành lá và ngò rí vào đảo nhanh 15 giây rồi tắt bếp. Bày bò xào nấm đùi gà ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-019bbf517408a529_v4_step_1', 'imp-019bbf517408a529', 1, 'marinate', 'Thấm khô và ướp khúc cá với muối tiêu', 'Thấm thật khô 4 khúc cá thu bằng khăn giấy sạch, xoa đều 3 g muối ăn và 0,7 g tiêu đen xay lên các mặt cá rồi để ướp 10 phút cho thịt cá săn chắc và đậm vị hơn khi chiên.', 'Thấm thật khô hai mặt khúc cá bằng khăn giấy trước khi ướp giúp thịt cá săn chắc và không bị nát khi trở mặt.', 10),
('imp-019bbf517408a529_v4_step_2', 'imp-019bbf517408a529', 2, 'prep', 'Sơ chế cà chua, hành tím, tỏi và hành lá', 'Cà chua chín đỏ rửa sạch, bỏ cuống rồi thái hạt lựu nhỏ để sốt nhanh nhừ mịn. Hành tím và tỏi khô bóc vỏ băm nhỏ; ớt hiểm thái lát; hành lá cắt khúc ngắn 2 cm.', NULL, NULL),
('imp-019bbf517408a529_v4_step_3', 'imp-019bbf517408a529', 3, 'cook', 'Chiên cá vàng đều hai mặt', 'Làm nóng 40 ml dầu ăn trong chảo chống dính trên lửa vừa, đặt các khúc cá vào chiên khoảng 4 phút mỗi mặt đến khi hai mặt vàng xém săn chắc và thịt cá gần chín hoàn toàn thì gắp ra đĩa để ráo bớt dầu.', 'Lau cá thật khô và chờ dầu nóng già mới thả cá vào sẽ giúp cá không bị sát chảo và ít bắn dầu.', 8),
('imp-019bbf517408a529_v4_step_4', 'imp-019bbf517408a529', 4, 'sauce', 'Phi thơm hành tỏi và xào nhừ sốt cà chua', 'Chắt bớt dầu cũ, làm nóng 20 ml dầu ăn sạch trong chảo trên lửa vừa rồi phi thơm hành tím băm và tỏi băm 1 phút. Cho toàn bộ cà chua vào xào đảo 3 phút đến khi mềm nhuyễn, rót thêm 120 ml nước lọc vào đun sôi nhẹ và nêm 30 ml nước mắm ngon, 8 ml dầu hào cùng 12 g đường cát trắng khuấy đều.', 'Xào cà chua thật nhừ thành sốt sánh mịn trước khi thả cá vào sẽ giúp màu đỏ đẹp và sốt bám đều quanh từng khúc cá.', 4),
('imp-019bbf517408a529_v4_step_5', 'imp-019bbf517408a529', 5, 'cook', 'Rim cá thấm sốt cà chua trên lửa nhỏ', 'Xếp nhẹ nhàng các khúc cá đã chiên vào chảo sốt, hạ lửa nhỏ và rim khoảng 8 phút (có thể lật nhẹ một lần hoặc dùng thìa rưới sốt lên mặt trên) cho sốt sánh sệt lại, thịt cá chín kỹ hoàn toàn và thấm đẫm vị chua ngọt.', 'Rim cá trên lửa nhỏ và chỉ trở nhẹ một lần giúp khúc cá nguyên vẹn, thấm sâu vị sốt cà chua đậm đà.', 8),
('imp-019bbf517408a529_v4_step_6', 'imp-019bbf517408a529', 6, 'finish', 'Rắc hành lá, ớt và dọn dùng nóng', 'Thả hành lá cắt khúc và ớt hiểm thái lát (nếu ăn cay) vào chảo, đảo nhẹ 30 giây rồi tắt bếp. Gắp cá ra đĩa, rưới đều sốt cà chua lên mặt, rắc nốt phần tiêu đen xay còn lại và thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-d7836b7d1a4d90b3_v4_step_1', 'imp-d7836b7d1a4d90b3', 1, 'prep', 'Chần sơ và xé dải nấm đùi gà thật ráo', 'Cắt bỏ phần gốc nấm đùi gà, rửa sạch rồi thả vào 800 ml nước lọc đang sôi chần nhanh 2 phút. Vớt nấm ra để nguội, dùng khăn giấy ép thấm thật khô ráo nước rồi cắt hoặc xé thành dải dài dọc theo thân nấm dày khoảng 1 cm.', 'Chần sơ rồi thấm thật khô giúp nấm bớt tiết nước khi chiên, giữ được độ dai ngọt và không làm ỉu lớp vỏ bột.', 2),
('imp-d7836b7d1a4d90b3_v4_step_2', 'imp-d7836b7d1a4d90b3', 2, 'marinate', 'Ướp nấm và chuẩn bị trứng áo bột năng', 'Ướp các dải nấm với 4 g muối ăn và 2 g tiêu đen xay trong 10 phút cho ngấm vị. Trong tô, đánh tan 1 quả trứng gà với 10 g bột năng; đổ 90 g bột năng khô còn lại ra đĩa phẳng. Lá húng quế rửa sạch vẩy ráo hoàn toàn, hành lá thái nhỏ nếu dùng.', NULL, 10),
('imp-d7836b7d1a4d90b3_v4_step_3', 'imp-d7836b7d1a4d90b3', 3, 'prep', 'Nhúng trứng và áo đều bột năng quanh nấm', 'Lần lượt nhúng từng dải nấm qua chén trứng bột cho ướt đều rồi lăn ngay qua đĩa bột năng khô, lắc nhẹ tay cho bột phủ đều và rơi bớt phần bột thừa.', 'Không để nấm nhúng trứng nằm chờ quá lâu trước khi chiên để lớp bột khô không bị vón ẩm.', NULL),
('imp-d7836b7d1a4d90b3_v4_step_4', 'imp-d7836b7d1a4d90b3', 4, 'cook', 'Chiên nấm hai lần lửa cho vỏ giòn lâu', 'Đun nóng 450 ml dầu ăn trong chảo sâu lòng trên lửa vừa đến khi đầu đũa sủi tăm. Thả nấm vào chiên lần 1 khoảng 4 phút cho vỏ vừa se vàng nhạt và nấm chín kỹ thì vớt ra giá. Sau đó đun dầu nóng già ở lửa lớn rồi thả nấm vào chiên nhanh lần 2 thêm 1 phút cho vỏ vàng giòn rụm, vớt ra giấy thấm dầu.', 'Chiên 2 lần lửa là kỹ thuật giúp món nấm chiên giữ độ giòn xốp lâu hơn hẳn và đẩy bớt dầu thừa ra ngoài.', 5),
('imp-d7836b7d1a4d90b3_v4_step_5', 'imp-d7836b7d1a4d90b3', 5, 'cook', 'Chiên giòn nhanh lá húng quế ăn kèm', 'Tắt bớt hoặc hạ lửa nhỏ, nhúng nhanh nắm lá húng quế khô ráo vào phần trứng bột còn lại (hoặc thả trực tiếp) chiên khoảng 20–30 giây đến khi lá vừa giòn tan xanh sậm thì vớt ngay ra giấy thấm dầu để không bị cháy đắng.', NULL, 1),
('imp-d7836b7d1a4d90b3_v4_step_6', 'imp-d7836b7d1a4d90b3', 6, 'finish', 'Bày nấm chiên giòn và thưởng thức nóng', 'Xếp nấm đùi gà chiên giòn xen kẽ lá húng quế chiên ra đĩa, rắc thêm hành lá thái nhỏ (nếu dùng) và dùng nóng ngay với tương ớt.', NULL, NULL),
('imp-9d527dacd46efc67_v4_step_1', 'imp-9d527dacd46efc67', 1, 'prep', 'Thấm khô đậu phụ và băm nhuyễn sả tỏi ớt', 'Rửa nhẹ đậu phụ trắng, thấm thật khô hai mặt rồi cắt miếng vuông dày khoảng 2 cm để khi chiên không bị bắn dầu. Sả tươi băm thật nhuyễn; tỏi khô (nếu dùng) băm nhỏ; 2 quả ớt hiểm băm nhỏ và 1 quả thái lát; ngò rí cắt khúc 3 cm; hành lá thái nhỏ; dưa leo thái lát mỏng xếp sẵn quanh viền đĩa.', 'Thấm khô kỹ bề mặt đậu phụ trước khi chiên là bí quyết để dầu không bắn tung tóe và đậu lên màu vàng giòn.', NULL),
('imp-9d527dacd46efc67_v4_step_2', 'imp-9d527dacd46efc67', 2, 'cook', 'Chiên đậu phụ vàng giòn đều các mặt', 'Đun nóng 225 ml dầu ăn trong chảo trên lửa vừa đến khi đầu đũa sủi bọt mạnh. Thả từng miếng đậu phụ vào chiên thành 2 mẻ khoảng 4–5 phút mỗi mẻ đến khi các mặt phồng vàng giòn rụm, vớt ra đĩa có lót giấy thấm dầu.', 'Không xếp đậu quá khít trong chảo để nhiệt độ dầu không bị tụt, giúp vỏ đậu giòn đều mà không ngấm dầu.', 9),
('imp-9d527dacd46efc67_v4_step_3', 'imp-9d527dacd46efc67', 3, 'sauce', 'Phi thơm sả băm, tỏi và ớt hiểm', 'Chắt bớt dầu thừa trong chảo, giữ lại 25 ml dầu ăn sạch rồi phi thơm tỏi băm (nếu dùng) ở lửa vừa trong 30 giây, sau đó cho toàn bộ sả băm và 2 quả ớt băm vào đảo đều tay khoảng 2 phút cho sả chuyển màu vàng nhạt và dậy mùi thơm lừng.', 'Đảo liên tục trên lửa vừa để sả vàng giòn đều mà không bị cháy khét ở phần cạnh chảo.', 2),
('imp-9d527dacd46efc67_v4_step_4', 'imp-9d527dacd46efc67', 4, 'sauce', 'Nêm gia vị chay vào chảo sả ớt', 'Hạ lửa nhỏ, cho 15 ml nước tương, 6 g hạt nêm chay nấm hương, 2 g đường cát trắng và 1,5 g tiêu đen xay vào chảo sả ớt, đảo nhanh 30 giây cho gia vị tan đều thấm vào từng vụn sả.', NULL, NULL),
('imp-9d527dacd46efc67_v4_step_5', 'imp-9d527dacd46efc67', 5, 'cook', 'Xóc đều đậu phụ chiên bám sả ớt thơm', 'Trút toàn bộ đậu phụ đã chiên giòn vào chảo sả ớt, tăng nhẹ lên lửa vừa và đảo xóc nhẹ nhàng bằng đũa trong khoảng 2 phút để lớp sả ớt đậm đà bám đều quanh từng miếng đậu mà không làm vỡ nát.', 'Dùng đũa đảo nhẹ tay khi xóc đậu phụ với sả ớt để giữ nguyên khối miếng đậu vàng giòn không bị vỡ nát.', 2),
('imp-9d527dacd46efc67_v4_step_6', 'imp-9d527dacd46efc67', 6, 'finish', 'Pha nước chấm xì dầu và bày đĩa thưởng thức', 'Trộn 25 ml nước tương còn lại với 2 g đường và ớt thái lát làm nước chấm. Xếp đậu phụ chiên sả ớt vào giữa đĩa đã viền lát dưa leo, rắc ngò rí và hành lá thái nhỏ (nếu dùng) lên trên rồi dọn nóng với cơm trắng.', NULL, NULL),
('imp-236e3b84d403909e_v4_step_1', 'imp-236e3b84d403909e', 1, 'prep', 'Làm sạch khử mùi đùi gà và sơ chế hành gừng', 'Nhặt sạch lông tơ còn sót trên 4 chiếc đùi gà, chà xát đều 6 g muối hạt và nước cốt 1 quả chanh tươi lên bề mặt da trong 2 phút rồi xả sạch dưới vòi nước lạnh, để ráo. Đập dập 40 g gừng và 30 g hành tím; rửa sạch hành lá cắt khúc 1 bó và thái nhỏ 1 bó; lá chanh thái sợi chỉ mảnh.', 'Chà xát muối hạt cùng nước cốt chanh giúp làm sạch hoàn toàn chất nhờn và mùi hôi trên da gà mà vẫn giữ được độ căng mịn.', NULL),
('imp-236e3b84d403909e_v4_step_2', 'imp-236e3b84d403909e', 2, 'cook', 'Luộc đùi gà từ nước lạnh và hớt bọt trong', 'Xếp đùi gà vào nồi rộng, đổ 2 lít nước lọc lạnh ngập mặt thịt rồi thêm gừng đập dập, hành tím đập dập, 1 bó hành lá cắt khúc, 6 g muối hạt và 5 g hạt nêm. Bật lửa vừa đun khoảng 8 phút đến khi nước bắt đầu sôi thì hớt sạch bọt nổi cho nước dùng trong veo.', 'Cho gà vào từ nước lạnh và chỉ đun lửa vừa giúp nhiệt truyền vào tận xương mà da gà không bị co rút nứt rách.', 8),
('imp-236e3b84d403909e_v4_step_3', 'imp-236e3b84d403909e', 3, 'cook', 'Sôi lăn tăn rồi tắt bếp ủ chín mềm mọng', 'Hạ nhỏ lửa để nồi nước chỉ sôi lăn tăn nhẹ trong 6 phút, sau đó tắt bếp, đậy kín nắp vung và ủ gà trong nồi thêm 20 phút cho thịt chín ngấm từ từ đến tận xương mà vẫn giữ nguyên độ ẩm ngọt.', 'Phương pháp luộc kết hợp ủ nhiệt giúp thịt đùi gà mềm mọng đều, không bị khô bã ở phần ngoài hay còn đỏ máu ở khớp xương.', 26),
('imp-236e3b84d403909e_v4_step_4', 'imp-236e3b84d403909e', 4, 'cook', 'Ngâm nước lạnh làm giòn da và tạo màu vàng óng', 'Dùng tăm xiên vào phần thịt dày nhất của đùi gà thấy nước ứa ra trong suốt không còn màu hồng là đã chín. Vớt gà ra ngâm ngay vào thau nước lạnh sạch khoảng 5 phút cho da săn giòn, rồi vớt ra rổ để ráo. Hòa 2 g bột nghệ với 1 muỗng canh nước luộc gà quét thật mỏng lên mặt da để lên màu vàng ươm bắt mắt.', NULL, 5),
('imp-236e3b84d403909e_v4_step_5', 'imp-236e3b84d403909e', 5, 'sauce', 'Pha muối tiêu chanh ớt chấm thịt gà', 'Trộn 6 g muối hạt còn lại với 2 g tiêu đen xay và vài lát ớt tươi trong chén nhỏ, vắt nước cốt 1 quả chanh tươi còn lại vào khuấy nhẹ cho dậy mùi thơm.', NULL, NULL),
('imp-236e3b84d403909e_v4_step_6', 'imp-236e3b84d403909e', 6, 'finish', 'Chặt gà xếp đĩa và rắc hành lá, lá chanh', 'Đợi đùi gà ráo mặt, dùng dao sắc chặt thành từng miếng vừa ăn xếp ngay ngắn ra đĩa. Rắc đều phần hành lá thái nhỏ và lá chanh thái chỉ lên trên, dọn dùng ngay cùng chén muối tiêu chanh ớt.', NULL, NULL),
('imp-df7571988423623f_v4_step_1', 'imp-df7571988423623f', 1, 'prep', 'Làm sạch mực tươi và cắt khoanh vừa ăn', 'Kéo nhẹ đầu mực tách khỏi thân, rút bỏ túi mực, nang sống lưng và nội tạng, cắt bỏ mắt và răng mực rồi lột lớp da ngoài. Rửa mực 2–3 lần dưới vòi nước lạnh cho thật sạch nhớt, để ráo; mực nhỏ để nguyên con, mực to cắt khoanh dày 2 cm.', 'Lột bỏ lớp màng da sẫm bên ngoài giúp miếng mực sau khi hấp có màu trắng đẹp mắt, ăn giòn ngọt và giảm hẳn mùi tanh.', NULL),
('imp-df7571988423623f_v4_step_2', 'imp-df7571988423623f', 2, 'marinate', 'Ướp mực với nước mắm, đường và tiêu xay', 'Cho mực vào tô sạch cùng 15 ml nước mắm ngon, 4 g đường cát trắng và 1 g tiêu đen xay, trộn nhẹ cho gia vị bám đều rồi để ướp 15 phút cho thịt mực săn và đậm đà.', 'Ướp mực trước với chút nước mắm giúp mực khi hấp ra ít nước hơn và giữ được vị ngọt đậm tự nhiên.', 15),
('imp-df7571988423623f_v4_step_3', 'imp-df7571988423623f', 3, 'prep', 'Sơ chế sả, gừng, ớt hiểm và hành lá', 'Bóc bỏ bẹ già 3 cây sả, đập dập rồi cắt khúc dài 5 cm. Cạo vỏ 20 g gừng thái lát mỏng. Thái lát vát 1 quả ớt hiểm để hấp và băm nhỏ 1 quả làm nước chấm. Rửa sạch hành lá, cắt khúc 4 cm.', NULL, NULL),
('imp-df7571988423623f_v4_step_4', 'imp-df7571988423623f', 4, 'sauce', 'Pha chén nước mắm chanh ớt chấm mực', 'Khuấy tan 15 ml nước mắm ngon còn lại với 4 g đường cát trắng, vắt nước cốt 1 quả chanh tươi cùng 1 g tiêu đen xay và 1 quả ớt hiểm băm nhỏ tạo thành chén nước chấm chua ngọt cay nồng.', NULL, NULL),
('imp-df7571988423623f_v4_step_5', 'imp-df7571988423623f', 5, 'cook', 'Hấp mực nhanh trên lửa lớn cùng sả ớt', 'Đổ 500 ml nước lọc vào nồi hấp đun sôi bùng trên lửa lớn. Xếp sả đập dập và gừng thái lát xuống đáy đĩa sâu lòng, đặt mực đã ướp lên trên rồi rải ớt hiểm thái lát và hành lá cắt khúc phủ mặt. Cho đĩa vào xửng đậy kín vung và hấp lửa lớn 7 phút đến khi mực chuyển trắng đục và cong săn lại.', 'Hấp mực ở lửa lớn vừa đủ 6–8 phút; mực vừa chín tới sẽ giòn sần sật, nếu kéo dài thời gian mực sẽ bị teo dai.', 7),
('imp-df7571988423623f_v4_step_6', 'imp-df7571988423623f', 6, 'finish', 'Ủ ngắn và dọn đĩa mực hấp nóng hổi', 'Tắt bếp, giữ nguyên đĩa mực trong nồi thêm 1 phút rồi nhấc ra, gạn rưới phần nước hấp thơm sả ớt đều lên thân mực và dọn ăn nóng ngay cùng chén nước mắm chanh ớt.', NULL, NULL),
('imp-2b88b3e83b941e80_v4_step_1', 'imp-2b88b3e83b941e80', 1, 'prep', 'Sơ chế khử nhựa và bào sợi su su, cà rốt', 'Khứa nhẹ vài đường quanh quả su su và ngâm nước lạnh 5 phút cho chảy bớt nhựa rồi gọt vỏ, bổ đôi bỏ hạt và bào sợi mảnh. Cà rốt gọt vỏ bào sợi tương tự. Trộn su su với 4 g muối ăn, cà rốt với 2 g muối ăn trong hai tô riêng, để yên 10 phút cho ra bớt nước rồi dùng tay sạch vắt thật ráo.', 'Khứa vỏ su su ngâm nước trước khi gọt giúp tránh dính nhựa tay và giữ sợi su su giòn trắng không chát.', 10),
('imp-2b88b3e83b941e80_v4_step_2', 'imp-2b88b3e83b941e80', 2, 'cook', 'Luộc chín tôm tươi và chẻ đôi', 'Đun sôi 500 ml nước lọc trên lửa lớn, thả tôm tươi đã rửa sạch rút chỉ đen vào luộc khoảng 3 phút đến khi tôm chuyển màu đỏ cam đều, thịt săn chín hoàn toàn. Vớt tôm ra để nguội, bóc sạch vỏ và chẻ đôi theo chiều dọc.', NULL, 3),
('imp-2b88b3e83b941e80_v4_step_3', 'imp-2b88b3e83b941e80', 3, 'cook', 'Rang lạc, phi hành tím và chuẩn bị rau thơm', 'Rang chín vàng lạc trên lửa nhỏ, xát sạch vỏ lụa và giã dập vừa. Bắc chảo nhỏ với 15 ml dầu ăn ở lửa nhỏ, phi hành tím thái lát đến khi vừa ngả vàng giòn thì vớt ngay ra giấy thấm dầu. Nhặt rửa sạch rau răm và ngò rí, cắt khúc; băm nhỏ tỏi và 1 quả ớt hiểm, quả còn lại thái lát.', NULL, NULL),
('imp-2b88b3e83b941e80_v4_step_4', 'imp-2b88b3e83b941e80', 4, 'sauce', 'Pha nước trộn gỏi chua ngọt hài hòa', 'Khuấy tan 35 ml nước mắm ngon với 30 g đường cát trắng, 15 ml giấm gạo và nước cốt 1,5 quả chanh tươi đến khi tan hết đường, sau đó cho tỏi băm và ớt hiểm băm vào đảo đều.', NULL, NULL),
('imp-2b88b3e83b941e80_v4_step_5', 'imp-2b88b3e83b941e80', 5, 'prep', 'Trộn thấm hai lượt su su, cà rốt và tôm', 'Cho su su và cà rốt đã vắt ráo vào âu lớn, rưới 2/3 lượng nước trộn vào đảo đều và để 5 phút cho thấm. Tiếp tục thêm tôm chẻ đôi, rau răm và một nửa lượng lạc rang cùng phần nước trộn còn lại vào trộn nhẹ tay.', 'Su su và cà rốt đã ướp muối trước nên có sẵn vị mặn nhẹ, hãy rưới nước trộn từ từ và nếm lại trước khi hoàn thiện.', 5),
('imp-2b88b3e83b941e80_v4_step_6', 'imp-2b88b3e83b941e80', 6, 'finish', 'Hoàn thiện đĩa gỏi su su tôm giòn mát', 'Bày gỏi ra đĩa, rắc phần lạc rang giã dập còn lại, ngò rí, hành tím phi giòn và vài lát ớt hiểm lên trên; dọn ăn ngay kèm bánh phồng tôm.', 'Rắc phần lạc rang và hành tím phi còn lại lên mặt đĩa ngay lúc dọn sẽ giữ trọn độ giòn thơm khi xúc cùng bánh phồng tôm.', NULL),
('imp-0b34a73de8ccab71_v4_step_1', 'imp-0b34a73de8ccab71', 1, 'prep', 'Bóp muối vắt khô dưa leo và cà rốt', 'Rửa sạch dưa leo, gọt vỏ, xẻ dọc bỏ hết phần ruột hạt rồi thái lát mỏng vừa ăn. Cà rốt cạo vỏ, thái lát mỏng tương tự. Trộn dưa leo và cà rốt với 5 g muối ăn, để yên 5 phút cho ra nước rồi dùng khăn sạch vắt thật khô ráo.', 'Thấm và vắt thật khô dưa leo cà rốt trước khi trộn sẽ giúp món gỏi giữ được độ giòn và không làm ỉu đậu phụ chiên.', 5),
('imp-0b34a73de8ccab71_v4_step_2', 'imp-0b34a73de8ccab71', 2, 'cook', 'Chiên vàng giòn đậu phụ rồi thái miếng vừa ăn', 'Thấm thật ráo nước bề mặt 3 bìa đậu phụ trắng. Làm nóng chảo trên lửa vừa với 40 ml dầu ăn, thả đậu vào chiên khoảng 6 phút, lật đều các mặt đến khi lớp vỏ chuyển vàng giòn ruộm thì vớt ra giấy thấm dầu, để nguội bớt rồi thái lát mỏng hoặc sợi to vừa gắp.', 'Chiên nguyên bìa đậu phụ cho vàng giòn trước rồi mới thái mỏng giúp miếng đậu giữ form đẹp và không bị vỡ nát khi trộn.', 6),
('imp-0b34a73de8ccab71_v4_step_3', 'imp-0b34a73de8ccab71', 3, 'cook', 'Rang giã đậu phộng và sơ chế rau thơm', 'Rang chín vàng đậu phộng trên lửa nhỏ trong 5 phút, để nguội xát sạch vỏ lụa rồi giã dập vừa. Nhặt rửa sạch rau răm, rau húng quế và hành lá, để ráo rồi thái nhỏ. Băm nhuyễn tỏi khô, 1 quả ớt hiểm băm nhỏ và 1 quả thái lát.', NULL, 5),
('imp-0b34a73de8ccab71_v4_step_4', 'imp-0b34a73de8ccab71', 4, 'sauce', 'Pha nước mắm chay chua ngọt', 'Cho 30 ml nước mắm chay, 20 g đường cát trắng và nước cốt 1,5 quả chanh tươi vào bát, khuấy kỹ cho đường tan hết rồi thêm tỏi băm và ớt hiểm băm nhuyễn vào đảo đều.', NULL, NULL),
('imp-0b34a73de8ccab71_v4_step_5', 'imp-0b34a73de8ccab71', 5, 'prep', 'Trộn thấm dưa leo, cà rốt và đậu phụ chiên', 'Cho dưa leo, cà rốt đã vắt khô cùng đậu phụ chiên thái mỏng vào tô lớn, rưới đều bát nước mắm chay lên trên, trộn thật nhẹ tay để đậu phụ không nát và để nghỉ 5 phút cho ngấm vị.', NULL, 5),
('imp-0b34a73de8ccab71_v4_step_6', 'imp-0b34a73de8ccab71', 6, 'finish', 'Thêm rau thơm, đậu phộng và bày đĩa', 'Cho rau răm, rau húng quế thái nhỏ cùng một nửa lượng đậu phộng rang giã dập vào tô gỏi, đảo nhẹ lần cuối. Bày gỏi ra đĩa, rắc hành lá cắt nhỏ, phần đậu phộng còn lại và vài lát ớt hiểm lên trên rồi thưởng thức ngay.', 'Chỉ rắc phần đậu phộng rang còn lại và hành lá lên trên ngay khi chuẩn bị dọn để đậu không bị mềm ỉu.', NULL),
('imp-0ea0e53318af9de9_v4_step_1', 'imp-0ea0e53318af9de9', 1, 'prep', 'Phi giòn hành tím và sơ chế rau củ', 'Đun nóng 45 ml dầu ăn trên chảo ở lửa vừa, thả hành tím khô thái lát mỏng vào đảo đều tay đến khi vừa ngả màu vàng rơm thì vớt ngay ra giấy thấm dầu để hành giòn rụm (giữ lại 15 ml dầu hành). Rửa sạch xà lách, húng quế, ngò rí rồi thái vừa ăn; bào sợi cà rốt; thái lát dưa leo; thái múi cau mỏng hành tây và cắt nhỏ hành lá.', 'Vớt hành phi khi vừa vàng nhạt vì lượng nhiệt giữ trong lát hành sẽ giúp hành tiếp tục chín vàng giòn mà không bị đắng.', 5),
('imp-0ea0e53318af9de9_v4_step_2', 'imp-0ea0e53318af9de9', 2, 'marinate', 'Thái mỏng và ướp thịt bò thấm gia vị', 'Thịt bò thăn thái lát mỏng ngang thớ, ướp cùng 15 ml xì dầu, 15 ml dầu hào, 5 g hạt nêm, 2 g tiêu đen xay, 1/2 lượng sả cây băm và 10 g tỏi khô băm, thêm 5 ml dầu hành phi rồi trộn đều và ướp 15 phút cho thịt ngấm mềm.', NULL, 15),
('imp-0ea0e53318af9de9_v4_step_3', 'imp-0ea0e53318af9de9', 3, 'sauce', 'Pha nước mắm chua ngọt chan bún', 'Khuấy tan 20 g đường cát trắng trong 100 ml nước lọc với 45 ml nước mắm ngon và nước cốt của 1,5 quả chanh tươi; sau đó thả 15 g tỏi khô băm còn lại và ớt tươi băm vào để tỏi ớt nổi đều trên mặt chén.', 'Đợi đường tan hoàn toàn trước khi thả tỏi ớt băm sẽ giúp tỏi ớt nổi đều đẹp mắt trên mặt nước chấm.', NULL),
('imp-0ea0e53318af9de9_v4_step_4', 'imp-0ea0e53318af9de9', 4, 'prep', 'Trụng bún tươi và chần sơ giá đỗ', 'Đun sôi nồi nước lớn, trụng nhanh bún gạo tươi khoảng 1 phút cho tơi mềm rồi vớt ra rổ để thật ráo nước; tiếp tục chần giá đỗ khoảng 30 giây cho vừa chín tới vẫn giữ độ giòn.', NULL, 2),
('imp-0ea0e53318af9de9_v4_step_5', 'imp-0ea0e53318af9de9', 5, 'cook', 'Xào nhanh thịt bò cùng sả tỏi và hành tây', 'Làm nóng chảo trên lửa lớn với 15 ml dầu ăn còn lại và 10 ml dầu hành phi, cho phần sả băm và 10 g tỏi băm còn lại vào đảo thơm 15 giây. Trút thịt bò đã ướp vào đảo thật nhanh tay 1–2 phút, thêm hành tây thái lát vào xào chung thêm 45 giây đến khi thịt bò vừa chín tới mềm ngọt thì tắt bếp ngay.', 'Xào thịt bò ở lửa thật lớn trong thời gian ngắn giúp thịt chín mềm mọng mà không bị ra nước hoặc dai.', 3),
('imp-0ea0e53318af9de9_v4_step_6', 'imp-0ea0e53318af9de9', 6, 'finish', 'Xếp tô bún bò Nam Bộ và trộn đều thưởng thức', 'Chia bún tươi ra 4 tô, xếp xà lách, húng quế, ngò rí, giá đỗ chần, cà rốt bào sợi và dưa leo xung quanh, đặt thịt bò xào hành tây nóng hổi lên trên cùng. Rắc đậu phộng rang giã dập, hành tím phi giòn và hành lá thái nhỏ rồi chan nước mắm chua ngọt trộn đều trước khi ăn.', NULL, NULL),
('imp-1fa2a5a65ec5a26d_v4_step_1', 'imp-1fa2a5a65ec5a26d', 1, 'prep', 'Sơ chế, giã và lọc nước cua đồng', 'Ngâm cua đồng tươi 1 giờ cho nhả hết bùn đất rồi rửa sạch. Tách mai, bỏ yếm và dùng thìa khều phần gạch cua ra chén, ướp với 2 g hạt nêm và 2 g tiêu đen xay. Giã nhuyễn thân cua cùng 3 g muối ăn, sau đó hòa với 2 lít nước lọc chia làm 3 lần bóp nhẹ và gạn lọc qua rây để lấy phần nước thịt cua, bỏ xác vỏ cứng.', 'Gạn lọc qua nhiều lần với nước nguội giúp lấy hết phần thịt cua mịn mà không lẫn cặn vỏ cứng.', 10),
('imp-1fa2a5a65ec5a26d_v4_step_2', 'imp-1fa2a5a65ec5a26d', 2, 'cook', 'Chưng riêu cua kết tảng xốp mịn', 'Hòa 6 g muối ăn, 4 g hạt nêm và 2 g đường cát trắng vào nồi nước cua, đặt lên bếp đun ở lửa vừa và khuấy nhẹ đáy nồi theo một chiều trong 3 phút đầu. Khi nước nóng lên và riêu cua bắt đầu kết mảng nổi dần lên mặt thì ngưng khuấy, hạ lửa nhỏ đợi riêu đóng tảng dày rồi nhẹ tay vớt riêng ra tô.', 'Hạ lửa nhỏ và không để nước sôi sùng sục sau khi riêu nổi sẽ giữ được mảng riêu nguyên vẹn, xốp mềm.', 8),
('imp-1fa2a5a65ec5a26d_v4_step_3', 'imp-1fa2a5a65ec5a26d', 3, 'cook', 'Chiên vàng đậu phụ và xào gạch cua, cà chua', 'Đun nóng 85 ml dầu ăn trên chảo lửa vừa, thả đậu phụ trắng cắt vuông vào chiên vàng giòn các mặt khoảng 6 phút rồi vớt ra giấy thấm dầu. Trên chảo khác, đun nóng 15 ml dầu ăn và 15 ml dầu màu điều, phi thơm một nửa hành tím khô thái lát rồi trút gạch cua đã ướp vào đảo nhanh 1 phút thành phần nước gạch đỏ óng trút ra chén; tiếp tục phi thơm phần hành tím còn lại và xào cà chua múi cau với 3 g đường cát trắng trong 3 phút.', NULL, 10),
('imp-1fa2a5a65ec5a26d_v4_step_4', 'imp-1fa2a5a65ec5a26d', 4, 'cook', 'Hoàn thiện nồi nước dùng bún riêu chua thanh', 'Trút cà chua xào, đậu phụ chiên và phần nước gạch cua vào nồi nước cua, nêm 10 g mắm tôm Bắc và 20 ml nước mắm ngon rồi đun sôi nhẹ 5 phút cho đậu ngấm vị. Trước khi tắt bếp, rót từ từ 60 ml giấm bỗng vào nồi, khuấy nhẹ rồi nếm lại vị chua thanh mặn ngọt vừa miệng.', 'Cho giấm bỗng ở bước cuối cùng giúp giữ trọn hương thơm đặc trưng của rượu nếp mà không bị bay mất mùi.', 5),
('imp-1fa2a5a65ec5a26d_v4_step_5', 'imp-1fa2a5a65ec5a26d', 5, 'prep', 'Sơ chế rau sống và trụng bún tươi', 'Rửa sạch xà lách, rau kinh giới với 3 g muối ăn pha loãng rồi vẩy ráo; chẻ sợi rau muống ngâm nước cho xoăn giòn; ngâm hoa chuối bào trong nước có vắt 1/2 quả chanh tươi cho trắng giòn. Thái khúc hành lá, thái lát ớt tươi và cắt múi 1/2 quả chanh còn lại. Trụng nhanh bún tươi qua nước sôi cho nóng tơi rồi chia vào 4 tô.', NULL, NULL),
('imp-1fa2a5a65ec5a26d_v4_step_6', 'imp-1fa2a5a65ec5a26d', 6, 'finish', 'Bày tô bún riêu cua đậu và thưởng thức', 'Gắp tảng riêu cua đặt lên trên tô bún, chan ngập nước dùng nóng cùng đậu phụ chiên và cà chua, rắc hành lá thái nhỏ. Dọn nóng ngay kèm đĩa rau sống, chén 10 g mắm tôm Bắc còn lại, chanh tươi và ớt tươi.', NULL, NULL),
('imp-ff6d8fe6659e4976_v4_step_1', 'imp-ff6d8fe6659e4976', 1, 'prep', 'Sơ chế thịt, vắt cốt hành sả và thắng nước hàng', 'Chà rửa thịt ba chỉ heo với 3 g muối ăn rồi xả sạch, thấm ráo và thái lát mỏng 0,5 cm. Xay nhuyễn sả tươi và hành tím khô với 20 ml nước lọc rồi vắt lấy nước cốt thơm, bỏ bã. Thắng 8 g đường vàng với chút nước lọc trên chảo nhỏ đến màu cánh gián tạo nước hàng.', NULL, 8),
('imp-ff6d8fe6659e4976_v4_step_2', 'imp-ff6d8fe6659e4976', 2, 'marinate', 'Ướp thịt ba chỉ và thịt nạc vai xay', 'Trộn đều nước cốt sả hành, nước hàng vừa thắng, 5 ml nước mắm ngon, 4 g mắm tôm, 8 g đường cát trắng, 6 g hạt nêm, 4 g muối ăn và 3 g tiêu đen xay. Chia đôi hỗn hợp ướp đều vào thịt ba chỉ và thịt nạc vai heo xay, bọc kín để ngăn mát tủ lạnh ít nhất 1 giờ. Trước khi nướng 15 phút, trộn thêm 1/2 muỗng cà phê nước cốt chanh tươi vào cả hai phần thịt.', 'Thêm chút nước cốt chanh trước khi nướng giúp thớ thịt mềm ẩm và dậy mùi thơm hơn khi gặp nhiệt cao.', 60),
('imp-ff6d8fe6659e4976_v4_step_3', 'imp-ff6d8fe6659e4976', 3, 'prep', 'Làm dưa góp đu đủ xanh và cà rốt', 'Thái lát mỏng đu đủ xanh và cà rốt, bóp nhẹ với 2 g muối ăn trong 5 phút rồi rửa sạch, vắt ráo nước. Trộn dưa góp với 6 g đường cát trắng, 10 ml giấm gạo, 1 g muối ăn còn lại và 1 quả ớt hiểm tươi băm, ướp mát 20 phút cho giòn thấm vị.', NULL, 20),
('imp-ff6d8fe6659e4976_v4_step_4', 'imp-ff6d8fe6659e4976', 4, 'cook', 'Nướng chả miếng và chả viên trong lò nướng', 'Làm nóng lò nướng ở 200°C trước 10 phút. Nặn thịt nạc vai xay thành viên dẹt tròn vừa ăn rồi xếp cùng thịt ba chỉ lên khay vỉ nướng có lót khay hứng mỡ bên dưới. Nướng ở 200°C khoảng 12–15 phút, giữa chừng lật mặt thịt và phết nhẹ 15 ml dầu ăn lên bề mặt để chả chín kỹ hoàn toàn, vàng óng xém cạnh mà không bị khô.', 'Đặt khay hứng có chút nước bên dưới vỉ nướng giúp lò không bị khói và chả giữ được độ ẩm mềm.', 15),
('imp-ff6d8fe6659e4976_v4_step_5', 'imp-ff6d8fe6659e4976', 5, 'sauce', 'Pha nước mắm ấm chấm bún chả', 'Hòa tan 220 ml nước lọc còn lại với 80 ml nước mắm ngon, 56 g đường cát trắng, 15 ml giấm gạo và nước cốt chanh tươi còn lại. Đun trên lửa nhỏ đến khi đường tan hết và nước chấm ấm nóng (không đun sôi), tắt bếp rồi cho tỏi khô băm và 1 quả ớt hiểm tươi băm vào.', 'Giữ nước chấm ở độ ấm nóng vừa phải giúp mỡ chả không bị đông và hòa quyện hương thơm tỏi ớt chanh.', NULL),
('imp-ff6d8fe6659e4976_v4_step_6', 'imp-ff6d8fe6659e4976', 6, 'finish', 'Bày biện bún, rau sống và thưởng thức', 'Rửa sạch xà lách tươi, lá tía tô cùng rau kinh giới và húng lủi, vẩy ráo nước. Múc nước chấm ấm ra 4 bát, thả chả miếng, chả viên nướng nóng và dưa góp đu đủ cà rốt vào bát; ăn kèm đĩa bún gạo tươi và rổ rau sống.', NULL, NULL),
('imp-675a6c1cea0b604e_v4_step_1', 'imp-675a6c1cea0b604e', 1, 'prep', 'Sơ chế cơm nguội và cắt hạt lựu rau củ, đậu nấm', 'Bóp tơi nhẹ 550 g cơm trắng để nguội cho các hạt cơm rời nhau. Nấm đùi gà cắt gốc, rửa nhanh để ráo rồi thái hạt lựu cạnh 0,8 cm; cà rốt gọt vỏ thái hạt lựu nhỏ 0,5 cm; đậu phụ thấm khô thái hạt lựu cạnh 1 cm; tỏi khô băm nhuyễn; hành lá thái nhỏ.', 'Cơm nguội hong ráo hoặc để ngăn mát 30 phút trước khi rang sẽ giúp từng hạt cơm săn tơi, không bị bết dính.', NULL),
('imp-675a6c1cea0b604e_v4_step_2', 'imp-675a6c1cea0b604e', 2, 'cook', 'Phi thơm tỏi và xào chín nấm đùi gà, cà rốt', 'Làm nóng chảo rộng đáy trên lửa vừa với 15 ml dầu ăn, cho tỏi băm vào phi thơm trong 30 giây. Trút nấm đùi gà và cà rốt thái hạt lựu vào đảo đều 3 phút đến khi cà rốt vừa chín tới và nấm săn ráo nước.', NULL, 3),
('imp-675a6c1cea0b604e_v4_step_3', 'imp-675a6c1cea0b604e', 3, 'cook', 'Xào nhẹ đậu phụ cùng nhân nấm cà rốt', 'Nêm vào chảo nhân 4 g hạt nêm chay và 4 g đường cát trắng, đảo đều. Tiếp theo thả đậu phụ cắt hạt lựu vào đảo nhẹ tay khoảng 2 phút cho đậu se mặt và ngấm gia vị mà không bị vỡ nát, sau đó trút phần nhân ra đĩa riêng.', 'Đảo nhẹ đậu phụ hạt lựu bằng xẻng bản rộng giúp giữ khối vuông đẹp mắt.', 2),
('imp-675a6c1cea0b604e_v4_step_4', 'imp-675a6c1cea0b604e', 4, 'cook', 'Rang tơi hạt cơm nguội trên chảo nóng', 'Lau sạch chảo, thêm 15 ml dầu ăn còn lại làm nóng trên lửa vừa rồi đổ cơm nguội vào. Dùng muôi gỗ dàn đều và đảo liên tục trong 4 phút để hạt cơm nóng đều, tách rời từng hạt tơi ráo và hơi săn bóng.', NULL, 4),
('imp-675a6c1cea0b604e_v4_step_5', 'imp-675a6c1cea0b604e', 5, 'cook', 'Trộn nhân đậu nấm và nêm xì dầu dậy hương', 'Trút đĩa nhân nấm, cà rốt và đậu phụ trở lại chảo cơm, bật lửa lớn. Rưới 25 ml nước tương dọc theo thành chảo cho dậy mùi thơm cùng 3 g muối ăn, đảo đều tay thêm 3 phút cho hạt cơm thấm vị và quyện đều với phần nhân.', 'Rưới nước tương quanh thành chảo đang nóng giúp nước tương bốc hương thơm lừng mà không làm ướt nhão cơm.', 3),
('imp-675a6c1cea0b604e_v4_step_6', 'imp-675a6c1cea0b604e', 6, 'finish', 'Hoàn thiện với hành lá và tiêu đen xay', 'Nêm lại cho vừa khẩu vị, rắc hành lá thái nhỏ và 1,5 g tiêu đen xay vào đảo nhanh 15 giây rồi tắt bếp. Múc cơm rang ra đĩa và thưởng thức nóng.', NULL, NULL),
('imp-4dbcf05ec1f88763_v4_step_1', 'imp-4dbcf05ec1f88763', 1, 'prep', 'Sơ chế nấm đùi gà, sả, ớt và hành tỏi', 'Cắt bỏ phần gốc nấm đùi gà, rửa sạch nhanh dưới vòi nước rồi để thật ráo và thái dọc thành lát dày 0,8–1 cm. Sả tươi bóc bỏ bẹ già, băm nhuyễn; tỏi khô băm nhuyễn; ớt hiểm băm nhỏ hoặc thái lát; hành lá tách đầu hành đập dập và phần lá thái nhỏ; ngò rí thái nhỏ.', 'Thái nấm dọc thân dày khoảng 0,8–1 cm giúp nấm giữ được độ giòn dai mà không bị teo vụn khi xào lửa lớn.', NULL),
('imp-4dbcf05ec1f88763_v4_step_2', 'imp-4dbcf05ec1f88763', 2, 'marinate', 'Ướp nấm đùi gà thấm gia vị sả tỏi', 'Cho nấm đùi gà vào tô cùng 30 ml nước tương, 12 g đường cát trắng, 2 g muối ăn, 1 g bột ngọt cùng một nửa lượng sả băm và một nửa lượng tỏi băm. Trộn nhẹ tay cho gia vị phủ đều và ướp trong 15 phút để nấm ngấm đậm vị.', NULL, 15),
('imp-4dbcf05ec1f88763_v4_step_3', 'imp-4dbcf05ec1f88763', 3, 'cook', 'Phi thơm sả, tỏi, ớt và đầu hành lá', 'Làm nóng chảo với 20 ml dầu ăn trên lửa vừa, thả phần sả băm và tỏi băm còn lại cùng đầu hành lá đập dập và ớt hiểm vào phi khoảng 1–2 phút đến khi sả ngả vàng nhẹ và dậy mùi thơm nồng.', 'Chia sả tỏi làm hai phần để vừa ướp thấm vào thớ nấm, vừa phi thơm tạo lớp áo thơm giòn bên ngoài.', 2),
('imp-4dbcf05ec1f88763_v4_step_4', 'imp-4dbcf05ec1f88763', 4, 'cook', 'Xào săn nấm đùi gà trên lửa vừa', 'Trút toàn bộ tô nấm đã ướp cùng phần nước ướp vào chảo, giữ lửa vừa và đảo nhẹ nhàng khoảng 4 phút cho nấm tiết nước ngọt tự nhiên và thấm đều hương sả phi.', 'Xào nấm trên lửa vừa ở giai đoạn đầu giúp nấm chín đều từ trong ra ngoài mà không bị cháy sả tỏi.', 4),
('imp-4dbcf05ec1f88763_v4_step_5', 'imp-4dbcf05ec1f88763', 5, 'cook', 'Xào ráo se cạnh và nêm hạt nêm chay', 'Khi nước trong chảo cạn dần, nêm thêm 3 g hạt nêm chay vào đảo đều và tăng nhẹ lên lửa vừa lớn trong 3 phút đến khi từng lát nấm săn chắc, se mặt và ngả màu vàng nâu óng ả.', NULL, 3),
('imp-4dbcf05ec1f88763_v4_step_6', 'imp-4dbcf05ec1f88763', 6, 'finish', 'Hoàn thiện với hành lá, mè rang và ngò rí', 'Thả phần lá xanh hành lá vào đảo nhanh 15 giây rồi tắt bếp. Gắp nấm đùi gà xào sả ớt ra đĩa, rắc mè trắng rang vàng và ngò rí lên trên rồi dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-b88c09328fa3f33a_v4_step_1', 'imp-b88c09328fa3f33a', 1, 'prep', 'Sơ chế rau sống, cà rốt, dưa leo và giá đỗ', 'Nhặt xà lách, rau húng quế và hẹ lá, ngâm nước muối pha 1,5 g muối ăn trong 10 phút rồi rửa sạch, vẩy thật ráo nước. Cà rốt bào sợi dài, chần trong nồi nước sôi có 1,5 g muối khoảng 2 phút rồi vớt ra để ráo. Giá đỗ trụng nhanh 15 giây, dưa leo bỏ ruột thái sợi dài.', 'Rau sống, bún và giá đỗ phải để thật ráo nước thì gỏi cuốn mới không bị nhão ướt hay rách bánh tráng.', 2),
('imp-b88c09328fa3f33a_v4_step_2', 'imp-b88c09328fa3f33a', 2, 'cook', 'Chiên vàng đậu phụ và xào nấm đùi gà', 'Đun nóng 15 ml dầu ăn trên lửa vừa, chiên vàng đều hai mặt đậu phụ trắng trong 6 phút rồi vớt ra, thái thanh dài và rưới ngay 15 ml nước tương lên khi đậu còn nóng để thấm vị. Dùng chảo với 10 ml dầu ăn còn lại xào nấm đùi gà thái sợi cùng 4 g hạt nêm chay trên lửa lớn khoảng 3 phút cho nấm vừa chín săn, để riêng.', 'Tẩm nước tương ngay lúc đậu phụ vừa chiên còn nóng giúp từng thanh đậu thấm đậm đà hơn.', 6),
('imp-b88c09328fa3f33a_v4_step_3', 'imp-b88c09328fa3f33a', 3, 'cook', 'Trụng tơi bún gạo tươi', 'Đun sôi nồi nước, thả nhanh 300 g bún gạo tươi vào trụng khoảng 30 giây cho sợi bún mềm tơi, sau đó đổ ra rổ xả ngay dưới vòi nước lạnh và để thật ráo nước.', NULL, NULL),
('imp-b88c09328fa3f33a_v4_step_4', 'imp-b88c09328fa3f33a', 4, 'sauce', 'Pha nước chấm nước tương chanh ớt mè rang', 'Cho vào chén 35 ml nước tương còn lại, 20 g đường cát trắng, 20 ml giấm gạo và nước cốt 1 quả chanh tươi, khuấy đều đến khi đường tan hoàn toàn. Cuối cùng thêm 2 g ớt bột và 9 g mè trắng rang vàng vào khuấy đều.', NULL, NULL),
('imp-b88c09328fa3f33a_v4_step_5', 'imp-b88c09328fa3f33a', 5, 'finish', 'Làm mềm bánh tráng và cuốn gỏi chay chặt tay', 'Nhúng nhanh từng lá bánh tráng cuốn gỏi qua nước sạch rồi trải lên thớt phẳng. Lót 1–2 lá xà lách lên 1/3 miếng bánh tráng, xếp bún gạo tươi, nấm đùi gà xào, thanh đậu phụ, cà rốt, dưa leo, giá đỗ và rau húng quế lên trên; gấp hai mép bánh vào trong, đặt 1 cọng hẹ lá ở mép ngoài rồi cuộn tròn thật chắc tay đến hết 12 cuốn.', 'Chỉ lướt nhanh bánh tráng qua nước chứ không ngâm lâu vì bánh sẽ tiếp tục hút ẩm mềm ra trong lúc xếp nhân.', NULL),
('imp-b88c09328fa3f33a_v4_step_6', 'imp-b88c09328fa3f33a', 6, 'finish', 'Trình bày và thưởng thức gỏi cuốn chay', 'Xếp các cuốn gỏi chay ngay ngắn ra đĩa lớn, có thể cắt đôi chéo cho đẹp mắt rồi dọn kèm chén nước chấm nước tương mè rang để thưởng thức ngay khi rau còn tươi giòn.', NULL, NULL),
('imp-66711b78b6c12643_v4_step_1', 'imp-66711b78b6c12643', 1, 'marinate', 'Dần mềm và ướp sườn cốt lết với sữa tươi mật ong', 'Thấm khô 640 g sườn cốt lết, cắt nhẹ viền mỡ gân để miếng thịt không cong khi nướng và dùng sống dao dần nhẹ hai mặt. Giã lấy nước cốt từ 15 g tỏi và 25 g hành tím khô. Trộn đều sườn với nước cốt hành tỏi, 30 ml nước mắm ngon, 20 ml dầu hào, 20 ml mật ong, 60 ml sữa tươi không đường, 10 g đường cát trắng và 1,5 g tiêu đen xay, ướp ít nhất 20 phút trong ngăn mát.', 'Chỉ dùng nước cốt hành tỏi thay vì xác băm khi ướp sẽ giúp miếng sườn nướng lên màu vàng cánh gián đẹp mắt mà không bị cháy đen.', 20),
('imp-66711b78b6c12643_v4_step_2', 'imp-66711b78b6c12643', 2, 'prep', 'Làm đồ chua củ cải cà rốt và nấu cơm tấm', 'Trộn sợi cà rốt và củ cải trắng với 2 g muối ăn trong 5 phút rồi vắt ráo, ngâm vào hỗn hợp 25 ml giấm gạo, 15 g đường cát trắng và 150 ml nước lọc ấm. Vo nhẹ 320 g gạo tấm qua 1 nước, cho vào nồi cơm điện cùng 420 ml nước lọc nấu chín tơi dẻo trong 20 phút.', NULL, 20),
('imp-66711b78b6c12643_v4_step_3', 'imp-66711b78b6c12643', 3, 'sauce', 'Nấu nước mắm kẹo và làm mỡ hành xanh thơm', 'Đun sôi nhẹ 30 ml nước mắm ngon còn lại với 20 g đường cát trắng và 80 ml nước lọc trong 3 phút cho hơi sánh rồi để nguội, thêm 10 ml giấm gạo, 10 g tỏi băm nhuyễn và 2 quả ớt hiểm băm. Đun nóng 20 ml dầu ăn rồi dội thẳng vào chén hành lá thái nhỏ trộn 1 g muối ăn để làm mỡ hành xanh mướt.', 'Nấu sôi nhẹ nước mắm đường rồi để nguội hoàn toàn trước khi cho tỏi ớt băm giúp tỏi ớt nổi đẹp và nước chấm sánh dịu đúng vị cơm tấm.', 3),
('imp-66711b78b6c12643_v4_step_4', 'imp-66711b78b6c12643', 4, 'cook', 'Nướng sườn cốt lết vàng xém thơm lừng', 'Làm nóng lò nướng hoặc nồi chiên không dầu ở 190°C. Xếp 4 miếng sườn lên vỉ, phết nhẹ phần nước sốt ướp pha 10 ml dầu ăn lên mặt thịt. Nướng 10 phút rồi lật mặt, phết thêm lớp sốt ướp và nướng tiếp 8 phút đến khi sườn xém vàng hai mặt, chín mọng nước bên trong.', 'Phết thêm sốt ướp giữa chừng khi lật mặt giúp miếng sườn bóng mọng và đậm hương mật ong mà không bị khô.', 18),
('imp-66711b78b6c12643_v4_step_5', 'imp-66711b78b6c12643', 5, 'cook', 'Chiên 4 quả trứng gà ốp la ăn kèm', 'Làm nóng 5 ml dầu ăn trên chảo chống dính với lửa nhỏ vừa, đập 4 quả trứng gà vào ốp la khoảng 2 phút cho lòng trắng đông chín trắng và lòng đỏ sánh dẻo, rắc nốt 1 g muối ăn và 0,5 g tiêu đen xay còn lại lên mặt trứng.', NULL, NULL),
('imp-66711b78b6c12643_v4_step_6', 'imp-66711b78b6c12643', 6, 'finish', 'Trình bày đĩa cơm tấm sườn nướng hoàn chỉnh', 'Xới cơm tấm nóng tơi ra 4 đĩa, rưới đều mỡ hành béo thơm lên mặt cơm và đặt miếng sườn nướng nóng hổi cùng 1 quả trứng ốp la bên cạnh. Xếp thêm đồ chua củ cải cà rốt vắt ráo rồi dọn ăn nóng kèm chén nước mắm tỏi ớt chua ngọt.', NULL, NULL),
('imp-6a3a83f38e6d3f9c_v4_step_1', 'imp-6a3a83f38e6d3f9c', 1, 'prep', 'Rang thơm gạo tẻ và gạo nếp', 'Trộn 180 g gạo tẻ với 30 g gạo nếp, vo nhẹ 2 nước rồi để thật ráo. Bắc nồi đáy dày lên bếp không dầu, cho gạo vào rang đều tay trên lửa nhỏ khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và dậy mùi thơm nhẹ.', 'Rang gạo trước khi ninh giúp hạt gạo nở đều thành cháo sánh mượt mà vẫn giữ độ dẻo thơm.', 6),
('imp-6a3a83f38e6d3f9c_v4_step_2', 'imp-6a3a83f38e6d3f9c', 2, 'cook', 'Ninh cháo trắng sánh nhừ trên lửa nhỏ', 'Đổ 1,6 lít nước lọc sôi vào nồi gạo rang, khuấy đều một lượt rồi đậy hé nắp. Đun sôi bùng sau đó hạ lửa nhỏ ninh khoảng 22 phút, thỉnh thoảng khuấy sát đáy nồi để cháo không bị bén khét.', NULL, 22),
('imp-6a3a83f38e6d3f9c_v4_step_3', 'imp-6a3a83f38e6d3f9c', 3, 'marinate', 'Thái mỏng và ướp mềm thịt bò thăn', 'Trong lúc ninh cháo, thái 300 g thịt bò thăn thành lát thật mỏng ngang thớ. Ướp bò với 15 g gừng băm nhuyễn, 1/2 củ tỏi băm, 5 ml nước mắm ngon, 3 g hạt nêm, 1 g tiêu đen xay và 5 ml dầu ăn trong 12 phút để thịt thơm mềm không bị khô.', 'Thái thịt bò thật mỏng ngang thớ và trộn chút dầu ăn giúp thịt chín tái nhanh trong cháo nóng mà vẫn mềm ngọt.', NULL),
('imp-6a3a83f38e6d3f9c_v4_step_4', 'imp-6a3a83f38e6d3f9c', 4, 'cook', 'Phi vàng hành tím và sơ chế rau thơm', 'Làm nóng 10 ml dầu ăn trên chảo nhỏ với lửa vừa, cho 25 g hành tím thái lát mỏng vào phi đều tay khoảng 2 phút đến khi vàng giòn thì vớt ra giấy thấm dầu. Thái sợi chỉ 20 g gừng tươi còn lại; rửa sạch hành lá và lá tía tô rồi thái nhỏ.', NULL, NULL),
('imp-6a3a83f38e6d3f9c_v4_step_5', 'imp-6a3a83f38e6d3f9c', 5, 'cook', 'Nêm cháo và làm chín tới thịt bò trong nồi', 'Khi cháo đã nhừ sánh, nêm 15 ml nước mắm ngon còn lại, 3 g hạt nêm và 5 g muối ăn vào nồi khuấy đều. Tăng lửa vừa cho cháo sôi bùng lăn tăn, thả toàn bộ thịt bò đã ướp cùng một nửa lượng gừng thái chỉ vào khuấy nhanh 1 phút cho thịt bò vừa chín hồng đều thì tắt bếp ngay.', 'Chỉ đun thịt bò trong cháo sôi khoảng 1 phút rồi tắt bếp ngay để thịt giữ trọn độ mềm mọng, tránh đun lâu làm bò bị dai.', NULL),
('imp-6a3a83f38e6d3f9c_v4_step_6', 'imp-6a3a83f38e6d3f9c', 6, 'finish', 'Chan cháo nóng lên lá tía tô và thưởng thức', 'Lót lá tía tô và hành lá thái nhỏ dưới đáy 4 tô sứ, múc cháo bò nóng hổi chan đều lên trên. Rắc phần gừng thái chỉ còn lại, hành tím phi vàng giòn và 1 g tiêu đen xay rồi dùng nóng ngay.', NULL, NULL),
('imp-b1dcb812f8671a49_v4_step_1', 'imp-b1dcb812f8671a49', 1, 'prep', 'Sơ chế hành lá, xúc xích, ớt và đánh trứng', 'Thái lát mỏng 20 g hành tím khô; rửa sạch hành lá thái nhỏ và ớt hiểm thái lát mỏng. Thái lát mỏng đều 45 g xúc xích. Đập 3 quả trứng gà vào tô cùng 1,5 g muối ăn, đánh tan nhẹ vừa đủ cho hòa quyện.', 'Thái xúc xích thật mỏng sẽ giúp nhân bám chặt vào lớp trứng phô mai và nóng thơm nhanh hơn khi nướng trên chảo.', NULL),
('imp-b1dcb812f8671a49_v4_step_2', 'imp-b1dcb812f8671a49', 2, 'cook', 'Phi vàng giòn hành tím và áp sơ xúc xích', 'Làm nóng 15 ml dầu ăn trong chảo nhỏ trên lửa vừa, cho hành tím thái lát vào phi đều tay khoảng 2 phút đến khi vừa chuyển vàng nhạt thì vớt ra giấy thấm dầu, giữ lại phần dầu hành thơm. Đảo nhanh xúc xích trên chảo nóng 30 giây cho hơi xém thơm rồi gắp ra chén.', NULL, 2),
('imp-b1dcb812f8671a49_v4_step_3', 'imp-b1dcb812f8671a49', 3, 'cook', 'Làm nóng đế bánh tráng và phết trứng hành lá', 'Đặt chảo chống dính đáy rộng lên bếp với lửa nhỏ nhất, đặt 1 chiếc bánh tráng gạo vào làm nóng 20 giây cho hơi phẳng. Phết nhẹ 1 lớp mỏng dầu hành lên mặt bánh rồi múc 1/3 lượng trứng đánh tan cùng 1/3 hành lá thái nhỏ vào, dùng lưng muỗng dàn đều khắp mặt bánh.', 'Luôn nướng bánh tráng ở mức lửa nhỏ nhất để phần trứng và phô mai kịp chín tan trong khi đế bánh giòn vàng mà không bị khét.', NULL),
('imp-b1dcb812f8671a49_v4_step_4', 'imp-b1dcb812f8671a49', 4, 'cook', 'Phủ phô mai Mozzarella, xúc xích và nướng giòn đế', 'Khi mặt trứng hơi se lại, rắc đều 25 g phô mai Mozzarella bào sợi, 1/3 lượng xúc xích và vài lát ớt hiểm lên trên. Tiếp tục nướng liu riu khoảng 2 phút đến khi phô mai tan chảy hoàn toàn, mép bánh tráng giòn cứng và hơi cong nhẹ.', 'Có thể đậy hé nắp chảo khoảng 30 giây cuối nếu muốn phô mai tan chảy nhanh và kéo sợi mượt hơn.', 2),
('imp-b1dcb812f8671a49_v4_step_5', 'imp-b1dcb812f8671a49', 5, 'cook', 'Lặp lại thao tác với 2 chiếc bánh còn lại', 'Gắp chiếc bánh đầu tiên ra thớt hoặc đĩa, tiếp tục nướng lần lượt 2 chiếc bánh tráng gạo còn lại với phần trứng, hành lá, phô mai Mozzarella, xúc xích và ớt hiểm theo đúng trình tự trên.', NULL, NULL),
('imp-b1dcb812f8671a49_v4_step_6', 'imp-b1dcb812f8671a49', 6, 'finish', 'Rưới tương ớt, Mayonnaise, rắc hành phi và gấp bánh', 'Rưới đều tương ớt và sốt Mayonnaise theo đường ziczac lên mặt cả 3 chiếc bánh nóng, rắc thêm hành tím phi vàng giòn lên trên. Gấp đôi bánh hoặc cắt miếng tam giác vừa ăn và thưởng thức ngay lúc giòn rụm.', NULL, NULL),
('imp-8f24a253602fc9be_v4_step_1', 'imp-8f24a253602fc9be', 1, 'prep', 'Làm sạch khử tanh và ướp nhẹ cá diêu hồng', 'Đánh sạch vảy, bỏ mang, cạo màng đen trong bụng 1000 g cá diêu hồng tươi rồi chà xát với 3 g muối hạt trong 2 phút, xả thật sạch và thấm khô. Cắt cá thành khúc dày 2,5 cm, ướp với 10 ml nước mắm ngon, 3 g hạt nêm và một nửa gừng thái sợi trong 15 phút để thịt cá săn chắc đậm vị.', 'Cạo sạch lớp màng đen trong khoang bụng cá diêu hồng là bước quan trọng nhất để loại bỏ hoàn toàn mùi tanh bùn.', 15),
('imp-8f24a253602fc9be_v4_step_2', 'imp-8f24a253602fc9be', 2, 'prep', 'Xử lý dọc mùng, dứa và rau nhúng lẩu', 'Tước bỏ vỏ xơ 150 g dọc mùng, thái lát xéo dày 0,5 cm, bóp với 2 g muối hạt rồi xả nhiều lần nước sạch và vắt ráo để không gây ngứa. Thái lát 1/2 quả dứa chín, bổ múi cau 2 quả cà chua và băm nhỏ 1 quả. Rửa sạch nấm đùi gà thái lát, rau muống cắt khúc, ngò gai, rau ngổ, hành lá; băm nhỏ hành tím, tỏi, 1 cây sả, đập dập 2 cây sả và vắt nước cốt 2 quả chanh tươi.', NULL, NULL),
('imp-8f24a253602fc9be_v4_step_3', 'imp-8f24a253602fc9be', 3, 'cook', 'Phi thơm sả gừng và xào nền cà chua dứa', 'Làm nóng nồi trên lửa vừa với 20 ml dầu ăn, cho hành tím, tỏi, sả băm, sả cây đập dập và gừng thái sợi còn lại vào phi thơm 1 phút. Trút cà chua băm và một nửa lượng dứa thái lát vào xào 3 phút cho cà chua mềm nhuyễn ra màu, thêm 15 ml sa tế ớt đảo đều.', NULL, 4),
('imp-8f24a253602fc9be_v4_step_4', 'imp-8f24a253602fc9be', 4, 'cook', 'Nấu nước lẩu chua ngọt và làm chín cá diêu hồng', 'Đổ 2000 ml nước lọc vào nồi, đun sôi bùng trên lửa lớn rồi hớt sạch bọt. Thả phần dứa còn lại, cà chua bổ múi cau và 1 quả ớt tươi đập dập vào nấu 5 phút cho tiết vị ngọt chua tự nhiên, nêm 25 ml nước mắm ngon, 7 g hạt nêm, 5 g muối hạt và 20 g đường cát trắng. Nhẹ nhàng thả cá diêu hồng vào nấu sôi lăn tăn 6 phút đến khi mắt cá đục trắng và thịt cá chín chắc hoàn toàn.', 'Giữ lửa vừa sôi lăn tăn khi nấu cá diêu hồng và không đảo mạnh tay sẽ giữ nguyên từng khúc cá đẹp mắt, không bị vỡ nát.', 11),
('imp-8f24a253602fc9be_v4_step_5', 'imp-8f24a253602fc9be', 5, 'sauce', 'Pha chén mắm gừng chấm cá và rưới nước cốt chanh', 'Hạ nhỏ lửa tối đa hoặc tắt bếp nồi lẩu rồi rưới từ từ nước cốt chanh tươi vào khuấy nhẹ, nếm lại vị chua ngọt thanh dịu. Pha 10 ml nước mắm ngon còn lại cùng 10 g gừng băm nhuyễn và 1 quả ớt tươi thái lát làm chén nước chấm thịt cá.', 'Chỉ rưới nước cốt chanh sau khi cá đã chín và hạ nhỏ lửa để giữ hương thơm tinh dầu chanh tươi mà không bị đắng.', NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-8f24a253602fc9be_v4_step_6', 'imp-8f24a253602fc9be', 6, 'finish', 'Chuyển nồi lẩu ra bàn và nhúng rau xanh ăn với bún', 'Chuyển nồi lẩu sang bếp giữa bàn giữ sôi nhẹ, thả nấm đùi gà, hành lá, ngò gai và rau ngổ vào. Khi ăn, nhúng dọc mùng và rau muống vừa chín tới giữ độ giòn xanh, gắp thưởng thức nóng cùng thịt cá diêu hồng chấm mắm gừng và bún tươi.', NULL, NULL),
('imp-cd86ce166f002f60_v4_step_1', 'imp-cd86ce166f002f60', 1, 'prep', 'Rửa sạch tàu xì và thấm khô sườn non', 'Rửa nhanh 20 g đậu tương đen lên men dưới vòi nước sạch để loại bỏ bớt muối mặn bên ngoài, vớt ra để ráo rồi băm thô. Sườn non rửa sạch, chặt miếng vừa ăn 3 cm rồi dùng khăn giấy thấm thật khô từng miếng; băm nhỏ tỏi, gừng tươi và thái nhỏ hành lá.', 'Đậu tương đen lên men (tàu xì) có lớp muối bảo quản khá gắt nên cần xả nhanh qua nước sạch rồi băm thô để dậy mùi đều.', NULL),
('imp-cd86ce166f002f60_v4_step_2', 'imp-cd86ce166f002f60', 2, 'cook', 'Áp chảo xém vàng hai mặt sườn', 'Đun nóng 25 ml dầu ăn trong nồi đáy dày trên lửa lớn, xếp sườn non vào áp chảo 5 phút, lật đều các mặt cho thịt săn lại và xém vàng cạnh để giữ trọn vị ngọt bên trong rồi gắp sườn ra đĩa riêng.', 'Áp chảo khô mặt sườn trước giúp món hầm dậy mùi thơm và nước sốt không bị đục.', 5),
('imp-cd86ce166f002f60_v4_step_3', 'imp-cd86ce166f002f60', 3, 'cook', 'Phi thơm đậu đen lên men cùng gừng tỏi', 'Hạ xuống lửa vừa, tận dụng phần dầu nóng trong nồi cho tỏi băm, gừng băm, đậu tương đen lên men băm thô và một nửa phần hành lá vào đảo đều 1 phút cho dậy hương thơm đặc trưng.', NULL, 1),
('imp-cd86ce166f002f60_v4_step_4', 'imp-cd86ce166f002f60', 4, 'sauce', 'Hòa xì dầu và áo sốt lên sườn', 'Khuấy đều 15 ml xì dầu nhạt, 30 ml xì dầu đặc với 5 g đường cát trắng trong chén nhỏ rồi đổ vào nồi gia vị, đảo nhanh 15 giây cho quyện mùi. Trút đĩa sườn đã áp chảo trở lại nồi, xóc đều cho sườn áo lớp sốt đen bóng.', NULL, NULL),
('imp-cd86ce166f002f60_v4_step_5', 'imp-cd86ce166f002f60', 5, 'cook', 'Hầm lửa nhỏ cho sườn mềm tách xương', 'Rưới 30 ml rượu Thiệu Hưng quanh thành nồi rồi đổ 300 ml nước lọc xâm xấp mặt sườn. Đun sôi bùng lên thì hạ lửa nhỏ liu riu, đậy nắp kín và hầm 50 phút; thỉnh thoảng mở nắp đảo nhẹ để sườn ngấm đều và không bén đáy.', 'Nếu nước cạn trước khi sườn mềm, hãy châm thêm từng chút nước sôi để giữ nhiệt độ nồi ổn định.', 50),
('imp-cd86ce166f002f60_v4_step_6', 'imp-cd86ce166f002f60', 6, 'finish', 'Cô sánh sốt và hoàn thiện món hầm', 'Khi sườn đã mềm tơi dễ tách xương, mở nắp tăng lên lửa vừa đun thêm 5 phút đến khi nước sốt sánh lại ôm trọn từng khúc sườn. Nếm thử vị mặn ngọt, chỉ bổ sung muối ăn nếu thấy nhạt rồi tắt bếp, rắc phần hành lá còn lại lên trên và dọn nóng.', NULL, 5),
('imp-3e8e08fb584de7f3_v4_step_1', 'imp-3e8e08fb584de7f3', 1, 'prep', 'Chần thịt bò khử mùi với gừng hành rượu', 'Cho 900 g thịt bò cắt khối 5 cm vào nồi nước lạnh ngập mặt cùng 20 g gừng thái lát, 2 cây hành lá cắt khúc và 15 ml rượu Thiệu Hưng. Đun sôi trên lửa lớn rồi hạ lửa vừa chần 8 phút và hớt sạch bọt nổi, sau đó vớt thịt ra rửa lại nước mát, thấm thật khô (bỏ phần nước chần và gừng hành).', 'Bắt đầu chần từ nước lạnh giúp máu dư và tạp chất tiết ra triệt để, nước hầm sau cùng sẽ trong và thơm sạch.', 8),
('imp-3e8e08fb584de7f3_v4_step_2', 'imp-3e8e08fb584de7f3', 2, 'cook', 'Áp chảo vàng cạnh thịt bò', 'Đun nóng 15 ml dầu ăn trong nồi gang hoặc nồi đáy dày trên lửa vừa lớn, thả thịt bò đã thấm khô vào áp chảo 3 phút, trở đều các mặt đến khi thịt xém vàng nâu nhẹ.', NULL, 3),
('imp-3e8e08fb584de7f3_v4_step_3', 'imp-3e8e08fb584de7f3', 3, 'cook', 'Xào thơm hành tây, tỏi, gừng và gia vị tương', 'Hạ xuống lửa vừa, cho hành tây thái lát vào đảo 3 phút đến khi mềm thơm, tiếp tục thêm tỏi đập dập và 40 g gừng thái lát còn lại đảo 30 giây. Cho tương cà, tương ớt đậu bản Tứ Xuyên, 35 ml xì dầu nhạt, 15 ml xì dầu đặc và 15 g đường phèn vào đảo đều 2 phút cho thịt áo màu nâu đỏ.', NULL, 5),
('imp-3e8e08fb584de7f3_v4_step_4', 'imp-3e8e08fb584de7f3', 4, 'cook', 'Hầm lửa nhỏ cho thịt bò mềm rục', 'Rót 500 ml nước dùng bò, 500 ml nước lọc cùng 15 ml rượu Thiệu Hưng còn lại vào nồi cho ngập thịt, thả 3 g hoa hồi khô và 1 g lá nguyệt quế khô vào. Đun sôi lên rồi hạ lửa thật nhỏ, đậy nắp hầm liu riu 100 phút đến khi xiên đũa qua miếng bò dễ dàng.', 'Cắt thịt khối lớn 5 cm giúp từng miếng bò giữ nguyên thớ mọng nước dù hầm gần 2 giờ.', 100),
('imp-3e8e08fb584de7f3_v4_step_5', 'imp-3e8e08fb584de7f3', 5, 'cook', 'Thả cà rốt nấu mềm ngọt tự nhiên', 'Cho 2,5 củ cà rốt cắt khúc vào nồi thịt bò, đậy nắp hầm tiếp 20 phút trên lửa nhỏ cho cà rốt chín mềm ngọt mà vẫn giữ nguyên khối đẹp mắt.', 'Cho cà rốt vào cuối giai đoạn hầm giúp rau củ không bị nát nhừ và nước hầm vẫn giữ độ sánh trong.', 20),
('imp-3e8e08fb584de7f3_v4_step_6', 'imp-3e8e08fb584de7f3', 6, 'finish', 'Làm sánh sốt, nêm nếm và hoàn thiện', 'Hòa 8 g bột bắp với 2 muỗng canh nước lạnh (nếu muốn nước sốt sánh đặc), rót từ từ vào nồi đang sôi nhẹ và khuấy đều 1 phút. Nêm thử, chỉ bổ sung 2 g muối ăn nếu thấy nhạt rồi vớt bỏ hoa hồi và lá nguyệt quế, múc ra tô và rắc phần hành lá còn lại thái nhỏ lên trên.', NULL, NULL),
('imp-abcc9b72400680cf_v4_step_1', 'imp-abcc9b72400680cf', 1, 'prep', 'Thái hành lá và đánh mịn hỗn hợp trứng', 'Hành lá rửa sạch, thấm khô rồi thái thật nhỏ. Đập 5 quả trứng gà vào tô lớn, thêm 4 g muối ăn, 1 g tiêu trắng xay và 2 g đường cát trắng. Hòa 3 g bột bắp với 10 ml rượu Thiệu Hưng cho tan mịn rồi đổ vào tô cùng hành lá, dùng đũa đánh đều tay đến khi lòng trắng và lòng đỏ quyện hoàn toàn.', 'Sau khi nêm muối vào trứng nên đem tráng ngay, tránh để lâu khiến trứng bị tách nước và kém xốp mịn.', NULL),
('imp-abcc9b72400680cf_v4_step_2', 'imp-abcc9b72400680cf', 2, 'cook', 'Làm nóng chảo và tráng lớp trứng mỏng', 'Đặt chảo chống dính lên bếp lửa vừa, tráng một lớp mỏng dầu ăn (khoảng 1/3 lượng dầu) khắp lòng chảo. Múc 1/3 lượng hỗn hợp trứng đổ vào chảo, nghiêng nhẹ chảo xoay tròn để trứng trải thành lớp mỏng đều.', 'Sử dụng chảo chống dính phẳng đáy giúp lớp trứng mỏng đều và không bị rách mép khi cuộn.', NULL),
('imp-abcc9b72400680cf_v4_step_3', 'imp-abcc9b72400680cf', 3, 'cook', 'Chiên chín tới và cuộn trứng khi còn nóng', 'Hạ xuống lửa vừa nhỏ, chiên khoảng 2 phút đến khi mặt dưới chín vàng nhạt và mặt trên vừa se lại nhưng vẫn còn hơi ẩm bóng. Dùng xẻng mềm hoặc đũa cuộn tròn tấm trứng từ mép ngoài vào trong ngay trên chảo, nhẹ nhàng gắp cuộn trứng ra đĩa.', 'Không chiên khô quá vì mặt trứng hơi ẩm sẽ giúp các lớp cuộn dính chặt vào nhau và không bị nứt gãy.', 2),
('imp-abcc9b72400680cf_v4_step_4', 'imp-abcc9b72400680cf', 4, 'cook', 'Tráng và cuộn nốt hai mẻ trứng còn lại', 'Dùng giấy thấm dầu hoặc cọ tráng thêm một lớp mỏng dầu ăn lên chảo giữa mỗi mẻ, tiếp tục đổ 2 phần trứng còn lại tráng và cuộn tương tự cho đến khi hết hỗn hợp.', NULL, 4),
('imp-abcc9b72400680cf_v4_step_5', 'imp-abcc9b72400680cf', 5, 'prep', 'Để định hình và cắt khoanh vừa ăn', 'Để các cuộn trứng nghỉ trên thớt sạch khoảng 2 phút cho bớt nóng và định hình chắc tay, rồi dùng dao sắc cắt thành từng khúc dài khoảng 3–4 cm thật gọn đẹp.', NULL, 2),
('imp-abcc9b72400680cf_v4_step_6', 'imp-abcc9b72400680cf', 6, 'finish', 'Rưới xì dầu nhạt và dọn nóng', 'Xếp các khúc trứng cuộn hành lá ra đĩa phẳng, rưới đều 15 ml xì dầu nhạt lên bề mặt (hoặc chừa lại ra chén nhỏ làm nước chấm) và thưởng thức ngay khi trứng còn nóng mềm.', NULL, NULL),
('imp-26359a897d4be366_v4_step_1', 'imp-26359a897d4be366', 1, 'marinate', 'Làm sạch và ướp khử tanh tôm tươi', 'Tôm tươi bóc vỏ, bỏ đầu, rạch nhẹ lưng rút sạch chỉ đen rồi rửa nước lạnh và thấm ráo. Ướp tôm trong tô với 15 ml rượu Thiệu Hưng và 1 g muối ăn trong 10 phút cho thịt tôm săn và thơm ngọt.', 'Ướp chút rượu Thiệu Hưng giúp khử hoàn toàn mùi tanh hải sản mà vẫn giữ vị ngọt tự nhiên của tôm.', 10),
('imp-26359a897d4be366_v4_step_2', 'imp-26359a897d4be366', 2, 'prep', 'Thái lát nấm đùi gà và rau gia vị', 'Dùng khăn ẩm lau sạch 200 g nấm đùi gà, cắt bỏ phần gốc già rồi thái lát dày 0,5 cm. Gừng tươi thái lát mỏng, tỏi thái lát, hành lá tách riêng phần đầu trắng thái khúc và phần lá xanh thái nhỏ.', NULL, NULL),
('imp-26359a897d4be366_v4_step_3', 'imp-26359a897d4be366', 3, 'cook', 'Phi thơm gừng tỏi và đun nước dùng gà', 'Đun nóng 15 ml dầu ăn trong nồi trên lửa vừa, thả gừng thái lát, tỏi thái lát và đầu hành trắng vào phi thơm nhanh 20 giây đến khi dậy mùi (không để tỏi xém cháy). Đổ 1200 ml nước dùng gà vào nồi và đun lửa lớn đến khi sôi.', NULL, NULL),
('imp-26359a897d4be366_v4_step_4', 'imp-26359a897d4be366', 4, 'cook', 'Nấu chín nấm đùi gà và nêm vị thanh', 'Khi nước dùng sôi, thả nấm đùi gà thái lát vào nấu 3 phút trên lửa vừa để nấm tiết vị ngọt. Nêm thêm 15 ml xì dầu nhạt và 4 g muối ăn, khuấy đều và hớt bọt nếu có.', 'Cắt nấm đùi gà độ dày 0,5 cm giúp nấm chín nhanh trong 3 phút mà vẫn giữ được độ giòn sần sật.', 3),
('imp-26359a897d4be366_v4_step_5', 'imp-26359a897d4be366', 5, 'cook', 'Thả tôm nấu chín hồng vừa tới', 'Thả toàn bộ tôm đã ướp vào nồi súp đang sôi nhẹ, nấu thêm đúng 3 phút đến khi thân tôm uốn cong, chuyển màu hồng đục đều và chín hoàn toàn bên trong thì tắt bếp ngay.', 'Không nấu tôm quá lâu sau khi thân tôm đã chuyển hồng săn chắc vì tôm sẽ bị bở hoặc dai khô.', 3),
('imp-26359a897d4be366_v4_step_6', 'imp-26359a897d4be366', 6, 'finish', 'Rắc tiêu trắng, rưới dầu mè và dùng nóng', 'Khuấy nhẹ 1 g tiêu trắng xay vào nồi súp, múc ra 4 tô sâu lòng, rưới đều 5 ml dầu mè thơm và rắc phần lá hành xanh thái nhỏ lên trên rồi dùng nóng ngay.', NULL, NULL),
('imp-00e0b1417e11b291_v4_step_1', 'imp-00e0b1417e11b291', 1, 'prep', 'Thấm khô và lăn bột bắp cho đậu phụ', 'Dùng khăn giấy sạch thấm thật khô bề mặt 3,5 bìa đậu phụ cứng rồi cắt thành khối vuông 2,5 cm. Cho 38 g bột bắp ra đĩa rộng, lăn nhẹ từng miếng đậu cho bột bám một lớp áo mỏng đều xung quanh; hòa tan 7 g bột bắp còn lại với 120 ml nước lọc ấm trong chén nhỏ để sẵn.', 'Thấm thật ráo nước và chỉ áo lớp bột mỏng giúp đậu chiên giòn lâu mà không bị bết bột.', NULL),
('imp-00e0b1417e11b291_v4_step_2', 'imp-00e0b1417e11b291', 2, 'cook', 'Chiên vàng giòn các mặt đậu phụ', 'Đun nóng 75 ml dầu ăn trong chảo chống dính hoặc chảo gang trên lửa vừa. Xếp từng miếng đậu phụ cách nhau vào chảo, chiên 8 phút kết hợp lật đều đến khi tất cả các mặt vàng giòn thì vớt ra đĩa riêng.', 'Xếp các khối đậu có khoảng hở đều nhau để hơi nóng lưu thông, tránh các mặt đậu dính chặt vào nhau khi chiên.', 8),
('imp-00e0b1417e11b291_v4_step_3', 'imp-00e0b1417e11b291', 3, 'cook', 'Phi thơm gừng tỏi và xào mềm hành tây', 'Chắt bớt dầu thừa trong chảo chỉ chừa lại khoảng 1 muỗng canh. Băm nhỏ tỏi khô rồi cho cùng gừng tươi nạo nhuyễn vào phi thơm 1 phút trên lửa vừa, sau đó thả hành tây thái lát vào xào đều 3 phút đến khi hành chuyển trong mềm mà vẫn giữ độ giòn ngọt tự nhiên.', NULL, 4),
('imp-00e0b1417e11b291_v4_step_4', 'imp-00e0b1417e11b291', 4, 'sauce', 'Nấu sôi hỗn hợp gia vị sốt', 'Rót 20 ml rượu Thiệu Hưng quanh thành chảo cho dậy mùi thơm, tiếp tục thêm 30 ml xì dầu nhạt, 10 ml xì dầu đặc, 16 g đường nâu và 5 ml dầu mè thơm trực tiếp vào chảo hành tây, đảo đều và đun sôi lăn tăn 2 phút cho đường tan hết.', NULL, 2),
('imp-00e0b1417e11b291_v4_step_5', 'imp-00e0b1417e11b291', 5, 'cook', 'Áo sốt sánh mịn quanh đậu phụ', 'Khuấy đều lại chén nước bột bắp rồi rót vào chảo cùng toàn bộ đậu phụ đã chiên giòn. Dùng xẻng nhẹ tay đảo đều 1 phút trên lửa vừa cho nước sốt sánh lại, bám bóng mượt quanh từng khối đậu mà không làm vỡ miếng đậu.', 'Đảo hất nhẹ từ đáy chảo lên thay vì dầm trực tiếp vào miếng đậu phụ.', 1),
('imp-00e0b1417e11b291_v4_step_6', 'imp-00e0b1417e11b291', 6, 'finish', 'Hoàn thiện với hành lá và mè rang', 'Rắc hành lá thái nhỏ vào chảo đảo thêm vài giây cho dậy hương rồi tắt bếp. Dọn đậu phụ xào hành tây nóng hổi ra đĩa, rắc thêm hạt mè trắng rang lên mặt và dùng kèm cơm trắng.', NULL, NULL),
('imp-45274582db71eb9f_v4_step_1', 'imp-45274582db71eb9f', 1, 'prep', 'Sơ chế tôm, rau củ và pha chén sốt', 'Tôm tươi bóc vỏ, rút chỉ lưng, rửa sạch rồi thấm thật khô; bắp cải thái sợi mỏng, giá đỗ rửa ráo, hành lá cắt khúc 4–5 cm và tỏi băm nhuyễn. Trong chén nhỏ, khuấy tan 22 ml dầu hào, 22 ml xì dầu, 15 g đường cát trắng, 5 ml dầu mè thơm, 2 g muối ăn cùng 70 ml nước lọc.', 'Pha sẵn chén sốt trước khi bật bếp giúp quá trình xào lửa lớn diễn ra liên tục mà không bị cháy chảo.', NULL),
('imp-45274582db71eb9f_v4_step_2', 'imp-45274582db71eb9f', 2, 'cook', 'Trụng tơi sợi mì trứng chống dính', 'Đun sôi nồi nước lớn, thả 300 g mì trứng vào trụng 2 phút vừa chín mềm. Vớt mì ra xả ngay qua nước lạnh cho sợi săn dai, để thật ráo nước rồi xóc đều với 5 ml dầu ăn để sợi mì tơi bóng không dính nhau.', 'Xả nước lạnh ngay sau khi trụng giúp sợi mì săn lại, không bị bở nát khi đảo trên chảo lửa lớn.', 2),
('imp-45274582db71eb9f_v4_step_3', 'imp-45274582db71eb9f', 3, 'cook', 'Xào nhanh tôm tươi trên lửa lớn', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn, cho tỏi băm vào phi thơm 15 giây rồi thả tôm vào đảo nhanh tay 2 phút đến khi tôm vừa chuyển hồng đục thì trút ra đĩa riêng.', 'Xào tôm vừa chín tới rồi vớt ra giúp tôm giữ độ giòn ngọt và không bị dai khi đảo chung với mì ở bước cuối.', 2),
('imp-45274582db71eb9f_v4_step_4', 'imp-45274582db71eb9f', 4, 'cook', 'Xào bắp cải và đảo mì thấm sốt', 'Thêm 10 ml dầu ăn vào chảo nóng, thả bắp cải thái sợi vào xào 2 phút cho vừa mềm giòn. Rưới 10 ml dầu ăn còn lại quanh chảo rồi trút mì trứng vào cùng toàn bộ chén sốt đã pha, đảo hất đều tay 1 phút trên lửa lớn nhất cho từng sợi mì thấm đều sốt bóng đẹp.', NULL, 3),
('imp-45274582db71eb9f_v4_step_5', 'imp-45274582db71eb9f', 5, 'cook', 'Kết hợp tôm và giá đỗ giòn ngọt', 'Đổ đĩa tôm đã xào trở lại chảo cùng 150 g giá đỗ tươi, đảo đều tay 1 phút đến khi giá vừa chín tới và tôm chín hoàn toàn.', NULL, 1),
('imp-45274582db71eb9f_v4_step_6', 'imp-45274582db71eb9f', 6, 'finish', 'Thêm hành lá và dọn mì xào nóng', 'Thả hành lá cắt khúc vào chảo, đảo thêm 15 giây giữ màu xanh tươi rồi tắt bếp ngay. Gắp mì xào tôm ra đĩa lớn và thưởng thức nóng.', NULL, NULL),
('imp-3d2e5735cbfe9654_v4_step_1', 'imp-3d2e5735cbfe9654', 1, 'prep', 'Rang và giã bột muối tiêu Tứ Xuyên', 'Cho 6 g hạt tiêu Tứ Xuyên vào chảo khô rang trên lửa vừa nhỏ 3 phút đến khi dậy mùi thơm nồng (tránh để cháy đắng), trút ra cối để nguội hoàn toàn rồi giã thành bột mịn. Tiếp tục cho 6 g muối biển vào chảo khô rang 2 phút đến khi hạt muối khô ráo hơi ngả vàng, trộn đều với bột tiêu để được hỗn hợp bột muối tiêu.', 'Rang riêng tiêu và muối trên chảo khô giúp bột muối tiêu thơm nồng và không bị vón ẩm.', 5),
('imp-3d2e5735cbfe9654_v4_step_2', 'imp-3d2e5735cbfe9654', 2, 'marinate', 'Làm sạch, ướp gừng và áo bột bắp cho tôm', 'Tôm cắt râu, giữ nguyên vỏ, rút sạch chỉ lưng rồi thấm thật khô. Ướp tôm với 3 g muối biển và 15 g gừng tươi đập dập trong 15 phút cho ngấm vị, sau đó gạt bỏ hết xác gừng và thấm lại nếu tôm còn ẩm. Lăn từng con tôm qua 25 g bột bắp, giũ thật kỹ cho rơi hết bột thừa để chỉ còn một lớp áo mỏng.', NULL, 15),
('imp-3d2e5735cbfe9654_v4_step_3', 'imp-3d2e5735cbfe9654', 3, 'cook', 'Chiên giòn vàng từng mẻ tôm nguyên vỏ', 'Đun nóng 150 ml dầu ăn trong chảo sâu lòng trên lửa vừa lớn đến khi mặt dầu gợn sóng nóng già (khoảng 180°C). Chia tôm thành 2–3 mẻ nhỏ chiên mỗi mặt khoảng 1–1,5 phút cho đến khi vỏ tôm phồng giòn rụm, chuyển màu đỏ cam đẹp mắt và thịt tôm bên trong săn chắc, chuyển trắng đục hoàn toàn, sau đó vớt ra giấy thấm dầu và rắc ngay một chút bột muối tiêu lên khi tôm còn nóng.', 'Chiên từng mẻ nhỏ giúp nhiệt độ dầu không bị tụt, nhờ đó vỏ tôm giòn tan mà không hút dầu.', 3),
('imp-3d2e5735cbfe9654_v4_step_4', 'imp-3d2e5735cbfe9654', 4, 'cook', 'Phi vàng giòn tỏi băm với ít dầu', 'Chắt bớt dầu chiên ra ngoài, chỉ để lại khoảng 1 muỗng canh dầu trong chảo. Hạ lửa vừa, cho tỏi băm vào phi đều tay 1–2 phút đến khi vừa ngả vàng thơm thì nhanh tay vớt riêng tỏi phi ra giấy thấm dầu để không bị cháy đắng.', 'Nhiệt dư sau khi vớt vẫn làm tỏi tiếp tục sẫm màu, nên hãy vớt ngay khi tỏi vừa chuyển vàng nhạt.', 2),
('imp-3d2e5735cbfe9654_v4_step_5', 'imp-3d2e5735cbfe9654', 5, 'cook', 'Xóc nhanh tôm với tỏi phi, ớt và muối tiêu', 'Cho ớt hiểm thái lát và hành lá cắt khúc vào chảo đang nóng đảo nhanh 15 giây cho dậy hương. Tắt bếp, trút tỏi phi vàng và toàn bộ tôm chiên giòn vào chảo cùng phần bột muối tiêu vừa miệng (khoảng 2/3 lượng đã làm), xóc nhanh tay 10 giây cho gia vị bám đều khô ráo.', NULL, NULL),
('imp-3d2e5735cbfe9654_v4_step_6', 'imp-3d2e5735cbfe9654', 6, 'finish', 'Bày đĩa và thưởng thức nóng giòn', 'Trút tôm rang muối tiêu ra đĩa rộng, rắc thêm chút bột muối tiêu còn lại lên mặt để tăng hương vị và dùng nóng ngay khi vỏ tôm còn giòn rụm.', NULL, NULL),
('imp-73568e9a99d0ccdf_v4_step_1', 'imp-73568e9a99d0ccdf', 1, 'prep', 'Sơ chế hành tây và đánh bông trứng gà', 'Hành tây lột vỏ, thái sợi thô 0,5 cm rồi tách rời các múi để hành chín đồng đều; hành lá rửa sạch thái nhỏ. Đập 4 quả trứng gà vào tô lớn, thêm 15 ml sữa tươi không đường, 7 g sốt Mayonnaise và 1 g muối ăn rồi đánh tan đều tay đến khi hỗn hợp mịn mượt đồng nhất.', 'Thêm một chút sữa tươi và mayonnaise vào trứng trước khi đánh giúp thành phẩm cực kỳ mềm ẩm, xốp mịn.', NULL),
('imp-73568e9a99d0ccdf_v4_step_2', 'imp-73568e9a99d0ccdf', 2, 'cook', 'Xào bông mềm trứng gà trước rồi vớt riêng', 'Đặt chảo chống dính lên bếp lửa vừa lớn với 20 ml dầu ăn, khi dầu nóng già thì đổ hỗn hợp trứng vào. Chờ 10 giây cho rìa trứng bắt đầu đông lại rồi dùng xẻng nhẹ nhàng đẩy thành từng mảng lớn còn hơi ẩm bóng (khoảng 2 phút), lập tức trút ra đĩa riêng.', 'Xào trứng vừa chín tới 80% rồi trút ra ngay giúp trứng giữ độ ẩm mềm, không bị khô xác khi đảo lại cùng hành.', 2),
('imp-73568e9a99d0ccdf_v4_step_3', 'imp-73568e9a99d0ccdf', 3, 'cook', 'Xào chín trong và làm mềm ngọt hành tây', 'Dùng chính chảo đó, thêm 15 ml dầu ăn còn lại rồi cho hành tây vào xào đều tay 2 phút trên lửa lớn. Khi hành bắt đầu chuyển trong, rưới 30 ml nước lọc vào đảo thêm 1 phút để hành chín mềm ngọt mà không bị cháy xém.', 'Thêm 2 muỗng canh nước lọc giúp hơi nước làm hành tây chín mọng và giữ độ ẩm mượt cho toàn bộ đĩa trứng xào.', 3),
('imp-73568e9a99d0ccdf_v4_step_4', 'imp-73568e9a99d0ccdf', 4, 'sauce', 'Nêm gia vị vào phần hành tây', 'Rắc 2 g muối ăn còn lại, 3 g hạt nêm gà và 1 g tiêu đen xay vào chảo hành tây, đảo đều 20 giây cho gia vị tan đều và thấm vào hành trước khi cho trứng vào.', NULL, NULL),
('imp-73568e9a99d0ccdf_v4_step_5', 'imp-73568e9a99d0ccdf', 5, 'cook', 'Trộn nhẹ trứng gà trở lại chảo hành', 'Trút đĩa trứng gà đã xào vào chảo hành tây, dùng xẻng đảo nhẹ tay 1 phút trên lửa vừa để các mảng trứng nóng lại và quyện đều gia vị với hành mà không bị nát vụn.', NULL, 1),
('imp-73568e9a99d0ccdf_v4_step_6', 'imp-73568e9a99d0ccdf', 6, 'finish', 'Rắc hành lá và dọn nóng với cơm', 'Rắc phần hành lá thái nhỏ vào chảo, đảo thêm 15 giây cho dậy hương rồi tắt bếp ngay. Múc trứng xào hành tây ra đĩa và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-a17f5a86a1bc891c_v4_step_1', 'imp-a17f5a86a1bc891c', 1, 'cook', 'Luộc liu riu tảng ba chỉ với thảo mộc', 'Cho 450 g thịt ba chỉ nguyên tảng vào nồi cùng 1400 ml nước lạnh ngập mặt, thêm 25 g gừng thái lát, hoa hồi khô, 30 ml rượu Thiệu Hưng, 2 cây hành lá và 2 g tiêu Tứ Xuyên nguyên hạt. Đun sôi trên lửa lớn rồi lập tức hạ lửa nhỏ, đậy nắp luộc liu riu 35 phút cho thịt chín mềm mọng (xiên đũa qua dễ dàng không còn nước hồng).', 'Luộc thịt từ nước lạnh trên lửa nhỏ liu riu giúp thớ thịt chín đều, giữ trọn vị ngọt mà không bị co cứng.', 35),
('imp-a17f5a86a1bc891c_v4_step_2', 'imp-a17f5a86a1bc891c', 2, 'prep', 'Ủ nguội tảng thịt và giữ nước luộc', 'Vớt tảng thịt ba chỉ ra đĩa sâu, úp một chiếc đĩa hoặc nắp vung kín lên trên 15 phút để thịt nguội hoàn toàn mà mặt bì không bị khô thâm. Múc giữ lại khoảng 80 ml nước luộc thịt trong.', 'Thịt ba chỉ nguội hẳn mới dễ thái lát thật mỏng và giữ nguyên khoanh thịt đẹp mắt.', 15),
('imp-a17f5a86a1bc891c_v4_step_3', 'imp-a17f5a86a1bc891c', 3, 'sauce', 'Rưới dầu nóng lên gia vị tạo dầu ớt tỏi', 'Băm thật nhuyễn tỏi khô, 15 g gừng tươi còn lại và phần đầu trắng của 1 cây hành lá, cho vào tô chịu nhiệt cùng 10 g ớt bột khô và 2 g bột tiêu Tứ Xuyên. Đun nóng 45 ml dầu ăn đến khi sủi tăm nhẹ (khoảng 110°C) rồi rưới từ từ lên tô gia vị, khuấy nhanh cho dậy mùi thơm và lên màu đỏ đẹp.', 'Không đun dầu bốc khói quá nóng vì sẽ làm ớt bột và tỏi bị cháy đắng.', NULL),
('imp-a17f5a86a1bc891c_v4_step_4', 'imp-a17f5a86a1bc891c', 4, 'sauce', 'Hoàn thiện nước sốt xì dầu giấm đen', 'Thêm 50 ml xì dầu nhạt, 15 ml giấm đen Trấn Giang, 12 g đường cát trắng, 5 ml dầu mè thơm và 15 g sốt tương mè vào tô dầu ớt tỏi, khuấy đều đến khi đường và tương mè tan mịn rồi nếm lại cho vừa vị chua cay mặn ngọt cân bằng.', NULL, NULL),
('imp-a17f5a86a1bc891c_v4_step_5', 'imp-a17f5a86a1bc891c', 5, 'prep', 'Thái lát mỏng ba chỉ và lót dưa leo', 'Thái sợi mỏng 3/4 quả dưa leo xếp đều lót kín đáy đĩa lớn. Dùng dao sắc thái tảng thịt ba chỉ đã nguội hẳn thành những lát thật mỏng đều nhau và xếp ngay ngắn lên lớp dưa leo.', NULL, NULL),
('imp-a17f5a86a1bc891c_v4_step_6', 'imp-a17f5a86a1bc891c', 6, 'finish', 'Pha nước luộc vào sốt và rưới hoàn thiện', 'Hòa 80 ml nước luộc thịt giữ lại cùng 9 g hạt mè trắng rang vào tô sốt, khuấy đều rồi chan khắp mặt đĩa thịt ba chỉ, rắc phần lá hành xanh thái nhỏ lên trên và dùng ngay.', NULL, NULL),
('imp-fbbe89a1039604fc_v4_step_1', 'imp-fbbe89a1039604fc', 1, 'prep', 'Lau sạch, thái khoanh và khía caro nấm đùi gà', 'Dùng khăn giấy ẩm lau sạch 400 g nấm đùi gà (tránh rửa trực tiếp dưới nước làm nấm hút ẩm mất độ giòn). Cắt bỏ phần chân cứng, cắt nấm thành khoanh dày 1,5 cm rồi khía các đường caro nông hai mặt; băm nhuyễn tỏi khô, thái khúc 3 cm hành lá và thái lát ớt hiểm.', 'Chỉ dùng khăn ẩm lau sạch nấm giúp giữ trọn kết cấu dai giòn tự nhiên, không bị chảy nước khi áp chảo.', NULL),
('imp-fbbe89a1039604fc_v4_step_2', 'imp-fbbe89a1039604fc', 2, 'cook', 'Áp chảo xém vàng hai mặt từng khoanh nấm', 'Tráng 15 ml dầu ăn lên chảo rộng trên lửa vừa lớn, xếp các khoanh nấm thành một lớp đều, áp chảo 4 phút và lật mặt đến khi hai mặt nấm hơi xém vàng cạnh săn giòn thì gắp ra đĩa riêng.', 'Khía caro giúp nấm nhanh chín đều bên trong và giữ sốt bám chặt quanh từng khoanh nấm.', 4),
('imp-fbbe89a1039604fc_v4_step_3', 'imp-fbbe89a1039604fc', 3, 'cook', 'Phi thơm phần lớn tỏi băm trên lửa vừa', 'Thêm 15 ml dầu ăn còn lại vào chảo, hạ lửa vừa rồi cho 3/4 lượng tỏi băm vào phi 1 phút đến khi vừa chuyển vàng nhạt và dậy hương thơm nồng.', 'Không phi tỏi quá vàng đậm vì tỏi sẽ bị đắng khi kết hợp cùng xì dầu.', 1),
('imp-fbbe89a1039604fc_v4_step_4', 'imp-fbbe89a1039604fc', 4, 'sauce', 'Hòa tỏi sống và gia vị thành sốt thơm', 'Cho 1/4 lượng tỏi băm sống còn lại vào chảo cùng 2 g muối ăn, 2 g đường cát trắng, 15 ml xì dầu nhạt và 8 ml dầu hào, đảo nhanh 15 giây cho gia vị hòa quyện sôi nhẹ.', 'Kết hợp cả tỏi phi vàng lẫn chút tỏi sống giúp món nấm dậy tầng hương thơm nồng nàn đặc trưng.', NULL),
('imp-fbbe89a1039604fc_v4_step_5', 'imp-fbbe89a1039604fc', 5, 'cook', 'Đảo nấm đùi gà thấm đều sốt tỏi', 'Trút đĩa nấm đùi gà đã áp chảo trở lại chảo, tăng lửa vừa lớn đảo nhanh tay 2 phút cho các khoanh nấm áo đều lớp sốt bóng đẹp.', NULL, 2),
('imp-fbbe89a1039604fc_v4_step_6', 'imp-fbbe89a1039604fc', 6, 'finish', 'Thêm hành lá, ớt và dọn nóng', 'Thả hành lá cắt khúc và ớt hiểm thái lát vào chảo đảo thêm 30 giây giữ màu tươi rồi tắt bếp, trút ra đĩa thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('imp-3ee45f761eb0b78d_v4_step_1', 'imp-3ee45f761eb0b78d', 1, 'cook', 'Luộc và ủ chín mềm mọng ức gà', 'Đun sôi nồi nước vừa ngập mặt thịt cùng 10 g gừng thái lát và 2 cây hành lá cắt khúc. Thả 450 g ức gà vào nồi, đợi nước sôi lăn tăn trở lại khoảng 2 phút thì đậy kín nắp, tắt bếp ngay và để ủ yên 20 phút cho gà chín đều hoàn toàn bên trong mà vẫn giữ trọn độ mềm mọng.', 'Kỹ thuật tắt bếp ủ kín giúp thịt ức gà trắng mềm, mọng nước và không bị bã khô.', 20),
('imp-3ee45f761eb0b78d_v4_step_2', 'imp-3ee45f761eb0b78d', 2, 'prep', 'Làm nguội và xé sợi thịt ức gà', 'Vớt ức gà ra đĩa để nguội hoàn toàn (kiểm tra thớ giữa đã trắng chín hoàn toàn, không còn màu hồng), sau đó dùng tay xé dọc thớ thành những sợi tơi vừa ăn, bỏ phần gừng hành luộc.', 'Xé gà bằng tay theo chiều thớ thịt giúp từng sợi gà tơi tự nhiên và bám nước sốt tương mè ngon hơn thái dao.', NULL),
('imp-3ee45f761eb0b78d_v4_step_3', 'imp-3ee45f761eb0b78d', 3, 'sauce', 'Pha sánh mịn nước sốt tương mè Tứ Xuyên', 'Cho 45 g sốt tương mè, 45 ml xì dầu nhạt, 30 ml giấm đen Trấn Giang, 20 ml dầu ớt Tứ Xuyên, 25 ml dầu mè thơm, tỏi băm nhuyễn, 25 g đường cát trắng, 1 g tiêu Tứ Xuyên xay và 3 g muối ăn vào tô. Khuấy kỹ (có thể thêm 1–2 muỗng canh nước ấm nếu tương mè đặc) đến khi hỗn hợp hòa quyện sánh mịn.', 'Để nước sốt nghỉ 15 phút trong lúc luộc mì giúp tỏi và tiêu Tứ Xuyên ngấm sâu vào sốt.', NULL),
('imp-3ee45f761eb0b78d_v4_step_4', 'imp-3ee45f761eb0b78d', 4, 'cook', 'Luộc chín tới và xả lạnh sợi mì dai', 'Đun sôi nồi nước lớn, cho 350 g mì sợi vào luộc 3 phút đến khi vừa chín tới còn độ dai nhẹ. Vớt mì xả ngay dưới vòi nước mát, để thật ráo nước rồi trộn đều với 5 ml dầu ăn cho sợi mì tơi bóng không dính.', NULL, 3),
('imp-3ee45f761eb0b78d_v4_step_5', 'imp-3ee45f761eb0b78d', 5, 'prep', 'Thái sợi dưa leo giòn mát', 'Rửa sạch 1,2 quả dưa leo, gọt bỏ bớt phần ruột hạt mềm nếu cần rồi thái sợi mỏng đều tay, để riêng cùng 1 cây hành lá còn lại thái nhỏ.', NULL, NULL),
('imp-3ee45f761eb0b78d_v4_step_6', 'imp-3ee45f761eb0b78d', 6, 'finish', 'Xếp tô, chan sốt mè và thưởng thức', 'Chia mì nguội vào 3 tô sâu lòng, xếp dưa leo thái sợi và gà xé tơi lên trên. Chan đều nước sốt tương mè Tứ Xuyên, rắc đậu phộng rang giã dập, hạt mè trắng rang và hành lá thái nhỏ lên mặt, trộn đều ngay trước khi ăn.', NULL, NULL),
('imp-cbb5635bfe848a49_v4_step_1', 'imp-cbb5635bfe848a49', 1, 'prep', 'Thấm khô đùi gà và sơ chế gia vị thơm', 'Rửa sạch 1400 g đùi gà có xương và thấm thật khô mặt da bằng khăn giấy để khi áp chảo vàng giòn không bắn dầu. Thái lát mỏng 40 g gừng tươi, đập dập tỏi, cắt khúc 5 cm hành lá (tách riêng đầu trắng và lá xanh).', NULL, NULL),
('imp-cbb5635bfe848a49_v4_step_2', 'imp-cbb5635bfe848a49', 2, 'cook', 'Phi thơm gừng, tỏi và đầu hành trắng', 'Làm nóng 15 ml dầu ăn trong nồi đáy dày trên lửa vừa, cho gừng thái lát, tỏi đập dập và phần đầu hành trắng vào phi thơm 2 phút đến khi dậy hương dịu và tỏi vừa ngả vàng nhẹ (không để cháy đắng).', NULL, 2),
('imp-cbb5635bfe848a49_v4_step_3', 'imp-cbb5635bfe848a49', 3, 'cook', 'Áp chảo xém vàng hai mặt đùi gà', 'Xếp các miếng đùi gà thành một lớp phẳng không chồng lấn (ưu tiên úp mặt da xuống trước), áp chảo 8 phút trên lửa vừa đến khi hai mặt săn lại và da gà lên màu vàng nhạt đẹp mắt.', 'Áp chảo trước giúp phần mỡ dưới da tiết bớt và giữ thịt gà săn chắc trong suốt quá trình om.', 8),
('imp-cbb5635bfe848a49_v4_step_4', 'imp-cbb5635bfe848a49', 4, 'sauce', 'Đổ hỗn hợp xì dầu, rượu và thảo mộc', 'Rót 90 ml xì dầu nhạt, 40 ml xì dầu đặc, 60 ml rượu Thiệu Hưng, 15 ml dầu mè thơm, 50 g đường nâu và 160 ml nước lọc vào nồi. Khuấy nhẹ cho đường tan rồi thả hoa hồi khô và lá nguyệt quế khô vào cùng.', 'Kết hợp xì dầu nhạt để lấy vị mặn thanh và xì dầu đặc để tạo màu nâu cánh gián óng mượt cho thịt gà.', NULL),
('imp-cbb5635bfe848a49_v4_step_5', 'imp-cbb5635bfe848a49', 5, 'cook', 'Om liu riu cho gà chín mềm thấm sốt', 'Đun nồi sốt sôi bùng lên rồi lập tức hạ xuống lửa nhỏ nhất, đậy nắp kín om liu riu 35 phút cho thịt gà chín mềm tận xương và thấm đẫm nước sốt. Ở phút thứ 15, mở nắp lật trở mặt gà một lần cho ngấm đều hai phía.', 'Giữ lửa thật nhỏ khi om để nước sốt xì dầu không bị trào hoặc cô cạn quá nhanh gây mặn cháy.', 35),
('imp-cbb5635bfe848a49_v4_step_6', 'imp-cbb5635bfe848a49', 6, 'finish', 'Cô sánh sốt, nêm vị và hoàn thiện', 'Mở nắp nồi, đun thêm 5 phút trên lửa vừa cho nước sốt sánh bóng ôm đều miếng gà rồi rắc tiêu trắng xay vào đảo nhẹ. Thả phần lá hành xanh vào đảo đều rồi tắt bếp, vớt bỏ hoa hồi, lá nguyệt quế, gắp gà ra đĩa và chỉ rưới một lớp nước sốt bóng mượt vừa đủ lên trên (không chan hết phần nước om đậm vị dưới đáy nồi), dọn nóng cùng cơm trắng.', NULL, 5),
('imp-7bf9327b2c48f2d4_v4_step_1', 'imp-7bf9327b2c48f2d4', 1, 'marinate', 'Pha sốt tương ngũ vị và ướp sườn qua đêm', 'Thấm thật khô 1200 g sườn non. Trộn đều trong tô lớn gồm 45 ml xì dầu nhạt, tỏi băm nhuyễn, 25 g đường cát trắng, 6 g muối ăn, 1,5 g tiêu trắng xay, 1,5 g ngũ vị hương, 15 ml rượu Thiệu Hưng, 5 ml dầu mè thơm và 15 ml tương đen Hoisin. Chừa lại 1/3 lượng sốt để phết khi nướng, phần còn lại xoa đều lên khắp các dẻ sườn, bọc kín ướp ngăn mát tối thiểu 2 giờ.', 'Trước khi nướng 30 phút, lấy sườn ra khỏi tủ lạnh để thịt về nhiệt độ phòng giúp sườn chín đều từ trong ra ngoài.', 120),
('imp-7bf9327b2c48f2d4_v4_step_2', 'imp-7bf9327b2c48f2d4', 2, 'prep', 'Làm nóng lò và chuẩn bị khay nước giữ ẩm', 'Làm nóng lò nướng ở 200°C trước 10 phút. Lót giấy bạc vào khay nướng hứng bên dưới, đặt vỉ nướng thưa lên trên rồi rót 240 ml nước lọc vào khay đáy giúp hơi nước giữ sườn mềm mọng và tránh mỡ nhỏ xuống bốc khói.', 'Đặt khay nước bên dưới vỉ nướng giúp sườn không bị khô bề mặt trong suốt quá trình nướng và dễ vệ sinh khay lò.', NULL),
('imp-7bf9327b2c48f2d4_v4_step_3', 'imp-7bf9327b2c48f2d4', 3, 'cook', 'Nướng chín mềm sườn lần một ở 200°C', 'Xếp các dẻ sườn lên vỉ nướng (không chồng lên nhau), đưa vào rãnh giữa lò nướng 30 phút ở 200°C cho thịt sườn chín mềm và săn bề mặt.', NULL, 30),
('imp-7bf9327b2c48f2d4_v4_step_4', 'imp-7bf9327b2c48f2d4', 4, 'cook', 'Quét sốt ướp và nướng tiếp mặt còn lại', 'Kéo khay sườn ra, dùng cọ phết đều phần sốt ướp giữ lại lên khắp bề mặt sườn, lật mặt sườn rồi cho lại vào lò nướng thêm 20 phút ở 200°C cho gia vị thấm sâu và xém nhẹ cạnh.', NULL, 20),
('imp-7bf9327b2c48f2d4_v4_step_5', 'imp-7bf9327b2c48f2d4', 5, 'cook', 'Phết mật ong nướng xém bóng caramel', 'Quét một lớp mỏng 15 ml mật ong nguyên chất lên bề mặt sườn, chuyển khay lên rãnh trên cùng của lò và tăng nhiệt lên 220°C (chế độ lửa trên) nướng thêm 5 phút cho đến khi mặt sườn óng ánh và xém cạnh thơm lừng.', 'Canh sát lò trong 5 phút cuối vì mật ong lên màu rất nhanh và dễ bị cháy đắng.', 5),
('imp-7bf9327b2c48f2d4_v4_step_6', 'imp-7bf9327b2c48f2d4', 6, 'finish', 'Nghỉ thịt, chặt khúc và rắc hành lá', 'Lấy sườn ra để nghỉ 5 phút trên thớt cho nước thịt ổn định lại, rồi dùng dao sắc chặt thành từng miếng vừa ăn. Xếp sườn ra đĩa, rắc hành lá thái nhỏ lên trên và dùng nóng.', NULL, NULL),
('imp-bbfdcf2e3b277fed_v4_step_1', 'imp-bbfdcf2e3b277fed', 1, 'prep', 'Ngâm Kombu và sơ chế gà, hành boa-rô, gừng', 'Ngâm 15 g tảo bẹ Kombu khô trong 1000 ml nước lọc lạnh ít nhất 30 phút. Trong lúc chờ, cắt 300 g đùi gà còn da thành miếng vừa ăn, xóc đều với 1 g muối ăn để 10 phút; hành boa-rô cắt khúc dài 5 cm; gừng tươi gọt vỏ mài nhuyễn để riêng.', 'Giữ nguyên lớp da gà giúp khi áp chảo tiết ra mỡ gà thơm béo tự nhiên làm hành boa-rô cháy cạnh ngọt đậm.', 30),
('imp-bbfdcf2e3b277fed_v4_step_2', 'imp-bbfdcf2e3b277fed', 2, 'cook', 'Nấu và lọc nước dùng Dashi từ Kombu và cá bào', 'Bắc nồi nước ngâm Kombu lên bếp lửa vừa, đun đến khi sủi tăm sắp sôi thì vớt ngay miếng Kombu ra. Thả 30 g cá bào khô Katsuobushi vào đun liu riu 30 giây rồi tắt bếp, ngâm yên 10 phút cho cá bào chìm xuống đáy, sau đó lọc qua rây lót khăn giấy lấy khoảng 950 ml nước dùng Dashi trong veo.', 'Ngâm cá bào sau khi tắt bếp đủ 10 phút giúp nước dùng rút trọn vị ngọt umami mà không bị đục hay tanh.', 10),
('imp-bbfdcf2e3b277fed_v4_step_3', 'imp-bbfdcf2e3b277fed', 3, 'cook', 'Áp chảo gà da vàng giòn và hành boa-rô xém cạnh', 'Làm nóng chảo rộng trên lửa vừa với 8 ml dầu ăn thực vật, xếp đùi gà mặt da xuống và đặt các khúc hành boa-rô xen vào khoảng trống. Áp chảo yên khoảng 4–5 phút đến khi da gà vàng giòn và mặt cắt hành boa-rô chuyển màu hổ phách trong thì lật mặt áp tiếp 2–3 phút.', 'Không đảo gà và hành quá sớm để mặt cắt hành boa-rô áp xém vàng ngọt mà không bị cháy đen đắng.', 7),
('imp-bbfdcf2e3b277fed_v4_step_4', 'imp-bbfdcf2e3b277fed', 4, 'cook', 'Nêm nước dùng Dashi và nấu chín kỹ thịt gà', 'Rót toàn bộ nước dùng Dashi đã lọc vào chảo gà và hành boa-rô, đun sôi rồi hạ lửa nhỏ. Nêm 22 ml rượu Sake nấu ăn, 45 ml rượu Mirin, 40 ml xì dầu Nhật và 1 g muối ăn còn lại, hớt sạch bọt rồi đun liu riu 4–5 phút đến khi thịt gà chín hoàn toàn bên trong.', NULL, 5),
('imp-bbfdcf2e3b277fed_v4_step_5', 'imp-bbfdcf2e3b277fed', 5, 'cook', 'Luộc, xả lạnh và trụng nóng lại mì Soba', 'Đun sôi 600 ml nước lọc trong nồi riêng, thả 270 g mì Soba kiều mạch vào luộc khoảng 3–4 phút cho vừa chín tới rồi vớt ra xả ngay dưới vòi nước lạnh kết hợp chà nhẹ cho sạch lớp tinh bột nhớt. Trước khi chan nước dùng, nhúng nhanh mì Soba vào nước sôi 5 giây cho nóng rồi xóc thật ráo.', 'Xả lạnh giúp sợi Soba săn dai, sau đó nhúng nhanh qua nước nóng trước khi xếp vào tô giúp giữ nhiệt cho cả tô mì.', 4),
('imp-bbfdcf2e3b277fed_v4_step_6', 'imp-bbfdcf2e3b277fed', 6, 'finish', 'Trình bày tô mì Soba nóng thịt gà', 'Chia mì Soba ra 3 tô lớn, chan ngập nước dùng Dashi đang sôi cùng các miếng thịt gà và hành boa-rô lên trên, đặt chút gừng tươi mài nhuyễn và rắc bột ớt 7 vị Nhật Shichimi tùy thích rồi dùng nóng ngay.', NULL, NULL),
('imp-f2334219f33e48d0_v4_step_1', 'imp-f2334219f33e48d0', 1, 'prep', 'Sơ chế tôm sú sạch chỉ lưng và cắt râu', 'Rửa sạch 400 g tôm sú tươi nguyên vỏ dưới vòi nước lạnh, dùng kéo cắt gọn phần râu dài, chóp nhọn ở đầu và chân tôm, dùng tăm nhọn khéo léo rút chỉ đen dọc lưng tôm mà không làm rách vỏ. Rửa lại rồi thấm khô.', 'Giữ nguyên vỏ tôm khi nướng giúp khóa chặt độ ẩm và vị ngọt của thịt tôm bên trong.', NULL),
('imp-f2334219f33e48d0_v4_step_2', 'imp-f2334219f33e48d0', 2, 'marinate', 'Ướp tôm với rượu Sake khử tanh rồi thấm thật khô', 'Xếp tôm vào khay nông, rưới đều 45 ml rượu Sake nấu ăn lên mình tôm và để yên 5 phút cho khử mùi tanh hải sản. Sau đó vớt tôm ra, dùng khăn giấy thấm thật khô cả hai mặt vỏ tôm.', 'Thấm thật khô mặt vỏ tôm trước khi nướng giúp vỏ tôm lên màu đỏ đẹp và hơi xém giòn thay vì bị hấp hơi.', 5),
('imp-f2334219f33e48d0_v4_step_3', 'imp-f2334219f33e48d0', 3, 'prep', 'Xiên que giữ dáng tôm thẳng và rắc muối hạt biển', 'Dùng que tre đã ngâm nước lạnh xiên dọc từ đuôi lên sát đầu tôm để tôm giữ dáng thẳng đẹp khi gặp nhiệt. Rắc đều 10 g muối hạt biển phủ lên cả hai mặt vỏ tôm.', 'Ngâm que tre vào nước 10 phút trước khi xiên giúp đầu que không bị cháy sém khi nướng trên lửa lớn.', NULL),
('imp-f2334219f33e48d0_v4_step_4', 'imp-f2334219f33e48d0', 4, 'cook', 'Làm nóng vỉ nướng và phết dầu chống dính', 'Làm nóng lò nướng chế độ lửa trên 220°C (hoặc bếp nướng than/vỉ nướng) trước 5 phút, lót giấy bạc gấp mép lên khay và phết đều 8 ml dầu ăn thực vật lên bề mặt tiếp xúc.', NULL, 5),
('imp-f2334219f33e48d0_v4_step_5', 'imp-f2334219f33e48d0', 5, 'cook', 'Nướng tôm đỏ au xém cạnh hai mặt', 'Xếp tôm lên khay nướng, nướng mặt đầu tiên khoảng 4–5 phút đến khi vỏ tôm chuyển sang màu đỏ cam tươi và hơi xém nhẹ thì lật mặt, nướng tiếp 2–3 phút nữa đến khi thịt tôm chín trắng đục hoàn toàn và săn chắc.', 'Không nướng tôm quá lâu kẻo thịt tôm bị khô xác và mất đi độ ngọt mọng tự nhiên.', 7),
('imp-f2334219f33e48d0_v4_step_6', 'imp-f2334219f33e48d0', 6, 'finish', 'Trình bày đĩa tôm nướng muối cùng chanh tươi và hành lá', 'Nhẹ nhàng rút bỏ que tre, xếp tôm nướng muối ra đĩa cùng các múi chanh tươi cắt sẵn, rắc hành lá thái nhỏ và chuẩn bị thêm chút tiêu đen xay bên cạnh; khi ăn bóc bỏ lớp vỏ muối và vắt chanh lên thịt tôm nóng hổi.', NULL, NULL),
('imp-8f6eeb8b34b7cd65_v4_step_1', 'imp-8f6eeb8b34b7cd65', 1, 'prep', 'Vo ngâm gạo và nấu cơm trắng Nhật', 'Vo nhẹ 300 g gạo hạt ngắn Nhật 2–3 lần cho trong nước rồi cho vào nồi cơm điện cùng 360 ml nước lọc, ngâm 15 phút trước khi bật nấu khoảng 30 phút cho cơm chín dẻo thơm.', 'Nấu cơm trước vì cơm cần thời gian nấu và ủ hơi, trong lúc đó có thể hoàn tất khâu sơ chế và nướng mực.', 30),
('imp-8f6eeb8b34b7cd65_v4_step_2', 'imp-8f6eeb8b34b7cd65', 2, 'prep', 'Làm sạch, khứa vằn thân mực và chuẩn bị sốt', 'Rút bỏ đầu, râu và nội tạng khỏi thân 450 g mực ống tươi; rút xương sống trong suốt, bỏ mắt và răng cứng ở phần đầu râu rồi rửa sạch dưới vòi nước lạnh. Dùng khăn giấy thấm thật khô cả thân và râu mực, khứa nhẹ các đường song song cách 1 cm lên thân mực mà không cắt đứt. Trộn đều 30 ml xì dầu Nhật, 30 ml rượu Sake nấu ăn, 15 ml rượu Mirin, 24 g đường cát trắng và 10 g gừng tươi mài nhuyễn trong chén nhỏ; thái nhỏ hành lá.', 'Thấm mực thật khô và khứa nhẹ thân mực giúp mực không bị bắn nước khi áp chảo và giữ thân phẳng đẹp.', NULL),
('imp-8f6eeb8b34b7cd65_v4_step_3', 'imp-8f6eeb8b34b7cd65', 3, 'cook', 'Áp chảo thân mực xém cạnh hai mặt', 'Làm nóng chảo rộng trên lửa vừa lớn với 10 ml dầu ăn thực vật, xếp 3 thân mực vào áp chảo mỗi mặt khoảng 2 phút đến khi thân mực săn phồng, chuyển màu trắng đục và hơi cháy xém cạnh thơm lừng.', 'Áp chảo nhanh trên lửa vừa lớn giúp mực giữ độ giòn ngọt mà không bị dai như cao su.', 4),
('imp-8f6eeb8b34b7cd65_v4_step_4', 'imp-8f6eeb8b34b7cd65', 4, 'sauce', 'Áo sốt Teriyaki gừng sánh bóng cho thân mực', 'Đổ toàn bộ chén nước sốt xì dầu Sake Mirin gừng đã pha vào chảo thân mực, liên tục lật trở mực khoảng 2 phút trên lửa vừa đến khi nước sốt sôi sệt lại, bám bóng đều quanh thân mực thì gắp thân mực ra thớt.', NULL, 2),
('imp-8f6eeb8b34b7cd65_v4_step_5', 'imp-8f6eeb8b34b7cd65', 5, 'cook', 'Đảo chín phần râu mực với nước sốt còn lại', 'Thả phần râu mực vào chảo cùng lượng sốt Teriyaki sánh còn lại, đảo nhanh trên lửa vừa khoảng 1–2 phút cho râu mực săn chín hoàn toàn và thấm đẫm sốt thơm ngon rồi tắt bếp.', NULL, 2),
('imp-8f6eeb8b34b7cd65_v4_step_6', 'imp-8f6eeb8b34b7cd65', 6, 'finish', 'Thái khoanh mực, xếp lên cơm nóng và thưởng thức', 'Thái thân mực thành từng khoanh tròn dày 1,5 cm. Xới cơm nóng ra 3 bát, xếp các khoanh mực và râu mực nướng lên trên, rưới đều phần sốt còn lại trong chảo, rắc hành lá thái nhỏ và dùng nóng ngay.', NULL, NULL),
('imp-9e4ad3e4074d2a1c_v4_step_1', 'imp-9e4ad3e4074d2a1c', 1, 'prep', 'Sơ chế tôm sú và luộc chín giữ độ giòn ngọt', 'Bóc vỏ, bỏ đầu, rạch nhẹ lưng rút chỉ đen 250 g tôm sú tươi rồi rửa nhanh với 1 g muối ăn và xả lại nước lạnh. Đun sôi 350 ml nước lọc cùng 1 g muối ăn còn lại, thả tôm vào luộc khoảng 2–3 phút đến khi tôm cong tròn, chuyển màu hồng đỏ đục và chín hoàn toàn thì vớt ra để nguội, cắt miếng vừa ăn.', 'Không luộc tôm quá 3 phút để thịt tôm giữ được độ giòn ngọt mà không bị khô bở.', 3),
('imp-9e4ad3e4074d2a1c_v4_step_2', 'imp-9e4ad3e4074d2a1c', 2, 'prep', 'Thái sợi bắp cải, cà rốt và ngâm hành tây hết hăng', 'Bắp cải xanh thái sợi thật mỏng, cà rốt gọt vỏ thái sợi mảnh. Hành tây thái lát thật mỏng, cho vào tô 250 ml nước lọc lạnh ngâm khoảng 8 phút (có thể thả bắp cải vào ngâm cùng 3 phút cuối cho giòn) rồi vớt tất cả ra rổ, vắt và vẩy thật ráo nước.', 'Ngâm hành tây trong nước lạnh giúp khử vị hăng nồng và giữ độ giòn, nhớ vẩy thật ráo nước để sốt không bị loãng.', 8),
('imp-9e4ad3e4074d2a1c_v4_step_3', 'imp-9e4ad3e4074d2a1c', 3, 'sauce', 'Pha sốt Mayonnaise mật ong giấm chanh hài hòa', 'Cho 45 g sốt Mayonnaise, 15 ml mật ong, 12 ml giấm gạo, nước cốt của nửa quả chanh tươi và 5 ml xì dầu Nhật vào chén, dùng phới lồng nhỏ khuấy đều đến khi hỗn hợp sốt quyện mịn bóng mượt.', NULL, NULL),
('imp-9e4ad3e4074d2a1c_v4_step_4', 'imp-9e4ad3e4074d2a1c', 4, 'cook', 'Trộn nhẹ tay rau củ và tôm với nước sốt', 'Cho bắp cải, cà rốt, hành tây đã ráo nước cùng tôm sú luộc cắt miếng vào tô trộn lớn. Rưới đều phần sốt đã pha lên trên và dùng hai chiếc thìa lớn đảo nhẹ tay để sốt áo mỏng đều mà không làm nát tôm.', 'Trộn salad ngay sau khi ráo nước giúp phần sốt Mayonnaise bám đều từng sợi bắp cải.', NULL),
('imp-9e4ad3e4074d2a1c_v4_step_5', 'imp-9e4ad3e4074d2a1c', 5, 'prep', 'Làm mát salad trong tủ lạnh trước khi dọn', 'Bọc kín tô salad và cho vào ngăn mát tủ lạnh khoảng 15 phút cho các nguyên liệu mát giòn và quyện vị thơm ngon hơn.', NULL, 15),
('imp-9e4ad3e4074d2a1c_v4_step_6', 'imp-9e4ad3e4074d2a1c', 6, 'finish', 'Trình bày đĩa salad bắp cải tôm Nhật mát lạnh', 'Múc salad bắp cải tôm ra đĩa sâu lòng, rắc hành lá thái nhỏ lên trên để tăng màu sắc tươi mát rồi thưởng thức ngay.', NULL, NULL),
('imp-4023e971948407f6_v4_step_1', 'imp-4023e971948407f6', 1, 'marinate', 'Thấm khô và ướp gia vị cho cá hồi', 'Rửa nhanh cá hồi phi lê với nước lạnh rồi dùng khăn giấy thấm thật khô bề mặt, cắt thành 3 miếng vừa ăn khoảng 100 g mỗi miếng. Rắc đều 2 g muối ăn và 1/2 lượng tiêu đen xay lên cả hai mặt cá, để nghỉ 10 phút cho thịt cá săn và thấm gia vị.', 'Thấm thật khô cá trước khi ướp và áo bột giúp cá không bị bắn dầu khi áp chảo và giữ được lớp bề mặt vàng đẹp.', 10),
('imp-4023e971948407f6_v4_step_2', 'imp-4023e971948407f6', 2, 'prep', 'Chần bóc vỏ cà chua và sơ chế rau củ', 'Khía hình chữ thập nhẹ ở đáy 3 quả cà chua chín, thả vào nồi nước sôi chần khoảng 30 giây đến khi mép vỏ hơi tách rồi vớt ra ngâm nước lạnh, bóc sạch vỏ, bỏ hạt và thái hạt lựu. Bóc vỏ hành tây và thái múi cau mỏng, băm nhuyễn tỏi tươi, thái lát nấm đùi gà dày 0,5 cm và cắt khúc hành lá dài 2–3 cm.', 'Chần bỏ vỏ và hạt cà chua giúp nước sốt om sau khi nấu mịn mượt, không bị lợn cợn xác vỏ.', NULL),
('imp-4023e971948407f6_v4_step_3', 'imp-4023e971948407f6', 3, 'prep', 'Áo một lớp bột mì mỏng lên miếng cá', 'Rắc đều 12 g bột mì đa dụng lên hai mặt từng miếng cá hồi đã ướp, dùng tay vỗ và giũ nhẹ cho phần bột thừa rơi bớt, chỉ giữ lại lớp áo thật mỏng phủ đều quanh cá.', NULL, NULL),
('imp-4023e971948407f6_v4_step_4', 'imp-4023e971948407f6', 4, 'cook', 'Áp chảo sơ cho cá hồi vàng nhẹ hai mặt', 'Đun nóng 8 ml dầu ô liu trong chảo rộng trên lửa vừa, đặt từng miếng cá hồi vào áp chảo mỗi mặt khoảng 2 phút đến khi bề mặt chuyển vàng nhạt và se cạnh thì nhẹ nhàng gắp ra đĩa riêng. Không chiên chín kỹ ở bước này vì cá sẽ tiếp tục được om trong sốt.', 'Áp chảo lửa vừa trong thời gian ngắn giúp khóa ẩm bên trong thớ thịt cá hồi, tránh bị khô bở khi om tiếp.', 4),
('imp-4023e971948407f6_v4_step_5', 'imp-4023e971948407f6', 5, 'cook', 'Xào thơm tỏi, hành tây và nấm đùi gà', 'Vẫn dùng chảo đó, thêm 7 ml dầu ô liu còn lại trên lửa vừa, cho tỏi băm vào phi khoảng 20 giây đến khi dậy mùi thơm dịu (không để cháy xém). Tiếp tục cho hành tây và nấm đùi gà vào đảo đều khoảng 3 phút đến khi hành tây hơi trong và nấm mềm tỏa hương ngọt.', NULL, 3),
('imp-4023e971948407f6_v4_step_6', 'imp-4023e971948407f6', 6, 'sauce', 'Nấu nhừ cà chua thành sốt mặn ngọt', 'Trút toàn bộ cà chua thái hạt lựu vào chảo cùng 25 ml xì dầu Nhật Bản, 15 ml rượu ngọt Mirin và 5 g đường cát trắng. Đảo đều và đun sôi trên lửa vừa, sau đó hạ nhỏ lửa om khoảng 5 phút đến khi cà chua nhừ ra sốt đỏ cam sánh nhẹ; nếu chảo hơi khô thì thêm từ từ 60 ml nước lọc.', 'Nêm thử phần sốt cà chua trước khi thả cá vào; vị đạt là chua dịu tự nhiên, hài hòa giữa mặn của xì dầu và ngọt thanh từ Mirin.', 5),
('imp-4023e971948407f6_v4_step_7', 'imp-4023e971948407f6', 7, 'cook', 'Om cá hồi thấm đẫm sốt cà chua', 'Xếp nhẹ các miếng cá hồi đã áp chảo trở lại chảo sốt, dùng thìa rưới đều nước sốt lên mặt cá. Đậy nắp và om trên lửa nhỏ khoảng 5 phút cho đến khi thịt cá chuyển màu hồng cam đục đồng nhất, chín tới hoàn toàn ở phần lõi mà vẫn mềm ẩm.', NULL, 5),
('imp-4023e971948407f6_v4_step_8', 'imp-4023e971948407f6', 8, 'finish', 'Chỉnh gia vị và hoàn thiện đĩa cá om', 'Mở nắp chảo, rắc 1 g muối ăn còn lại cùng phần tiêu đen xay còn lại nếu cần điều chỉnh độ đậm, lắc nhẹ chảo cho sốt hòa quyện. Rắc hành lá thái khúc lên trên, tắt bếp và dọn nóng ngay cùng cơm trắng.', NULL, NULL),
('imp-76ddca35768468fe_v4_step_1', 'imp-76ddca35768468fe', 1, 'prep', 'Băm hành lá và chuẩn bị chanh vàng', 'Rửa sạch 2 bó hành lá tươi, vẩy ráo rồi thấm thật khô bằng khăn giấy, sau đó băm thật nhỏ cả phần đầu trắng lẫn lá xanh. Bào nhuyễn tỏi tươi, cắt đôi quả chanh vàng để vắt lấy 15 ml nước cốt, phần còn lại cắt thành 4–6 múi cau xếp ra đĩa riêng.', 'Thấm thật khô hành lá trước khi băm giúp sốt Negi-shio sánh quyện vào dầu mè mà không bị chảy nhiều nước loãng.', NULL),
('imp-76ddca35768468fe_v4_step_2', 'imp-76ddca35768468fe', 2, 'sauce', 'Pha sốt hành lá Negi-shio thơm béo', 'Cho toàn bộ hành lá băm vào tô nhỏ, thêm 15 ml dầu mè thơm, 15 ml nước cốt chanh vàng, 15 ml rượu Sake, tỏi bào nhuyễn, 3 g muối ăn, 1 g tiêu đen xay và 6 g hạt mè trắng rang. Trộn thật đều và để sốt nghỉ tối thiểu 5 phút cho hành lá dịu vị hăng và tiết nước quyện đều gia vị.', NULL, 5),
('imp-76ddca35768468fe_v4_step_3', 'imp-76ddca35768468fe', 3, 'prep', 'Để thịt bò hồi nhiệt và thấm khô bề mặt', 'Xếp 360 g thịt bò thăn thái lát mỏng ra đĩa lớn, để ở nhiệt độ phòng khoảng 10 phút cho thịt bớt lạnh, dùng khăn giấy thấm khô nhẹ bề mặt từng lát thịt.', 'Thịt bò lạnh đặt thẳng lên vỉ dễ bị tiết nước làm hấp thịt thay vì xém cạnh; để hồi nhiệt nhẹ giúp bò nướng mềm ngọt hơn.', 10),
('imp-76ddca35768468fe_v4_step_4', 'imp-76ddca35768468fe', 4, 'cook', 'Làm nóng vỉ nướng hoặc chảo gang', 'Làm nóng vỉ nướng điện, bếp than hoặc chảo gang rãnh trên lửa lớn khoảng 3 phút cho đến khi mặt vỉ thật nóng và bốc hơi nhẹ.', NULL, NULL),
('imp-76ddca35768468fe_v4_step_5', 'imp-76ddca35768468fe', 5, 'cook', 'Nướng thịt bò nhanh tay trên lửa lớn', 'Xếp từng lát thịt bò lên mặt vỉ nóng thành một lớp thoáng, không chồng lên nhau. Nướng lửa lớn khoảng 45–60 giây cho mặt dưới xém nâu cạnh, rắc một phần muối ăn (trong số 3 g còn lại) và tiêu đen xay lên mặt trên rồi lật mặt nướng tiếp 30–45 giây đến khi thịt chín đều không còn màu đỏ sống.', 'Lát bò Yakiniku mỏng chín rất nhanh; lật ngay khi thấy mặt dưới xém cạnh để thịt giữ độ mọng nước, tránh nướng quá kỹ gây dai.', 2),
('imp-76ddca35768468fe_v4_step_6', 'imp-76ddca35768468fe', 6, 'finish', 'Vắt chanh tươi và thưởng thức cùng sốt Negi-shio', 'Gắp thịt bò vừa nướng xong ra đĩa nóng, vắt vài giọt chanh vàng từ múi cau lên thịt để dậy hương thanh mát, đặt một ít sốt hành lá Negi-shio lên trên từng miếng bò hoặc chấm trực tiếp vào chén sốt và dùng ngay khi nóng.', NULL, NULL),
('imp-1bbb2341036dd966_v4_step_1', 'imp-1bbb2341036dd966', 1, 'prep', 'Sơ chế bông cải xanh và hành lá', 'Rửa sạch bông cải xanh dưới vòi nước, tách thành các nhánh nhỏ đều cỡ 3–4 cm và gọt bỏ phần xơ cứng quanh cuống để rau chín đồng đều. Rửa sạch hành lá tươi, thấm khô và thái khoanh thật nhỏ.', NULL, NULL),
('imp-1bbb2341036dd966_v4_step_2', 'imp-1bbb2341036dd966', 2, 'prep', 'Rang thơm và giã dập hạt mè trắng', 'Cho 27 g hạt mè trắng vào chảo khô, rang trên lửa nhỏ khoảng 3 phút và đảo liên tục đến khi mè chuyển vàng nhạt, dậy mùi thơm bùi thì trút ra ngay kẻo cháy. Đợi nguội bớt, cho 2/3 lượng mè vào cối giã dập cho tiết dầu thơm, giữ lại 1/3 nguyên hạt để rắc mặt.', 'Giã dập 2/3 lượng mè giúp tinh dầu mè tiết ra quyện sốt béo ngậy, trong khi phần mè nguyên hạt tạo điểm nhấn giòn bùi khi ăn.', 3),
('imp-1bbb2341036dd966_v4_step_3', 'imp-1bbb2341036dd966', 3, 'cook', 'Luộc nhanh bông cải xanh giữ độ giòn', 'Đun sôi 1000 ml nước lọc với 5 g muối ăn trên lửa lớn. Thả các nhánh bông cải xanh vào luộc khoảng 2–3 phút đến khi rau vừa chín tới, cuống còn giòn nhẹ và giữ nguyên màu xanh ngọc tươi sáng.', 'Không luộc bông cải quá mềm nhũn vì rau sẽ ngậm nhiều nước, làm loãng sốt mè và mất độ giòn đặc trưng.', 3),
('imp-1bbb2341036dd966_v4_step_4', 'imp-1bbb2341036dd966', 4, 'prep', 'Xả nguội và vắt thật ráo bông cải', 'Vớt bông cải xanh ra rổ ngay khi đạt độ chín, xả nhanh qua nước lọc mát (hoặc quạt nguội trên mâm thưa) để chặn nhiệt giữ màu xanh, sau đó để thật ráo nước và dùng khăn sạch thấm nhẹ cho bề mặt rau khô ráo hoàn toàn.', NULL, NULL),
('imp-1bbb2341036dd966_v4_step_5', 'imp-1bbb2341036dd966', 5, 'sauce', 'Khuấy sốt mè trộn kiểu Nhật', 'Trong tô trộn lớn, khuấy đều 24 ml xì dầu Nhật Bản, 15 ml rượu Sake, 8 ml mật ong nguyên chất và 30 ml nước dùng Dashi đến khi mật ong tan hoàn toàn, sau đó cho toàn bộ phần hạt mè trắng đã giã dập vào trộn sánh mịn.', 'Nếm nhẹ phần sốt trước khi trộn rau; nếu thích vị ngọt dịu hơn có thể thêm vài giọt mật ong, thích đậm hơn thêm chút xì dầu.', NULL),
('imp-1bbb2341036dd966_v4_step_6', 'imp-1bbb2341036dd966', 6, 'finish', 'Trộn đều bông cải với sốt mè và hoàn thiện', 'Cho bông cải xanh đã ráo nước vào tô sốt mè, dùng đũa hoặc phới trộn nhẹ tay từ dưới lên cho sốt áo đều từng nhánh rau, để yên 2 phút cho thấm. Bày ra đĩa, rắc phần mè trắng nguyên hạt còn lại cùng hành lá thái nhỏ lên trên và thưởng thức.', NULL, NULL),
('imp-5ed977305ac677b6_v4_step_1', 'imp-5ed977305ac677b6', 1, 'prep', 'Chuẩn bị hành lá và các loại topping', 'Rửa sạch hành lá tươi, thấm thật khô rồi thái khoanh mỏng. Cắt rong biển lá khô Nori thành sợi mảnh, bóp tơi nhẹ cá bào khô Katsuobushi và chuẩn bị sẵn hạt mè trắng rang cùng 2 viên bơ lạt (14 g mỗi viên).', NULL, NULL),
('imp-5ed977305ac677b6_v4_step_2', 'imp-5ed977305ac677b6', 2, 'prep', 'Xới cơm thật nóng ra hai tô', 'Đảm bảo cơm trắng hạt ngắn Nhật vừa nấu chín hoặc đã hâm nóng bốc hơi. Xới đều 360 g cơm ra 2 tô (180 g/tô), dùng muỗng ấn nhẹ tạo một hõm nhỏ ở chính giữa mỗi tô cơm.', 'Cơm phải đủ nóng bốc hơi mới giúp viên bơ tan chảy hoàn toàn và giải phóng hương thơm đặc trưng.', NULL),
('imp-5ed977305ac677b6_v4_step_3', 'imp-5ed977305ac677b6', 3, 'cook', 'Đặt bơ lạt vào hõm cơm để tan chảy', 'Đặt mỗi tô cơm một viên bơ lạt 14 g vào giữa hõm cơm nóng, chờ khoảng 1 phút cho hơi nóng làm bơ mềm và bắt đầu tan chảy thấm xuống lớp cơm bên dưới.', 'Có thể phủ nhẹ một lớp cơm mỏng lên viên bơ trong 30 giây đầu để giữ nhiệt giúp bơ chảy đều nhanh hơn.', 1),
('imp-5ed977305ac677b6_v4_step_4', 'imp-5ed977305ac677b6', 4, 'sauce', 'Rưới xì dầu Nhật Bản quanh viên bơ', 'Rưới từ từ 7,5 ml xì dầu Nhật Bản lên phần bơ đang tan của mỗi tô (tổng 15 ml cho 2 tô). Không rưới quá nhiều một lúc để giữ cân bằng vị béo của bơ và vị mặn thanh của xì dầu.', 'Nên giữ tỷ lệ vừa phải giữa bơ và xì dầu để món cơm không bị mặn gắt mà vẫn nổi bật mùi thơm bơ sữa.', NULL),
('imp-5ed977305ac677b6_v4_step_5', 'imp-5ed977305ac677b6', 5, 'finish', 'Rắc hành lá, cá bào, rong biển và mè rang', 'Rắc đều hành lá thái mỏng, cá bào khô Katsuobushi, rong biển lá khô Nori cắt sợi, hạt mè trắng rang và một ít tiêu đen xay lên mặt mỗi tô cơm.', NULL, NULL),
('imp-5ed977305ac677b6_v4_step_6', 'imp-5ed977305ac677b6', 6, 'finish', 'Trộn đều cơm bơ xì dầu và thưởng thức nóng', 'Dùng đũa trộn thật đều khoảng 1 phút ngay trước khi ăn cho từng hạt cơm áo bóng bơ lạt tan chảy, xì dầu Nhật Bản và các loại topping thơm lừng, dùng nóng ngay.', NULL, 1),
('imp-57294c4da3e61e24_v4_step_1', 'imp-57294c4da3e61e24', 1, 'prep', 'Sơ chế tôm tươi, nấm đùi gà và rong biển', 'Rửa sạch tôm tươi dưới vòi nước lạnh, cắt bỏ râu và chân dài, tách nhẹ đầu tôm và rạch lưng rút bỏ chỉ đen, giữ nguyên đầu vỏ để nấu nước dùng ngọt thanh. Lau sạch nấm đùi gà và thái lát dày 0,5 cm. Ngâm rong biển Wakame khô trong nước lạnh khoảng 3 phút cho nở mềm rồi vắt ráo; thái khoanh mỏng hành lá tươi.', 'Nấu nguyên đầu và vỏ tôm giúp tiết ra vị ngọt hải sản tự nhiên, hòa quyện rất hợp với nước dùng Dashi và Miso.', 3);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-57294c4da3e61e24_v4_step_2', 'imp-57294c4da3e61e24', 2, 'cook', 'Đun sôi nước dùng với rượu Sake', 'Đổ 550 ml nước lọc và 100 ml nước dùng Dashi cùng 15 ml rượu Sake vào nồi, đặt lên bếp đun trên lửa vừa đến khi nước dùng sôi lăn tăn.', NULL, NULL),
('imp-57294c4da3e61e24_v4_step_3', 'imp-57294c4da3e61e24', 3, 'cook', 'Nấu chín tôm tươi và vớt bọt trong nước', 'Thả tôm tươi vào nồi nước dùng đang sôi, đun trên lửa vừa khoảng 2–3 phút đến khi vỏ tôm chuyển màu đỏ cam rực và thịt tôm săn đục chín hoàn toàn; dùng muôi hớt sạch bọt nổi để nước súp thật trong.', NULL, 3),
('imp-57294c4da3e61e24_v4_step_4', 'imp-57294c4da3e61e24', 4, 'cook', 'Nấu nấm đùi gà và rong biển Wakame', 'Cho nấm đùi gà thái lát vào nồi, hạ lửa vừa nhỏ nấu sôi liu riu thêm 3 phút cho nấm chín mềm tiết vị ngọt. Tiếp tục thả rong biển Wakame đã nở ráo và hành lá thái khoanh vào nồi nấu khoảng 1 phút.', 'Không nấu nấm và rong biển quá lâu để nấm giữ được độ giòn nhẹ còn rong biển không bị nhũn nát.', 3),
('imp-57294c4da3e61e24_v4_step_5', 'imp-57294c4da3e61e24', 5, 'sauce', 'Tắt bếp và hòa tan tương Miso Nhật Bản', 'Tắt bếp hoàn toàn để nước súp ngừng sôi. Cho 54 g tương Miso Nhật Bản vào chén hoặc rây lọc, múc một vá nước dùng nóng từ nồi khuấy cho Miso tan mịn hoàn toàn rồi đổ ngược vào nồi súp, khuấy nhẹ đều tay.', 'Tuyệt đối không đun sôi lại nồi súp sau khi đã cho tương Miso vì nhiệt sôi mạnh sẽ làm bay mất hương thơm lên men đặc trưng.', NULL),
('imp-57294c4da3e61e24_v4_step_6', 'imp-57294c4da3e61e24', 6, 'finish', 'Nêm chỉnh vị và múc súp dùng nóng', 'Nếm thử độ mặn của nước dùng, nếu cần tăng nhẹ độ đậm có thể thêm 5 ml xì dầu Nhật Bản tùy khẩu vị. Múc súp Miso ra 3 bát, chia đều tôm, nấm đùi gà và rong biển rồi thưởng thức ngay khi còn nóng.', NULL, NULL),
('imp-ea9ba867b7d2c6ad_v4_step_1', 'imp-ea9ba867b7d2c6ad', 1, 'prep', 'Sơ chế ức gà, bắp cải và gừng hành', 'Rửa sạch 320 g ức gà không da không xương, thấm khô bằng khăn giấy và khứa vài đường nông trên bề mặt cho nhanh chín. Rửa sạch bắp cải tươi, để ráo và cắt miếng vuông vừa ăn khoảng 4 cm. Chia 20 g gừng tươi: 10 g thái lát mỏng, 10 g bào thật nhuyễn; hành lá chia phần đầu lót hấp và phần lá xanh thái nhỏ.', NULL, NULL),
('imp-ea9ba867b7d2c6ad_v4_step_2', 'imp-ea9ba867b7d2c6ad', 2, 'marinate', 'Ướp ức gà với muối và rượu Sake', 'Xát đều 2 g muối ăn lên hai mặt ức gà, rưới 25 ml rượu Sake Nhật Bản lên thịt và ướp khoảng 10 phút cho thịt gà thấm vị, khử mùi và giữ được độ mềm ẩm khi hấp.', 'Hấp nguyên miếng ức gà rồi mới xé sợi sau giúp khóa nước ngọt bên trong thớ thịt, tránh làm ức gà bị khô xơ.', 10),
('imp-ea9ba867b7d2c6ad_v4_step_3', 'imp-ea9ba867b7d2c6ad', 3, 'cook', 'Lót bắp cải và hấp chín ức gà', 'Đổ 400 ml nước lọc vào nồi hấp và đun sôi trên lửa lớn. Trải đều bắp cải vào đĩa sâu lòng chịu nhiệt, xếp đầu hành lá và 10 g gừng thái lát lên trên rồi đặt miếng ức gà cùng toàn bộ nước ướp lên mặt. Cho đĩa vào xửng, đậy nắp kín và hấp trên lửa vừa khoảng 14–15 phút đến khi thịt gà chuyển màu trắng đục hoàn toàn và nước chảy ra trong khi xiên thử.', 'Không hấp quá lâu sau khi gà đã chín tới để phần ức gà giữ được kết cấu mềm mọng và bắp cải vẫn còn vị giòn ngọt.', 15),
('imp-ea9ba867b7d2c6ad_v4_step_4', 'imp-ea9ba867b7d2c6ad', 4, 'sauce', 'Pha sốt nước tương Ponzu gừng dầu mè', 'Trong lúc chờ hấp, pha sốt trong chén nhỏ gồm 50 ml nước tương Ponzu chanh Nhật, 10 ml dầu mè thơm và 10 g gừng tươi bào nhuyễn; khuấy thật đều tay cho gia vị hòa quyện.', 'Nếu thích món có thêm chút nước ngọt thanh, có thể chắt 2 muỗng canh nước hấp gà trong đĩa hòa chung vào chén sốt Ponzu.', NULL),
('imp-ea9ba867b7d2c6ad_v4_step_5', 'imp-ea9ba867b7d2c6ad', 5, 'prep', 'Để gà nghỉ và xé sợi vừa ăn', 'Nhấc đĩa gà hấp ra khỏi xửng, gắp ức gà để nghỉ khoảng 3 phút cho nguội bớt và ổn định nước thịt, sau đó dùng tay xé thành từng sợi vừa ăn theo thớ thịt. Chắt bớt nếu nước hấp trong đĩa quá nhiều để sốt không bị loãng.', NULL, 3),
('imp-ea9ba867b7d2c6ad_v4_step_6', 'imp-ea9ba867b7d2c6ad', 6, 'finish', 'Trộn sốt, rắc mè và hành lá hoàn thiện', 'Xếp gà xé trở lại lên lớp bắp cải hấp chín mềm trong đĩa, rưới đều toàn bộ sốt nước tương Ponzu gừng dầu mè lên trên, rắc 10 g hạt mè trắng rang cùng phần hành lá thái nhỏ và thưởng thức ngay.', NULL, NULL),
('imp-7d764feba948bce3_v4_step_1', 'imp-7d764feba948bce3', 1, 'prep', 'Sơ chế kim chi, đậu phụ và rau củ', 'Cắt 320 g cải kim chi thành khúc dài khoảng 3 cm, giữ riêng 80 g nước kim chi. Thái lát đậu phụ trắng dày khoảng 1,2 cm, đặt lên đĩa có lót khăn giấy cho ráo bớt nước. Thái lát hành tây dày 0,5 cm, băm nhỏ 4 tép tỏi và thái vát hành lá.', 'Kim chi càng lên men chua kỹ thì nước canh càng đậm đà, dậy vị chua thanh tự nhiên mà không cần dùng thêm giấm.', NULL),
('imp-7d764feba948bce3_v4_step_2', 'imp-7d764feba948bce3', 2, 'prep', 'Cắt khúc và thấm khô cá hồi', 'Rửa nhanh 400 g phi lê cá hồi dưới vòi nước lạnh, dùng khăn giấy thấm thật khô cả hai mặt rồi cắt khúc vuông khoảng 3–4 cm để khi nấu thịt cá giữ nguyên miếng không bị bở nát.', 'Thấm thật khô bề mặt cá hồi trước khi nấu giúp cá săn thớ và giảm đáng kể mùi tanh đặc trưng của hải sản.', NULL),
('imp-7d764feba948bce3_v4_step_3', 'imp-7d764feba948bce3', 3, 'cook', 'Xào kim chi cùng tỏi và ớt bột Hàn', 'Làm nóng nồi đáy dày trên lửa vừa với 15 ml dầu ăn thực vật, cho tỏi băm, phần cải kim chi đã cắt khúc và 6 g ớt bột Hàn Quốc vào đảo đều trong 5 phút đến khi lá kim chi hơi trong, mềm dịu và tiết ra màu đỏ cam thơm nồng.', 'Xào kỹ kim chi trước khi đổ nước giúp giảm vị chua gắt và giải phóng hương thơm đặc trưng của ớt bột Hàn.', 5),
('imp-7d764feba948bce3_v4_step_4', 'imp-7d764feba948bce3', 4, 'cook', 'Hầm nền nước dùng kim chi đậm vị', 'Đổ phần nước kim chi giữ lại cùng 750 ml nước lọc vào nồi. Bật lửa lớn đun sôi bùng, sau đó đậy nắp và hạ về lửa vừa, nấu liu riu trong 10 phút cho kim chi ra hết vị ngọt chua vào nước dùng.', NULL, 10),
('imp-7d764feba948bce3_v4_step_5', 'imp-7d764feba948bce3', 5, 'cook', 'Nấu chín cá hồi và hành tây', 'Thả nhẹ từng khúc cá hồi và hành tây thái lát vào nồi nước đang sôi lăn tăn, nấu trên lửa vừa khoảng 7 phút đến khi thớ cá hồi chuyển màu hồng nhạt đục đều và chín hẳn từ bên trong, chú ý không khuấy mạnh làm vỡ cá.', 'Kiểm tra lát cá ở phút thứ 7: chỉ cần thịt cá tách múi dễ dàng và không còn lõi trong sống là đạt, tránh nấu quá lâu khiến cá bị khô.', 7),
('imp-7d764feba948bce3_v4_step_6', 'imp-7d764feba948bce3', 6, 'finish', 'Thả đậu phụ, nêm gia vị và hoàn thiện', 'Xếp nhẹ đậu phụ trắng lên mặt nồi canh, nêm 15 ml nước tương, 8 g đường cát trắng, 1 g tiêu đen xay và nếm thử trước khi thêm từ từ 3 g muối ăn cho vừa khẩu vị. Rưới 10 ml dầu mè rang, đun sôi nhẹ thêm 3 phút cho đậu phụ nóng đều, rắc hành lá lên trên rồi tắt bếp.', NULL, 3),
('imp-a24e0f07380bfdc2_v4_step_1', 'imp-a24e0f07380bfdc2', 1, 'prep', 'Ngâm nấm hương và ngâm sườn loại bỏ máu thừa', 'Ngâm 35 g nấm hương khô vào 500 ml nước lọc lạnh khoảng 40 phút cho nở mềm; vớt nấm ra cắt bỏ chân và thái miếng vừa ăn, lọc giữ lại phần nước ngâm nấm trong sạch. Rửa sườn bò, ngâm trong nước lạnh 30 phút và thay nước 2 lần cho ra hết máu thừa.', 'Ngâm sườn đủ thời gian giúp loại bỏ mùi hôi của bò và giữ cho nước sốt hầm sau này thật trong, thanh vị.', 35),
('imp-a24e0f07380bfdc2_v4_step_2', 'imp-a24e0f07380bfdc2', 2, 'prep', 'Chần sơ sườn bò cho sạch tạp chất', 'Đun sôi 1000 ml nước lọc trong nồi lớn trên lửa lớn, thả toàn bộ sườn bò vào chần trong 5 phút, đảo nhẹ để tiết bọt bẩn. Vớt sườn ra rửa lại kỹ dưới vòi nước lạnh cho sạch cặn vụn xương rồi rửa sạch lòng nồi.', 'Rửa sạch nồi sau khi chần giúp nước hầm không bị đục và không bám cặn đen vào mặt thịt.', 5),
('imp-a24e0f07380bfdc2_v4_step_3', 'imp-a24e0f07380bfdc2', 3, 'sauce', 'Pha sốt hầm sườn và sơ chế rau củ', 'Xay nhuyễn 1/2 củ hành tây rồi trộn đều với 90 ml nước tương Hàn Quốc, 120 ml rượu ngọt Mirin Nhật, 50 g đường cát trắng, tỏi băm, gừng băm, 2 g tiêu đen xay và 450 ml nước ngâm nấm hương cho tan đường. Gọt vỏ củ cải trắng và cà rốt, cắt khối 3,5–4 cm và tỉa tròn nhẹ góc cạnh; bổ múi cau nửa hành tây còn lại; bổ đôi táo đỏ khô bỏ hạt; cắt khúc hành lá.', 'Tỉa tròn góc cạnh củ cải và cà rốt giúp rau củ giữ nguyên khối đẹp mắt, không bị sứt vỡ khi hầm lâu.', NULL),
('imp-a24e0f07380bfdc2_v4_step_4', 'imp-a24e0f07380bfdc2', 4, 'cook', 'Hầm sườn giai đoạn đầu trên lửa vừa', 'Xếp sườn bò đã chần vào nồi sạch, đổ toàn bộ hỗn hợp sốt vừa pha cùng nửa củ hành tây bổ múi cau vào, đậy nắp kín và đun lửa vừa trong 20 phút cho sườn thấm đều gia vị và bắt đầu mềm thớ.', NULL, 20),
('imp-a24e0f07380bfdc2_v4_step_5', 'imp-a24e0f07380bfdc2', 5, 'cook', 'Hầm tiếp cùng củ cải, cà rốt và nấm hương', 'Cho nấm hương, củ cải trắng và cà rốt vào nồi, đảo nhẹ để rau củ ngập trong nước sốt. Đậy nắp, hạ xuống lửa nhỏ và hầm liu riu thêm 55 phút, thỉnh thoảng mở nắp múc sốt rưới lên trên và kiểm tra lượng nước để không bị bén đáy.', 'Nếu nước cạn nhanh trong lúc hầm, châm thêm 100–150 ml nước lọc nóng và giữ lửa nhỏ liu riu.', 55),
('imp-a24e0f07380bfdc2_v4_step_6', 'imp-a24e0f07380bfdc2', 6, 'cook', 'Thêm táo đỏ, siro gạo và làm bóng sốt', 'Khi dùng xiên tre xiên qua thịt sườn thấy mềm dễ dàng, cho táo đỏ khô và 30 ml siro gạo vào đảo nhẹ, đậy nắp rim lửa nhỏ thêm 10 phút. Sau đó mở nắp, tăng lửa vừa-lớn khoảng 5 phút, liên tục múc nước sốt dưới đáy rưới đều lên thịt và rau củ đến khi sốt sánh quyện bóng đẹp.', NULL, 15),
('imp-a24e0f07380bfdc2_v4_step_7', 'imp-a24e0f07380bfdc2', 7, 'finish', 'Hoàn thiện hương mè và hành lá trước khi dọn', 'Tắt bếp, rưới đều 15 ml dầu mè rang Hàn Quốc và thả hành lá cắt khúc vào đảo nhẹ một lượt rồi dọn sườn cùng rau củ ra đĩa sâu lòng thưởng thức nóng.', NULL, NULL),
('imp-706c3678abea88b4_v4_step_1', 'imp-706c3678abea88b4', 1, 'prep', 'Đánh tan trứng với hành lá và gia vị', 'Rửa sạch hành lá, để thật ráo nước rồi thái nhỏ khoảng 0,5 cm. Đập 4 quả trứng gà vào tô, dùng đũa đánh tan thật kỹ đến khi lòng đỏ và lòng trắng hòa quyện hoàn toàn. Cho hành lá, 2 g muối ăn và 0,5 g tiêu đen xay vào khuấy đều.', 'Hành lá phải thật ráo nước để không làm loãng trứng và tránh bắn dầu khi chiên; đánh kỹ giúp mặt trứng mịn đẹp không bị đốm trắng.', NULL),
('imp-706c3678abea88b4_v4_step_2', 'imp-706c3678abea88b4', 2, 'sauce', 'Pha nước chấm tương giấm mè', 'Khuấy tan 25 ml nước tương với 5 ml giấm gạo và 2 g đường cát trắng trong chén nhỏ, thêm một nửa lượng hạt mè trắng rang lên trên để dùng chấm kèm trứng.', NULL, NULL),
('imp-706c3678abea88b4_v4_step_3', 'imp-706c3678abea88b4', 3, 'cook', 'Chiên chiếc trứng tròn đầu tiên', 'Đặt chảo chống dính đường kính 20–22 cm lên bếp lửa vừa, tráng đều 7,5 ml dầu ăn thực vật. Khi dầu nóng già, đổ một nửa hỗn hợp trứng vào, nghiêng nhẹ chảo cho trứng dàn tròn đều rồi chiên khoảng 2 phút đến khi mặt dưới vàng nâu và viền trứng hơi giòn se lại.', 'Chia làm 2 mẻ chiên thay vì 1 mẻ lớn giúp bánh trứng tròn đẹp, dễ lật và chín đều mà không bị sống lõi.', 2),
('imp-706c3678abea88b4_v4_step_4', 'imp-706c3678abea88b4', 4, 'cook', 'Lật mặt và chiên chín vàng đều hai mặt', 'Dùng xẻng bản rộng lật nhẹ miếng trứng sang mặt còn lại, hạ lửa vừa-nhỏ chiên thêm 2 phút đến khi mặt dưới vàng ruộm và phần giữa chín hoàn toàn không còn ướt rồi trút ra đĩa.', 'Chỉ lật đúng một lần khi mép trứng đã se chắc; nếu mặt trên còn hơi ướt thì chờ thêm 20–30 giây trước khi lật để trứng không bị vỡ.', 2),
('imp-706c3678abea88b4_v4_step_5', 'imp-706c3678abea88b4', 5, 'cook', 'Chiên nốt mẻ trứng thứ hai', 'Lau nhanh mặt chảo bằng khăn giấy sạch nếu có vụn trứng cháy, cho nốt 7,5 ml dầu ăn thực vật vào tráng đều rồi đổ phần hỗn hợp trứng còn lại vào chiên vàng đều hai mặt tương tự (khoảng 2 phút mỗi mặt).', NULL, 4),
('imp-706c3678abea88b4_v4_step_6', 'imp-706c3678abea88b4', 6, 'finish', 'Cắt miếng và trình bày đĩa trứng chiên', 'Để trứng nghỉ trên thớt khoảng 2 phút cho định hình chắc tay rồi cắt mỗi chiếc thành 6 miếng tam giác vừa ăn, rắc phần hạt mè trắng rang còn lại lên mặt và dọn nóng cùng chén nước tương pha.', NULL, NULL),
('imp-d88e008b28a31151_v4_step_1', 'imp-d88e008b28a31151', 1, 'prep', 'Làm sạch, khứa caro và thấm khô mực', 'Tách đầu mực khỏi thân, bỏ túi nội tạng, mắt, mỏ cứng và rút thanh mai trong suốt. Rửa sạch mực dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô. Khứa mặt trong thân mực theo đường caro nông, thái miếng vừa ăn và cắt râu thành khúc 4 cm.', 'Khứa caro giúp mực cong đẹp mắt, nhanh chín và thấm đều sốt cay; thấm thật khô để mực không tiết nhiều nước khi vào chảo.', NULL),
('imp-d88e008b28a31151_v4_step_2', 'imp-d88e008b28a31151', 2, 'sauce', 'Sơ chế rau củ và pha sẵn sốt cay', 'Thái nhỏ 200 g kim chi cải thảo, thái múi cau hành tây, thái lát mỏng cà rốt và cắt khúc hành lá. Trong chén nhỏ, khuấy đều 45 g tương ớt Hàn Quốc, 15 g ớt bột Hàn Quốc, 35 ml nước tương, tỏi băm nhuyễn và 2 g tiêu đen xay thành hỗn hợp sốt sệt.', 'Chuẩn bị sẵn toàn bộ nguyên liệu và sốt trước khi bật bếp vì món xào lửa lớn diễn ra liên tục chỉ trong vài phút.', NULL),
('imp-d88e008b28a31151_v4_step_3', 'imp-d88e008b28a31151', 3, 'cook', 'Phi thơm hành lá và xào sơ rau củ', 'Làm nóng chảo lớn trên lửa lớn với 30 ml dầu ăn thực vật, cho đầu hành lá vào đảo khoảng 45 giây đến khi thơm và hơi xém cạnh. Thêm hành tây và cà rốt vào xào nhanh 1 phút cho rau vừa dịu.', NULL, 2),
('imp-d88e008b28a31151_v4_step_4', 'imp-d88e008b28a31151', 4, 'cook', 'Xào săn kim chi cho dậy hương', 'Thả kim chi cải thảo đã thái nhỏ vào chảo, đảo đều trên lửa lớn trong 2 phút cho kim chi săn lại, quyện dầu hành và tỏa mùi thơm cay nồng.', NULL, 2),
('imp-d88e008b28a31151_v4_step_5', 'imp-d88e008b28a31151', 5, 'cook', 'Xào mực với đường và cô đặc sốt một góc chảo', 'Cho toàn bộ mực vào chảo, rắc đều 15 g đường cát trắng lên trên và đảo nhanh tay khoảng 1 phút đến khi mực bắt đầu cong lại và chuyển màu trắng đục. Gạt mực và rau sang một bên chảo, đổ chén sốt cay vào khoảng trống còn lại, đun sôi sùng sục 30 giây cho sốt hơi sánh lại.', 'Rắc đường lên mực trước khi gặp nước tương mặn giúp mực giữ được độ mềm ngọt, đồng thời cô sốt riêng một góc giúp tránh loãng nước.', 2),
('imp-d88e008b28a31151_v4_step_6', 'imp-d88e008b28a31151', 6, 'finish', 'Trộn đều áo sốt và rưới dầu mè hoàn thiện', 'Đảo đều toàn bộ mực, kim chi và phần lá xanh hành lá với sốt thêm khoảng 30 giây trên lửa lớn đến khi mực chín đều, săn giòn và áo sốt đỏ bóng. Tắt bếp ngay, rưới 10 ml dầu mè rang, rắc hạt mè trắng rang lên trên rồi trút ra đĩa thưởng thức nóng.', NULL, NULL),
('imp-3ec4d8a534fc8861_v4_step_1', 'imp-3ec4d8a534fc8861', 1, 'prep', 'Sơ chế và khứa nhẹ thịt đùi gà', 'Rửa sạch 600 g thịt đùi gà dưới vòi nước lạnh, thấm thật khô bằng khăn giấy. Dùng dao khứa 2–3 đường chéo sâu khoảng 1 cm trên phần thịt dày để nước ướp thấm nhanh và thịt không bị co rút khi gặp nhiệt cao.', NULL, NULL),
('imp-3ec4d8a534fc8861_v4_step_2', 'imp-3ec4d8a534fc8861', 2, 'marinate', 'Pha sốt bulgogi và ướp gà thấm vị', 'Trong tô lớn, khuấy tan 45 ml nước tương Hàn Quốc, 20 g đường nâu, 15 ml mật ong nguyên chất, 15 ml rượu ngọt Mirin Nhật, 10 ml dầu mè rang, tỏi băm, gừng băm, đầu hành lá băm và 1,5 g tiêu đen xay. Cho thịt gà và hành tây thái mỏng vào bóp đều cho phủ kín sốt, đậy kín ướp ít nhất 30 phút (hoặc 2–4 giờ trong ngăn mát cho đậm đà).', 'Đảm bảo đường nâu tan hết trong hỗn hợp ướp để sốt bám đều vào thớ gà, tránh bị cháy cục bộ khi nướng.', 30),
('imp-3ec4d8a534fc8861_v4_step_3', 'imp-3ec4d8a534fc8861', 3, 'cook', 'Làm nóng chảo gang hoặc lò nướng', 'Nếu ướp lạnh, lấy gà ra ngoài khoảng 15 phút cho bớt lạnh. Làm nóng chảo gang hoặc vỉ nướng ở lửa vừa-cao (hoặc làm nóng lò nướng ở 200°C), phết đều 10 ml dầu ăn thực vật lên bề mặt chảo/vỉ để chống dính.', 'Để thịt về gần nhiệt độ phòng trước khi nướng giúp gà chín đều từ trong ra ngoài mà bề mặt không bị cháy khét.', NULL),
('imp-3ec4d8a534fc8861_v4_step_4', 'imp-3ec4d8a534fc8861', 4, 'cook', 'Nướng gà chín vàng xém cạnh hai mặt', 'Gạt bớt phần hành tây bám trên thịt (giữ lại nước ướp), đặt gà lên vỉ hoặc chảo nóng nướng khoảng 6 phút mỗi mặt đến khi bề mặt xém vàng bóng đẹp. Kiểm tra phần thịt dày nhất đạt độ chín hoàn toàn, cắt thử không còn màu hồng và nước thịt chảy ra trong.', 'Trở mặt khi mặt dưới đã lên màu nâu cánh gián; vì sốt có đường và mật ong nên cần canh lửa vừa-cao, tránh lửa quá gắt.', 12),
('imp-3ec4d8a534fc8861_v4_step_5', 'imp-3ec4d8a534fc8861', 5, 'sauce', 'Đun sôi sánh phần nước ướp làm sốt rưới', 'Đổ toàn bộ nước ướp còn dư cùng hành tây thái lát vào chảo nhỏ, đun sôi mạnh rồi hạ lửa vừa-nhỏ nấu thêm 3 phút cho hành tây chín mềm và nước sốt sánh nhẹ lại, đảm bảo tiệt trùng an toàn trước khi dùng làm sốt rưới.', 'Luôn đun sôi kỹ phần nước ướp từng tiếp xúc với thịt gà sống ít nhất 2–3 phút trước khi rưới lên thành phẩm.', 3),
('imp-3ec4d8a534fc8861_v4_step_6', 'imp-3ec4d8a534fc8861', 6, 'finish', 'Thái miếng, rưới sốt và rắc mè hoàn thiện', 'Cho gà nướng nghỉ 4 phút trên thớt để giữ trọn nước ngọt bên trong, thái miếng vừa ăn rồi xếp ra đĩa. Rưới nước sốt bulgogi sánh bóng cùng hành tây lên trên, rắc lá xanh hành lá thái nhỏ và hạt mè trắng rang rồi dùng nóng.', NULL, NULL),
('imp-750cef719bf5f2f6_v4_step_1', 'imp-750cef719bf5f2f6', 1, 'prep', 'Vo gạo và chuẩn bị kim chi, hành tỏi', 'Vo sạch 150 g gạo tẻ thơm, ngâm nước lạnh 15 phút rồi vớt ra để ráo. Thái nhỏ 170 g cải kim chi cỡ 1 cm, giữ lại 50 g nước kim chi. Băm nhỏ tỏi và thái nhỏ hành lá.', NULL, NULL),
('imp-750cef719bf5f2f6_v4_step_2', 'imp-750cef719bf5f2f6', 2, 'cook', 'Xào mềm kim chi với dầu mè và tỏi', 'Cho 15 ml dầu mè rang vào nồi đáy dày khi bếp còn nguội, thêm tỏi băm, cải kim chi, nước kim chi, 10 g đường cát trắng và 5 ml nước mắm. Bật lửa vừa, đảo đều trong 4 phút đến khi kim chi mềm thấm gia vị và dậy mùi thơm.', 'Cho dầu mè vào từ lúc nồi còn nguội rồi mới bật lửa vừa giúp dầu mè không bị cháy khét hay mất mùi thơm.', 4),
('imp-750cef719bf5f2f6_v4_step_3', 'imp-750cef719bf5f2f6', 3, 'cook', 'Rang sơ gạo và đổ nước ninh cháo sánh mịn', 'Trút gạo đã ngâm ráo vào nồi đảo cùng kim chi 1 phút cho hạt gạo áo dầu thơm. Đổ 1100 ml nước lọc vào, bật lửa lớn đun sôi bùng rồi hạ về lửa nhỏ, đậy hờ nắp ninh liu riu 18 phút, thỉnh thoảng khuấy nhẹ đáy nồi để hạt gạo nở bung sánh mịn và không bén đáy.', 'Nếu thích cháo loãng hơn hoặc cháo đặc nhanh khi gần chín, có thể châm thêm 50–100 ml nước nóng.', 18),
('imp-750cef719bf5f2f6_v4_step_4', 'imp-750cef719bf5f2f6', 4, 'cook', 'Nêm vị cháo và thả một nửa hành lá', 'Nêm 15 ml nước tương, 5 ml nước mắm còn lại cùng 1/2 lượng hành lá thái nhỏ vào nồi cháo, khuấy đều và nếm lại sao cho đạt vị chua dịu, mặn ngọt hài hòa.', NULL, NULL),
('imp-750cef719bf5f2f6_v4_step_5', 'imp-750cef719bf5f2f6', 5, 'cook', 'Cho trứng gà vào ủ chín mềm trong nồi cháo', 'Hạ lửa thật nhỏ, đập nhẹ 3 quả trứng gà vào bề mặt nồi cháo (hoặc đánh tan rưới vòng tròn nếu thích dạng vân trứng), đậy kín nắp ủ khoảng 3 phút cho lòng trắng đông chín hoàn toàn và lòng đỏ chín mềm theo ý muốn.', 'Ủ đúng 3 phút trên lửa nhỏ giúp trứng chín mềm mịn mà không bị khô xác hay làm đục màu cháo.', 3),
('imp-750cef719bf5f2f6_v4_step_6', 'imp-750cef719bf5f2f6', 6, 'finish', 'Múc cháo ra tô và rắc rong biển hoàn thiện', 'Tắt bếp, múc cháo nóng cùng trứng ra tô. Rưới nốt 5 ml dầu mè rang, rắc phần hành lá còn lại, rong biển khô cắt vụn, 4 g ớt bột Hàn Quốc và hạt mè trắng rang lên mặt rồi thưởng thức ngay.', NULL, NULL),
('imp-28d20ebe44b82a22_v4_step_1', 'imp-28d20ebe44b82a22', 1, 'prep', 'Thái nấm đùi gà và sơ chế ớt, hành tỏi', 'Cắt bỏ phần gốc cứng của 350 g nấm đùi gà tươi, rửa nhanh rồi thấm ráo nước, thái lát vát dày 0,6–0,8 cm để khi xào nấm ngót lại vẫn giữ độ dai giòn. Thái lát xéo ớt sừng đỏ, băm nhỏ tỏi và cắt khúc hành lá.', 'Không ngâm nấm trong nước quá lâu vì nấm hút nước sẽ làm chảo xào bị nhão và mất độ giòn sần sật.', NULL),
('imp-28d20ebe44b82a22_v4_step_2', 'imp-28d20ebe44b82a22', 2, 'sauce', 'Pha sẵn hỗn hợp sốt tương dầu hào', 'Trộn đều 25 ml nước tương, 20 ml dầu hào, 8 g đường cát trắng và 1 g tiêu đen xay trong chén nhỏ, khuấy kỹ đến khi đường tan hoàn toàn.', NULL, NULL),
('imp-28d20ebe44b82a22_v4_step_3', 'imp-28d20ebe44b82a22', 3, 'cook', 'Phi thơm tỏi trên chảo nóng', 'Đun nóng chảo trên lửa vừa với 25 ml dầu ăn thực vật, cho tỏi băm vào phi khoảng 1–2 phút đến khi tỏi dậy mùi thơm và vừa ngả vàng nhẹ.', 'Canh lửa vừa và đảo đều để tỏi không bị cháy sém gây vị đắng cho nấm.', 2),
('imp-28d20ebe44b82a22_v4_step_4', 'imp-28d20ebe44b82a22', 4, 'cook', 'Xào săn nấm đùi gà và ớt sừng', 'Cho toàn bộ nấm đùi gà và ớt sừng đỏ thái lát vào chảo, tăng lửa vừa-cao xào đều tay khoảng 4 phút cho nấm tiết bớt nước ngọt, săn cạnh và chín mềm dẻo.', NULL, 4),
('imp-28d20ebe44b82a22_v4_step_5', 'imp-28d20ebe44b82a22', 5, 'cook', 'Rưới sốt và đảo bóng đều nấm', 'Rưới hỗn hợp sốt tương dầu hào đã pha vào chảo, đảo liên tục trên lửa vừa khoảng 2–3 phút đến khi phần sốt sánh quyện lại, bám đều một lớp nâu óng mượt quanh từng miếng nấm.', 'Đảo liên tục khi nước sốt cạn dần để sốt phủ đều khắp mặt nấm mà không bị cháy khét đáy chảo.', 3),
('imp-28d20ebe44b82a22_v4_step_6', 'imp-28d20ebe44b82a22', 6, 'finish', 'Rưới dầu mè và rắc hành lá, mè rang', 'Tắt bếp, rưới 10 ml dầu mè rang Hàn Quốc và thêm hành lá cắt khúc vào đảo nhanh một lượt. Trút nấm ra đĩa, rắc hạt mè trắng rang lên trên rồi dọn ăn kèm cơm nóng.', NULL, NULL),
('imp-922028bd2fb07eb8_v4_step_1', 'imp-922028bd2fb07eb8', 1, 'prep', 'Thấm khô, cắt lát đậu phụ và pha sốt tương', 'Dùng khăn giấy thấm thật khô 4 miếng đậu phụ chắc rồi thái lát chữ nhật dày khoảng 1 cm. Thái nhỏ hành lá và băm nhuyễn tỏi. Trong chén nhỏ, hòa đều 35 ml nước tương Hàn Quốc, 15 ml siro ngô, 4 g ớt bột Hàn Quốc và 30 ml nước lọc.', 'Thấm khô đậu phụ kỹ trước khi chiên giúp mặt đậu nhanh vàng giòn, không bị bắn dầu và không vỡ nát khi lật.', NULL),
('imp-922028bd2fb07eb8_v4_step_2', 'imp-922028bd2fb07eb8', 2, 'cook', 'Áp chảo mặt đầu đậu phụ vàng đều', 'Làm nóng chảo chống dính với 30 ml dầu ăn thực vật trên lửa vừa-nhỏ, xếp từng miếng đậu phụ vào chảo sao cho không chồng lên nhau. Áp chảo yên trong 5 phút đến khi mặt dưới chuyển vàng nâu và cứng cạnh.', 'Không lật đậu sớm khi mặt dưới chưa vàng giòn vì miếng đậu mềm dễ bị dính và vỡ.', 5),
('imp-922028bd2fb07eb8_v4_step_3', 'imp-922028bd2fb07eb8', 3, 'cook', 'Lật nhẹ tay chiên vàng mặt còn lại', 'Dùng xẻng mỏng lật nhẹ từng miếng đậu phụ sang mặt còn lại, tiếp tục áp chảo thêm 4 phút trên lửa vừa-nhỏ cho hai mặt vàng giòn đều nhau.', NULL, 4),
('imp-922028bd2fb07eb8_v4_step_4', 'imp-922028bd2fb07eb8', 4, 'cook', 'Phi thơm tỏi trực tiếp trong chảo đậu', 'Gạt nhẹ các miếng đậu sang xung quanh, cho tỏi băm vào khoảng trống giữa chảo và đảo nhanh 30 giây trên lửa nhỏ cho tỏi dậy mùi thơm vàng nhẹ mà không bị cháy đắng.', 'Cho tỏi vào sau khi đậu đã chiên vàng giúp tỏi thơm dậy mùi mà không bị cháy khét suốt thời gian áp chảo đậu.', NULL),
('imp-922028bd2fb07eb8_v4_step_5', 'imp-922028bd2fb07eb8', 5, 'cook', 'Rưới sốt tương và rim sánh bóng', 'Rưới đều chén sốt tương đã pha lên khắp mặt đậu phụ, lắc nhẹ chảo cho sốt tràn đều dưới đáy. Hạ lửa vừa-nhỏ rim khoảng 3 phút, thả hành lá thái nhỏ vào đảo nhẹ cho hành mềm dịu và sốt sánh quyện bám quanh từng lát đậu.', NULL, 3),
('imp-922028bd2fb07eb8_v4_step_6', 'imp-922028bd2fb07eb8', 6, 'finish', 'Rưới dầu mè và rắc mè rang hoàn thiện', 'Tắt bếp, rưới 10 ml dầu mè rang Hàn Quốc lên mặt đậu, gắp xếp gọn gàng ra đĩa, chan phần nước sốt hành còn trong chảo và rắc hạt mè trắng rang lên trên rồi thưởng thức.', NULL, NULL),
('imp-b575db6fcd68a387_v4_step_1', 'imp-b575db6fcd68a387', 1, 'prep', 'Đánh tan trứng gà và sơ chế hành tỏi', 'Đập 4 quả trứng gà vào tô lớn, dùng đũa đánh tan thật đều đến khi không còn sợi lòng trắng. Thái nhỏ hành lá, băm thật nhuyễn tỏi và dùng khăn khô lau nhẹ miếng tảo bẹ khô.', NULL, NULL),
('imp-b575db6fcd68a387_v4_step_2', 'imp-b575db6fcd68a387', 2, 'cook', 'Nấu nước dùng tảo bẹ ngọt thanh', 'Cho 750 ml nước lọc và 8 g tảo bẹ khô vào nồi, đun lửa vừa trong 5 phút đến khi nước vừa sôi lăn tăn quanh mép nồi thì gắp bỏ miếng tảo bẹ ra ngay để nước dùng trong và không bị nhớt.', 'Không đun tảo bẹ sôi sùng sục quá lâu vì chất nhầy trong tảo tiết ra sẽ làm đục nước canh.', 5),
('imp-b575db6fcd68a387_v4_step_3', 'imp-b575db6fcd68a387', 3, 'cook', 'Nêm gia vị tạo nền nước canh đậm đà', 'Cho tỏi băm, 15 ml nước tương, 5 ml nước mắm ngon và 2,5 g muối ăn vào nồi nước dùng, khuấy đều và đun sôi bùng trở lại trên lửa vừa.', NULL, NULL),
('imp-b575db6fcd68a387_v4_step_4', 'imp-b575db6fcd68a387', 4, 'cook', 'Rưới trứng theo dòng mảnh tạo vân mềm mịn', 'Khi nước canh đang sôi nhẹ, cầm tô trứng rót từ từ theo dòng thật mảnh theo vòng tròn quanh nồi. Để yên tuyệt đối không khuấy trong 10 giây để trứng tự định hình thành sợi tơ mềm mượt.', 'Không khuấy ngay lúc mới đổ trứng vì sẽ làm trứng tan vụn và khiến nước canh bị đục.', NULL),
('imp-b575db6fcd68a387_v4_step_5', 'imp-b575db6fcd68a387', 5, 'cook', 'Khuấy nhẹ và nấu chín hoàn toàn vân trứng', 'Dùng đũa khua nhẹ một vòng dưới đáy cho các dải trứng tơi đều nhau, đun thêm 1 phút trên lửa vừa đến khi trứng chín phồng nhẹ và nổi đều trong nồi canh.', NULL, 1),
('imp-b575db6fcd68a387_v4_step_6', 'imp-b575db6fcd68a387', 6, 'finish', 'Thả hành lá, rắc tiêu và nhỏ dầu mè', 'Thả hành lá thái nhỏ và 1 g tiêu đen xay vào nồi, nêm nếm lại cho vừa miệng rồi tắt bếp. Múc canh nóng ra tô, rưới nhẹ 5 ml dầu mè rang lên trên và dùng nóng với cơm trắng.', 'Nếu thích vị cay nhẹ giải cảm, có thể rắc thêm một chút ớt bột mịn hoặc ớt tươi thái lát mỏng lên mặt tô canh.', NULL),
('imp-53933600fa3853f3_v4_step_1', 'imp-53933600fa3853f3', 1, 'prep', 'Thái mỏng thịt bò ngang thớ', 'Làm sạch 400 g thịt thăn bò, thấm khô bề mặt rồi thái lát mỏng khoảng 3 mm theo chiều ngang thớ để thịt mềm ngọt và không bị dai khi xào nhanh.', 'Đặt miếng bò vào ngăn đá khoảng 15 phút trước khi thái giúp thớ thịt hơi se cứng lại, rất dễ thái lát mỏng đều tay.', NULL),
('imp-53933600fa3853f3_v4_step_2', 'imp-53933600fa3853f3', 2, 'marinate', 'Pha sốt bulgogi và ướp thịt bò', 'Trong tô lớn, khuấy tan 35 ml nước tương Hàn Quốc, 20 g đường cát trắng, 10 ml dầu mè rang, tỏi băm nhuyễn và 1,5 g tiêu đen xay. Cho thịt bò vào bóp nhẹ cho từng lát thấm đều sốt, đậy kín ướp 15–20 phút.', NULL, 15),
('imp-53933600fa3853f3_v4_step_3', 'imp-53933600fa3853f3', 3, 'prep', 'Thái dọc nấm đùi gà và sơ chế hành', 'Trong lúc chờ ướp thịt, thái dọc 200 g nấm đùi gà thành lát dày 3–4 mm, thái múi cau mỏng hành tây và cắt khúc hành lá dài khoảng 5–6 cm.', 'Thái nấm dọc theo chiều dài thân nấm giúp miếng nấm giữ độ dai sần sật và không bị nát vụn khi đảo cùng thịt.', NULL),
('imp-53933600fa3853f3_v4_step_4', 'imp-53933600fa3853f3', 4, 'cook', 'Xào thơm nấm đùi gà, hành tây và hành lá', 'Làm nóng chảo sâu lòng trên lửa vừa-cao với 25 ml dầu ăn thực vật. Cho nấm đùi gà, hành tây và phần lớn hành lá (giữ lại ít lá xanh rắc mặt) vào đảo nhanh tay trong 2 phút đến khi hành hơi xém cạnh và nấm dịu mềm.', NULL, 2),
('imp-53933600fa3853f3_v4_step_5', 'imp-53933600fa3853f3', 5, 'cook', 'Xào nhanh thịt bò chín mềm quyện sốt', 'Dàn đều toàn bộ thịt bò cùng nước ướp vào chảo, giữ lửa lớn-vừa đảo đều tay khoảng 4 phút đến khi thịt bò chuyển màu nâu chín đều, nước sốt rút sánh lại bám bóng quanh thịt, nấm và hành.', 'Thịt bò thái mỏng chín rất nhanh, chỉ cần xào vừa chuyển màu hoàn toàn là đạt; đảo quá lâu thịt sẽ khô và ra nước.', 4),
('imp-53933600fa3853f3_v4_step_6', 'imp-53933600fa3853f3', 6, 'finish', 'Rưới dầu mè, rắc mè rang và thưởng thức', 'Nêm nếm lại vừa khẩu vị, tắt bếp rồi rưới nốt 5 ml dầu mè rang còn lại vào đảo đều. Trút ra đĩa, rắc phần hành lá xanh và hạt mè trắng rang lên trên rồi dùng nóng với cơm trắng.', NULL, NULL),
('imp-81fc284c0bafa826_v4_step_1', 'imp-81fc284c0bafa826', 1, 'prep', 'Sơ chế tôm, băm sả tỏi ớt và thái lá chanh', 'Thấm thật khô 400 g tôm tươi đã bóc vỏ chừa đuôi rút chỉ lưng. Băm thật nhuyễn phần gốc non của 3 cây sả cùng 3/4 củ tỏi khô; băm nhỏ 3 quả ớt hiểm và thái lát xéo 2 quả còn lại; tước bỏ gân giữa 4 g lá chanh Thái rồi thái sợi.', 'Băm sả thật nhỏ và thấm khô tôm trước khi xào giúp sả bám chặt lên thân tôm mà không bị bắn dầu.', NULL),
('imp-81fc284c0bafa826_v4_step_2', 'imp-81fc284c0bafa826', 2, 'sauce', 'Pha sẵn nước sốt dầu hào đường thốt nốt', 'Khuấy tan hoàn toàn trong chén nhỏ gồm 10 g đường thốt nốt băm nhỏ, 20 ml xì dầu nhạt, 5 ml xì dầu đen đặc Thái, 25 ml dầu hào, 6 ml nước mắm ngon và 30 ml nước lọc để sẵn cạnh bếp.', NULL, NULL),
('imp-81fc284c0bafa826_v4_step_3', 'imp-81fc284c0bafa826', 3, 'cook', 'Phi thơm sả, tỏi, ớt hiểm cùng bột nghệ', 'Làm nóng chảo sâu lòng trên lửa vừa với 25 ml dầu ăn, cho sả băm, tỏi băm và ớt hiểm băm vào đảo đều 2 phút đến khi sả tỏi dậy hương thơm nồng và hơi vàng cạnh. Tiếp tục thêm lá chanh Thái và 2 g bột nghệ vàng vào đảo nhanh 30 giây.', 'Phi sả trên lửa vừa trước để sả chín thơm và dịu mùi hăng mà không làm cháy khét tỏi.', 2),
('imp-81fc284c0bafa826_v4_step_4', 'imp-81fc284c0bafa826', 4, 'cook', 'Xào tôm lửa lớn vừa chuyển hồng săn', 'Tăng lên lửa lớn, trút toàn bộ 400 g tôm tươi cùng ớt hiểm thái lát vào chảo, đảo đều tay khoảng 2 phút đến khi tôm bắt đầu chuyển màu đỏ cam và săn chắc các cạnh.', NULL, 2),
('imp-81fc284c0bafa826_v4_step_5', 'imp-81fc284c0bafa826', 5, 'cook', 'Rưới nước sốt và đảo keo bóng quanh tôm', 'Khuấy đều chén sốt đã pha rồi rưới hết vào chảo tôm, tiếp tục đảo nhanh tay trên lửa lớn thêm 1–2 phút đến khi tôm cuộn cong chín hoàn toàn bên trong và nước sốt sôi sệt lại, áo bóng đều quanh từng con tôm cùng sả ớt.', 'Chỉ xào tôm tổng cộng khoảng 3–4 phút trên lửa lớn để thịt tôm giòn ngọt mà không bị khô bở.', NULL),
('imp-81fc284c0bafa826_v4_step_6', 'imp-81fc284c0bafa826', 6, 'finish', 'Nếm chỉnh vị và trình bày ra đĩa nóng', 'Nếm lại nước sốt cho vừa khẩu vị mặn ngọt cay thơm rồi tắt bếp, gắp tôm ra đĩa, rưới toàn bộ phần sốt sả ớt trong chảo lên trên và dọn nóng với cơm trắng.', NULL, NULL),
('imp-15e4185437e9198c_v4_step_1', 'imp-15e4185437e9198c', 1, 'prep', 'Ngâm mềm bánh phở khô đúng chuẩn', 'Ngâm 180 g bánh phở khô trong nước ở nhiệt độ phòng ít nhất 60 phút cho đến khi sợi phở mềm dẻo có thể quấn quanh ngón tay mà không gãy, vớt ra để ráo hoàn toàn và cắt đôi những sợi quá dài.', 'Nếu cần làm nhanh, bạn có thể trụng bánh phở trong nước vừa sôi đúng 3 phút rồi xả ngay nước lạnh để không bị bở nát.', 60),
('imp-15e4185437e9198c_v4_step_2', 'imp-15e4185437e9198c', 2, 'prep', 'Sơ chế đồng bộ toàn bộ nguyên liệu', 'Ngâm 60 g me chín với 80 ml nước ấm rồi dằm lọc bỏ hạt lấy nước cốt. Băm thô 20 g tôm khô, băm nhỏ 55 g hành tím và 1/2 củ tỏi, thái nhỏ 1 miếng đậu phụ ép, cắt khúc 5 cm phần 90 g hẹ lá, rửa ráo 180 g giá đỗ, giã thô 50 g đậu phộng rang và cắt múi cau 1,5 quả chanh tươi.', NULL, NULL),
('imp-15e4185437e9198c_v4_step_3', 'imp-15e4185437e9198c', 3, 'sauce', 'Thắng caramen đường thốt nốt nấu sốt me', 'Cho 50 g đường thốt nốt băm nhỏ vào nồi nhỏ đun lửa vừa, đảo liên tục 3 phút đến khi đường tan chảy và ngả màu nâu sậm thơm dịu. Tắt bếp rồi cẩn thận rót nước cốt me đã lọc cùng 40 ml nước mắm ngon vào khuấy đều đến khi sốt sánh quyện bóng mượt.', 'Đường có thể hơi vón lại khi gặp nước cốt me nguội, chỉ cần khuấy nhẹ hoặc để yên vài phút sẽ tự tan hết.', 3),
('imp-15e4185437e9198c_v4_step_4', 'imp-15e4185437e9198c', 4, 'cook', 'Áp chảo tôm chín vàng và giữ riêng', 'Làm nóng chảo sâu lòng trên lửa lớn với 15 ml dầu ăn, xếp 300 g tôm tươi vào áp chảo mỗi mặt 1 phút đến khi tôm chuyển màu hồng cam, săn chắc chín hoàn toàn thì gắp ra đĩa riêng.', NULL, 2),
('imp-15e4185437e9198c_v4_step_5', 'imp-15e4185437e9198c', 5, 'cook', 'Xào thơm đậu phụ, tôm khô và hành tỏi', 'Thêm 20 ml dầu ăn vào chảo trên lửa vừa, cho đậu phụ thái nhỏ, hành tím, tỏi, tôm khô băm và 2 g ớt bột vào đảo đều 3 phút đến khi hành tỏi thơm vàng nhẹ và đậu phụ săn cạnh.', NULL, 3),
('imp-15e4185437e9198c_v4_step_6', 'imp-15e4185437e9198c', 6, 'cook', 'Xào bánh phở ngấm sốt và đánh tơi trứng', 'Tăng lửa lớn, trút bánh phở đã ráo cùng toàn bộ nước sốt me vào đảo đều 3 phút đến khi sợi phở hút cạn nước sốt, tơi bóng và mềm dai vừa ăn. Gạt mì sang một bên chảo, thêm 10 ml dầu ăn còn lại, đập 3 quả trứng gà vào đánh vỡ lòng đỏ, gạt mì phủ lên trên chờ 25 giây cho trứng se chín rồi đảo tơi quyện đều.', 'Phủ bánh phở lên trên lớp trứng vừa đánh vỡ giúp trứng chín mềm ẩm và bám quyện thành từng sợi tơi quanh bánh phở.', 3),
('imp-15e4185437e9198c_v4_step_7', 'imp-15e4185437e9198c', 7, 'finish', 'Trộn giá hẹ và trình bày Pad Thai nóng', 'Tắt bếp ngay, cho tôm áp chảo, một nửa lượng đậu phộng rang giã dập, 120 g giá đỗ và phần lớn hẹ cắt khúc vào đảo nhanh 15 giây cho giá hẹ vừa chín tái giòn ngọt. Chia ra 3 đĩa, rắc phần đậu phộng còn lại và dọn kèm giá sống, hẹ tươi cùng múi chanh.', NULL, NULL),
('imp-cc62ea4de6a7436b_v4_step_1', 'imp-cc62ea4de6a7436b', 1, 'prep', 'Sơ chế tôm, dứa chín và rau thơm', 'Rửa sạch 300 g tôm tươi đã bóc vỏ rút chỉ lưng. Gọt vỏ, bỏ sạch mắt và lõi cứng 3/4 quả dứa chín rồi thái miếng vuông cạnh 1,5 cm. Thái lát thật mỏng 40 g hành tím, thái nhỏ 1/2 bó hành lá, thái lát mỏng 4 quả ớt hiểm, xắt rối 12 g lá bạc hà tươi và giã dập 45 g đậu phộng rang.', 'Chọn dứa chín tới có độ giòn ngọt vừa phải để khi trộn gỏi không bị nát và tiết quá nhiều nước.', NULL),
('imp-cc62ea4de6a7436b_v4_step_2', 'imp-cc62ea4de6a7436b', 2, 'cook', 'Luộc chín tôm giữ độ giòn ngọt', 'Đun sôi mạnh 600 ml nước lọc trong nồi nhỏ trên lửa lớn, thả 300 g tôm vào luộc khoảng 2 phút đến khi tôm cuộn cong, chuyển màu đỏ cam đều và thịt chín chắc hoàn toàn thì vớt ra ngay, để thật ráo và nguội hẳn.', 'Không luộc tôm quá lâu và để tôm nguội ráo trước khi trộn sẽ giúp thịt tôm giòn ngọt mà không làm ỉu gỏi.', 2),
('imp-cc62ea4de6a7436b_v4_step_3', 'imp-cc62ea4de6a7436b', 3, 'sauce', 'Pha nước trộn gỏi chua cay mặn ngọt', 'Vắt nước cốt từ 1,5 quả chanh tươi lọc bỏ hạt cho vào chén, thêm 30 ml nước mắm ngon và 12 g đường cát trắng, khuấy đều tay đến khi đường tan hết hoàn toàn tạo hỗn hợp nước trộn sánh thơm.', NULL, NULL),
('imp-cc62ea4de6a7436b_v4_step_4', 'imp-cc62ea4de6a7436b', 4, 'cook', 'Trộn nhẹ tay dứa, tôm cùng hành ớt', 'Cho dứa cắt miếng, tôm luộc đã nguội, hành tím thái lát, hành lá và ớt hiểm vào tô lớn. Rưới đều toàn bộ chén nước trộn gỏi lên trên, đảo nhẹ tay từ dưới lên để tất cả nguyên liệu áo đều gia vị.', NULL, NULL),
('imp-cc62ea4de6a7436b_v4_step_5', 'imp-cc62ea4de6a7436b', 5, 'finish', 'Để gỏi nghỉ ngấm vị trong 5 phút', 'Để tô gỏi nghỉ 5 phút cho miếng dứa và tôm thấm sâu vị chua mặn ngọt cay hài hòa rồi nếm thử lại một lần, điều chỉnh thêm nước cốt chanh hoặc nước mắm nếu cần.', 'Chỉ nên cho đậu phộng rang và lá bạc hà vào ngay trước lúc ăn để đậu không bị ỉu và lá rau không bị thâm.', 5),
('imp-cc62ea4de6a7436b_v4_step_6', 'imp-cc62ea4de6a7436b', 6, 'finish', 'Rắc đậu phộng rang, bạc hà và dọn mát', 'Gắp gỏi dứa tôm ra đĩa (chắt bớt nước đọng đáy tô nếu nhiều), rắc 45 g đậu phộng rang giã dập và lá bạc hà xắt rối lên trên rồi thưởng thức ngay khi còn tươi mát.', NULL, NULL),
('imp-3d7573766352454e_v4_step_1', 'imp-3d7573766352454e', 1, 'prep', 'Sơ chế thịt gà, nấm và nhóm thảo mộc', 'Cắt 380 g thịt đùi gà rút xương thành miếng vuông 2,5–3 cm. Thái lát dày 0,5 cm phần 200 g nấm đùi gà, bổ múi cau nhỏ 1 quả cà chua và thái nhỏ 3/4 bó hành lá. Đập dập cắt khúc 5 cm phần 3 cây sả, thái lát mỏng 30 g củ riềng, vò nhẹ xé bỏ gân 6 g lá chanh Thái, đập dập 1/2 củ tỏi và 4 quả ớt hiểm. Ngâm 30 g me chín với chút nước ấm lọc bỏ hạt lấy nước cốt.', NULL, NULL),
('imp-3d7573766352454e_v4_step_2', 'imp-3d7573766352454e', 2, 'cook', 'Áp chảo xém cạnh hành tím tạo hương thơm khói', 'Bổ đôi 35 g hành tím theo chiều dọc, đặt úp mặt cắt xuống nồi hoặc chảo khô nóng trên lửa vừa khoảng 3 phút đến khi mặt cắt hành xém nâu nhẹ và tỏa mùi thơm ngọt đặc trưng.', 'Áp chảo hành tím cho xém cạnh trước khi hầm giúp nước dùng canh gà có chiều sâu hương vị thơm dịu rất riêng.', 3),
('imp-3d7573766352454e_v4_step_3', 'imp-3d7573766352454e', 3, 'cook', 'Hầm mềm thịt đùi gà với nước dùng gà', 'Đổ 960 ml nước dùng gà vào nồi đun sôi lăn tăn, thả thịt đùi gà cùng 30 ml nước mắm ngon vào hạ lửa nhỏ vừa, hầm khoảng 12 phút và hớt bọt thường xuyên cho thịt gà chín mềm hoàn toàn và nước dùng trong ngọt.', NULL, 12),
('imp-3d7573766352454e_v4_step_4', 'imp-3d7573766352454e', 4, 'cook', 'Nấu thảo mộc thơm nồng cùng hành tím nướng', 'Thả hành tím áp chảo, sả, củ riềng, lá chanh Thái, tỏi và ớt hiểm đập dập vào nồi canh đang sôi lăn tăn, nấu tiếp 5 phút cho các loại thảo mộc tiết hết tinh dầu thơm vào nước dùng.', 'Giữ lửa sôi nhẹ để tinh dầu sả, riềng và lá chanh lan tỏa từ từ mà không làm đục nước canh.', 5),
('imp-3d7573766352454e_v4_step_5', 'imp-3d7573766352454e', 5, 'cook', 'Nấu nấm đùi gà, cà chua và nước cốt me', 'Rót nước cốt me đã lọc cùng 200 g nấm đùi gà, cà chua bổ múi cau, 15 ml nước mắm ngon còn lại và 5 g đường cát trắng vào nồi. Đun sôi nhẹ thêm 4 phút đến khi nấm chín giòn ngọt và cà chua vừa mềm mà chưa nát.', NULL, 4),
('imp-3d7573766352454e_v4_step_6', 'imp-3d7573766352454e', 6, 'finish', 'Tắt bếp thêm nước cốt chanh và hành lá', 'Tắt bếp chờ nước canh ngừng sôi hẳn mới rót nước cốt từ 1,5 quả chanh tươi vào khuấy đều, nếm chỉnh vị chua cay mặn ngọt cân bằng rồi múc ra tô, rắc hành lá thái nhỏ lên trên và dùng nóng.', 'Kết hợp vị chua trầm của me chín và vị chua sáng của chanh tươi sau khi tắt bếp giúp canh thơm thanh mà không bị gắt.', NULL),
('imp-88fc351665d5e9fc_v4_step_1', 'imp-88fc351665d5e9fc', 1, 'prep', 'Sơ chế thịt thăn bò và ngâm nở mộc nhĩ', 'Ngâm 15 g mộc nhĩ khô trong nước ấm khoảng 15 phút cho nở mềm, cắt bỏ chân nấm rồi thái miếng vừa ăn. Thấm khô 300 g thịt thăn bò bằng khăn giấy, dùng dao sắc thái lát mỏng 2–3 mm ngang thớ để thịt mềm không bị dai.', 'Đặt miếng thịt bò vào ngăn đá tủ lạnh khoảng 20 phút cho hơi se cứng trước khi thái sẽ giúp cắt được những lát thịt mỏng đều rất dễ dàng.', 15),
('imp-88fc351665d5e9fc_v4_step_2', 'imp-88fc351665d5e9fc', 2, 'prep', 'Cắt thái rau củ và chuẩn bị hương liệu', 'Rửa sạch ớt chuông, bỏ hạt và thái miếng xéo vừa ăn. Hành tây bóc vỏ bổ múi cau mỏng; ớt hiểm rửa sạch, bỏ cuống rồi thái lát xéo; tỏi khô bóc vỏ băm nhỏ; hành lá rửa sạch cắt khúc 3–4 cm để riêng.', NULL, NULL),
('imp-88fc351665d5e9fc_v4_step_3', 'imp-88fc351665d5e9fc', 3, 'sauce', 'Pha chén sốt dầu hào và nước bột bắp', 'Trong chén nhỏ, hòa tan hoàn toàn 8 g bột bắp với 45 ml nước lọc cho hết vón cục. Ở một chén khác, trộn đều 30 ml dầu hào, 15 ml xì dầu nhạt, 5 ml xì dầu đặc, 5 ml nước mắm, 5 g đường cát trắng và 1,5 g tiêu trắng xay.', 'Pha sẵn nước bột bắp và chén sốt gia vị trước khi bật bếp vì thao tác xào lửa lớn diễn ra rất nhanh, tránh để thịt bị quá lửa.', NULL),
('imp-88fc351665d5e9fc_v4_step_4', 'imp-88fc351665d5e9fc', 4, 'cook', 'Áp chảo xém mặt thịt bò trên lửa lớn', 'Đặt chảo đáy rộng lên bếp, đun nóng 20 ml dầu ăn trên lửa lớn đến khi dầu hơi gợn sóng. Dàn đều thịt thăn bò thành một lớp mỏng, áp chảo khoảng 2 phút cho hai mặt xém nâu nhẹ và thịt gần chín tới thì gắp nhanh ra đĩa.', 'Không đổ dồn quá nhiều thịt chồng lên nhau khiến nhiệt chảo giảm đột ngột, thịt dễ bị ra nước và dai thay vì cháy cạnh thơm ngon.', 2),
('imp-88fc351665d5e9fc_v4_step_5', 'imp-88fc351665d5e9fc', 5, 'cook', 'Phi thơm tỏi ớt và nấu sánh phần sốt', 'Hạ lửa vừa, thêm 10 ml dầu ăn còn lại vào chảo, cho tỏi băm và ớt hiểm vào đảo thơm 30 giây đến khi tỏi dậy mùi vàng nhẹ. Khuấy đều chén nước bột bắp rồi rưới vào cùng hỗn hợp dầu hào, xì dầu nhạt, xì dầu đặc, nước mắm, đường và tiêu trắng, đun sôi nhẹ 1 phút cho sốt sánh bóng.', NULL, 1),
('imp-88fc351665d5e9fc_v4_step_6', 'imp-88fc351665d5e9fc', 6, 'cook', 'Xào nhanh rau củ và đảo quyện thịt bò', 'Vặn lại lửa lớn, cho ớt chuông, hành tây và mộc nhĩ vào đảo nhanh tay 1–2 phút đến khi rau củ vừa chín tới vẫn giữ được độ giòn ngọt. Nếu sốt quá đặc, rưới thêm 60 ml nước dùng gà để điều chỉnh độ sánh vừa ý, rồi trút thịt bò vào đảo đều 30 giây cho thịt chín hoàn toàn và áo bóng sốt.', NULL, NULL),
('imp-88fc351665d5e9fc_v4_step_7', 'imp-88fc351665d5e9fc', 7, 'finish', 'Rắc hành lá và trình bày ra đĩa', 'Thả hành lá cắt khúc vào chảo, đảo thêm 15 giây cho hành vừa chín xanh mướt rồi tắt bếp ngay. Múc bò xào ớt ra đĩa sâu lòng cùng phần sốt sánh đậm và thưởng thức ngay khi còn nóng với cơm trắng.', NULL, NULL),
('imp-4ec49419e966f676_v4_step_1', 'imp-4ec49419e966f676', 1, 'prep', 'Làm sạch cá giữ nguyên vảy và thấm thật khô', 'Giữ nguyên lớp vảy ngoài của 2 con cá diêu hồng và chỉ móc bỏ ruột, mang qua đường mang cá để bụng cá kín hoàn toàn. Rửa sạch máu đọng bên trong dưới vòi nước lạnh rồi dùng khăn giấy thấm thật khô cả trong bụng lẫn ngoài da cá.', 'Việc giữ nguyên vảy và không mổ phanh bụng giúp lớp muối không thấm mặn vào thịt cá mà chỉ tạo lớp vỏ giữ ẩm kín hơi khi nướng.', NULL),
('imp-4ec49419e966f676_v4_step_2', 'imp-4ec49419e966f676', 2, 'prep', 'Nhồi sả và lá chanh Kaffir vào bụng cá', 'Dùng sống dao đập dập 5 cây sả tươi cho dập tơi sợi, gập đôi lại. Vò nhẹ 10 g lá chanh Kaffir cho dậy tinh dầu thơm rồi nhồi đều sả và lá chanh qua miệng vào bên trong bụng cả 2 con cá, nhồi vừa tay tránh làm rách thịt cá.', NULL, NULL),
('imp-4ec49419e966f676_v4_step_3', 'imp-4ec49419e966f676', 3, 'marinate', 'Trộn vữa muối bột mì và trát kín thân cá', 'Cho 250 g muối hạt vào tô lớn cùng 16 g bột mì đa dụng và 15 ml nước lọc, bóp trộn đều đến khi muối hơi ẩm kết dính như cát ướt. Đặt từng con cá lên mặt phẳng rồi dùng tay trát và miết đều hỗn hợp muối phủ kín hai mặt thân cá từ đầu đến đuôi.', 'Bột mì và một chút nước giúp các hạt muối bám chắc thành lớp áo dày, không bị rơi rụng khi lật cá trên vỉ nướng.', NULL),
('imp-4ec49419e966f676_v4_step_4', 'imp-4ec49419e966f676', 4, 'cook', 'Nướng cá trên lửa than hồng hoặc lò nướng 200°C', 'Nhóm bếp than hoa lửa vừa ổn định (hoặc làm nóng trước lò nướng/nồi chiên ở 200°C). Đặt cá lên vỉ nướng khoảng 20 phút cho mặt dưới se khô hẳn lớp muối rồi nhẹ nhàng lật sang mặt còn lại nướng thêm 20 phút đến khi lớp vỏ muối khô cứng ngả vàng xém và thịt cá chín trắng hoàn toàn tận xương.', 'Nên đợi ít nhất 15–20 phút cho lớp vỏ muối mặt dưới khô cứng hẳn mới lật để tránh da cá dính vào vỉ gây rách lớp muối.', 40),
('imp-4ec49419e966f676_v4_step_5', 'imp-4ec49419e966f676', 5, 'sauce', 'Giã tỏi ớt và pha sốt chấm hải sản Thái', 'Trong lúc chờ cá chín, cho 3 g muối còn lại cùng tỏi bóc vỏ và ớt hiểm vào cối giã nhuyễn vừa. Trút ra chén, thêm nước cốt của 2 quả chanh tươi, 30 ml nước mắm, 12 g đường cát trắng và 45 ml nước lọc, khuấy tan đường để có chén sốt chua cay mặn ngọt hài hòa.', NULL, 5),
('imp-4ec49419e966f676_v4_step_6', 'imp-4ec49419e966f676', 6, 'finish', 'Lột bỏ vỏ muối và dọn cá nóng cùng sốt chấm', 'Gắp cá nướng muối sả ra đĩa lớn, dùng mũi dao rạch nhẹ một đường dọc sống lưng rồi nhẹ nhàng lật bỏ toàn bộ lớp da bọc muối cứng bên ngoài để lộ phần thịt cá trắng mọng bốc khói thơm lừng mùi sả lá chanh. Dọn ăn nóng ngay kèm chén sốt chấm hải sản.', NULL, NULL),
('imp-e47b2f01ee81031a_v4_step_1', 'imp-e47b2f01ee81031a', 1, 'prep', 'Ngâm mềm sợi hủ tiếu khô và ướp tôm tươi', 'Ngâm 180 g hủ tiếu khô trong nước lạnh khoảng 30 phút đến khi sợi dẻo mềm nhưng vẫn còn độ dai nhẹ bên trong, vớt ra rổ để thật ráo. Tôm tươi bóc vỏ, rút chỉ đen, ướp với nước cốt của nửa quả chanh tươi trong 10 phút cho thịt săn và sạch mùi.', 'Ngâm sợi hủ tiếu bằng nước lạnh thay vì nước sôi giúp sợi giữ được độ dai đặc trưng, không bị nát vụn khi đảo trên chảo nóng.', 30),
('imp-e47b2f01ee81031a_v4_step_2', 'imp-e47b2f01ee81031a', 2, 'sauce', 'Lọc nước cốt me và pha sốt xào chua ngọt', 'Dằm 40 g me chín với 180 ml nước lọc ấm rồi lọc qua rây bỏ hạt lấy phần nước cốt me. Hòa vào chén nước me này 20 ml nước mắm, 20 ml xì dầu, 20 g đường cát trắng và 3 g muối ăn, khuấy tan đều đường.', NULL, NULL),
('imp-e47b2f01ee81031a_v4_step_3', 'imp-e47b2f01ee81031a', 3, 'prep', 'Sơ chế dứa, giá đỗ, hành tỏi và đậu phộng', 'Cắt dứa chín thành miếng tam giác vừa ăn; rửa giá đỗ và để ráo; băm nhỏ tỏi và phần đầu hành lá; thái khúc 2 cm phần lá xanh; giã dập 50 g đậu phộng rang; đánh tan 2 quả trứng gà trong chén.', NULL, NULL),
('imp-e47b2f01ee81031a_v4_step_4', 'imp-e47b2f01ee81031a', 4, 'cook', 'Phi thơm hành tỏi và xào săn tôm tươi', 'Làm nóng chảo rộng trên lửa vừa-lớn với 15 ml dầu ăn, cho tỏi băm và đầu hành lá vào phi thơm 30 giây. Trút tôm vào xào nhanh 2 phút đến khi tôm chuyển màu đỏ hồng săn chắc hoàn toàn thì trút riêng ra đĩa.', 'Xào tôm riêng và lấy ra trước giúp tôm chín ngọt, không bị teo dai trong lúc xào mì.', 2),
('imp-e47b2f01ee81031a_v4_step_5', 'imp-e47b2f01ee81031a', 5, 'cook', 'Xào tơi trứng gà và om mì thấm sốt me', 'Thêm 20 ml dầu ăn còn lại vào chảo, đổ trứng gà đã đánh tan vào đảo nhẹ cho trứng chín tơi thành miếng vừa. Cho hủ tiếu đã ráo và toàn bộ chén sốt me vào, đảo đều tay 3 phút trên lửa vừa đến khi sợi mì hút hết sốt và mềm dẻo bóng đẹp.', NULL, 3),
('imp-e47b2f01ee81031a_v4_step_6', 'imp-e47b2f01ee81031a', 6, 'cook', 'Đảo nhanh tôm, dứa và giá đỗ giữ độ giòn', 'Trút tôm đã xào trở lại chảo cùng dứa chín và giá đỗ, tăng lửa lớn đảo đều tay 1–2 phút cho các nguyên liệu nóng quyện đều mà dứa không bị nát ra nước, giá đỗ vẫn giòn ngọt.', 'Chỉ cho dứa và giá đỗ ở phút cuối ngay trước khi tắt bếp để giữ trọn hương thơm tươi mát và độ giòn tự nhiên.', NULL),
('imp-e47b2f01ee81031a_v4_step_7', 'imp-e47b2f01ee81031a', 7, 'finish', 'Rắc đậu phộng, hành lá và hoàn thiện món ăn', 'Tắt bếp, rắc phần hành lá xanh lên đảo nhanh một lượt rồi gắp mì ra đĩa. Phủ đậu phộng rang giã dập lên mặt, bày thêm nửa quả chanh tươi cắt múi và ít ớt bột khô bên cạnh rồi dùng nóng ngay.', NULL, NULL),
('imp-192973f6e1b702b5_v4_step_1', 'imp-192973f6e1b702b5', 1, 'prep', 'Ép ráo nước và cắt miếng đậu phụ', 'Đặt 4,5 bìa đậu phụ lên khăn sạch hoặc rổ có lót giấy thấm, chèn đĩa phẳng hoặc vật nặng nhẹ lên trên để ép bớt nước trong 15 phút. Sau đó thấm khô bề mặt rồi cắt đậu thành khối vuông cạnh khoảng 3 cm.', 'Ép đậu ráo nước giúp miếng đậu săn chắc, chiên nhanh giòn lâu và không bị nổ bắn dầu.', 15),
('imp-192973f6e1b702b5_v4_step_2', 'imp-192973f6e1b702b5', 2, 'prep', 'Sơ chế tỏi ớt, rau củ và áo bột bắp cho đậu', 'Băm nhuyễn tỏi, thái hạt lựu nhỏ hành tây, bào sợi mảnh cà rốt, thái lát ớt hiểm, cắt nhỏ ngò rí và hành lá. Cho các viên đậu phụ vào hộp lớn, rắc đều 45 g bột bắp và xóc nhẹ tay cho lớp bột mỏng bám đều quanh từng miếng đậu.', NULL, NULL),
('imp-192973f6e1b702b5_v4_step_3', 'imp-192973f6e1b702b5', 3, 'sauce', 'Phi thơm tỏi và pha nước sốt chua cay Thái', 'Trong chảo nhỏ, đun nóng 10 ml dầu ăn trên lửa vừa, phi thơm tỏi băm khoảng 30 giây rồi tắt bếp trút ra chén. Hòa tan 35 g đường thốt nốt bào nhỏ cùng 30 ml tương ớt, 35 ml xì dầu và nước cốt của 1,5 quả chanh tươi; thêm tỏi phi, hành tây, cà rốt sợi và ớt hiểm vào khuấy đều.', 'Nếm thử chén sốt để cân chỉnh vị chua cay mặn ngọt hơi đậm một chút vì đậu phụ chiên có vị nhạt thanh.', NULL),
('imp-192973f6e1b702b5_v4_step_4', 'imp-192973f6e1b702b5', 4, 'cook', 'Đun nóng dầu ăn đạt chuẩn nhiệt độ chiên', 'Đổ khoảng 390 ml dầu ăn còn lại vào chảo sâu lòng, đun trên lửa vừa-lớn đến khoảng 180°C. Thử nhiệt bằng cách nhúng đầu đũa gỗ xuống đáy chảo, thấy bọt khí nhỏ sủi đều quanh đầu đũa là dầu đã sẵn sàng.', NULL, NULL),
('imp-192973f6e1b702b5_v4_step_5', 'imp-192973f6e1b702b5', 5, 'cook', 'Chiên ngập dầu đậu phụ thành hai mẻ vàng giòn', 'Thả nhẹ từng viên đậu phụ đã áo bột bắp vào chảo dầu nóng, chia làm 2 mẻ để đậu không dính vào nhau. Chiên khoảng 4–5 phút mỗi mẻ đến khi lớp vỏ phồng nhẹ và vàng giòn đều các mặt thì vớt ra rổ lót giấy thấm dầu.', 'Không cho quá nhiều đậu cùng lúc làm tụt nhiệt độ dầu, khiến vỏ đậu hút dầu và bị ỉu nhanh.', 5),
('imp-192973f6e1b702b5_v4_step_6', 'imp-192973f6e1b702b5', 6, 'finish', 'Xếp đĩa, rưới sốt cay và rắc rau thơm', 'Xếp các khối đậu phụ chiên giòn nóng hổi lên đĩa, rưới đều phần sốt chua cay lên mặt (hoặc để sốt chấm riêng nếu muốn giữ vỏ giòn tối đa). Rắc ngò rí và hành lá cắt nhỏ lên trên rồi dùng nóng ngay.', NULL, NULL),
('imp-2a705e2ff35573b1_v4_step_1', 'imp-2a705e2ff35573b1', 1, 'prep', 'Ngâm ớt khô, lọc nước cốt me và sơ chế tôm rau', 'Ngâm 8 g ớt khô trong nước ấm khoảng 10 phút cho mềm, vớt ráo bỏ hạt. Dằm 60 g me chín với 100 ml nước dùng gà ấm rồi rây bỏ hạt thu nước cốt me. Tôm tươi bóc vỏ, rút chỉ đen; cà chua bổ múi cau; nấm đùi gà thái lát dày 0,5 cm; hành lá thái nhỏ.', NULL, 10),
('imp-2a705e2ff35573b1_v4_step_2', 'imp-2a705e2ff35573b1', 2, 'prep', 'Giã nhuyễn cốt gia vị ớt hành tỏi và mắm tôm', 'Cho ớt khô đã ngâm mềm cùng 2 g muối ăn vào cối giã thật mịn, sau đó cho mắm tôm, hành tím và tỏi khô vào giã tiếp thành hỗn hợp cốt gia vị sánh nhuyễn đồng nhất.', 'Giã ớt với muối hạt trước sẽ giúp vỏ ớt nhanh nát mịn mà không bị bắn ra ngoài cối.', NULL),
('imp-2a705e2ff35573b1_v4_step_3', 'imp-2a705e2ff35573b1', 3, 'cook', 'Luộc cá phi lê và nghiền mịn tạo độ sánh nước dùng', 'Đun sôi 500 ml nước dùng gà còn lại cùng 600 ml nước lọc trong nồi, thả 80 g phi lê cá thịt trắng vào luộc khoảng 4 phút cho chín hoàn toàn. Vớt cá ra chén, dùng nĩa hoặc chày nghiền thật nhuyễn mịn rồi khuấy trở lại nồi nước dùng.', 'Nghiền mịn thịt cá vào nước dùng là bí quyết truyền thống giúp nước canh Gaeng Som có độ sánh mượt tự nhiên và vị ngọt thanh đậm đà.', 4),
('imp-2a705e2ff35573b1_v4_step_4', 'imp-2a705e2ff35573b1', 4, 'cook', 'Hòa cốt gia vị và nêm vị chua mặn ngọt cân bằng', 'Cho toàn bộ hỗn hợp cốt ớt hành tỏi đã giã vào nồi nước dùng khuấy tan đều, đun sôi nhẹ trên lửa vừa. Tiếp theo trút nước cốt me, 20 ml nước mắm và 24 g đường thốt nốt vào khuấy tan hết đường, nếm để vị chua dẫn đầu, tiếp đến mặn vừa và hậu ngọt dịu.', NULL, NULL),
('imp-2a705e2ff35573b1_v4_step_5', 'imp-2a705e2ff35573b1', 5, 'cook', 'Nấu cà chua, nấm đùi gà và thả tôm tươi', 'Thả cà chua bổ múi cau và nấm đùi gà thái lát vào nồi canh nấu sôi liu riu 4 phút cho nấm vừa chín ngọt nước. Tăng lửa vừa-lớn rồi thả tôm tươi vào nấu khoảng 1–2 phút đến khi tôm chuyển màu đỏ hồng, cong mình chín tới thì tắt bếp ngay.', 'Không đun tôm quá 2 phút sau khi nước sôi trở lại để thịt tôm giữ được độ giòn ngọt, không bị bã hay teo cứng.', 5),
('imp-2a705e2ff35573b1_v4_step_6', 'imp-2a705e2ff35573b1', 6, 'finish', 'Vắt chanh tươi, rắc hành lá ớt lát và dọn nóng', 'Vắt nước cốt của 1 quả chanh tươi vào nồi canh đã tắt bếp để dậy hương chua thanh tươi mát. Múc canh chua me tôm ra tô lớn, rắc hành lá và vài lát ớt hiểm tươi lên trên rồi dọn dùng nóng với cơm trắng.', NULL, NULL),
('imp-f050984a2c4deb91_v4_step_1', 'imp-f050984a2c4deb91', 1, 'prep', 'Sơ chế các loại nấm tươi sạch sẽ', 'Rửa nhanh 200 g nấm đùi gà và 100 g nấm mỡ qua nước muối loãng rồi thấm ráo, cắt dọc nấm đùi gà thành miếng dài vừa ăn và bổ đôi nấm mỡ. Cắt bỏ phần gốc rễ của 150 g nấm kim châm, tách thành từng chùm nhỏ vừa gắp và rửa sạch để ráo.', 'Không ngâm nấm quá lâu trong nước vì nấm sẽ hút ẩm làm giảm độ giòn ngọt khi chần và trộn gỏi.', NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('imp-f050984a2c4deb91_v4_step_2', 'imp-f050984a2c4deb91', 2, 'prep', 'Thái mỏng rau củ và giã dập đậu phộng rang', 'Bóc vỏ hành tây tím và hành tây trắng, thái lát thật mỏng theo chiều ngang (có thể ngâm nước đá 5 phút rồi vắt ráo để giảm vị hăng). Rửa sạch cà chua bi bổ đôi, cần tây và hành lá cắt khúc dài 3 cm; giã dập thô 55 g đậu phộng rang.', NULL, NULL),
('imp-f050984a2c4deb91_v4_step_3', 'imp-f050984a2c4deb91', 3, 'sauce', 'Pha nước trộn gỏi chua cay mặn ngọt', 'Cho tỏi băm nhuyễn và ớt hiểm băm nhỏ vào chén, thêm 45 ml xì dầu, nước cốt của 1,5 quả chanh tươi và 15 g đường cát trắng. Khuấy đều tay đến khi đường tan hoàn toàn rồi nếm lại để đạt vị chua cay mặn ngọt cân bằng.', 'Nên pha nước trộn đậm đà hơn khẩu vị thường một chút vì nấm và cà chua sẽ tiết thêm chút nước khi trộn.', NULL),
('imp-f050984a2c4deb91_v4_step_4', 'imp-f050984a2c4deb91', 4, 'cook', 'Chần chín tới từng loại nấm trong nước muối sôi', 'Đun sôi 1000 ml nước lọc cùng 5 g muối ăn trên lửa lớn. Lần lượt chần riêng nấm mỡ khoảng 1 phút, tiếp đến nấm đùi gà 1 phút và cuối cùng là nấm kim châm 45 giây cho từng loại vừa chín tới; vớt ngay ra rổ để thật ráo và nguội hẳn.', 'Chần riêng từng loại với thời gian ngắn giúp nấm không bị nhũn nát mà vẫn giữ được độ giòn sần sật và vị ngọt tự nhiên.', 3),
('imp-f050984a2c4deb91_v4_step_5', 'imp-f050984a2c4deb91', 5, 'cook', 'Vắt nhẹ nấm và trộn cùng rau củ tươi', 'Khi nấm đã nguội và ráo hẳn nước, dùng tay bóp nhẹ cho hết nước đọng rồi cho vào tô trộn lớn cùng hành tây tím, hành tây trắng, cà chua bi, cần tây và hành lá cắt khúc, đảo sơ cho các nguyên liệu tơi đều.', NULL, 5),
('imp-f050984a2c4deb91_v4_step_6', 'imp-f050984a2c4deb91', 6, 'finish', 'Rưới nước trộn gỏi, đảo đều và rắc đậu phộng', 'Rưới từ từ chén nước trộn chua cay vào tô nấm, dùng tay đeo găng hoặc đũa trộn nhẹ nhàng để nguyên liệu thấm đều mà cà chua không bị dập. Bày gỏi ra đĩa, rắc đều 55 g đậu phộng rang giã dập lên trên và thưởng thức ngay.', 'Chỉ rưới nước trộn và đậu phộng ngay trước khi dọn lên bàn ăn để đậu phộng giữ trọn độ giòn bùi và gỏi không bị ra nước.', NULL);
